  dashboardRange: (() => {
    const raw = localStorage.getItem('easyaiconfig_dashboard_range') || '';
    if (!raw.includes('|')) return null;
    const [from, to] = raw.split('|');
    if (!/^\d{4}-\d{2}-\d{2}$/.test(from) || !/^\d{4}-\d{2}-\d{2}$/.test(to)) return null;
    return { from, to };
  })(),
