function getTemporarilyDisabledToolMeta(toolId) {
  return TEMPORARILY_DISABLED_TOOLS[String(toolId || '').trim()] || null;
}

function isTemporarilyDisabledTool(toolId) {
  return Boolean(getTemporarilyDisabledToolMeta(toolId));
}

function flashTemporarilyDisabledTool(toolId) {
  const meta = getTemporarilyDisabledToolMeta(toolId);
  if (!meta) return false;
  flash(meta.message, 'info');
  return true;
}

function renderQuickRailSupportPanel() {
  const titleEl = el('configTipsTitle');
  const bodyEl = el('configTipsList');
  if (!titleEl || !bodyEl) return;

  const readyCount = TOOL_CAPABILITY_MATRIX.filter((item) => item.stageKind === 'ready').length;
  const partialCount = TOOL_CAPABILITY_MATRIX.filter((item) => item.stageKind === 'partial').length;
  const extensionCount = TOOL_CAPABILITY_MATRIX.filter((item) => ['extension', 'catalog', 'planned'].includes(item.stageKind)).length;
  const cell = (item, column) => {
    const value = item[column.key] || 'none';
    const label = TOOL_CAPABILITY_CELL_LABELS[value] || TOOL_CAPABILITY_CELL_LABELS.none;
    return `<span class="qcap-cell qcap-cell-${escapeHtml(value)}" title="${escapeHtml(column.label)}：${escapeHtml(label)}">${escapeHtml(label)}</span>`;
  };
  const rows = TOOL_CAPABILITY_MATRIX.map((item) => `
    <div class="qcap-row qcap-row-${escapeHtml(item.stageKind)}">
      <div class="qcap-head">
        <strong>${escapeHtml(item.name)}</strong>
        <span>${escapeHtml(item.stage)}</span>
      </div>
      <div class="qcap-cells">
        ${TOOL_CAPABILITY_COLUMNS.map((column) => cell(item, column)).join('')}
      </div>
      <em>${escapeHtml(item.note)}</em>
    </div>
  `).join('');

  titleEl.textContent = '支持范围';
  bodyEl.className = 'quick-capability-panel';
  bodyEl.innerHTML = `
    <div class="qcap-summary">
      <span><strong>${escapeHtml(String(readyCount))}</strong><em>完整闭环</em></span>
      <span><strong>${escapeHtml(String(partialCount))}</strong><em>部分闭环</em></span>
      <span><strong>${escapeHtml(String(extensionCount))}</strong><em>扩展/计划</em></span>
    </div>
    <div class="qcap-legend">
      ${TOOL_CAPABILITY_COLUMNS.map((column) => `<span>${escapeHtml(column.label)}</span>`).join('')}
    </div>
    <div class="qcap-list">${rows}</div>
  `;
}

function buildOpenClawDashboardFallbackUrl(baseUrl) {
  const raw = baseUrl || state.openclawState?.dashboardUrl || state.openclawState?.gatewayUrl || '';
  if (!raw) return '';
  const url = new URL(raw, window.location.origin);
  const token = state.openclawState?.config?.gateway?.auth?.token || state.openclawState?.gatewayToken || '';
  if (token) {
    url.hash = '';
    url.searchParams.set('token', token);
  }
  return url.toString();
}

function isLikelyOpenClawBootstrapUrl(rawUrl) {
  try {
    const url = new URL(String(rawUrl || '').trim());
    return Boolean(url.hash || url.searchParams.get('token') || url.pathname !== '/');
  } catch {
    return false;
  }
}

async function openOpenClawDashboard(baseUrl) {
  let url = isLikelyOpenClawBootstrapUrl(baseUrl) ? String(baseUrl || '').trim() : '';
  if (!url) {
    try {
      const json = await api('/api/openclaw/dashboard-url', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ cwd: state.current?.launch?.cwd || '' }),
      });
      url = (json?.ok ? (json.data?.url || '') : '') || buildOpenClawDashboardFallbackUrl(baseUrl);
    } catch { /* ignore */ }
  }
  if (!url) return;
  api('/api/open-url', { method: 'POST', body: JSON.stringify({ url }) }).then(res => {
    if (!res?.ok) window.open(url, '_blank');
  }).catch(() => window.open(url, '_blank'));
}

/* ── Task Manager ── */
let _taskId = 0;

function addTask(name, meta = {}) {
  const id = ++_taskId;
  const task = { id, name, status: 'running', progress: -1, message: '', startTime: Date.now(), ...meta };
  state.tasks.push(task);
  renderSidebarTasks();
  _ensureTaskTimer();
  return id;
}

function updateTask(id, updates) {
  const task = state.tasks.find(t => t.id === id);
  if (!task) return;
  if (updates.status && updates.status !== 'running' && !task.endTime) {
    updates.endTime = Date.now();
  }
  Object.assign(task, updates);
  renderSidebarTasks();
  renderTasksPage();
}

function removeTask(id, delay = 0) {
  if (delay > 0) {
    setTimeout(() => {
      state.tasks = state.tasks.filter(t => t.id !== id);
      renderSidebarTasks();
      renderTasksPage();
    }, delay);
  } else {
    state.tasks = state.tasks.filter(t => t.id !== id);
    renderSidebarTasks();
    renderTasksPage();
  }
}

function renderSidebarTasks() {
  // Update nav badge with running count
  const badge = el('taskNavBadge');
  const running = state.tasks.filter(t => t.status === 'running').length;
  if (badge) {
    if (running > 0) {
      badge.style.display = '';
      badge.textContent = running;
    } else {
      badge.style.display = 'none';
    }
  }
}

function _formatElapsed(ms) {
  const s = Math.floor(ms / 1000);
  if (s < 60) return `${s}s`;
  const m = Math.floor(s / 60);
  return `${m}m ${s % 60}s`;
}

let _taskPageFilter = 'all';

function renderTasksPage() {
  const list = el('tasksPageList');
  const empty = el('tasksEmpty');
  if (!list) return;

  let tasks = [...state.tasks].reverse(); // newest first
  if (_taskPageFilter !== 'all') {
    tasks = tasks.filter(t => t.status === _taskPageFilter);
  }

  if (tasks.length === 0) {
    if (empty) empty.style.display = '';
    list.querySelectorAll('.task-page-item').forEach(e => e.remove());
    return;
  }
  if (empty) empty.style.display = 'none';

  const now = Date.now();
  const html = tasks.map(t => {
    let indicator, statusClass;
    if (t.status === 'running') {
      indicator = '<div class="sti-spinner"></div>';
      statusClass = 'running';
    } else if (t.status === 'done') {
      indicator = '<svg class="sti-done" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><path d="M8 12l3 3 5-6"/></svg>';
      statusClass = 'done';
    } else if (t.status === 'cancelled') {
      indicator = '<svg class="sti-fail" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><path d="M8 8l8 8"/><path d="M16 8l-8 8"/></svg>';
      statusClass = 'error';
    } else {
      indicator = '<svg class="sti-fail" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><line x1="15" y1="9" x2="9" y2="15"/><line x1="9" y1="9" x2="15" y2="15"/></svg>';
      statusClass = 'error';
    }

    const elapsed = _formatElapsed((t.endTime || now) - t.startTime);
    const statusLabel = t.status === 'running' ? '进行中' : t.status === 'done' ? '完成' : t.status === 'cancelled' ? '已中断' : '失败';
    const timeStr = new Date(t.startTime).toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' });

    const progressBar = t.status === 'running'
      ? `<div class="tpi-progress"><div class="sti-progress-fill ${t.progress < 0 ? 'indeterminate' : ''}" style="width:${t.progress < 0 ? '100' : t.progress}%"></div></div>`
      : '';

    return `
      <div class="task-page-item ${statusClass}">
        <div class="tpi-head">
          ${indicator}
          <span class="tpi-name">${escapeHtml(t.name)}</span>
          <span class="tpi-time">${timeStr}</span>
        </div>
        <div class="tpi-meta">
          <span class="tpi-status-label ${statusClass}">${statusLabel}</span>
          <span class="tpi-elapsed">${elapsed}</span>
          ${t.message ? `<span class="tpi-message">${escapeHtml(t.message)}</span>` : ''}
        </div>
        ${progressBar}
      </div>
    `;
  }).join('');

  // Keep the empty div, replace task items
  list.querySelectorAll('.task-page-item').forEach(e => e.remove());
  list.insertAdjacentHTML('beforeend', html);
}

// Auto-tick running task elapsed time
let _taskTimer = null;
function _ensureTaskTimer() {
  const hasRunning = state.tasks.some(t => t.status === 'running');
  if (hasRunning && !_taskTimer) {
    _taskTimer = setInterval(() => {
      if (!state.tasks.some(t => t.status === 'running')) {
        clearInterval(_taskTimer);
        _taskTimer = null;
        return;
      }
      renderSidebarTasks();
      renderTasksPage();
    }, 1000);
  }
}

function normalizeToolOperationStatus(status = '') {
  const value = String(status || '').trim().toLowerCase();
  if (value === 'done') return 'success';
  if (value === 'canceling') return 'cancelling';
  if (['running', 'cancelling', 'success', 'error', 'cancelled'].includes(value)) return value;
  return 'running';
}

function isToolOperationActive(operation) {
  if (!operation || !operation.status) return false;
  const status = normalizeToolOperationStatus(operation?.status);
  return status === 'running' || status === 'cancelling';
}

function getToolOperation(toolId = '') {
  const key = String(toolId || '').trim();
  return key ? (state.toolOperations?.[key] || null) : null;
}

function renderToolsPageIfVisible() {
  if (state.activePage === 'tools') renderToolsPage();
}

function clampToolOperationProgress(value, fallback = 0) {
  const number = Number(value);
  if (!Number.isFinite(number)) return fallback;
  return Math.max(0, Math.min(100, Math.round(number)));
}

function cleanToolOperationText(text = '') {
  return String(text || '')
    .replace(/https?:\/\/\S+/gi, '官方源')
    .replace(/ms-windows-store:\/\/\S+/gi, 'Microsoft Store')
    .replace(/\s+/g, ' ')
    .trim();
}

function setToolOperation(toolId, updates = {}, { render = true, keepCompletedMs = 0 } = {}) {
  const key = String(toolId || '').trim();
  if (!key) return null;
  const previous = getToolOperation(key) || {};
  const status = updates.status ? normalizeToolOperationStatus(updates.status) : normalizeToolOperationStatus(previous.status);
  const next = {
    ...previous,
    ...updates,
    toolId: key,
    status,
    progress: clampToolOperationProgress(updates.progress, clampToolOperationProgress(previous.progress, 0)),
    updatedAt: Date.now(),
  };
  if (!isToolOperationActive(next) && !next.completedAt) next.completedAt = Date.now();
  state.toolOperations[key] = next;
  if (render) renderToolsPageIfVisible();
  if (keepCompletedMs > 0 && !isToolOperationActive(next)) {
    window.setTimeout(() => {
      const current = getToolOperation(key);
      if (current && current.updatedAt === next.updatedAt && !isToolOperationActive(current)) {
        delete state.toolOperations[key];
        renderToolsPageIfVisible();
      }
    }, keepCompletedMs);
  }
  return next;
}

function clearToolOperation(toolId, { delayMs = 0 } = {}) {
  const key = String(toolId || '').trim();
  if (!key) return;
  const clear = () => {
    delete state.toolOperations[key];
    renderToolsPageIfVisible();
  };
  if (delayMs > 0) window.setTimeout(clear, delayMs);
  else clear();
}

function getToolOperationStepTitle(task = {}) {
  const steps = Array.isArray(task.steps) ? task.steps : [];
  const index = Number(task.stepIndex || 0) || 0;
  return steps[index]?.title || '';
}

function syncToolOperationFromTask(toolId, task = {}, fallback = {}) {
  if (!task) return null;
  const status = normalizeToolOperationStatus(task.status || 'running');
  const stepTitle = getToolOperationStepTitle(task);
  const summary = cleanToolOperationText(task.summary || fallback.summary || stepTitle || '正在处理');
  const detail = cleanToolOperationText(task.hint || task.detail || fallback.detail || '');
  return setToolOperation(toolId, {
    action: task.action || fallback.action || '',
    taskId: task.taskId || task.id || fallback.taskId || '',
    status,
    progress: clampToolOperationProgress(task.progress, status === 'success' ? 100 : 8),
    stepIndex: Number(task.stepIndex || 0) || 0,
    stepTitle: cleanToolOperationText(stepTitle),
    summary,
    detail,
    error: cleanToolOperationText(task.error || ''),
  }, { keepCompletedMs: status === 'running' || status === 'cancelling' ? 0 : 9000 });
}

function startToolOperationTicker(toolId, ceiling = 86) {
  const key = String(toolId || '').trim();
  if (!key) return () => {};
  const timer = window.setInterval(() => {
    const operation = getToolOperation(key);
    if (!isToolOperationActive(operation)) return;
    const current = clampToolOperationProgress(operation.progress, 8);
    if (current >= ceiling) return;
    const increment = Math.max(1, Math.round((ceiling - current) * 0.12));
    setToolOperation(key, { progress: Math.min(ceiling, current + increment) });
  }, 850);
  return () => window.clearInterval(timer);
}

function mapTaskStatusToTaskCardStatus(status = '') {
  const normalized = normalizeToolOperationStatus(status);
  if (normalized === 'success') return 'done';
  if (normalized === 'cancelled') return 'cancelled';
  if (normalized === 'error') return 'error';
  return 'running';
}

function renderToolOperationProgress(item, { detail = false } = {}) {
  const operation = getToolOperation(item?.id);
  if (!operation) return '';
  const status = normalizeToolOperationStatus(operation.status);
  const active = isToolOperationActive(operation);
  const progress = clampToolOperationProgress(operation.progress, active ? 8 : 100);
  const label = status === 'success'
    ? '完成'
    : status === 'error'
      ? '失败'
      : status === 'cancelled'
        ? '已中断'
        : status === 'cancelling'
          ? '中断中'
          : (operation.stepTitle || '进行中');
  const summary = cleanToolOperationText(operation.summary || label);
  const detailText = cleanToolOperationText(operation.error || operation.detail || '');
  return `
    <div class="tool-operation tool-operation-${escapeHtml(status)} ${active ? 'is-active' : ''} ${detail ? 'is-detail' : ''}">
      <div class="tool-operation-head">
        <span>${escapeHtml(label)}</span>
        <strong>${escapeHtml(String(progress))}%</strong>
      </div>
      <div class="tool-operation-bar" aria-hidden="true">
        <i style="width:${progress}%"></i>
      </div>
      <div class="tool-operation-copy">
        <span>${escapeHtml(summary)}</span>
        ${detail || detailText ? `<em>${escapeHtml(detailText)}</em>` : ''}
      </div>
    </div>
  `;
}

/* ── Theme ── */
function getAutoTheme() {
  const hour = new Date().getHours();
  return (hour >= 6 && hour < 18) ? 'light' : 'dark';
}

function resolveTheme(preference) {
  if (preference === 'auto') return getAutoTheme();
  return preference;
}

function initTheme() {
  const saved = localStorage.getItem('easyaiconfig_theme') || 'auto';
  state.themePreference = saved; // 'dark' | 'light' | 'auto'
  state.theme = resolveTheme(saved);
  applyTheme(state.theme);
  // Re-evaluate auto theme every minute
  const themeTimer = setInterval(() => {
    if (state.themePreference === 'auto') {
      const next = getAutoTheme();
      if (next !== state.theme) {
        state.theme = next;
        applyTheme(next);
      }
    }
  }, 60000);
  window.addEventListener('beforeunload', () => clearInterval(themeTimer));
}

function applyTheme(theme) {
  document.documentElement.setAttribute('data-theme', theme);
  // Update range slider fills for new theme colors
  document.querySelectorAll('.config-range').forEach(updateRangeFill);
  syncRawCodeEditorTheme();
  syncSystemThemeButtons();
  const titles = { dark: '暗黑模式 · 点击切换浅色', light: '浅色模式 · 点击切换自动', auto: '自动模式 · 点击切换暗黑' };
  document.querySelectorAll('[data-role="theme-toggle"]').forEach((btn) => {
    btn.dataset.themePref = state.themePreference;
    btn.title = titles[state.themePreference] || '切换主题';
    btn.setAttribute('aria-label', btn.title);
  });
}

function toggleTheme() {
  // Cycle: dark → light → auto
  const order = ['dark', 'light', 'auto'];
  const idx = order.indexOf(state.themePreference);
  state.themePreference = order[(idx + 1) % order.length];
  state.theme = resolveTheme(state.themePreference);
  localStorage.setItem('easyaiconfig_theme', state.themePreference);
  applyTheme(state.theme);
  const labels = { dark: '已切换：暗黑模式', light: '已切换：浅色模式', auto: '已切换：自动模式（跟随时间）' };
  flash(labels[state.themePreference] || '', 'success');
}

function getAppLanguage() {
  return window.EasyAIConfigI18n?.getLanguage?.() || 'zh-CN';
}

function isEnglishAppLanguage() {
  return getAppLanguage() === 'en-US';
}

function appText(text, vars) {
  const translator = window.EasyAIConfigI18n?.translate || window.EasyAIConfigI18n?.t || window.t;
  if (typeof translator === 'function') return translator(text, vars);
  let out = String(text == null ? '' : text);
  if (vars && typeof vars === 'object') {
    Object.entries(vars).forEach(([key, value]) => {
      out = out.split(`{${key}}`).join(String(value));
    });
  }
  return out;
}

function applyAppLanguage(language, { silent = false } = {}) {
  const i18n = window.EasyAIConfigI18n;
  if (!i18n) return;
  const before = i18n.getLanguage();
  const next = i18n.setLanguage(language);
  state.language = next;
  if (!silent && next !== before) {
    flash(next === 'en-US' ? 'Language switched to English' : '已切换到中文', 'success');
  }
}

function toggleAppLanguage() {
  const next = getAppLanguage() === 'en-US' ? 'zh-CN' : 'en-US';
  applyAppLanguage(next);
}

function refreshLanguageSensitiveViews() {
  state.language = getAppLanguage();
  window.EasyAIConfigI18n?.apply?.();
  try { setPage(state.activePage || 'quick'); } catch (_) {}
  try { window.refreshCustomSelects?.(); } catch (_) {}
  try { renderQuickRailSupportPanel(); } catch (_) {}
  try { renderSidebarTasks(); } catch (_) {}
  try { renderTasksPage(); } catch (_) {}
  try { renderToolsPage(); } catch (_) {}
  try { if (typeof renderSystemSettingsPage === 'function') renderSystemSettingsPage(); } catch (_) {}
  try { window.renderConnectionHub?.(); } catch (_) {}
  if (state.activePage === 'console') {
    try { renderToolConsole(); } catch (_) {}
  }
  if (state.activePage === 'dashboard') {
    try { renderDashboardPage(); } catch (_) {}
  }
  if (state.activePage === 'terminal') {
    try { if (typeof window.renderTerminalPage === 'function') window.renderTerminalPage(); } catch (_) {}
  }
  if (state.configEditorOpen || state.activePage === 'configEditor') {
    try { if (typeof renderConfigEditor === 'function') renderConfigEditor(); } catch (_) {}
  }
  requestAnimationFrame(() => window.EasyAIConfigI18n?.apply?.());
}

window.addEventListener('easyaiconfig:languagechange', refreshLanguageSensitiveViews);

// Apply theme before any rendering to prevent flash
initTheme();

/* ── Multi-tool Support ── */
function normalizeToolCatalogId(toolId) {
  const value = String(toolId || '').trim().toLowerCase().replace(/[_\s]+/g, '-');
  if (['claude-desktop', 'claudedesktop'].includes(value)) return 'claude-desktop';
  if (['claude-code', 'claudecode'].includes(value)) return 'claudecode';
  if (['gemini', 'gemini-cli', 'google-gemini'].includes(value)) return 'gemini';
  if (['open-code', 'opencode'].includes(value)) return 'opencode';
  if (['open-claw', 'openclaw'].includes(value)) return 'openclaw';
  if (['hermes', 'hermes-agent'].includes(value)) return 'hermes';
  if (['amp', 'amp-code'].includes(value)) return 'amp';
  if (['droid', 'factory-droid'].includes(value)) return 'droid';
  if (['codebuff'].includes(value)) return 'codebuff';
  if (['pi', 'pi-agent', 'piagent'].includes(value)) return 'pi-agent';
  if (['goose', 'block-goose'].includes(value)) return 'goose';
  if (['kimi', 'kimi-code', 'moonshot-kimi'].includes(value)) return 'kimi';
  if (['copilot', 'copilot-cli', 'github-copilot', 'github-copilot-cli'].includes(value)) return 'copilot';
  if (['cline', 'cline-extension'].includes(value)) return 'cline';
  if (['roo', 'roo-code', 'roocode'].includes(value)) return 'roo-code';
  if (['kilo', 'kilo-code', 'kilocode'].includes(value)) return 'kilo-code';
  if (['continue', 'continue-dev'].includes(value)) return 'continue';
  if (['cursor', 'cursor-editor'].includes(value)) return 'cursor';
  if (['windsurf', 'codeium-windsurf'].includes(value)) return 'windsurf';
  if (['qwen', 'qwen-code', 'qwen-code-cli', 'qwen-cli'].includes(value)) return 'qwen-code';
  if (['codebuddy', 'codebuddy-code', 'codebuddy-cli', 'tencent-codebuddy'].includes(value)) return 'codebuddy-code';
  if (['qoder', 'qoder-ide'].includes(value)) return 'qoder';
  if (['zcode', 'z-code', 'z-ai-code'].includes(value)) return 'zcode';
  if (['lingma', 'tongyi-lingma', 'qoder-cn'].includes(value)) return 'lingma';
  if (['zed', 'zed-ide', 'zed-editor'].includes(value)) return 'zed';
  if (['trae', 'trae-ide'].includes(value)) return 'trae';
  if (['vscode', 'vs-code', 'visual-studio-code', 'vscode-ide'].includes(value)) return 'vscode';
  return value || 'codex';
}

function getToolDisplayName(toolId) {
  const normalized = normalizeToolCatalogId(toolId);
  const tool = state.tools?.find?.((item) => normalizeToolCatalogId(item.id) === normalized);
  return tool?.name || {
    codex: 'Codex',
    claudecode: 'Claude Code',
    'claude-desktop': 'Claude Desktop',
    gemini: 'Gemini CLI',
    opencode: 'OpenCode',
    openclaw: 'OpenClaw',
    hermes: 'Hermes Agent',
    amp: 'Amp',
    droid: 'Droid',
    codebuff: 'Codebuff',
    'pi-agent': 'pi-agent',
    goose: 'Goose',
    kimi: 'Kimi',
    copilot: 'GitHub Copilot CLI',
    cline: 'Cline',
    'roo-code': 'Roo Code',
    'kilo-code': 'Kilo Code',
    continue: 'Continue',
    cursor: 'Cursor',
    windsurf: 'Windsurf',
    'qwen-code': 'Qwen Code CLI',
    'codebuddy-code': 'CodeBuddy Code CLI',
    qoder: 'Qoder',
    zcode: 'ZCode',
    lingma: '通义灵码 / Qoder CN',
    zed: 'Zed',
    trae: 'Trae',
    vscode: 'VS Code',
  }[normalized] || normalized;
}

function ensureKnownTools(tools = []) {
  const known = [
    { id: 'codex', name: 'Codex CLI', description: 'OpenAI 官方 AI 编程助手', supportStage: 'active' },
    { id: 'claudecode', name: 'Claude Code', description: 'Anthropic 终端原生 AI 编程助手', supportStage: 'active' },
    { id: 'claude-desktop', name: 'Claude Desktop', description: 'Anthropic 桌面端，重点接入 MCP 与本地配置同步', supportStage: 'active' },
    { id: 'gemini', name: 'Gemini CLI', description: 'Google Gemini 命令行编程助手', supportStage: 'active' },
    { id: 'opencode', name: 'OpenCode', description: '开放式 AI 编程助手 CLI', supportStage: 'active' },
    { id: 'openclaw', name: 'OpenClaw', description: '开源多渠道 AI 助手平台', supportStage: 'active' },
    { id: 'hermes', name: 'Hermes Agent', description: 'Hermes Agent 工作区与会话能力', supportStage: 'active' },
    { id: 'cline', name: 'Cline', description: 'VS Code AI 编程扩展，先支持检测、导入与 Router 接入包', supportStage: 'extension', supported: false, configFormat: 'extension', installMethod: 'manual' },
    { id: 'roo-code', name: 'Roo Code', description: 'VS Code 代理扩展，账号密钥需走扩展安全存储', supportStage: 'extension', supported: false, configFormat: 'extension', installMethod: 'manual' },
    { id: 'kilo-code', name: 'Kilo Code', description: 'Cline/Roo 兼容扩展路线，优先补配置导入闭环', supportStage: 'extension', supported: false, configFormat: 'extension', installMethod: 'manual' },
    { id: 'continue', name: 'Continue', description: 'Continue IDE 助手配置与模型入口，写入器待接入', supportStage: 'catalog', supported: false, configFormat: 'yaml', installMethod: 'manual' },
    { id: 'cursor', name: 'Cursor', description: 'Cursor 编辑器设置、扩展资产与 Router 接入说明', supportStage: 'catalog', supported: false, configFormat: 'editor', installMethod: 'manual' },
    { id: 'windsurf', name: 'Windsurf', description: 'Windsurf 编辑器设置、扩展资产与 Router 接入说明', supportStage: 'catalog', supported: false, configFormat: 'editor', installMethod: 'manual' },
    { id: 'qwen-code', name: 'Qwen Code CLI', description: '阿里 Qwen Code 命令行工具，支持安装、更新和历史版本', supportStage: 'active', supported: true, configFormat: 'unknown', installMethod: 'npm', npmPackage: '@qwen-code/qwen-code' },
    { id: 'codebuddy-code', name: 'CodeBuddy Code CLI', description: '腾讯 CodeBuddy CLI，支持安装、更新和历史版本', supportStage: 'active', supported: true, configFormat: 'unknown', installMethod: 'npm', npmPackage: '@tencent-ai/codebuddy-code' },
  ];
  const normalizedTools = (tools || [])
    .filter(Boolean)
    .map((tool) => ({ ...tool, id: normalizeToolCatalogId(tool.id) }));
  const map = new Map(normalizedTools.map((tool) => [tool.id, tool]));
  const ordered = known.map((tool) => map.get(tool.id) || {
    ...tool,
    supported: tool.supportStage === 'active',
    configFormat: tool.configFormat || (tool.id === 'codex' ? 'toml' : tool.id === 'opencode' ? 'jsonc' : tool.id === 'hermes' ? 'yaml' : 'json'),
    installMethod: tool.installMethod || (tool.id === 'opencode' ? 'auto' : tool.id === 'openclaw' ? 'multi' : tool.id === 'claude-desktop' || tool.id === 'hermes' ? 'manual' : 'npm'),
    npmPackage: tool.npmPackage || (tool.id === 'codex' ? '@openai/codex' : tool.id === 'claudecode' ? '@anthropic-ai/claude-code' : tool.id === 'opencode' ? 'opencode-ai' : tool.id === 'openclaw' ? 'openclaw' : tool.id === 'gemini' ? '@google/gemini-cli' : tool.id === 'qwen-code' ? '@qwen-code/qwen-code' : tool.id === 'codebuddy-code' ? '@tencent-ai/codebuddy-code' : ''),
    binary: { installed: false, version: null, path: null },
  });
  for (const tool of normalizedTools) {
    if (tool?.id && !known.some((item) => item.id === tool.id)) ordered.push(tool);
  }
  return ordered;
}

async function loadOpenCodeDesktopState({ render = true } = {}) {
  try {
    const json = await api('/api/opencode/desktop/state');
    if (json.ok && json.data) {
      state.openCodeDesktopState = json.data;
      if (render && state.activePage === 'tools') renderToolsPage();
    }
  } catch { /* silent */ }
}

async function loadCodexAppState({ render = true } = {}) {
  try {
    const json = await api('/api/codex-app/state');
    if (json.ok && json.data) {
      state.codexAppState = json.data;
      if (render && state.activePage === 'tools') renderToolsPage();
    }
  } catch { /* silent */ }
}

async function loadOpenCodeEcosystemState({ render = true } = {}) {
  try {
    const cwd = el('launchCwdInput')?.value?.trim() || state.current?.launch?.cwd || '';
    const params = new URLSearchParams();
    if (cwd) params.set('cwd', cwd);
    const json = await api(`/api/opencode/ecosystem/state${params.toString() ? `?${params.toString()}` : ''}`);
    if (json.ok && json.data) {
      state.openCodeEcosystemState = json.data;
      if (render && state.activePage === 'tools') renderToolsPage();
    }
  } catch { /* silent */ }
}

async function loadTools() {
  try {
    const json = await api('/api/tools');
    if (json.ok && json.data) {
      state.tools = ensureKnownTools(json.data);
      renderStatus();
      updateToolSelector();
      if (state.activePage === 'tools') {
        renderToolsPage();
        void loadToolUpdates({ force: false, render: true });
        await loadCodexAppState({ render: false }).catch((e) => console.warn('[loadTools] loadCodexAppState failed:', e));
        await loadOpenCodeDesktopState({ render: false }).catch((e) => console.warn('[loadTools] loadOpenCodeDesktopState failed:', e));
        await loadOpenCodeEcosystemState({ render: false }).catch((e) => console.warn('[loadTools] loadOpenCodeEcosystemState failed:', e));
      }
      renderCurrentConfig();
      renderToolConsole();
      if (state.activePage === 'tools') renderToolsPage();
    }
  } catch { /* silent */ }
}

function shouldResyncToolRuntimeState() {
  return state.activePage === 'quick'
    || state.activePage === 'configEditor'
    || state.activePage === 'console'
    || state.activePage === 'tools';
}

async function refreshToolRuntimeAfterMutation(toolId = '') {
  await loadTools().catch((e) => console.warn('[refreshToolRuntimeAfterMutation] loadTools failed:', e));
  if (!toolId || toolId === 'codex') {
    await loadState({ preserveForm: true }).catch((e) => console.warn('[refreshToolRuntimeAfterMutation] loadState failed:', e));
  }
  if (!toolId || toolId === 'claudecode') {
    await loadClaudeCodeQuickState({ force: false, cacheOnly: false }).catch((e) => console.warn('[refreshToolRuntimeAfterMutation] loadClaudeCodeQuickState failed:', e));
  }
  if (!toolId || toolId === 'opencode') {
    await loadOpenCodeQuickState().catch((e) => console.warn('[refreshToolRuntimeAfterMutation] loadOpenCodeQuickState failed:', e));
  }
  if (!toolId || toolId === 'openclaw') {
    await loadOpenClawQuickState().catch((e) => console.warn('[refreshToolRuntimeAfterMutation] loadOpenClawQuickState failed:', e));
  }
  if (!toolId || toolId === 'gemini') {
    await loadGeminiQuickState().catch((e) => console.warn('[refreshToolRuntimeAfterMutation] loadGeminiQuickState failed:', e));
  }
  if (!toolId || toolId === 'hermes') {
    await loadHermesQuickState().catch((e) => console.warn('[refreshToolRuntimeAfterMutation] loadHermesQuickState failed:', e));
  }
  renderCurrentConfig();
  renderToolConsole();
}

async function resyncToolRuntimeState({ force = false } = {}) {
  if (!force && !shouldResyncToolRuntimeState()) return;
  const now = Date.now();
  if (!force && state.toolRuntimeSync.running) return state.toolRuntimeSync.running;
  if (!force && now - (state.toolRuntimeSync.lastAt || 0) < 1200) return;

  const job = refreshToolRuntimeAfterMutation(state.activeTool || '').catch((e) => console.warn('[resyncToolRuntimeState] refresh failed:', e));

  state.toolRuntimeSync.running = job;
  try {
    await job;
    state.toolRuntimeSync.lastAt = Date.now();
  } finally {
    state.toolRuntimeSync.running = null;
  }
}

