function getToolCatalogItems() {
  const baseItems = (state.tools || []).map((tool) => {
    const isSoon = !tool.supported;
    const canManage = Boolean(tool.supported && ['npm', 'auto', 'multi'].includes(String(tool.installMethod || '')));
    const installed = Boolean(tool.binary?.installed);
    const updateInfo = getToolUpdateInfo(tool.id);
    const updateState = getCatalogUpdateState(tool, {
      installed,
      currentVersion: tool.binary?.version || '',
    });
    const autoChip = installed ? '可更新' : '可安装';
    const stage = tool.supportStage || (isSoon ? 'planned' : 'active');
    const typeLabel = stage === 'extension' ? '扩展' : stage === 'catalog' ? '目录' : 'CLI';
    const categoryTag = stage === 'extension'
      ? 'extension'
      : stage === 'catalog'
        ? (['cursor', 'windsurf'].includes(tool.id) ? 'ide' : 'extension')
        : 'cli';
    const stageLabel = stage === 'extension'
      ? '扩展接入'
      : stage === 'catalog'
        ? '目录接入'
        : stage === 'planned'
          ? '待接入'
          : '';
    const regionTags = getToolCatalogRegionTags(tool.id);
    const regionChips = getToolCatalogRegionChips(tool.id);
    const capabilityChip = getToolCatalogCapabilityChip({
      canManage,
      manualOnly: !canManage,
      supportStage: stage,
      installed,
    });
    const manualEntry = TOOL_CATALOG_MANUAL_ENTRIES[tool.id] || TOOL_CATALOG_MANUAL_ENTRIES[normalizeToolCatalogId(tool.id)] || null;
    return {
      id: tool.id,
      kind: 'tool',
      iconId: tool.id,
      typeLabel,
      name: tool.name,
      description: tool.description,
      supported: !isSoon,
      canManage,
      manualOnly: !canManage,
      supportStage: stage,
      installed,
      updateState,
      version: installed ? (tool.binary?.version || '已安装') : (isSoon ? (stageLabel || '暂未支持') : canManage ? '未安装' : '手动入口'),
      badge: updateState.hasUpdate ? '有更新' : installed ? '已安装' : isSoon ? (stageLabel || '目录') : canManage ? '可安装' : '入口',
      tags: [categoryTag, ...regionTags].concat(canManage ? ['automation'] : []).concat(installed ? ['installed'] : []),
      chips: [typeLabel, ...regionChips, stageLabel, canManage ? autoChip : capabilityChip].concat(updateState.hasUpdate ? [updateState.label] : []),
      primaryAction: !canManage && manualEntry?.url ? { externalUrl: manualEntry.url, label: manualEntry.label || '官方入口' } : null,
      updateInfo,
      tool,
    };
  });
  return [...baseItems, getCodexAppCatalogItem(), getOpenCodeDesktopCatalogItem(), ...getManualIdeCatalogItems(), ...getOpenCodeEcosystemCatalogItems()];
}

function filterToolCatalogItems(items = []) {
  const query = getToolsCatalogQuery();
  const tag = getToolsCatalogTag();
  return items.filter((item) => {
    if (tag !== 'all' && !(item.tags || []).includes(tag)) return false;
    if (!query) return true;
    const haystack = normalizeStoreText([
      item.name,
      item.description,
      item.typeLabel,
      item.version,
      ...(item.aliases || []),
      ...(item.tags || []),
      ...(item.chips || []),
    ].join(' '));
    return haystack.includes(query);
  });
}

function compareToolCatalogSidebarItems(a, b) {
  const kindOrder = { tool: 0, desktop: 1, ide: 2, ecosystem: 3 };
  const aOrder = kindOrder[a.kind] ?? 9;
  const bOrder = kindOrder[b.kind] ?? 9;
  if (aOrder !== bOrder) return aOrder - bOrder;
  return String(a.name || '').localeCompare(String(b.name || ''), 'zh-Hans-CN');
}

function getToolsSidebarBadge(item) {
  if (item.updateState?.hasUpdate) return '有更新';
  if (item.installed) return item.kind === 'ecosystem' ? '已就绪' : '已安装';
  if (item.kind === 'ide') return '官方入口';
  if (item.manualOnly) return '手动';
  return item.kind === 'ecosystem' ? '待配置' : '待安装';
}

function renderToolsSidebarEmpty(title, detail) {
  return `
    <div class="sec-empty tools-sec-empty">
      ${escapeHtml(title)}
      ${detail ? `<span>${escapeHtml(detail)}</span>` : ''}
    </div>
  `;
}

function renderToolsSidebarItem(item) {
  const active = getToolsCatalogQuery() === normalizeStoreText(item.name || '');
  const subtitle = [item.typeLabel, item.version].filter(Boolean).join(' · ');
  const badge = getToolsSidebarBadge(item);
  const badgeClass = item.updateState?.hasUpdate ? 'is-update' : item.installed ? 'is-installed' : 'is-pending';
  return `
    <button
      type="button"
      class="sec-item tools-sec-item ${active ? 'active' : ''}"
      data-tools-side-id="${escapeHtml(item.id)}"
      data-tools-side-query="${escapeHtml(item.name)}"
      data-tools-side-tag="${item.installed ? 'installed' : 'all'}"
    >
      <span class="tools-sec-ico tool-icon tool-icon-${item.iconId}">
        ${toolIconSvg(item.iconId)}
      </span>
      <span class="sec-text">
        <span class="sec-name">${escapeHtml(item.name)}</span>
        <span class="sec-subtitle">${escapeHtml(subtitle)}</span>
      </span>
      <span class="tools-sec-badge ${badgeClass}">${escapeHtml(badge)}</span>
    </button>
  `;
}

function bindToolsSecondaryPanel() {
  const body = el('secondaryBody');
  if (!body || body._toolsSidebarBound) return;
  body._toolsSidebarBound = true;
  body.addEventListener('click', (event) => {
    const item = event.target.closest('.sec-item[data-tools-side-id]');
    if (!item || state.activePage !== 'tools') return;
    state.toolsCatalogQuery = item.dataset.toolsSideQuery || '';
    state.toolsCatalogTag = item.dataset.toolsSideTag || 'all';
    state.toolsCatalogPage = 1;
    const searchInput = el('toolsCatalogSearchInput');
    if (searchInput) searchInput.value = state.toolsCatalogQuery;
    renderToolsPage();
  });
}

function renderToolsSecondaryPanel() {
  const installedList = el('toolsInstalledList');
  const pendingList = el('toolsPendingList');
  if (!installedList || !pendingList) return;
  bindToolsSecondaryPanel();

  const installedCount = el('toolsSideInstalledCount');
  const pendingCount = el('toolsSidePendingCount');
  const installedMeta = el('toolsInstalledMeta');
  const pendingMeta = el('toolsPendingMeta');
  const summary = installedCount?.closest?.('.tools-sec-summary') || null;
  const installedHead = installedList.previousElementSibling;
  const pendingHead = pendingList.previousElementSibling;
  const setSidebarNodeVisible = (node, visible, display = '') => {
    if (!node) return;
    node.style.display = visible ? display : 'none';
  };

  if (!state.tools.length) {
    if (installedCount) installedCount.textContent = '0';
    if (pendingCount) pendingCount.textContent = '0';
    if (installedMeta) installedMeta.textContent = '读取中';
    if (pendingMeta) pendingMeta.textContent = '读取中';
    setSidebarNodeVisible(summary, false);
    setSidebarNodeVisible(installedHead, false);
    setSidebarNodeVisible(pendingHead, false);
    setSidebarNodeVisible(installedList, true);
    setSidebarNodeVisible(pendingList, false);
    installedList.innerHTML = renderToolsSidebarEmpty('正在读取工具状态', '安装状态和扩展集成会显示在这里');
    pendingList.innerHTML = '';
    return;
  }

  const items = getToolCatalogItems().sort(compareToolCatalogSidebarItems);
  const installedItems = items.filter((item) => item.installed);
  const pendingItems = items.filter((item) => item.supported && !item.installed && !item.manualOnly);

  if (installedCount) installedCount.textContent = String(installedItems.length);
  if (pendingCount) pendingCount.textContent = String(pendingItems.length);
  if (installedMeta) installedMeta.textContent = `${installedItems.length} 项`;
  if (pendingMeta) pendingMeta.textContent = `${pendingItems.length} 项`;

  const hasInstalled = Boolean(installedItems.length);
  const hasPending = Boolean(pendingItems.length);
  const hasAny = hasInstalled || hasPending;
  setSidebarNodeVisible(summary, hasAny);
  setSidebarNodeVisible(installedHead, hasInstalled, 'flex');
  setSidebarNodeVisible(installedList, hasInstalled || !hasAny);
  setSidebarNodeVisible(pendingHead, hasPending, 'flex');
  setSidebarNodeVisible(pendingList, hasPending);

  installedList.innerHTML = hasInstalled
    ? installedItems.map((item) => renderToolsSidebarItem(item)).join('')
    : hasAny
      ? ''
      : renderToolsSidebarEmpty('从右侧目录选择工具', 'CLI 安装、IDE 下载和扩展入口都在目录里');
  pendingList.innerHTML = hasPending
    ? pendingItems.map((item) => renderToolsSidebarItem(item)).join('')
    : '';
}

function renderToolCardActions(item, actionSvgs) {
  const operationActive = isToolOperationActive(getToolOperation(item?.id));
  const detailButton = `
    <button class="secondary tool-action-btn tool-detail-btn" data-tool-detail="${escapeHtml(item.id)}">
      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9" /><path d="M12 11v5" /><path d="M12 8h.01" /></svg>
      <span>详情</span>
    </button>
  `;
  const externalToolButtons = [item.primaryAction, item.secondaryAction, item.tertiaryAction]
    .filter((action) => action?.externalUrl)
    .map((action) => `
      <button class="secondary tool-action-btn" data-external-url="${escapeHtml(action.externalUrl)}">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6" /><polyline points="15 3 21 3 21 9" /><line x1="10" y1="14" x2="21" y2="3" /></svg>
        <span>${escapeHtml(action.label || '官方入口')}</span>
      </button>
    `).join('');
	  if (item.kind === 'tool') {
    const tool = item.tool;
    const isInstalled = item.installed;
    if (!item.supported) {
        const label = item.supportStage === 'extension'
          ? '扩展接入'
          : item.supportStage === 'catalog'
            ? '已入目录'
            : item.supportStage === 'planned'
              ? '待接入'
              : '暂未支持';
        return `
          ${detailButton}
          ${externalToolButtons}
          <button class="secondary tool-action-btn" disabled>${escapeHtml(label)}</button>
        `;
      }
      if (!item.canManage) return `${detailButton}${externalToolButtons}`;
	    return `
	      ${detailButton}
	      <button class="secondary tool-action-btn tool-action-primary" data-tool-action="update" data-tool-id="${tool.id}" ${operationActive ? 'disabled' : ''}>
	        ${actionSvgs.update}
	        <span>${isInstalled ? '更新' : '安装'}</span>
	      </button>
	      ${isInstalled ? `
	        <button class="secondary tool-action-btn tool-action-danger" data-tool-action="uninstall" data-tool-id="${tool.id}" ${operationActive ? 'disabled' : ''}>
	          ${actionSvgs.uninstall}
          <span>卸载</span>
        </button>
      ` : ''}
    `;
	  }
	  const buttons = [item.primaryAction, item.secondaryAction, item.tertiaryAction].filter(Boolean).map((action) => {
	    const actionLabel = action.label
	      || (action.action === 'install'
	        ? (item.installed ? '更新' : '安装')
	        : action.action === 'update' || action.action === 'reinstall'
	          ? '更新'
	          : action.action === 'ecosystem-install'
	            ? (item.installed ? '处理' : '安装')
	            : '');
	    if (action.externalUrl) {
	      return `
	        <button class="secondary tool-action-btn" data-external-url="${escapeHtml(action.externalUrl)}">
	          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6" /><polyline points="15 3 21 3 21 9" /><line x1="10" y1="14" x2="21" y2="3" /></svg>
	          <span>${escapeHtml(actionLabel)}</span>
	        </button>
	      `;
	    }
    return `
	      <button class="secondary tool-action-btn ${['install', 'update'].includes(action.action) ? 'tool-action-primary' : ''}" data-tool-id="${escapeHtml(action.toolId)}" data-tool-action="${escapeHtml(action.action)}" ${action.ecosystemTarget ? `data-ecosystem-target="${escapeHtml(action.ecosystemTarget)}"` : ''} ${action.disabled || operationActive ? 'disabled' : ''}>
	        ${action.action === 'open' ? '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14" /><path d="m12 5 7 7-7 7" /></svg>' : actionSvgs.update}
	        <span>${escapeHtml(actionLabel)}</span>
	      </button>
	    `;
	  });
  return [detailButton, ...buttons].join('');
}

function getToolCatalogStatusText(item) {
  if (!item) return '';
  if (item.updateState?.latestVersion) {
    if (item.updateState?.hasUpdate) return '可更新';
    if (item.installed) return '已安装';
    return item.supported ? '可安装' : '待环境就绪';
  }
  if (item.kind === 'desktop') {
    const current = normalizeToolVersionText(item.updateState?.currentVersion || '');
    if (item.installed) return current ? `当前 ${current}` : '已安装';
    return item.supported ? '可下载' : '待环境就绪';
  }
  if (item.kind === 'ide') return '官方入口';
  if (item.manualOnly) {
    if (item.supportStage === 'extension') return '扩展资产入口';
    if (item.supportStage === 'catalog') return '配置读取入口';
    return item.installed ? '已检测' : '手动入口';
  }
  if (item.kind === 'tool') {
    const current = normalizeToolVersionText(item.updateState?.currentVersion || '');
    if (item.installed) return current ? `当前 ${current}` : '已安装';
    if (item.supported) return '未安装';
    if (item.supportStage === 'extension') return '扩展接入中';
    if (item.supportStage === 'catalog') return '已纳入目录';
    if (item.supportStage === 'planned') return '待接入';
    return '暂未支持';
  }
  if (item.updateState?.latestVersion) return `最新 ${item.updateState.latestVersion}`;
  if (item.installed) return item.kind === 'ecosystem' ? '已配置' : '已安装';
  return item.supported ? '可处理' : '待环境就绪';
}

function renderToolCatalogCard(item, actionSvgs) {
  const chips = (item.chips || []).filter(Boolean);
  const hasUpdate = Boolean(item.updateState?.hasUpdate);
  const badgeClass = hasUpdate ? 'tool-badge-update' : item.installed ? 'tool-badge-ok' : '';
  const selected = state.toolsCatalogDetailId === item.id;
  const currentVersion = normalizeToolVersionText(item.updateState?.currentVersion) || (item.installed ? '未知' : '未安装');
  const latestVersion = normalizeToolVersionText(item.updateState?.latestVersion || '');
  const showCurrentOnlyVersion = !latestVersion && item.kind === 'desktop' && item.installed && currentVersion && currentVersion !== '未知';
  return `
    <div class="tool-card ${selected ? 'is-selected' : ''} ${item.supportStage === 'planned' ? 'tool-card-soon' : ''} ${hasUpdate ? 'tool-card-has-update' : ''}" data-tool-id="${item.id}">
      <div class="tool-card-head">
        <div class="tool-icon tool-icon-${item.iconId}">
          ${toolIconSvg(item.iconId)}
        </div>
        <div class="tool-info">
          <div class="tool-name-row">
            <div class="tool-name">${escapeHtml(item.name)}</div>
            <span class="tool-type-tag">${escapeHtml(item.typeLabel)}</span>
          </div>
          <div class="tool-desc">${escapeHtml(item.description)}</div>
        </div>
      </div>
      ${chips.length ? `
      <div class="tool-chip-row">
        ${chips.map((chip) => `<span class="tool-chip ${hasUpdate && chip === item.updateState?.label ? 'tool-chip-update' : item.installed && chip === '已安装' ? 'tool-chip-active' : ''}">${escapeHtml(chip)}</span>`).join('')}
      </div>` : ''}
      ${latestVersion || showCurrentOnlyVersion ? `
      <div class="tool-version-pair">
        <span><em>当前</em><strong>${escapeHtml(currentVersion)}</strong></span>
        ${latestVersion ? `<span><em>最新</em><strong>${escapeHtml(latestVersion)}</strong></span>` : ''}
      </div>` : ''}
      <div class="tool-status">
        <span class="tool-version ${!item.installed ? 'tool-version-muted' : ''}">${escapeHtml(getToolCatalogStatusText(item))}</span>
        <span class="tool-badge ${badgeClass}">${escapeHtml(item.badge)}</span>
      </div>
      ${renderToolOperationProgress(item)}
      <div class="tool-actions">${renderToolCardActions(item, actionSvgs)}</div>
    </div>
  `;
}

function findToolCatalogItemById(id = '') {
  const target = String(id || '').trim();
  if (!target) return null;
  return getToolCatalogItems().find((item) => item.id === target) || null;
}

function renderToolDetailMetaChips(item, info, regionLabels = []) {
  const regions = Array.from(new Set(regionLabels.filter(Boolean)))
    .map((label) => `<span class="tool-detail-chip">${escapeHtml(label)}</span>`);
  const links = [];
  if (info?.packageUrl) links.push({ url: info.packageUrl, label: 'npm' });
  if (info?.repositoryUrl) links.push({ url: info.repositoryUrl, label: '代码仓库' });
  if (info?.homepage && info.homepage !== info.repositoryUrl) links.push({ url: info.homepage, label: '官网' });
  if (item?.secondaryAction?.externalUrl) links.push({ url: item.secondaryAction.externalUrl, label: item.secondaryAction.label || '下载' });
  if (item?.tertiaryAction?.externalUrl) links.push({ url: item.tertiaryAction.externalUrl, label: item.tertiaryAction.label || '文档' });
  const unique = [];
  const seen = new Set();
  links.forEach((link) => {
    if (!link.url || seen.has(link.url)) return;
    seen.add(link.url);
    unique.push(link);
  });
  if (!regions.length && !unique.length) return '';
  return `
    <div class="tool-detail-meta-chips">
      ${regions.join('')}
      ${unique.map((link) => `<button type="button" class="tool-detail-chip tool-detail-link" data-external-url="${escapeHtml(link.url)}">${escapeHtml(link.label)}</button>`).join('')}
    </div>
  `;
}

function getToolVersionActionLabel(item, version) {
  const current = normalizeToolVersionText(item?.updateState?.currentVersion || item?.tool?.binary?.version || '');
  const target = normalizeToolVersionText(version);
  if (current && target && compareToolVersions(target, current) === 0) return '当前已安装';
  if (item?.installed && current && target && compareToolVersions(target, current) < 0) return '回滚到此版本';
  return '安装此版本';
}

function formatToolVersionPublishedAt(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';
  const date = new Date(raw);
  if (!Number.isFinite(date.getTime())) return raw;
  return date.toLocaleDateString('zh-CN', { year: 'numeric', month: '2-digit', day: '2-digit' });
}

function getToolVersionNotes(entry, info) {
  const releaseNotes = String(entry?.releaseNotes || entry?.changelog || entry?.notes || '').trim();
  const description = String(entry?.description || info?.description || '').trim();
  return {
    hasReleaseNotes: Boolean(releaseNotes),
    body: releaseNotes || '上游未在 npm 元数据或 GitHub Releases 中提供此版本更新日志。',
    description: releaseNotes ? '' : description,
  };
}

function getToolVersionHistoryInfo(item, info) {
  const toolId = normalizeToolCatalogId(item?.id || info?.toolId || '');
  const liveInfo = info || getToolUpdateInfo(toolId) || {};
  const liveVersions = normalizeToolVersionHistoryEntries(liveInfo?.recentVersions || []);
  if (liveVersions.length) {
    return {
      info: { ...liveInfo, recentVersions: liveVersions },
      versions: liveVersions,
      cached: Boolean(liveInfo.historyFromCache),
      cachedAt: Number(liveInfo.historyCachedAt || 0),
      sourceLabel: liveInfo.historyFromCache
        ? (liveInfo.historySourceLabel || getToolUpdateSourceLabel(liveInfo) || '缓存')
        : (getToolUpdateSourceLabel(liveInfo) || 'npm'),
    };
  }
  const cached = getCachedToolVersionHistory(toolId);
  if (cached?.recentVersions?.length) {
    return {
      info: { ...cached, ...liveInfo, recentVersions: cached.recentVersions },
      versions: cached.recentVersions,
      cached: true,
      cachedAt: Number(cached.cachedAt || 0),
      sourceLabel: cached.sourceLabel || '缓存',
    };
  }
  return {
    info: liveInfo,
    versions: [],
    cached: false,
    cachedAt: 0,
    sourceLabel: getToolUpdateSourceLabel(liveInfo),
  };
}

function getToolVersionHistoryEmptyText(item, info) {
  if (!item || item.kind === 'ide') {
    return '这是官方入口，不读取本地账号配置，也不提供可回滚的 npm 历史版本。';
  }
  if (item.manualOnly) return '此项当前不走 npm 安装链路，因此不提供可回滚的历史版本。';
  if (state.toolUpdatesLoading) return '正在读取 npm 版本历史，稍后会自动刷新。';
  if (state.toolUpdatesError || info?.error) return '版本源暂不可用；一旦成功读取，会自动保留历史版本用于回滚。';
  if (info?.latestVersion) return '当前只读取到最新版本，完整历史会在 metadata 返回后自动补齐。';
  return '还没有可用的版本历史。';
}

function renderToolVersionHistory(item, info) {
  const history = getToolVersionHistoryInfo(item, info);
  const versions = history.versions;
  if (!versions.length) {
    return `<div class="tool-detail-empty">${escapeHtml(getToolVersionHistoryEmptyText(item, history.info))}</div>`;
  }
  const operationActive = isToolOperationActive(getToolOperation(item?.id));
  const sourceCopy = history.cached
    ? `使用上次缓存${history.cachedAt ? ` · ${formatRelativeTime(new Date(history.cachedAt).toISOString())}` : ''}`
    : `${history.sourceLabel || 'npm'} 版本源`;
  return `
    <div class="tool-version-history">
      <div class="tool-version-history-source">
        <span>${escapeHtml(sourceCopy)}</span>
        <em>${escapeHtml(`${versions.length} 个历史版本`)}</em>
      </div>
      ${versions.map((entry) => {
        const version = String(entry.version || '').trim();
        if (!version) return '';
        const at = entry.publishedAt ? formatRelativeTime(entry.publishedAt) : '';
        const expandedKey = `${item.id}@${version}`;
        const expanded = state.toolsVersionExpandedKey === expandedKey;
        const actionLabel = getToolVersionActionLabel(item, version);
        const isCurrent = actionLabel === '当前已安装';
        const publishedAt = formatToolVersionPublishedAt(entry.publishedAt);
        const notes = getToolVersionNotes(entry, history.info);
        const releaseUrl = String(entry.releaseUrl || '').trim();
        const npmUrl = String(entry.npmUrl || '').trim();
        return `
          <div class="tool-version-history-row ${expanded ? 'is-expanded' : ''}">
            <button type="button" class="tool-version-history-toggle" data-tool-version-toggle data-tool-id="${escapeHtml(item.id)}" data-tool-version="${escapeHtml(version)}" aria-expanded="${expanded ? 'true' : 'false'}">
              <strong>${escapeHtml(version)}</strong>
              <span>${escapeHtml(at || entry.publishedAt || '')}</span>
              <i>${expanded ? '收起' : '展开'}</i>
            </button>
            ${expanded ? `
              <div class="tool-version-history-expanded">
                <div class="tool-version-history-copy">
                  <div class="tool-version-history-meta">
                    <span>${escapeHtml(publishedAt ? `发布 ${publishedAt}` : '发布时间未知')}</span>
                    ${releaseUrl ? `<button type="button" class="tool-version-history-link" data-external-url="${escapeHtml(releaseUrl)}">GitHub Release</button>` : ''}
                    ${npmUrl ? `<button type="button" class="tool-version-history-link" data-external-url="${escapeHtml(npmUrl)}">npm 版本页</button>` : ''}
                  </div>
                  <p class="${notes.hasReleaseNotes ? '' : 'is-muted'}">${escapeHtml(notes.body)}</p>
                  ${notes.description ? `<small>${escapeHtml(`包说明：${notes.description}`)}</small>` : ''}
                </div>
                <div class="tool-version-history-actions">
                  <button type="button" class="tool-detail-action is-primary" data-tool-version-action="install-version" data-tool-id="${escapeHtml(item.id)}" data-tool-version="${escapeHtml(version)}" ${isCurrent || operationActive ? 'disabled' : ''}>${escapeHtml(actionLabel)}</button>
                  <button type="button" class="tool-detail-action" data-tool-version-action="install-version-domestic" data-tool-id="${escapeHtml(item.id)}" data-tool-version="${escapeHtml(version)}" ${isCurrent || operationActive ? 'disabled' : ''}>国内镜像</button>
                </div>
              </div>
            ` : ''}
          </div>
        `;
      }).join('')}
    </div>
  `;
}

function updateToolVersionHistoryExpansion(toolId, version) {
  const key = toolId && version ? `${toolId}@${version}` : '';
  if (!key) return false;
  const item = findToolCatalogItemById(toolId);
  const panel = el('toolsDetailPanel');
  const history = panel?.querySelector('.tool-version-history');
  if (!item || !history) return false;
  state.toolsVersionExpandedKey = state.toolsVersionExpandedKey === key ? '' : key;
  const info = item.updateInfo || getToolUpdateInfo(item.id);
  history.outerHTML = renderToolVersionHistory(item, info);
  window.EasyAIConfigI18n?.apply?.(panel.querySelector('.tool-version-history'));
  return true;
}

function renderToolDetailActionButtons(item) {
  if (!item) return '';
  const operationActive = isToolOperationActive(getToolOperation(item.id));
  if (item.kind === 'tool') {
    if (!item.canManage) return '';
    const primaryLabel = item.installed ? '更新' : '安装';
    const domesticLabel = item.installed ? '国内镜像更新' : '国内镜像安装';
    const uninstall = item.installed ? `
      <button type="button" class="tool-detail-action is-danger" data-tool-detail-action="uninstall" data-tool-id="${escapeHtml(item.id)}" ${operationActive ? 'disabled' : ''}>卸载</button>
    ` : '';
    return `
      <div class="tool-detail-actions">
        <button type="button" class="tool-detail-action is-primary" data-tool-detail-action="update" data-tool-id="${escapeHtml(item.id)}" ${operationActive ? 'disabled' : ''}>${escapeHtml(primaryLabel)}</button>
        <button type="button" class="tool-detail-action" data-tool-detail-action="update-domestic" data-tool-id="${escapeHtml(item.id)}" ${operationActive ? 'disabled' : ''}>${escapeHtml(domesticLabel)}</button>
        ${uninstall}
      </div>
    `;
  }
  const actions = [item.primaryAction, item.secondaryAction, item.tertiaryAction].filter(Boolean);
  if (!actions.length) return '';
  return `
	    <div class="tool-detail-actions">
	      ${actions.map((action, index) => {
	        const actionLabel = action.label
	          || (action.action === 'install'
	            ? (item.installed ? '更新' : '安装')
	            : action.action === 'update' || action.action === 'reinstall'
	              ? '更新'
	              : action.action === 'ecosystem-install'
	                ? (item.installed ? '处理' : '安装')
	                : '');
	        if (action.externalUrl) {
	          return `<button type="button" class="tool-detail-action ${index === 0 ? 'is-primary' : ''}" data-external-url="${escapeHtml(action.externalUrl)}">${escapeHtml(actionLabel)}</button>`;
	        }
	        return `<button type="button" class="tool-detail-action ${index === 0 ? 'is-primary' : ''}" data-tool-id="${escapeHtml(action.toolId)}" data-tool-detail-action="${escapeHtml(action.action)}" ${action.ecosystemTarget ? `data-ecosystem-target="${escapeHtml(action.ecosystemTarget)}"` : ''} ${action.disabled || operationActive ? 'disabled' : ''}>${escapeHtml(actionLabel)}</button>`;
	      }).join('')}
	    </div>
	  `;
}

function renderToolDetailPanel(item) {
  if (!item) {
    return `
      <div class="tool-detail-placeholder">
        <strong>选择一个工具</strong>
        <span>版本、更新和历史记录会显示在这里。</span>
      </div>
    `;
  }
  const info = item.updateInfo || getToolUpdateInfo(item.id);
  const manualEntry = Boolean(item.manualOnly || item.kind === 'ide');
  const currentVersion = normalizeToolVersionText(item.updateState?.currentVersion || item.tool?.binary?.version || '');
  const latestVersion = item.updateState?.latestVersion || info?.latestVersion || '';
  const sourceLabel = item.id === 'codex-app'
    ? '官方安装源'
    : manualEntry
      ? '官方入口'
    : getToolUpdateSourceLabel(info) || (state.toolUpdatesLoading ? '检查中' : state.toolUpdatesError ? '版本源暂不可用' : '版本源');
  const regions = (info?.regions || item.tags || [])
    .filter((tag) => tag === 'global' || tag === 'domestic')
    .map((tag) => tag === 'global' ? '海外源' : tag === 'domestic' ? '国内镜像' : (TOOL_UPDATE_REGION_LABELS[tag] || tag));
  const regionLabels = Array.from(new Set(regions));
  const summaryRows = manualEntry
    ? [
      { label: '能力范围', value: item.kind === 'ide' ? '官方下载安装' : item.supportStage === 'extension' ? '扩展入口' : item.supportStage === 'catalog' ? '配置入口' : '状态检测' },
      { label: '安装方式', value: item.kind === 'ide' ? '官网/市场' : item.supportStage === 'extension' ? '扩展市场' : '手动入口' },
      { label: '配置支持', value: item.supportStage === 'extension' || item.supportStage === 'catalog' ? '读取/导入' : '不自动写入' },
    ]
    : item.id === 'codex-app'
    ? [
      { label: '当前版本', value: currentVersion || (item.installed ? '已安装' : '未安装') },
      { label: '安装源', value: sourceLabel },
      { label: '更新方式', value: item.installed ? '更新' : '安装' },
    ]
    : [
      { label: '当前版本', value: currentVersion || (item.installed ? '待检测' : '未安装') },
      { label: '最新版本', value: latestVersion || (state.toolUpdatesLoading ? '检查中' : state.toolUpdatesError ? '可重试' : '暂无') },
      { label: '更新来源', value: sourceLabel },
    ];
  const manualDetailText = item.kind === 'ide'
    ? '此项打开官方下载页或插件市场；安装后的账号、密钥和 IDE 内部设置仍由对应工具自己管理。'
    : item.supportStage === 'extension' || item.supportStage === 'catalog'
      ? '此项用于识别扩展/IDE 相关资产并提供导入入口；账号密钥仍走对应工具自己的安全存储。'
      : '此项当前不提供自动安装按钮；页面只展示检测状态，账号、密钥和内部设置仍由对应工具自己管理。';
  const detailSection = manualEntry
    ? `
      <div class="tool-detail-section">
        <div class="tool-detail-section-head">
          <h4>${escapeHtml(item.kind === 'ide' ? '安装入口' : '管理方式')}</h4>
          <span>手动</span>
        </div>
        <div class="tool-detail-empty">${escapeHtml(manualDetailText)}</div>
      </div>
    `
    : `
      <div class="tool-detail-section">
        <div class="tool-detail-section-head">
          <h4>版本历史</h4>
          <span>${escapeHtml(info?.packageName || item.tool?.npmPackage || '')}</span>
        </div>
        ${renderToolVersionHistory(item, info)}
      </div>
    `;
  return `
    <div class="tool-detail-page">
      <div class="tool-detail-head">
        <div class="tool-icon tool-icon-${escapeHtml(item.iconId)}">${toolIconSvg(item.iconId)}</div>
        <div>
          <span>${escapeHtml(item.typeLabel || 'Tools')}</span>
          <strong>${escapeHtml(item.name)}</strong>
          <em>${escapeHtml(item.description || '')}</em>
        </div>
        <button type="button" class="tool-detail-close" data-tools-detail-close aria-label="关闭详情">×</button>
      </div>
      ${renderToolDetailMetaChips(item, info, regionLabels)}
      <div class="tool-detail-summary">
        ${summaryRows.map((row) => `<div><span>${escapeHtml(row.label)}</span><strong>${escapeHtml(row.value)}</strong></div>`).join('')}
      </div>
      ${renderToolOperationProgress(item, { detail: true })}
      ${renderToolDetailActionButtons(item)}
      ${detailSection}
      ${!manualEntry && info?.error ? `<div class="tool-detail-empty is-error">版本源暂不可用</div>` : ''}
    </div>
  `;
}

function renderToolsDetailPanel(items = getToolCatalogItems()) {
  const panel = el('toolsDetailPanel');
  const content = el('toolsContent');
  if (!panel || !content) return;
  const selected = state.toolsCatalogDetailId
    ? (items.find((item) => item.id === state.toolsCatalogDetailId) || findToolCatalogItemById(state.toolsCatalogDetailId))
    : null;
  content.classList.toggle('is-detail-open', Boolean(selected));
  panel.classList.toggle('is-open', Boolean(selected));
  panel.innerHTML = renderToolDetailPanel(selected);
  window.EasyAIConfigI18n?.apply?.(panel);
}

function openToolCatalogDetail(itemOrId) {
  const item = typeof itemOrId === 'string' ? findToolCatalogItemById(itemOrId) : itemOrId;
  if (!item) return;
  if (state.toolsCatalogDetailId !== item.id) state.toolsVersionExpandedKey = '';
  state.toolsCatalogDetailId = item.id;
  if (item.kind === 'tool' && state.toolUpdatesAutoCheck && !getToolUpdateInfo(item.id) && !state.toolUpdatesLoading) {
    void loadToolUpdates({ force: false, render: true });
  }
  renderToolsPage();
}

function renderToolsUpdateStrip() {
  const wrap = el('toolsUpdateStrip');
  if (!wrap) return;
  const fetchedAt = Number(state.toolUpdatesFetchedAt || 0);
  const latestCount = Object.values(state.toolUpdates?.items || {}).filter((item) => item?.latestVersion).length;
  const label = state.toolUpdatesLoading
    ? '正在检查版本'
    : state.toolUpdatesError
      ? '检查失败'
      : fetchedAt
        ? `已检查 ${formatRelativeTime(new Date(fetchedAt).toISOString())}`
        : '可检查更新';
  const detail = state.toolUpdatesError
    ? '稍后再试'
    : latestCount
      ? `${latestCount} 个工具有版本源`
      : state.toolUpdatesAutoCheck
        ? '自动检测已开启'
        : '自动检测已关闭';
  wrap.innerHTML = `
    <div class="tools-update-copy">
      <span>${escapeHtml(label)}</span>
      <em>${escapeHtml(detail)}</em>
    </div>
    <div class="tools-update-actions">
      <label class="tools-update-toggle" title="自动检测更新">
        <input type="checkbox" id="toolsUpdateAutoCheckToggle" ${state.toolUpdatesAutoCheck ? 'checked' : ''}>
        <span class="tools-update-toggle-text">自动检测</span>
        <span class="tools-update-switch" aria-hidden="true"></span>
      </label>
      <button type="button" class="tools-update-btn" id="toolsUpdateRefreshBtn" ${state.toolUpdatesLoading ? 'disabled' : ''}>
        ${state.toolUpdatesLoading ? '检查中' : '检查更新'}
      </button>
    </div>
  `;
  const toggle = el('toolsUpdateAutoCheckToggle');
  if (toggle && !toggle._bound) {
    toggle._bound = true;
    toggle.addEventListener('change', () => {
      setToolUpdatesAutoCheck(toggle.checked);
    });
  }
  const btn = el('toolsUpdateRefreshBtn');
  if (btn && !btn._bound) {
    btn._bound = true;
    btn.addEventListener('click', () => {
      void loadToolUpdates({ force: true, render: true });
    });
  }
}

function bindToolsCatalogControls() {
  const searchInput = el('toolsCatalogSearchInput');
  if (searchInput && !searchInput._bound) {
    searchInput._bound = true;
    searchInput.addEventListener('input', () => {
      state.toolsCatalogQuery = searchInput.value || '';
      state.toolsCatalogPage = 1;
      renderToolsPage();
    });
  }
  const tagWrap = el('toolsCatalogTags');
  if (tagWrap && !tagWrap._bound) {
    tagWrap._bound = true;
    tagWrap.addEventListener('click', (event) => {
      const button = event.target.closest('[data-tools-tag]');
      if (!button) return;
      state.toolsCatalogTag = button.dataset.toolsTag || 'all';
      state.toolsCatalogPage = 1;
      renderToolsPage();
    });
  }
  const detailPanel = el('toolsDetailPanel');
  if (detailPanel && !detailPanel._bound) {
    detailPanel._bound = true;
    detailPanel.addEventListener('click', (event) => {
      const closeBtn = event.target.closest('[data-tools-detail-close]');
      if (closeBtn) {
        state.toolsCatalogDetailId = '';
        state.toolsVersionExpandedKey = '';
        renderToolsPage();
        return;
      }
      const external = event.target.closest('[data-external-url]');
      if (external) {
        void openExternalUrl(external.getAttribute('data-external-url') || '');
        return;
      }
      const actionBtn = event.target.closest('[data-tool-detail-action]');
      if (actionBtn) {
        handleToolAction(
          actionBtn.getAttribute('data-tool-id') || '',
          actionBtn.getAttribute('data-tool-detail-action') || '',
          actionBtn,
        );
        return;
      }
      const versionActionBtn = event.target.closest('[data-tool-version-action]');
      if (versionActionBtn) {
        handleToolAction(
          versionActionBtn.getAttribute('data-tool-id') || '',
          versionActionBtn.getAttribute('data-tool-version-action') || '',
          versionActionBtn,
        );
        return;
      }
      const versionToggle = event.target.closest('[data-tool-version-toggle]');
      if (versionToggle) {
        const toolId = versionToggle.getAttribute('data-tool-id') || '';
        const version = versionToggle.getAttribute('data-tool-version') || '';
        updateToolVersionHistoryExpansion(toolId, version);
      }
    });
  }
}

function renderToolsPage() {
  const grid = document.querySelector('.tools-page .tools-grid');
  const page = document.querySelector('.tools-page');
  renderToolsSecondaryPanel();
  renderToolsUpdateStrip();
  if (!grid || !state.tools.length) return;
  bindToolsCatalogControls();

  const actionSvgs = {
    update: '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M21 12a9 9 0 0 1-15.36 6.36L3 21M3 12a9 9 0 0 1 15.36-6.36L21 3" /></svg>',
    reinstall: '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M2.5 2v6h6" /><path d="M2.5 8A10 10 0 1 1 4.34 16" /></svg>',
    uninstall: '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M3 6h18M8 6V4h8v2M19 6l-1 14H6L5 6" /><line x1="10" y1="11" x2="10" y2="17" /><line x1="14" y1="11" x2="14" y2="17" /></svg>',
  };

  const allItems = getToolCatalogItems();
  const selectedDetail = state.toolsCatalogDetailId
    ? (allItems.find((item) => item.id === state.toolsCatalogDetailId) || findToolCatalogItemById(state.toolsCatalogDetailId))
    : null;
  const detailOpen = Boolean(selectedDetail);
  page?.classList.toggle('is-detail-mode', detailOpen);

  if (detailOpen) {
    grid.innerHTML = '';
    renderToolsDetailPanel(allItems);
    el('toolsCatalogEmpty')?.classList.add('hide');
    el('toolsCatalogPagination')?.classList.add('hide');
    requestAnimationFrame(() => {
      window.EasyAIConfigI18n?.apply?.(document.querySelector('.tools-page'));
      window.EasyAIConfigI18n?.apply?.(el('secondaryBody'));
    });
    return;
  }

  const items = filterToolCatalogItems(allItems);
  const searchInput = el('toolsCatalogSearchInput');
  if (searchInput && searchInput.value !== state.toolsCatalogQuery) searchInput.value = state.toolsCatalogQuery;
  document.querySelectorAll('[data-tools-tag]').forEach((node) => {
    node.classList.toggle('active', node.dataset.toolsTag === getToolsCatalogTag());
  });

  state.toolsCatalogPage = 1;
  grid.innerHTML = items.map((item) => renderToolCatalogCard(item, actionSvgs)).join('');
  renderToolsDetailPanel(allItems);
  el('toolsCatalogEmpty')?.classList.toggle('hide', items.length > 0);
  const pagination = el('toolsCatalogPagination');
  const prevBtn = el('toolsCatalogPrevBtn');
  const nextBtn = el('toolsCatalogNextBtn');
  const pageMeta = el('toolsCatalogPageMeta');
  if (pagination) pagination.classList.add('hide');
  if (prevBtn) prevBtn.disabled = true;
  if (nextBtn) nextBtn.disabled = true;
  if (pageMeta) pageMeta.textContent = `共 ${items.length} 项`;

  if (pagination && !pagination._bound) {
    pagination._bound = true;
    prevBtn?.addEventListener('click', () => {
      if (state.toolsCatalogPage <= 1) return;
      state.toolsCatalogPage -= 1;
      renderToolsPage();
    });
    nextBtn?.addEventListener('click', () => {
      state.toolsCatalogPage += 1;
      renderToolsPage();
    });
  }

  if (!grid._toolsBound) {
    grid._toolsBound = true;
    grid.addEventListener('click', (e) => {
      const linkBtn = e.target.closest('[data-external-url]');
      if (linkBtn) {
        void openExternalUrl(linkBtn.dataset.externalUrl || '');
        return;
      }
      const detailBtn = e.target.closest('[data-tool-detail]');
      if (detailBtn) {
        void openToolCatalogDetail(detailBtn.dataset.toolDetail || '');
        return;
      }
      const btn = e.target.closest('[data-tool-action]');
      if (btn) {
        handleToolAction(btn.dataset.toolId, btn.dataset.toolAction, btn);
        return;
      }
      const card = e.target.closest('.tool-card[data-tool-id]');
      if (card) void openToolCatalogDetail(card.dataset.toolId || '');
    });
  }
  requestAnimationFrame(() => {
    window.EasyAIConfigI18n?.apply?.(document.querySelector('.tools-page'));
    window.EasyAIConfigI18n?.apply?.(el('secondaryBody'));
  });
}

async function runSimpleToolOperation(toolId, config, btn) {
  const toolName = config.toolName || toolId;
  const taskName = config.taskName || `${toolName} 操作`;
  const taskId = addTask(taskName, {
    progress: 8,
    message: '准备执行',
  });
  setToolBtnBusy(btn, true, config.busyText);
  setToolOperation(toolId, {
    action: config.action || '',
    status: 'running',
    progress: 8,
    stepTitle: '准备',
    summary: config.startText || '正在准备操作',
    detail: '正在检查当前状态',
  });
  const stopTicker = startToolOperationTicker(toolId, 82);

  try {
    await sleep(120);
    setToolOperation(toolId, {
      progress: 22,
      stepTitle: '执行',
      summary: config.executeText || config.busyText || '正在执行命令',
      detail: '请保持应用打开',
    });
    updateTask(taskId, { progress: 22, message: config.executeText || config.busyText || '正在执行命令' });

    const requestOptions = { method: 'POST' };
    if (config.body !== undefined) {
      requestOptions.headers = { 'Content-Type': 'application/json' };
      requestOptions.body = JSON.stringify(config.body);
    }
    const json = await api(config.api, requestOptions);
    if (!json.ok) {
      throw new Error(json.error || `${toolName} 操作失败`);
    }

    stopTicker();
    setToolOperation(toolId, {
      progress: 88,
      stepTitle: '验证',
      summary: '正在刷新工具状态',
      detail: '确认版本和安装状态',
    });
    updateTask(taskId, { progress: 88, message: '正在刷新工具状态' });
    await refreshToolRuntimeAfterMutation(toolId);

    setToolOperation(toolId, {
      status: 'success',
      progress: 100,
      stepTitle: '完成',
      summary: config.successText,
      detail: '状态已刷新',
    }, { keepCompletedMs: 9000 });
    updateTask(taskId, { status: 'done', progress: 100, message: config.successText });
    flash(config.successText, 'success');
    return { ok: true, data: json.data };
  } catch (error) {
    stopTicker();
    const message = error?.message || `${toolName} 操作失败`;
    setToolOperation(toolId, {
      status: 'error',
      progress: 100,
      stepTitle: '失败',
      summary: `${toolName} 操作失败`,
      detail: message,
      error: message,
    }, { keepCompletedMs: 12000 });
    updateTask(taskId, { status: 'error', progress: 100, message });
    flash(message, 'error');
    return { ok: false, error: message };
  } finally {
    stopTicker();
    setToolBtnBusy(btn, false);
  }
}

function getToolVersionActionConfig({ toolId, action, btn, toolName, apiPrefix }) {
  if (!['install-version', 'install-version-domestic'].includes(action)) return null;
  const version = normalizeToolVersionText(btn?.getAttribute?.('data-tool-version') || btn?.dataset?.toolVersion || '');
  if (!version) {
    flash('缺少目标版本', 'error');
    return null;
  }
  const domestic = action === 'install-version-domestic';
  const item = findToolCatalogItemById(toolId);
  const currentVersion = normalizeToolVersionText(item?.updateState?.currentVersion || item?.tool?.binary?.version || '');
  const rollback = Boolean(item?.installed && currentVersion && compareToolVersions(version, currentVersion) < 0);
  const verb = rollback ? '回滚' : '安装';
  const sourceText = domestic ? '国内镜像' : 'npm';
  return {
    api: `/api/${apiPrefix}/${domestic ? 'install-version-domestic' : 'install-version'}`,
    body: { version },
    busyText: `${verb}中…`,
    successText: `${toolName} 已${verb}到 ${version}`,
    startText: `正在准备${sourceText}${verb} ${toolName} ${version}`,
    executeText: `正在通过${sourceText}${verb} ${toolName} ${version}`,
    confirm: null,
    taskName: `${toolName} ${verb} ${version}`,
  };
}

// Generic tool action handler
async function handleToolAction(toolId, action, btn) {
  const toolNames = { codex: 'Codex', claudecode: 'Claude Code', gemini: 'Gemini CLI', 'qwen-code': 'Qwen Code CLI', 'codebuddy-code': 'CodeBuddy Code CLI', opencode: 'OpenCode', 'codex-app': 'Codex App', 'opencode-desktop': 'OpenCode Desktop', openclaw: 'OpenClaw' };
  const toolName = toolNames[toolId] || toolId;

  const apiPrefixMap = { codex: 'codex', claudecode: 'claudecode', gemini: 'gemini', 'qwen-code': 'qwen-code', 'codebuddy-code': 'codebuddy-code', opencode: 'opencode', openclaw: 'openclaw' };
  const apiPrefix = apiPrefixMap[toolId] || toolId;

  const versionConfig = getToolVersionActionConfig({ toolId, action, btn, toolName, apiPrefix });
  if (versionConfig) {
    await runSimpleToolOperation(toolId, { ...versionConfig, action, toolName }, btn);
    return;
  }

  if (toolId === 'openclaw' && action === 'update') {
    await openClawInstallMethodDialog(btn);
    return;
  }

  if (toolId === 'openclaw' && action === 'uninstall') {
    await openClawUninstallDialog(btn);
    return;
  }

  if (action === 'ecosystem-install') {
    const target = btn?.dataset?.ecosystemTarget || toolId.replace('opencode-', '');
    setToolBtnBusy(btn, true, '处理中…');
    setToolOperation(toolId, {
      action,
      status: 'running',
      progress: 12,
      stepTitle: '准备',
      summary: '正在处理集成项',
      detail: '正在检查本机环境',
    });
    const stopTicker = startToolOperationTicker(toolId, 82);
    try {
      const cwd = el('launchCwdInput')?.value?.trim() || state.current?.launch?.cwd || '';
      setToolOperation(toolId, {
        progress: 30,
        stepTitle: '执行',
        summary: '正在写入或安装集成',
        detail: '完成后会刷新状态',
      });
      const json = await api('/api/opencode/ecosystem/install', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ target, cwd }),
      });
      if (!json.ok) {
        throw new Error(json.error || 'OpenCode 生态项处理失败');
      }
      stopTicker();
      setToolOperation(toolId, {
        progress: 88,
        stepTitle: '验证',
        summary: '正在刷新集成状态',
        detail: '确认配置是否生效',
      });
      await loadOpenCodeEcosystemState({ render: false });
      setToolOperation(toolId, {
        status: 'success',
        progress: 100,
        stepTitle: '完成',
        summary: json.data?.message || 'OpenCode 生态项已处理',
        detail: '状态已刷新',
      }, { keepCompletedMs: 9000 });
      flash(json.data?.message || 'OpenCode 生态项已处理', 'success');
      if (state.activePage === 'tools') renderToolsPage();
    } catch (error) {
      stopTicker();
      const message = error?.message || 'OpenCode 生态项处理失败';
      setToolOperation(toolId, {
        status: 'error',
        progress: 100,
        stepTitle: '失败',
        summary: 'OpenCode 生态项处理失败',
        detail: message,
        error: message,
      }, { keepCompletedMs: 12000 });
      flash(message, 'error');
    } finally {
      stopTicker();
      setToolBtnBusy(btn, false);
    }
    return;
  }

  if (toolId === 'opencode-desktop') {
    if (action === 'install') {
      await runOpenCodeDesktopInstallAction(btn, { reinstall: false });
      return;
    }
    if (action === 'update') {
      await runOpenCodeDesktopInstallAction(btn, { update: true });
      return;
    }
    if (action === 'reinstall') {
      await runOpenCodeDesktopInstallAction(btn, { reinstall: true });
      return;
    }
    if (action === 'open') {
      setToolBtnBusy(btn, true, '打开中…');
      try {
        const json = await api('/api/opencode/desktop/open', { method: 'POST' });
        if (!json.ok) {
          flash(json.error || '打开 OpenCode Desktop 失败', 'error');
          return;
        }
        flash('OpenCode Desktop 已打开', 'success');
        await loadOpenCodeDesktopState({ render: state.activePage === 'tools' });
      } catch (error) {
        flash(error?.message || '打开 OpenCode Desktop 失败', 'error');
      } finally {
        setToolBtnBusy(btn, false);
      }
      return;
    }
  }

  if (toolId === 'codex-app') {
    if (action === 'install' || action === 'update' || action === 'reinstall') {
      await runCodexAppInstallAction(btn, { update: action === 'update', reinstall: action === 'reinstall' });
      return;
    }
    if (action === 'open') {
      setToolBtnBusy(btn, true, '打开中…');
      try {
        const json = await api('/api/codex-app/open', { method: 'POST' });
        if (!json.ok) {
          flash(json.error || '打开 Codex App 失败', 'error');
          return;
        }
        flash(json.data?.message || 'Codex App 已打开', 'success');
        await loadCodexAppState({ render: state.activePage === 'tools' });
      } catch (error) {
        flash(error?.message || '打开 Codex App 失败', 'error');
      } finally {
        setToolBtnBusy(btn, false);
      }
      return;
    }
  }

  if (toolId === 'opencode' && action === 'update-domestic') {
    await runOpenCodeToolAction('update', btn, { method: 'domestic' });
    return;
  }

  if (toolId === 'opencode' && ['update', 'reinstall', 'uninstall'].includes(action)) {
    await runOpenCodeToolAction(action, btn);
    return;
  }

  const actionConfig = {
    update: {
      api: `/api/${apiPrefix}/update`,
      busyText: '更新中…',
      successText: `${toolName} 已更新到最新版`,
      startText: `正在准备更新 ${toolName}`,
      executeText: `正在更新 ${toolName}`,
      confirm: null,
    },
    'update-domestic': {
      api: `/api/${apiPrefix}/update-domestic`,
      busyText: '更新中…',
      successText: `${toolName} 已通过国内镜像更新`,
      startText: `正在准备国内镜像更新 ${toolName}`,
      executeText: `正在通过国内镜像更新 ${toolName}`,
      confirm: null,
    },
    reinstall: {
      api: `/api/${apiPrefix}/reinstall`,
      busyText: '重装中…',
      successText: `${toolName} 重装完成`,
      startText: `正在准备重装 ${toolName}`,
      executeText: `正在重装 ${toolName}`,
      confirm: {
        eyebrow: toolName,
        title: `重装 ${toolName}`,
        body: `<p>这会重新全局安装当前版本 ${toolName}。</p>`,
        confirmText: '确认重装',
        cancelText: '取消',
      },
    },
    uninstall: {
      api: `/api/${apiPrefix}/uninstall`,
      busyText: '卸载中…',
      successText: `${toolName} 已卸载`,
      startText: `正在准备卸载 ${toolName}`,
      executeText: `正在卸载 ${toolName}`,
      confirm: {
        eyebrow: toolName,
        title: `卸载 ${toolName}`,
        body: `<p>卸载后将无法直接从工具里启动 ${toolName}。</p>`,
        confirmText: '确认卸载',
        cancelText: '取消',
        tone: 'danger',
      },
    },
  };

  const config = actionConfig[action];
  if (!config) return;

  if (config.confirm) {
    const confirmed = await openUpdateDialog(config.confirm);
    if (!confirmed) {
      flash('操作已取消', 'info');
      return;
    }
  }

  await runSimpleToolOperation(toolId, { ...config, action, toolName, taskName: `${toolName} ${config.successText.includes('卸载') ? '卸载' : config.successText.includes('重装') ? '重装' : '更新'}` }, btn);
}
const SPINNER_SVG = '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 12a9 9 0 1 1-6.22-8.56" /></svg>';

function setToolBtnBusy(btn, busy, text) {
  if (!btn) return;
  if (busy) {
    btn._origHTML = btn.innerHTML;
    btn.innerHTML = `${SPINNER_SVG}<span>${text || '处理中…'}</span>`;
    btn.classList.add('tool-btn-busy');
    btn.disabled = true;
  } else {
    if (btn._origHTML) btn.innerHTML = btn._origHTML;
    btn.classList.remove('tool-btn-busy');
    btn.disabled = false;
  }
}

function getOpenCodeActionCopy(action, installedBefore = false) {
  if (action === 'desktop-install') {
    return installedBefore
      ? { busy: '更新中…', title: '正在更新 OpenCode Desktop', done: 'OpenCode Desktop 已更新完成' }
      : { busy: '安装中…', title: '正在安装 OpenCode Desktop', done: 'OpenCode Desktop 安装完成' };
  }
  if (action === 'install') {
    return { busy: '安装中…', title: '正在安装 OpenCode', done: 'OpenCode 安装完成' };
  }
  if (action === 'update') {
    return installedBefore
      ? { busy: '更新中…', title: '正在更新 OpenCode', done: 'OpenCode 已更新到最新版' }
      : { busy: '安装中…', title: '正在安装 OpenCode', done: 'OpenCode 安装完成' };
  }
  if (action === 'reinstall') {
    return { busy: '重装中…', title: '正在重装 OpenCode', done: 'OpenCode 重装完成' };
  }
  return { busy: '卸载中…', title: '正在卸载 OpenCode', done: 'OpenCode 已卸载' };
}

function getOpenCodeMethodLabel(method = '') {
  return ({
    auto: '自动检测',
    domestic: '国内 npm 镜像',
    script: '官方安装脚本',
    npm: 'npm 官方源',
    brew: 'Homebrew',
    scoop: 'Scoop',
    choco: 'Chocolatey',
  }[method] || method || '自动检测');
}

function getOpenCodeRequestedMethodLabel(method = '') {
  return method ? getOpenCodeMethodLabel(method) : '自动检测';
}

function getOpenCodeCommandPreview(action, requestedMethod = '') {
  if (action === 'desktop-install') {
    const isWin = navigator.platform?.startsWith('Win');
    return isWin
      ? ['内置下载器 → 官方 Windows 安装包', '下载完成后自动拉起安装器，尽量直接完成安装']
      : ['内置下载器 → 官方 macOS DMG', '下载完成后自动挂载并安装到 Applications'];
  }
  const isWin = navigator.platform?.startsWith('Win');
  const requested = requestedMethod || 'auto';
  const installMap = isWin
    ? {
      auto: ['Google 可达 → npm i -g opencode-ai@latest', 'Google 不可达 → npm i -g opencode-ai@latest --registry=https://registry.npmmirror.com'],
      domestic: ['npm i -g opencode-ai@latest --registry=https://registry.npmmirror.com'],
      npm: ['npm i -g opencode-ai@latest'],
      scoop: ['scoop install opencode'],
      choco: ['choco install opencode -y'],
    }
    : {
      auto: ['Google 可达 → curl -fsSL https://opencode.ai/install | bash', 'Google 不可达 → npm i -g opencode-ai@latest --registry=https://registry.npmmirror.com'],
      domestic: ['npm i -g opencode-ai@latest --registry=https://registry.npmmirror.com'],
      script: ['curl -fsSL https://opencode.ai/install | bash'],
      brew: ['brew install anomalyco/tap/opencode'],
      npm: ['npm i -g opencode-ai@latest'],
    };
  const uninstallMap = isWin
    ? {
      domestic: ['npm uninstall -g opencode-ai'],
      npm: ['npm uninstall -g opencode-ai'],
      scoop: ['scoop uninstall opencode'],
      choco: ['choco uninstall opencode -y'],
      auto: ['根据当前安装方式自动选择卸载命令'],
    }
    : {
      domestic: ['npm uninstall -g opencode-ai'],
      npm: ['npm uninstall -g opencode-ai'],
      script: ['rm -f <opencode-binary>'],
      brew: ['brew uninstall anomalyco/tap/opencode'],
      auto: ['根据当前安装方式自动选择卸载命令'],
    };
  const baseMap = action === 'uninstall' ? uninstallMap : installMap;
  return baseMap[requested] || baseMap.auto || [];
}

function createOpenCodeTracker(action, { installedBefore = false, requestedMethod = '' } = {}) {
  const copy = getOpenCodeActionCopy(action, installedBefore);
  const startedAt = new Date().toISOString();
  const uninstall = action === 'uninstall';
  const desktopInstall = action === 'desktop-install';
  const steps = desktopInstall
    ? [
      { key: 'inspect', title: '检查系统环境', description: '识别系统、架构与桌面版状态', status: 'running' },
      { key: 'download', title: '下载桌面安装器', description: '通过内置下载器拉取官方桌面版安装包', status: 'pending' },
      { key: 'install', title: '自动安装并启动', description: '自动安装 OpenCode Desktop 并尝试直接打开', status: 'pending' },
    ]
    : uninstall
      ? [
        { key: 'inspect', title: '检查当前安装', description: '确认当前 OpenCode 安装状态', status: 'running' },
        { key: 'remove', title: '执行卸载命令', description: '移除全局 OpenCode 命令与包', status: 'pending' },
        { key: 'verify', title: '验证卸载结果', description: '刷新工具状态并确认结果', status: 'pending' },
      ]
      : [
        { key: 'network', title: '检测网络环境', description: '检测 Google 可达性与当前网络情况', status: 'running' },
        { key: 'method', title: '确定安装方式', description: '根据网络和你的选择确认最终安装方案', status: 'pending' },
        { key: 'execute', title: '执行安装命令', description: '运行安装命令并等待依赖安装完成', status: 'pending' },
        { key: 'verify', title: '验证安装结果', description: '确认 opencode 命令已经可用', status: 'pending' },
      ];
  return {
    toolId: desktopInstall ? 'opencode-desktop' : 'opencode',
    action,
    installedBefore,
    requestedMethod,
    method: '',
    command: '',
    commandPreview: getOpenCodeCommandPreview(action, requestedMethod),
    googleReachable: null,
    usedDomesticMirror: null,
    status: 'running',
    progress: desktopInstall ? 10 : uninstall ? 10 : 8,
    stepIndex: 0,
    summary: desktopInstall ? copy.title : uninstall ? '正在检查当前 OpenCode 安装状态…' : '正在检测网络并准备安装 OpenCode…',
    hint: desktopInstall ? '会自动下载官方桌面版，不需要你自己找安装包。' : uninstall ? '先别关闭窗口，卸载完成后会自动刷新。' : '安装过程会自动继续，你现在不需要操作。',
    detail: desktopInstall ? '正在检查桌面版系统环境…' : uninstall ? '正在确认当前安装路径…' : '正在准备安装器…',
    steps,
    logs: [{ source: 'stdout', text: `${copy.title} 已开始`, at: startedAt }],
    startedAt,
    startedAtTs: Date.now(),
    completedAt: null,
    stdout: '',
    stderr: '',
    error: null,
    version: '',
    _markers: {},
  };
}

function stripAnsiControlText(text) {
  return String(text || '')
    .replace(/[\x1B\x9B][[\]()#;?]*(?:(?:[0-9]{1,4}(?:;[0-9]{0,4})*)?[0-9A-ORZcf-ntqry=><~]|(?:].*?(?:\x07|\x1B\\)))/g, '')
    .replace(/\r/g, '')
    .trim();
}

function pushOpenCodeTrackerLog(task, source, text) {
  const cleaned = stripAnsiControlText(text);
  if (!cleaned) return;
  task.logs.push({ source, text: cleaned, at: new Date().toISOString() });
  if (task.logs.length > 120) task.logs.shift();
  task.detail = cleaned;
}

function setOpenCodeTrackerStep(task, stepIndex, overrides = {}) {
  const safeIndex = Math.max(0, Math.min(stepIndex, (task.steps || []).length - 1));
  if (safeIndex < task.stepIndex && task.status === 'running') return;
  task.stepIndex = safeIndex;
  task.progress = Math.max(task.progress || 0, overrides.progress || [18, 36, 82, 96][safeIndex] || task.progress || 0);
  if (overrides.summary) task.summary = overrides.summary;
  if (overrides.hint) task.hint = overrides.hint;
  if (overrides.detail) task.detail = overrides.detail;
  task.steps = task.steps.map((step, index) => ({
    ...step,
    status: index < safeIndex ? 'done' : index === safeIndex ? (overrides.status || 'running') : 'pending',
  }));
}

function updateOpenCodeTrackerHeartbeat(task) {
  if (!task || task.status !== 'running') return;
  const elapsed = Date.now() - Number(task.startedAtTs || Date.now());
  if (task.action === 'uninstall') {
    if (!task._markers.inspectLog && elapsed > 280) {
      task._markers.inspectLog = true;
      pushOpenCodeTrackerLog(task, 'stdout', '正在读取当前 OpenCode 安装状态…');
    }
    if (!task._markers.removeStep && elapsed > 900) {
      task._markers.removeStep = true;
      setOpenCodeTrackerStep(task, 1, {
        progress: 34,
        summary: '正在执行卸载命令…',
        hint: '卸载完成后会自动刷新工具状态。',
        detail: '正在移除 OpenCode 安装文件…',
      });
      pushOpenCodeTrackerLog(task, 'stdout', '开始执行卸载命令…');
    }
    if (task.stepIndex === 1) {
      task.progress = Math.max(task.progress, Math.min(88, 34 + Math.floor(Math.max(0, elapsed - 900) / 450) * 4));
    }
    return;
  }

  if (!task._markers.networkLog && elapsed > 300) {
    task._markers.networkLog = true;
    pushOpenCodeTrackerLog(task, 'stdout', '正在检测当前网络连通性…');
  }
  if (!task._markers.awaitInstallerResultLog && elapsed > 620) {
    task._markers.awaitInstallerResultLog = true;
    pushOpenCodeTrackerLog(task, 'stdout', task.commandPreview?.length
      ? 'Google 可达性与实际执行命令会在安装器返回后确认，当前先展示候选命令。'
      : 'Google 可达性与实际执行命令会在安装器返回后确认。');
  }
  if (!task._markers.methodStep && elapsed > 900) {
    task._markers.methodStep = true;
    setOpenCodeTrackerStep(task, 1, {
      progress: 26,
      summary: '正在确定 OpenCode 安装方式…',
      hint: '会优先选择最快、最稳定的安装方式。',
      detail: task.requestedMethod ? `已收到安装方式：${getOpenCodeRequestedMethodLabel(task.requestedMethod)}` : '正在根据网络自动选择安装方式…',
    });
    pushOpenCodeTrackerLog(task, 'stdout', task.requestedMethod
      ? `用户选择安装方式：${getOpenCodeRequestedMethodLabel(task.requestedMethod)}`
      : '未指定安装方式，将自动选择最合适的安装方案。');
  }
  if (!task._markers.executeStep && elapsed > 1700) {
    task._markers.executeStep = true;
    setOpenCodeTrackerStep(task, 2, {
      progress: 42,
      summary: '正在执行 OpenCode 安装命令…',
      hint: '这里通常耗时最长，期间没有新日志也正常。',
      detail: task.commandPreview?.length ? '正在安装依赖并写入全局命令…候选命令见下方日志。' : '正在安装依赖并写入全局命令…',
    });
    pushOpenCodeTrackerLog(task, 'stdout', task.command
      ? `安装命令已启动：${task.command}`
      : task.commandPreview?.length
        ? '安装命令已启动，实际执行命令等待安装器返回；候选命令见上。'
        : '安装命令已启动，正在等待依赖安装完成…');
  }
  if (task.stepIndex === 2) {
    task.progress = Math.max(task.progress, Math.min(90, 42 + Math.floor(Math.max(0, elapsed - 1700) / 550) * 4));
  }
}

function getOpenCodeTrackerLogsText(task) {
  return (task.logs || []).map((item) => {
    const time = item.at ? new Date(item.at).toLocaleTimeString() : '--:--:--';
    return `[${time}] ${item.source === 'stderr' ? 'ERR' : 'LOG'} ${item.text}`;
  }).join('\n') || '安装日志会显示在这里。';
}

function buildOpenCodeTrackerRenderKey(task) {
  return JSON.stringify({
    status: task.status,
    progress: task.progress,
    stepIndex: task.stepIndex,
    summary: task.summary,
    hint: task.hint,
    detail: task.detail,
    error: task.error,
    version: task.version,
    method: task.method,
    command: task.command,
    googleReachable: task.googleReachable,
    usedDomesticMirror: task.usedDomesticMirror,
    steps: (task.steps || []).map((step) => `${step.key}:${step.status}`).join('|'),
    logs: (task.logs || []).map((item) => `${item.source}:${item.text}`).join('\n'),
  });
}

function shouldPauseOpenCodeInstallRender() {
  if (Date.now() < (state.openCodeInstallView.pauseUntil || 0)) return true;
  const selection = window.getSelection?.();
  const node = selection?.anchorNode?.parentElement || selection?.anchorNode;
  return Boolean(selection?.toString()?.trim() && node?.closest?.('.install-tracker-log'));
}

function renderOpenCodeTrackerDialog(task) {
  const copy = getOpenCodeActionCopy(task.action, task.installedBefore);
  const desktopInstall = task.action === 'desktop-install';
  const platformLabel = getOpenCodeDesktopPlatformLabel(state.openCodeDesktopState?.platform || navigator.platform || '');
  const logs = getOpenCodeTrackerLogsText(task);
  const statusLabel = task.status === 'success'
    ? copy.done
    : task.status === 'cancelled'
      ? `${copy.title.replace('正在', '').trim()} 已中断`
      : task.status === 'cancelling'
        ? `${copy.title.replace('正在', '').trim()} 中断中`
        : task.status === 'error'
          ? `${copy.title.replace('正在', '').trim()} 失败`
          : copy.title;
  const detailText = task.detail || (task.status === 'running' || task.status === 'cancelling'
    ? (desktopInstall ? '正在等待新的下载 / 安装输出…' : '正在等待新的安装输出…')
    : '');
  const todoItems = desktopInstall
    ? (task.status === 'success'
      ? ['桌面版已经安装完成。', '现在可以直接点“打开桌面版”。', '如果你也要用 CLI，可继续安装 OpenCode 命令行版。']
      : task.status === 'cancelling'
        ? ['正在停止本次下载任务。', '正在等待后端清理临时状态。', '请先不要关闭窗口，完成后会自动提示。']
        : task.status === 'cancelled'
          ? ['本次桌面版安装已经停止。', '如果要继续，重新点击“一键安装”即可。', '下载阶段的残留文件会自动处理。']
          : task.status === 'error'
            ? ['先看下面“最后日志”的最后几行。', '如果是权限问题，允许系统安装后再试一次。', '如果是网络问题，稍后重试即可。']
            : ['你不需要手动找安装包。', '下载完成后会自动继续安装。', platformLabel === 'Windows' ? 'Windows 会自动拉起安装器。' : 'mac 会自动安装到 Applications。'])
    : (task.status === 'success'
      ? ['已完成安装流程。', '如果你是首次使用，下一步建议去快速配置 Provider 和默认模型。', '也可以直接从工具页启动 OpenCode。']
      : task.status === 'cancelling'
        ? ['正在停止安装进程。', '正在等待后端清理本次任务。', '请先不要关闭窗口，清理完成后会自动提示。']
        : task.status === 'cancelled'
          ? ['本次安装已经停止。', '如需继续，重新点击安装即可。', '如果有残留，下次安装或卸载会继续自动处理。']
          : task.status === 'error'
            ? ['先看下面“最后日志”里的最后几行。', '如果是网络问题，可改用国内优化方式。', '如果是环境问题，先确认 Node.js / npm / Homebrew 可用。']
            : ['先别关闭窗口，也别重复点击安装。', '如果 30–90 秒没有新日志，通常只是网络下载中。', '安装完成后，这里会自动给出结果。']);
  const infoItems = desktopInstall
    ? [
      `平台：${platformLabel}`,
      '来源：OpenCode 官方稳定版安装包',
      `方式：${platformLabel === 'Windows' ? '内置下载器 + 自动拉起安装器' : '内置下载器 + 自动安装到 Applications'}`,
      `耗时：${formatRelativeDuration(task.startedAt, task.completedAt)}`,
      task.command ? `执行：${task.command}` : task.commandPreview?.length ? `流程：${task.commandPreview.join('；')}` : '流程：等待开始',
    ].filter(Boolean)
    : [
      `请求方式：${getOpenCodeRequestedMethodLabel(task.requestedMethod)}`,
      task.method ? `实际方式：${getOpenCodeMethodLabel(task.method)}` : (task.stepIndex >= 1 ? '实际方式：等待安装器确认（候选命令已显示）' : '实际方式：等待检测'),
      typeof task.googleReachable === 'boolean' ? `Google 可达：${task.googleReachable ? '是' : '否'}` : (task.stepIndex >= 1 ? 'Google 可达：等待安装器返回结果（未最终确认）' : 'Google 可达：检测中'),
      typeof task.usedDomesticMirror === 'boolean' ? `国内镜像：${task.usedDomesticMirror ? '已使用' : '未使用'}` : '',
      `耗时：${formatRelativeDuration(task.startedAt, task.completedAt)}`,
      task.command ? `命令：${task.command}` : task.commandPreview?.length ? `命令预览：${task.commandPreview.join('；')}` : '命令：等待生成',
    ].filter(Boolean);
  return `
    <div class="install-tracker">
      <div class="install-tracker-top">
        <div>
          <div class="install-tracker-status">${escapeHtml(statusLabel)}</div>
          <div class="install-tracker-summary">${escapeHtml(task.summary || '')}</div>
        </div>
        <div class="install-tracker-percent">${Math.max(0, Math.min(100, Number(task.progress || 0)))}%</div>
      </div>
      <div class="sti-progress install-tracker-bar"><div class="sti-progress-fill ${task.status === 'running' ? 'indeterminate' : ''}" style="width:${Math.max(6, task.progress || 0)}%"></div></div>
      <div class="install-tracker-hint">${escapeHtml(task.hint || '你现在不需要操作，等它自己完成即可。')}</div>
      <div class="install-tracker-detail">${escapeHtml(detailText)}</div>
      <div class="install-tracker-grid">
        <div class="install-tracker-col">${(task.steps || []).map((step, index) => renderOpenClawInstallStep(step, index, task.status)).join('')}</div>
        <div class="install-tracker-col">
          <div class="install-tracker-note-card">
            <div class="install-tracker-note-title">当前状态</div>
            <ul class="install-tracker-list">${infoItems.map((item) => `<li>${escapeHtml(item)}</li>`).join('')}</ul>
          </div>
          <div class="install-tracker-note-card">
            <div class="install-tracker-note-title">你现在该做什么</div>
            <ul class="install-tracker-list">${todoItems.map((item) => `<li>${escapeHtml(item)}</li>`).join('')}</ul>
          </div>
        </div>
      </div>
      <div class="install-tracker-log-head">
        <div class="install-tracker-log-title">最后日志</div>
        <button type="button" class="secondary install-tracker-copy-btn" data-copy-opencode-log>复制日志</button>
      </div>
      <pre class="install-tracker-log">${escapeHtml(logs)}</pre>
    </div>
  `;
}

function renderTrackedOpenCodeDialog(task, { force = false } = {}) {
  const renderKey = buildOpenCodeTrackerRenderKey(task);
  state.openCodeInstallView.lastLogsText = getOpenCodeTrackerLogsText(task);
  if (!force && shouldPauseOpenCodeInstallRender()) {
    state.openCodeInstallView.pendingTask = task;
    return;
  }
  if (!force && renderKey === state.openCodeInstallView.lastRenderKey) return;

  const body = el('updateDialogBody');
  const oldLog = body?.querySelector('.install-tracker-log');
  const oldBodyScrollTop = body?.scrollTop || 0;
  const oldLogScrollTop = oldLog?.scrollTop || 0;
  const oldLogScrollHeight = oldLog?.scrollHeight || 0;
  const wasNearBottom = !oldLog || (oldLog.scrollTop + oldLog.clientHeight >= oldLog.scrollHeight - 28);

  const copy = getOpenCodeActionCopy(task.action, task.installedBefore);
  const eyebrow = task.action === 'desktop-install' ? 'OpenCode Desktop' : 'OpenCode';
  patchUpdateDialog({
    eyebrow,
    title: task.status === 'success'
      ? copy.done
      : task.status === 'cancelled'
        ? `${copy.title.replace('正在', '').trim()} 已中断`
        : task.status === 'cancelling'
          ? `${copy.title.replace('正在', '').trim()} 中断中`
          : task.status === 'error'
            ? `${copy.title.replace('正在', '').trim()} 失败`
            : copy.title,
    body: renderOpenCodeTrackerDialog(task),
    confirmText: task.status === 'running' ? '处理中…' : task.status === 'cancelling' ? '中断中…' : '知道了',
    confirmDisabled: task.status === 'running' || task.status === 'cancelling',
    cancelText: task.status === 'running' ? '中断安装' : task.status === 'cancelling' ? '中断中…' : '取消',
    cancelDisabled: task.status === 'cancelling',
    cancelHidden: !(task.status === 'running' || task.status === 'cancelling'),
    trackerMode: true,
  });

  if (task.status !== 'running' && task.status !== 'cancelling') {
    state.updateDialogCancelHandler = null;
  }

  const syncScroll = () => {
    const newBody = el('updateDialogBody');
    const newLog = newBody?.querySelector('.install-tracker-log');
    if (newBody) newBody.scrollTop = oldBodyScrollTop;
    if (newLog) {
      if (wasNearBottom) {
        newLog.scrollTop = newLog.scrollHeight;
      } else {
        newLog.scrollTop = Math.max(0, oldLogScrollTop + (newLog.scrollHeight - oldLogScrollHeight));
      }
    }
  };
  if (typeof requestAnimationFrame === 'function') requestAnimationFrame(syncScroll);
  else syncScroll();
  state.openCodeInstallView.lastRenderKey = renderKey;
  state.openCodeInstallView.pendingTask = null;
}

async function finishOpenCodeTracker(task, result, errorMessage = '') {
  if (result?.requestedMethod) task.requestedMethod = result.requestedMethod;
  if (result?.method) task.method = result.method;
  if (typeof result?.googleReachable === 'boolean') task.googleReachable = result.googleReachable;
  if (typeof result?.usedDomesticMirror === 'boolean') task.usedDomesticMirror = result.usedDomesticMirror;
  if (result?.command) task.command = result.command;
  if (result?.stdout) task.stdout = String(result.stdout || '');
  if (result?.stderr) task.stderr = String(result.stderr || '');

  if (result?.googleReachable !== undefined) {
    pushOpenCodeTrackerLog(task, 'stdout', `Google 可达性检测结果：${result.googleReachable ? '可访问' : '不可访问'}`);
  }
  if (result?.method) {
    pushOpenCodeTrackerLog(task, 'stdout', `最终安装方式：${getOpenCodeMethodLabel(result.method)}`);
  }
  if (result?.command) {
    pushOpenCodeTrackerLog(task, 'stdout', `执行命令：${result.command}`);
  }
  const outputText = String(result?.stdout || result?.stderr || '').trim();
  if (outputText) {
    outputText.split(/\r?\n/).filter(Boolean).slice(-12).forEach((line) => pushOpenCodeTrackerLog(task, result?.stderr ? 'stderr' : 'stdout', line));
  }

  if (errorMessage) {
    task.status = 'error';
    task.error = errorMessage;
    task.completedAt = new Date().toISOString();
    if (task.action === 'uninstall') {
      setOpenCodeTrackerStep(task, Math.max(1, task.stepIndex), { status: 'error', detail: errorMessage, summary: 'OpenCode 卸载失败', hint: '先看最后日志，一般会直接指出失败原因。' });
    } else {
      setOpenCodeTrackerStep(task, Math.max(2, task.stepIndex), { status: 'error', detail: errorMessage, summary: 'OpenCode 安装失败', hint: '先看最后日志，通常会告诉你是网络、权限还是依赖问题。' });
    }
    renderTrackedOpenCodeDialog(task, { force: true });
    return;
  }

  if (task.action === 'uninstall') {
    setOpenCodeTrackerStep(task, 2, {
      progress: 94,
      summary: '正在验证 OpenCode 卸载结果…',
      hint: '马上就完成了。',
      detail: '正在刷新工具状态并确认卸载结果…',
    });
    renderTrackedOpenCodeDialog(task, { force: true });
    await sleep(260);
    task.steps = task.steps.map((step) => ({ ...step, status: 'done' }));
    task.progress = 100;
    task.status = 'success';
    task.summary = 'OpenCode 已卸载完成';
    task.hint = '如需恢复，重新点击安装即可。';
    task.detail = '工具状态已经刷新完成。';
    task.completedAt = new Date().toISOString();
    renderTrackedOpenCodeDialog(task, { force: true });
    return;
  }

  setOpenCodeTrackerStep(task, 3, {
    progress: 94,
    summary: '正在验证 OpenCode 安装结果…',
    hint: '马上就完成了，正在确认命令可用。',
    detail: result?.command ? `安装命令已完成，正在验证：${result.command}` : '安装命令已完成，正在验证 opencode 命令…',
  });
  renderTrackedOpenCodeDialog(task, { force: true });
  await sleep(320);
  task.steps = task.steps.map((step) => ({ ...step, status: 'done' }));
  task.progress = 100;
  task.status = 'success';
  task.summary = task.action === 'update' && task.installedBefore ? 'OpenCode 已更新到最新版' : task.action === 'reinstall' ? 'OpenCode 重装完成' : 'OpenCode 安装完成';
  task.hint = '下一步可以直接启动 OpenCode，或先去配置 Provider / 模型。';
  task.detail = result?.stdout ? String(result.stdout).trim().split(/\r?\n/).filter(Boolean).slice(-1)[0] || '已完成安装验证。' : '已完成安装验证。';
  task.version = state.tools.find((tool) => tool.id === 'opencode')?.binary?.version || '';
  task.completedAt = new Date().toISOString();
  renderTrackedOpenCodeDialog(task, { force: true });
}


async function fetchOpenCodeInstallTask(taskId) {
  const json = await api(`/api/opencode/install/status?taskId=${encodeURIComponent(taskId)}`, { timeoutMs: 12000 });
  if (!json.ok) throw new Error(json.error || '获取 OpenCode 安装进度失败');
  return json.data;
}

async function cancelOpenCodeInstallTask(taskId) {
  const json = await api('/api/opencode/install/cancel', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ taskId }),
    timeoutMs: 120000,
  });
  if (!json.ok) throw new Error(json.error || '中断 OpenCode 安装失败');
  return json.data;
}

