// 家族级 fallback：精确 / 前缀 都没命中时，用同家族里 input 单价最高的一条估算
// 这样新出的 gpt-5.x / claude-opus-4-x 不至于直接显示 $0。
const PRICING_FAMILIES = [
  { prefix: 'gpt-5',         label: 'GPT-5 家族' },
  { prefix: 'gpt-4',         label: 'GPT-4 家族' },
  { prefix: 'claude-opus',   label: 'Claude Opus 家族' },
  { prefix: 'claude-fable',  label: 'Claude Fable 家族' },
  { prefix: 'claude-mythos', label: 'Claude Mythos 家族' },
  { prefix: 'claude-sonnet', label: 'Claude Sonnet 家族' },
  { prefix: 'claude-haiku',  label: 'Claude Haiku 家族' },
  { prefix: 'o3',            label: 'o3 家族' },
  { prefix: 'o4',            label: 'o4 家族' },
];

function lookupModelPricingEntry(modelName) {
  const normalizedName = String(modelName || '')
    .trim()
    .toLowerCase()
    .replace(/[\u2010-\u2015\u2212\uFE58\uFE63\uFF0D]/g, '-');
  const name = normalizedName.includes('/') ? normalizedName.split('/').filter(Boolean).pop() : normalizedName;
  if (!name || name === 'unknown') return null;
  const resolveTimedPricing = (pricing) => {
    if (!pricing?.standardAfter || Date.now() < Date.parse(`${pricing.standardAfter}T00:00:00Z`)) return pricing;
    return {
      ...pricing,
      input: pricing.standardInput,
      output: pricing.standardOutput,
      cached: pricing.standardCached,
      cacheWrite: pricing.standardCacheWrite,
    };
  };
  if (CODEX_MODEL_PRICING[name]) return { key: name, pricing: resolveTimedPricing(CODEX_MODEL_PRICING[name]), fallback: false };
  const keys = Object.keys(CODEX_MODEL_PRICING).sort((a, b) => b.length - a.length);
  for (const key of keys) {
    if (!name.startsWith(key)) continue;
    const suffix = name.slice(key.length);
    const pricing = resolveTimedPricing(CODEX_MODEL_PRICING[key]);
    const isSnapshotAlias = /^-(latest|\d{8}|\d{4}-\d{2}-\d{2})(?:$|-)/.test(suffix);
    if (isSnapshotAlias) return { key, pricing, fallback: false };
    return {
      key,
      pricing: { ...pricing, label: `${pricing.label}（按 ${key} 估算）` },
      fallback: true,
    };
  }
  // 家族兜底
  for (const family of PRICING_FAMILIES) {
    if (!name.startsWith(family.prefix)) continue;
    const candidates = Object.entries(CODEX_MODEL_PRICING)
      .filter(([k]) => k.startsWith(family.prefix));
    if (!candidates.length) continue;
    candidates.sort((a, b) => (b[1].input || 0) - (a[1].input || 0));
    const [bestKey, rawBestPricing] = candidates[0];
    const bestPricing = resolveTimedPricing(rawBestPricing);
    return {
      key: bestKey,
      pricing: { ...bestPricing, label: `${family.label}（按 ${bestPricing.label} 估算）` },
      fallback: true,
    };
  }
  return null;
}

function lookupModelPricing(modelName) {
  return lookupModelPricingEntry(modelName)?.pricing || null;
}

// 算 dashboard 当前的时间窗。优先用 state.dashboardRange（自定义日期），
// 其次用 state.dashboardDays（预设的 7/14/30）。统一返回 { from, to, days, label }
// 给各看板的 cutoff 过滤和文案使用。
function getDashboardWindow() {
  const today = new Date();
  const todayStr = today.toISOString().slice(0, 10);
  const range = state.dashboardRange;
  const isValidDate = (s) => /^\d{4}-\d{2}-\d{2}$/.test(s);
  if (range && isValidDate(range.from) && isValidDate(range.to) && range.from <= range.to) {
    const fromMs = Date.parse(`${range.from}T00:00:00Z`);
    const toMs = Date.parse(`${range.to}T00:00:00Z`);
    const days = Math.max(1, Math.round((toMs - fromMs) / 86400000) + 1);
    return {
      from: range.from,
      to: range.to,
      days,
      label: range.from === range.to ? range.from : `${range.from} ~ ${range.to}`,
      custom: true,
    };
  }
  const days = Math.max(1, Number(state.dashboardDays) || 30);
  const fromDate = new Date(today.getTime() - (days - 1) * 86400000);
  return {
    from: fromDate.toISOString().slice(0, 10),
    to: todayStr,
    days,
    label: `${days} 天`,
    custom: false,
  };
}

function getDashboardRequestDays(win = getDashboardWindow()) {
  const windowDays = Math.min(366, Math.max(1, Number(win?.days) || 30));
  if (!win?.custom) return windowDays;
  const from = String(win.from || '');
  if (!/^\d{4}-\d{2}-\d{2}$/.test(from)) return windowDays;
  const fromMs = Date.parse(`${from}T00:00:00Z`);
  const todayMs = Date.parse(`${new Date().toISOString().slice(0, 10)}T00:00:00Z`);
  if (!Number.isFinite(fromMs) || !Number.isFinite(todayMs) || fromMs > todayMs) return windowDays;
  const daysFromStartToToday = Math.round((todayMs - fromMs) / 86400000) + 1;
  return Math.min(366, Math.max(windowDays, daysFromStartToToday));
}

// ─── 自定义日期范围 picker ──────────────────────────────
// 打开下拉时按当前 dashboardRange / window 给 picker 初始化
function ensureRangePicker() {
  if (state.rangePicker) return;
  const win = getDashboardWindow();
  state.rangePicker = {
    viewMonth: (state.dashboardRange?.to || win.to).slice(0, 7),
    fromDraft: state.dashboardRange?.from || '',
    toDraft: state.dashboardRange?.to || '',
  };
}

function shiftMonth(viewMonth, delta) {
  const [y, m] = viewMonth.split('-').map(Number);
  const date = new Date(Date.UTC(y, m - 1 + delta, 1));
  return `${date.getUTCFullYear()}-${String(date.getUTCMonth() + 1).padStart(2, '0')}`;
}

function renderRangePickerPanel() {
  ensureRangePicker();
  const { viewMonth, fromDraft, toDraft } = state.rangePicker;
  const [year, month] = viewMonth.split('-').map(Number);
  const monthIdx = month - 1;
  const firstWeekday = new Date(Date.UTC(year, monthIdx, 1)).getUTCDay(); // 0=Sun
  const lastDate = new Date(Date.UTC(year, monthIdx + 1, 0)).getUTCDate();
  const todayStr = new Date().toISOString().slice(0, 10);

  const cells = [];
  for (let i = 0; i < firstWeekday; i++) {
    cells.push('<div class="db2-range-cell is-empty"></div>');
  }
  for (let d = 1; d <= lastDate; d++) {
    const ds = `${year}-${String(month).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
    const isFuture = ds > todayStr;
    const isToday = ds === todayStr;
    const isFrom = ds === fromDraft;
    const isTo = ds === toDraft;
    const inRange = fromDraft && toDraft && ds > fromDraft && ds < toDraft;
    const cls = [
      'db2-range-cell',
      isFuture ? 'is-disabled' : '',
      isToday ? 'is-today' : '',
      (isFrom || isTo) ? 'is-selected' : '',
      isFrom ? 'is-start' : '',
      isTo ? 'is-end' : '',
      inRange ? 'is-in-range' : '',
    ].filter(Boolean).join(' ');
    cells.push(`<button type="button" class="${cls}" data-range-day="${ds}" ${isFuture ? 'disabled' : ''}>${d}</button>`);
  }

  const weekdays = (isEnglishAppLanguage() ? ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'] : ['日', '一', '二', '三', '四', '五', '六'])
    .map((w) => `<div class="db2-range-wkd">${w}</div>`).join('');

  const preview = fromDraft && toDraft
    ? (isEnglishAppLanguage()
      ? `${fromDraft} -> ${toDraft} · ${Math.round((Date.parse(toDraft + 'T00:00:00Z') - Date.parse(fromDraft + 'T00:00:00Z')) / 86400000) + 1} days`
      : `${fromDraft} → ${toDraft} · 共 ${Math.round((Date.parse(toDraft + 'T00:00:00Z') - Date.parse(fromDraft + 'T00:00:00Z')) / 86400000) + 1} 天`)
    : fromDraft
      ? (isEnglishAppLanguage() ? `${fromDraft} -> <em>Select end date</em>` : `${fromDraft} → <em>请选结束日期</em>`)
      : (isEnglishAppLanguage() ? '<em>Select start date</em>' : '<em>点击选择起始日期</em>');

  const canApply = fromDraft && toDraft;
  return `
    <div class="db2-range-picker" data-period-custom>
      <div class="db2-range-head">
        <button type="button" class="db2-range-nav" data-range-nav="prev" aria-label="${escapeHtml(appText('上个月'))}">
          <svg width="10" height="10" viewBox="0 0 10 10" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><path d="M6.5 1.5L3 5l3.5 3.5"/></svg>
        </button>
        <span class="db2-range-title">${isEnglishAppLanguage() ? `${year}-${String(month).padStart(2, '0')}` : `${year} 年 ${String(month).padStart(2, '0')} 月`}</span>
        <button type="button" class="db2-range-nav" data-range-nav="next" aria-label="${escapeHtml(appText('下个月'))}">
          <svg width="10" height="10" viewBox="0 0 10 10" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><path d="M3.5 1.5L7 5l-3.5 3.5"/></svg>
        </button>
      </div>
      <div class="db2-range-wkds">${weekdays}</div>
      <div class="db2-range-grid">${cells.join('')}</div>
      <div class="db2-range-preview">${preview}</div>
      <div class="db2-range-actions">
        <button type="button" class="db2-range-reset" data-range-reset>${escapeHtml(appText('清空'))}</button>
        <button type="button" class="db2-range-apply" data-range-apply ${canApply ? '' : 'disabled'}>${escapeHtml(appText('应用'))}</button>
      </div>
    </div>`;
}

// 用主模型单价 + 当日 token 分布直算一段时间的费用。返回 USD。
// dailyItems: [{ input, output, reasoning?, cachedInput|cacheRead|cached, cacheCreation? }]
// models: 已按 totals.total 降序排的 model 列表（首项视为窗口主模型，给出单价）
function estimateCostByDaily(dailyItems = [], models = [], kind = 'codex') {
  const primary = models[0];
  if (!primary) return 0;
  const pricing = lookupModelPricing(primary.model);
  if (!pricing) return 0;
  const provider = pricing.provider || 'openai';
  let total = 0;
  for (const item of dailyItems) {
    const input = Number(item.input || 0);
    const output = Number(item.output || 0) + Number(item.reasoning || 0);
    const cached = Number(item.cachedInput || item.cacheRead || item.cached || 0);
    const cacheCreation = Number(item.cacheCreation || 0);
    if (input + output + cached + cacheCreation <= 0) continue;
    if (provider === 'anthropic') {
      const writeRate = Number.isFinite(pricing.cacheWrite) ? pricing.cacheWrite : pricing.input * 1.25;
      total += (input * pricing.input
        + output * pricing.output
        + cached * pricing.cached
        + cacheCreation * writeRate) / 1e6;
    } else {
      const nonCached = Math.max(0, input - cached);
      const writeRate = Number.isFinite(pricing.cacheWrite) ? pricing.cacheWrite : 0;
      total += (nonCached * pricing.input
        + cached * pricing.cached
        + output * pricing.output
        + cacheCreation * writeRate) / 1e6;
    }
  }
  return total;
}

function formatDashboardUsd(value, { min = 2, max = 4 } = {}) {
  const num = Number(value || 0);
  if (!Number.isFinite(num)) return '–';
  return '$' + num.toLocaleString('en-US', {
    minimumFractionDigits: min,
    maximumFractionDigits: max,
  });
}

// 按 ccusage 思路：input/cached/output 单价的应用要看 provider 是怎么报字段的。
//
// OpenAI (Codex/GPT/o-series):
//   input_tokens         总输入（已包含 cached 那部分）
//   cached_input_tokens  其中命中缓存的部分（要扣掉后再按 cached 单价收）
//   output_tokens        输出
//   reasoning_output_tokens  推理（按 output 单价收）
//   公式 = (input - cached) * inputRate + cached * cachedRate + cacheCreation * cacheWriteRate + (output + reasoning) * outputRate
//   旧实现里 input * inputRate + cached * cachedRate 是把 cached 那段重复算了一次。
//
// Anthropic (Claude Code):
//   input_tokens                非缓存输入（不含 cache hit / cache write）
//   cache_creation_input_tokens 写入缓存的 token（5min TTL ≈ input * 1.25）
//   cache_read_input_tokens     命中缓存的 token（≈ input * 0.1）
//   output_tokens               输出
//   公式 = input * inputRate + cacheCreation * cacheWriteRate + cacheRead * cachedRate + output * outputRate
function calcModelCost(modelEntry) {
  const pricing = lookupModelPricing(modelEntry.model);
  if (!pricing) return null;
  const provider = pricing.provider || 'openai';
  const totals = modelEntry.totals || {};
  const input = (totals.input || 0) / 1e6;
  const out = (totals.output || 0) / 1e6;
  const reasoning = (totals.reasoning || 0) / 1e6;
  // Codex/OpenAI 用 cachedInput；Claude/Anthropic 用 cacheRead
  const cachedRead = (totals.cachedInput || totals.cacheRead || 0) / 1e6;
  const cacheWrite = (totals.cacheCreation || 0) / 1e6;

  let inputCost;
  let cacheWriteCost;
  if (provider === 'anthropic') {
    // input 字段本身就不含 cached / cacheWrite，全价收
    inputCost = input * pricing.input;
    const writeRate = Number.isFinite(pricing.cacheWrite) ? pricing.cacheWrite : pricing.input * 1.25;
    cacheWriteCost = cacheWrite * writeRate;
  } else {
    // OpenAI：input 字段含 cached，必须先减出 non-cached 部分
    const nonCached = Math.max(0, input - cachedRead);
    inputCost = nonCached * pricing.input;
    const writeRate = Number.isFinite(pricing.cacheWrite) ? pricing.cacheWrite : 0;
    cacheWriteCost = cacheWrite * writeRate;
  }
  const outputCost = (out + reasoning) * pricing.output;
  const cachedRate = Number.isFinite(pricing.cached) ? pricing.cached : pricing.input;
  const cachedReadCost = cachedRead * cachedRate;
  const totalCost = inputCost + outputCost + cachedReadCost + cacheWriteCost;
  return {
    inputCost,
    outputCost,
    cachedReadCost,
    cacheWriteCost,
    totalCost,
    pricing,
    provider,
  };
}

function renderPricingStandardsCards(models = [], preferredKeys = []) {
  const detectedKeys = new Set(
    (models || [])
      .map((entry) => lookupModelPricingEntry(entry.model)?.key)
      .filter(Boolean)
  );
  // 优先把"当前实际用到的"放最前面，再补预设展示项
  const keys = [...new Set([...detectedKeys, ...(preferredKeys || [])])]
    .filter((key) => CODEX_MODEL_PRICING[key])
    .slice(0, 6);
  if (!keys.length) return `<div class="db2-empty">${escapeHtml(appText('暂无可识别的官方计费标准。'))}</div>`;
  return `
    <div class="db3-standards-note">${escapeHtml(appText('USD / 1M tokens · 仅供参考'))}</div>
    <div class="db3-rate-table">
      <div class="db3-rate-table-head">
        <div>${escapeHtml(appText('模型'))}</div>
        <div>${escapeHtml(appText('输入'))}</div>
        <div>${escapeHtml(appText('输出'))}</div>
        <div>${escapeHtml(appText('缓存写'))}</div>
        <div>${escapeHtml(appText('缓存读'))}</div>
      </div>
      ${keys.map((key) => {
        const pricing = CODEX_MODEL_PRICING[key];
        const detected = detectedKeys.has(key);
        return `<div class="db3-rate-table-row ${detected ? 'is-detected' : ''}">
          <div class="db3-rate-table-model">
            <div class="db3-rate-table-name">${escapeHtml(pricing.label)}</div>
            <div class="db3-rate-table-key">${escapeHtml(key)}</div>
          </div>
          <div class="db3-rate-table-num">${escapeHtml(formatDashboardUsd(pricing.input, { min: pricing.input < 1 ? 3 : 2, max: 3 }))}</div>
          <div class="db3-rate-table-num">${escapeHtml(formatDashboardUsd(pricing.output, { min: pricing.output < 1 ? 3 : 2, max: 3 }))}</div>
          <div class="db3-rate-table-num">${Number.isFinite(pricing.cacheWrite) ? escapeHtml(formatDashboardUsd(pricing.cacheWrite, { min: pricing.cacheWrite < 1 ? 3 : 2, max: 3 })) : '—'}</div>
          <div class="db3-rate-table-num">${pricing.cached == null ? '—' : escapeHtml(formatDashboardUsd(pricing.cached, { min: pricing.cached < 1 ? 3 : 2, max: 3 }))}</div>
        </div>`;
      }).join('')}
    </div>`;
}

function renderModelCostRows(models = [], totalTokens = 0) {
  if (!models.length) return `<div class="db2-empty">${escapeHtml(appText('暂无模型计费数据。'))}</div>`;
  const totals = {
    input: 0,
    output: 0,
    reasoning: 0,
    cachedRead: 0,
    cacheWrite: 0,
    cacheWriteAvailable: false,
    requests: 0,
    totalCost: 0,
    matched: 0,
  };
  const rows = models.map((entry) => {
    const cost = calcModelCost(entry);
    const pricingEntry = lookupModelPricingEntry(entry.model);
    const tokens = entry.totals?.total || 0;
    const input = entry.totals?.input || 0;
    const output = entry.totals?.output || 0;
    const reasoning = entry.totals?.reasoning || 0;
    const cachedRead = entry.totals?.cachedInput || entry.totals?.cacheRead || 0;
    const cacheWrite = entry.totals?.cacheCreation || 0;
    const cacheWriteAvailable = entry.totals?.cacheCreationAvailable === true;
    const requestsValue = entry.requests ?? entry.totals?.requests;
    const requests = Number(requestsValue || 0);
    const requestsAvailable = requestsValue != null;
    const pct = totalTokens ? Math.round(tokens / totalTokens * 100) : 0;
    const modelLabel = (pricingEntry?.fallback ? entry.model : (cost?.pricing?.label || pricingEntry?.pricing?.label || entry.model));

    totals.input += input;
    totals.output += output;
    totals.reasoning += reasoning;
    totals.cachedRead += cachedRead;
    totals.cacheWrite += cacheWrite;
    totals.cacheWriteAvailable ||= cacheWriteAvailable;
    totals.requests += requests;
    if (cost) {
      totals.totalCost += cost.totalCost;
      totals.matched += 1;
    }

    // 状态文案：精准命中 / 家族兜底 / 未匹配
    const matchTag = !pricingEntry
      ? '未匹配定价'
      : (pricingEntry.fallback
        ? (isEnglishAppLanguage() ? `Estimated as ${pricingEntry.pricing.label}` : `按 ${pricingEntry.pricing.label} 估算`)
        : '已匹配');

    return `<div class="db3-price-row">
      <div class="db3-price-model-cell">
        <div class="db3-price-model-main">${escapeHtml(modelLabel)}</div>
        <div class="db3-price-model-meta">
          <span>${pct}%</span>
          <span>${escapeHtml(appText(matchTag))}</span>
        </div>
      </div>
      <div class="db3-price-metric">
        <strong>${requestsAvailable ? escapeHtml(String(requests)) : '—'}</strong>
        <span>${escapeHtml(appText('请求次数'))}</span>
      </div>
      <div class="db3-price-metric" title="${escapeHtml(formatDashboardMetricFull(input))}">
        <strong>${escapeHtml(formatDashboardMetric(input))}</strong>
        <span>${escapeHtml(appText('输入'))}</span>
      </div>
      <div class="db3-price-metric" title="${escapeHtml(formatDashboardMetricFull(output + reasoning))}">
        <strong>${escapeHtml(formatDashboardMetric(output + reasoning))}</strong>
        <span>${reasoning ? `${escapeHtml(appText('推理'))} ${escapeHtml(formatDashboardMetric(reasoning))}` : escapeHtml(appText('输出'))}</span>
      </div>
      <div class="db3-price-metric" title="${escapeHtml(formatDashboardMetricFull(cachedRead))}">
        <strong>${escapeHtml(formatDashboardMetric(cachedRead))}</strong>
        <span>${escapeHtml(appText('缓存读取'))}</span>
      </div>
      <div class="db3-price-metric" title="${escapeHtml(cacheWriteAvailable ? formatDashboardMetricFull(cacheWrite) : appText('Codex 本地日志未提供缓存创建用量'))}">
        <strong>${cacheWriteAvailable ? escapeHtml(formatDashboardMetric(cacheWrite)) : '—'}</strong>
        <span>${escapeHtml(appText(cacheWriteAvailable ? '缓存创建' : '缓存创建不可用'))}</span>
      </div>
      <div class="db3-price-total ${cost ? '' : 'db3-price-total--na'}">
        <strong>${escapeHtml(cost ? formatDashboardUsd(cost.totalCost, { min: 4, max: 4 }) : '—')}</strong>
        <span>${escapeHtml(cost ? appText('预估') : appText('无估算'))}</span>
      </div>
    </div>`;
  });
  rows.push(`<div class="db3-price-row db3-price-row--total">
    <div class="db3-price-model-cell">
      <div class="db3-price-model-main">${escapeHtml(appText('合计'))}</div>
      <div class="db3-price-model-meta">
        <span>${escapeHtml(isEnglishAppLanguage() ? `${totals.matched}/${models.length} matched` : `${totals.matched}/${models.length} 个匹配`)}</span>
      </div>
    </div>
    <div class="db3-price-metric">
      <strong>${models.some((entry) => (entry.requests ?? entry.totals?.requests) != null) ? escapeHtml(String(totals.requests)) : '—'}</strong>
      <span>${escapeHtml(appText('请求次数'))}</span>
    </div>
    <div class="db3-price-metric">
      <strong>${escapeHtml(formatDashboardMetric(totals.input))}</strong>
      <span>${escapeHtml(appText('输入'))}</span>
    </div>
    <div class="db3-price-metric">
      <strong>${escapeHtml(formatDashboardMetric(totals.output + totals.reasoning))}</strong>
      <span>${totals.reasoning ? `${escapeHtml(appText('推理'))} ${escapeHtml(formatDashboardMetric(totals.reasoning))}` : escapeHtml(appText('输出'))}</span>
    </div>
    <div class="db3-price-metric">
      <strong>${escapeHtml(formatDashboardMetric(totals.cachedRead))}</strong>
      <span>${escapeHtml(appText('缓存读取'))}</span>
    </div>
    <div class="db3-price-metric" title="${escapeHtml(totals.cacheWriteAvailable ? formatDashboardMetricFull(totals.cacheWrite) : appText('Codex 本地日志未提供缓存创建用量'))}">
      <strong>${totals.cacheWriteAvailable ? escapeHtml(formatDashboardMetric(totals.cacheWrite)) : '—'}</strong>
      <span>${escapeHtml(appText(totals.cacheWriteAvailable ? '缓存创建' : '缓存创建不可用'))}</span>
    </div>
    <div class="db3-price-total">
      <strong>${escapeHtml(totals.totalCost ? formatDashboardUsd(totals.totalCost, { min: 4, max: 4 }) : '—')}</strong>
      <span>${escapeHtml(appText('累计'))}</span>
    </div>
  </div>`);
  return `<div class="db3-price-table">
    <div class="db3-price-grid">
      <div class="db3-price-row db3-price-row--head">
        <div>${escapeHtml(appText('模型'))}</div>
        <div>${escapeHtml(appText('请求次数'))}</div>
        <div>${escapeHtml(appText('输入'))}</div>
        <div>${escapeHtml(appText('输出 / 推理'))}</div>
        <div>${escapeHtml(appText('缓存读取'))}</div>
        <div>${escapeHtml(appText('缓存创建'))}</div>
        <div>${escapeHtml(appText('预估费用'))}</div>
      </div>
      ${rows.join('')}
    </div>
  </div>`;
}

// 按 provider / model 过滤 dashboard 数据。'all' 不过滤。
// 输入是后端聚合好的 metrics（codex 或 opencode），输出是同样 shape
// 但 totals/daily/sessions/models/providers 已按 filter 重算的对象。
function applyDashboardFilter(metrics, filter, tool) {
  if (!metrics) return metrics;
  const sessions = Array.isArray(metrics.sessions) ? metrics.sessions : [];
  const normProvider = (v) => String(v || '').toLowerCase().replace(/[^a-z0-9]+/g, '');
  let wantProvider = filter?.provider || 'all';
  let wantModel = filter?.model || 'all';
  if (wantProvider !== 'all' && !sessions.some((s) => normProvider(s?.provider) === normProvider(wantProvider))) {
    wantProvider = 'all';
  }
  if (wantModel !== 'all' && !sessions.some((s) => String(s?.model || '').toLowerCase() === wantModel.toLowerCase())) {
    wantModel = 'all';
  }
  if (wantProvider === 'all' && wantModel === 'all') return metrics;
  const matchProvider = (p) => {
    if (wantProvider === 'all') return true;
    return normProvider(p) === normProvider(wantProvider);
  };
  const matchModel = (m) => {
    if (wantModel === 'all') return true;
    return String(m || '').toLowerCase() === wantModel.toLowerCase();
  };
  const filteredSessions = sessions.filter((s) => matchProvider(s?.provider) && matchModel(s?.model));
  const metric = (s, key) => Number((s && s[key] != null ? s[key] : s?.totals?.[key]) || 0);
  const requestMetric = (s) => {
    const value = s?.requests ?? s?.totals?.requests;
    return value == null ? null : Number(value || 0);
  };
  const cachedMetric = (s) => Number(s?.cachedInput ?? s?.cacheRead ?? s?.totals?.cachedInput ?? s?.totals?.cacheRead ?? 0);
  const sessionDay = (s) => String(s?.lastActiveAt || s?.updatedAt || s?.startedAt || '').slice(0, 10);
  // 重算 totals
  const totals = { input: 0, output: 0, reasoning: 0, cachedInput: 0, cacheRead: 0, cacheCreation: 0, total: 0, cost: 0, requests: null };
  for (const s of filteredSessions) {
    totals.input += metric(s, 'input');
    totals.output += metric(s, 'output');
    totals.reasoning += metric(s, 'reasoning');
    totals.cachedInput += cachedMetric(s);
    totals.cacheRead += metric(s, 'cacheRead');
    totals.cacheCreation += metric(s, 'cacheCreation');
    totals.total += metric(s, 'total');
    totals.cost += metric(s, 'cost');
    const requests = requestMetric(s);
    if (requests != null) totals.requests = Number(totals.requests || 0) + requests;
  }
  // 重算 daily：按日期分桶
  const dailyMap = new Map();
  for (const s of filteredSessions) {
    const day = sessionDay(s);
    if (!day) continue;
    const bucket = dailyMap.get(day) || { date: day, input: 0, output: 0, reasoning: 0, cachedInput: 0, cacheRead: 0, cacheCreation: 0, total: 0, cost: 0, requests: null };
    bucket.input += metric(s, 'input');
    bucket.output += metric(s, 'output');
    bucket.reasoning += metric(s, 'reasoning');
    bucket.cachedInput += cachedMetric(s);
    bucket.cacheRead += metric(s, 'cacheRead');
    bucket.cacheCreation += metric(s, 'cacheCreation');
    bucket.total += metric(s, 'total');
    bucket.cost += metric(s, 'cost');
    const requests = requestMetric(s);
    if (requests != null) bucket.requests = Number(bucket.requests || 0) + requests;
    dailyMap.set(day, bucket);
  }
  const daily = [...dailyMap.values()].sort((a, b) => a.date.localeCompare(b.date));
  // 重算 providers（聚合到当前筛选下还剩谁）
  const provMap = new Map();
  for (const s of filteredSessions) {
    const k = s.provider || 'unknown';
    const cur = provMap.get(k) || { provider: k, events: 0, requests: null, totals: { input: 0, output: 0, reasoning: 0, cachedInput: 0, cacheRead: 0, cacheCreation: 0, total: 0, cost: 0, requests: null } };
    cur.events += 1;
    cur.totals.input += metric(s, 'input');
    cur.totals.output += metric(s, 'output');
    cur.totals.reasoning += metric(s, 'reasoning');
    cur.totals.cachedInput += cachedMetric(s);
    cur.totals.cacheRead += metric(s, 'cacheRead');
    cur.totals.cacheCreation += metric(s, 'cacheCreation');
    cur.totals.total += metric(s, 'total');
    cur.totals.cost += metric(s, 'cost');
    const requests = requestMetric(s);
    if (requests != null) {
      cur.totals.requests = Number(cur.totals.requests || 0) + requests;
      cur.requests = Number(cur.requests || 0) + requests;
    }
    provMap.set(k, cur);
  }
  const providers = [...provMap.values()].sort((a, b) => b.totals.total - a.totals.total);
  // 重算 models
  const modelMap = new Map();
  for (const s of filteredSessions) {
    const k = s.model || 'unknown';
    const cur = modelMap.get(k) || { model: k, events: 0, requests: null, totals: { input: 0, output: 0, reasoning: 0, cachedInput: 0, cacheRead: 0, cacheCreation: 0, total: 0, cost: 0, requests: null } };
    cur.events += 1;
    cur.totals.input += metric(s, 'input');
    cur.totals.output += metric(s, 'output');
    cur.totals.reasoning += metric(s, 'reasoning');
    cur.totals.cachedInput += cachedMetric(s);
    cur.totals.cacheRead += metric(s, 'cacheRead');
    cur.totals.cacheCreation += metric(s, 'cacheCreation');
    cur.totals.total += metric(s, 'total');
    cur.totals.cost += metric(s, 'cost');
    const requests = requestMetric(s);
    if (requests != null) {
      cur.totals.requests = Number(cur.totals.requests || 0) + requests;
      cur.requests = Number(cur.requests || 0) + requests;
    }
    modelMap.set(k, cur);
  }
  const models = [...modelMap.values()].sort((a, b) => b.totals.total - a.totals.total);
  return {
    ...metrics,
    totals,
    daily,
    providers,
    sessions: filteredSessions,
    models,
    _filtered: true,
    _filterTool: tool,
  };
}

function getDashboardFilterOptions(metrics) {
  const sessions = Array.isArray(metrics?.sessions) ? metrics.sessions : [];
  const provSet = new Set();
  const modelSet = new Set();
  for (const s of sessions) {
    if (s.provider) provSet.add(s.provider);
    if (s.model) modelSet.add(s.model);
  }
  return {
    providers: [...provSet].sort(),
    models: [...modelSet].sort(),
  };
}

function formatDashboardUsageTimestamp(value) {
  if (!value) return '—';
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return '—';
  return date.toLocaleString(isEnglishAppLanguage() ? 'en-US' : 'zh-CN', {
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
  });
}

function getDashboardUsageStatusMeta(metrics = {}) {
  const level = String(metrics?.usageLevel || metrics?.usageStatus || '').trim() || 'missing';
  const evidence = metrics?.usageEvidence && typeof metrics.usageEvidence === 'object' ? metrics.usageEvidence : {};
  const labelMap = {
    exact: '精准用量',
    parsed: '已解析 Token',
    'sessions-only': '仅会话记录',
    'source-only': '仅发现来源',
    'connected-empty': '已接入无数据',
    unsupported: '未支持用量',
    missing: '未发现数据',
    error: '读取异常',
  };
  const detailMap = {
    exact: '来自该工具已接入的本地用量数据源。',
    parsed: '从本机会话文件中提取到 usage/token 字段。',
    'sessions-only': '已找到会话或活动日志，但没有发现可统计的 token 字段。',
    'source-only': '发现本地目录或配置入口，但还没有可解析的会话记录。',
    'connected-empty': '读取入口已接通，但当前窗口内没有 token 记录。',
    unsupported: '没有确认稳定的本地 JSONL/SQLite 数据源，不进入用量分析。',
    missing: '本机还没有发现可读取的会话或用量文件。',
    error: '发现本地来源，但解析或读取时返回异常。',
  };
  const sessionCount = Number(evidence.sessionCount || metrics?.sessions?.length || metrics?.requestLogs?.length || 0);
  const tokenizedCount = Number(evidence.tokenizedSessionCount || 0);
  const existingSourceCount = Number(evidence.existingSourceCount || 0);
  const configuredSourceCount = Number(evidence.configuredSourceCount || 0);
  return {
    level,
    label: metrics?.usageStatusLabel || labelMap[level] || labelMap.missing,
    detail: metrics?.usageStatusDetail || detailMap[level] || detailMap.missing,
    evidenceLabel: `${existingSourceCount}/${configuredSourceCount || existingSourceCount} 来源 · ${sessionCount} 会话 · ${tokenizedCount} 含 Token`,
  };
}

function renderDashboardUsageSourcePanel(tool = '', metrics = {}) {
  const warnings = Array.isArray(metrics?.warnings) ? metrics.warnings.filter(Boolean) : [];
  const status = getDashboardUsageStatusMeta(metrics);
  const sourcePaths = String(metrics?.source || '')
    .split('|')
    .map((item) => item.trim())
    .filter(Boolean)
    .slice(0, 6);
  const customPrices = metrics?.customPrices?.models
    ? `${metrics.customPrices.models} 个自定义模型价格`
    : '未配置自定义价格';
  const sourceType = metrics?.sourceType || 'session-backed';
  const showSourcePaths = status.level !== 'missing' && sourcePaths.length;
  return `
    <div class="db3-usage-source">
      <div class="db3-usage-status db3-usage-status--${escapeHtml(status.level)}">
        <strong>${escapeHtml(appText(status.label))}</strong>
        <span>${escapeHtml(appText(status.detail))}</span>
      </div>
      <div class="db3-usage-source-row">
        <span>${escapeHtml(appText('证据'))}</span>
        <strong>${escapeHtml(status.evidenceLabel)}</strong>
      </div>
      <div class="db3-usage-source-row">
        <span>${escapeHtml(appText('读取方式'))}</span>
        <strong>${escapeHtml(sourceType)}</strong>
      </div>
      <div class="db3-usage-source-row">
        <span>${escapeHtml(appText('价格本'))}</span>
        <strong>${escapeHtml(appText(customPrices))}</strong>
      </div>
      ${showSourcePaths ? `<div class="db3-usage-paths">${sourcePaths.map((item) => `<code title="${escapeHtml(item)}">${escapeHtml(item)}</code>`).join('')}</div>` : `<div class="dashboard-empty-note">${escapeHtml(appText(status.detail))}</div>`}
      ${warnings.length ? `<div class="db3-usage-warnings">${warnings.map((item) => `<span>${escapeHtml(item)}</span>`).join('')}</div>` : ''}
      <div class="db3-usage-actions">
        <button type="button" class="db3-usage-action" data-dashboard-goto-assets="${escapeHtml(tool)}">${escapeHtml(appText('资产中心'))}</button>
        <button type="button" class="db3-usage-action" data-dashboard-goto-config="${escapeHtml(tool)}">${escapeHtml(appText('配置工具'))}</button>
      </div>
    </div>`;
}

function renderDashboardUsageLogTable(logs = []) {
  const rows = (Array.isArray(logs) ? logs : []).slice(0, 120);
  if (!rows.length) return `<div class="dashboard-empty-note">${escapeHtml(appText('暂无请求或会话明细。刷新后仍为空，说明本机尚未留下可读取的日志。'))}</div>`;
  return `
    <div class="db3-usage-log-table" role="table" aria-label="${escapeHtml(appText('请求明细'))}">
      <div class="db3-usage-log-row db3-usage-log-head" role="row">
        <span>${escapeHtml(appText('时间'))}</span>
        <span>${escapeHtml(appText('会话 / 项目'))}</span>
        <span>${escapeHtml(appText('Provider / 模型'))}</span>
        <span>${escapeHtml(appText('Token'))}</span>
      </div>
      <div class="db3-usage-log-body">
        ${rows.map((log) => {
          const title = log.title || log.sessionId || log.id || 'session';
          const project = log.projectPath || log.sourceScope || '';
          const model = log.model || 'unknown';
          const provider = log.provider || 'unknown';
          const total = log.total || log.totals?.total || 0;
          return `<div class="db3-usage-log-row" role="row">
            <span>${escapeHtml(formatDashboardUsageTimestamp(log.updatedAt || log.lastActiveAt))}</span>
            <span>
              <strong title="${escapeHtml(title)}">${escapeHtml(title)}</strong>
              ${project ? `<em title="${escapeHtml(project)}">${escapeHtml(project)}</em>` : ''}
            </span>
            <span>
              <strong title="${escapeHtml(provider)}">${escapeHtml(provider)}</strong>
              <em title="${escapeHtml(model)}">${escapeHtml(model)}</em>
            </span>
            <span title="${escapeHtml(formatDashboardMetricFull(total))}">${escapeHtml(formatDashboardMetric(total))}</span>
          </div>`;
        }).join('')}
      </div>
    </div>`;
}

function renderGenericUsageDashboard(tool = '', metrics = null, win = getDashboardWindow(), { isLoading = false } = {}) {
  if (!metrics && isLoading) return renderDashboardLoadingCard();
  const def = getDashboardToolDef(tool) || { label: tool || 'Tool' };
  const totals = normalizeDashboardUsageTotals(metrics?.totals || {});
  const daily = (metrics?.daily || []).filter((item) => {
    const date = item.date || '';
    return date >= win.from && date <= win.to;
  });
  const sessions = Array.isArray(metrics?.sessions) ? metrics.sessions : [];
  const models = Array.isArray(metrics?.models) ? metrics.models : [];
  const providers = Array.isArray(metrics?.providers) ? metrics.providers : [];
  const dailyTotal = daily.reduce((sum, item) => sum + Number(item.total || 0), 0);
  const totalTokens = dailyTotal || totals.total;
  const inputTokens = daily.reduce((sum, item) => sum + Number(item.input || 0), 0) || totals.input;
  const outputTokens = daily.reduce((sum, item) => sum + Number(item.output || 0), 0) || totals.output;
  const reasoningTokens = daily.reduce((sum, item) => sum + Number(item.reasoning || 0), 0) || totals.reasoning;
  const cachedTokens = daily.reduce((sum, item) => sum + Number(item.cachedInput || item.cacheRead || 0), 0) || totals.cachedInput || totals.cacheRead;
  const cost = daily.reduce((sum, item) => sum + Number(item.cost || 0), 0) || totals.cost || totals.officialCost;
  const requestCount = totals.requests || sessions.length;
  const cacheHitPct = totalTokens ? Math.round(cachedTokens / totalTokens * 100) : 0;
  const topModel = models[0]?.model || 'unknown';
  const modelTotal = models.reduce((sum, entry) => sum + Number(entry.totals?.total || 0), 0);
  const hasAnyData = totalTokens > 0 || sessions.length > 0 || models.length > 0 || providers.length > 0;
  const usageStatus = getDashboardUsageStatusMeta(metrics || {});
  const tokenMix = [
    { label: '输入', value: totalTokens ? Math.round(inputTokens / totalTokens * 100) : 0, meta: inputTokens },
    { label: '输出', value: totalTokens ? Math.round(outputTokens / totalTokens * 100) : 0, meta: outputTokens },
    { label: '缓存', value: cacheHitPct, meta: cachedTokens },
    { label: '推理', value: totalTokens ? Math.round(reasoningTokens / totalTokens * 100) : 0, meta: reasoningTokens },
  ];
  const costSeries = daily.map((item) => ({ label: (item.date || '').slice(5), value: Number(item.cost || 0) }));
  return `
    <div class="db2-layout db2-layout--dashboard db3-usage-layout">
      <section class="db3-hero db3-hero--usage">
        <div class="db3-hero-stats">
          <div class="db3-hero-stat db3-hero-stat-emph">
            <div class="db3-hero-value">${escapeHtml(cost ? formatDashboardUsd(cost, { min: 2, max: 4 }) : '$0.00')}</div>
            <div class="db3-hero-label">${escapeHtml(appText('本地记录费用'))}</div>
          </div>
          <div class="db3-hero-stat">
            <div class="db3-hero-value">${escapeHtml(formatDashboardMetric(totalTokens))}</div>
            <div class="db3-hero-label">${escapeHtml(appText('总 Token'))}</div>
          </div>
          <div class="db3-hero-stat">
            <div class="db3-hero-value">${escapeHtml(formatDashboardMetric(requestCount))}</div>
            <div class="db3-hero-label">${escapeHtml(appText('请求 / 会话'))}</div>
          </div>
          <div class="db3-hero-stat">
            <div class="db3-hero-value">${escapeHtml(topModel === 'unknown' ? '—' : topModel)}</div>
            <div class="db3-hero-label">${escapeHtml(appText('主模型'))}</div>
          </div>
        </div>
        <div class="db3-hero-chart-wrap">
          <div class="db3-hero-chart-head">
            <span class="db3-hero-chart-title">${escapeHtml(appText('Token 用量趋势'))}</span>
            <span class="db3-hero-chart-meta">${escapeHtml(formatDashboardRecentWindowLabel(win))} · ${escapeHtml(def.label)} · ${escapeHtml(appText(usageStatus.label))}</span>
          </div>
          ${hasAnyData
            ? renderDashboardInteractiveChart(daily.map((item) => ({ label: item.date.slice(5), value: item.total || 0, input: item.input || 0, output: (item.output || 0) + (item.reasoning || 0), cached: item.cachedInput || item.cacheRead || 0 })), { stroke: '#22c55e', showCost: false, models })
            : `<div class="db3-usage-empty">
                <strong>${escapeHtml(appText(usageStatus.label))}</strong>
                <span>${escapeHtml(appText(usageStatus.detail))}</span>
                <div class="db3-usage-actions">
                  <button type="button" class="db3-usage-action" data-dashboard-goto-assets="${escapeHtml(tool)}">${escapeHtml(appText('查看资产来源'))}</button>
                  <button type="button" class="db3-usage-action" data-dashboard-refresh>${escapeHtml(appText('重新读取'))}</button>
                </div>
              </div>`}
        </div>
      </section>

      <div class="db3-analytics-board db3-analytics-board--generic">
        <section class="db2-section db3-panel db3-panel--primary">
          <div class="db2-card-head">
            <div class="db2-card-title">${escapeHtml(appText('请求明细'))}</div>
            <div class="db2-card-meta">${escapeHtml(isEnglishAppLanguage() ? `${sessions.length} sessions` : `${sessions.length} 条`)}</div>
          </div>
          ${renderDashboardUsageLogTable(sessions)}
        </section>
        <section class="db2-section db3-panel db3-panel--mix">
          <div class="db2-card-head">
            <div class="db2-card-title">${escapeHtml(appText('Token 构成'))}</div>
            <div class="db2-card-meta">${escapeHtml(cacheHitPct ? `Cache ${cacheHitPct}%` : 'Input / Output / Cache')}</div>
          </div>
          ${renderDashboardTokenMix(tokenMix)}
        </section>
        <section class="db2-section db3-panel db3-panel--dist">
          <div class="db2-card-head">
            <div class="db2-card-title">${escapeHtml(appText('模型分布'))}</div>
            <div class="db2-card-meta">${escapeHtml(formatDashboardModelCount(models.length))}</div>
          </div>
          ${renderDashboardModelDistChart(models, modelTotal)}
        </section>
        <section class="db2-section db3-panel db3-panel--trend">
          <div class="db2-card-head">
            <div class="db2-card-title">${escapeHtml(appText('费用趋势'))}</div>
            <div class="db2-card-meta">${escapeHtml(appText('来自本地日志或自定义价格'))}</div>
          </div>
          ${renderCostTrendPanel(costSeries, isEnglishAppLanguage() ? `${formatDashboardRecentWindowLabel(win)} total` : `${formatDashboardRecentWindowLabel(win)}合计`, '#22c55e')}
        </section>
        <section class="db2-section db3-panel db3-panel--standards">
          <div class="db2-card-head">
            <div class="db2-card-title">${escapeHtml(appText('读取来源'))}</div>
            <div class="db2-card-meta">${escapeHtml(metrics?.ok === false ? appText('存在解析问题') : appText('本地优先'))}</div>
          </div>
          ${renderDashboardUsageSourcePanel(tool, metrics || {})}
        </section>
      </div>
    </div>`;
}

function renderCursorDashboard(root) {
  if (!root) return;
  const esc = escapeHtml;
  const u = window.__consoleV3.cursorUsage;
  if (el('pageTitle')) el('pageTitle').textContent = appText('数据看板');
  if (!state.cursorDash) state.cursorDash = { model: 'all', days: 30 };
  const filter = state.cursorDash;

  // 冷启动才等扫描；已有历史数据则先展示、陈旧(>2min)时后台静默刷新
  if (!u) {
    if (!window.__consoleV3.cursorUsageLoading) loadConsoleCursorUsage();
  } else if (!window.__consoleV3.cursorUsageLoading && (Date.now() - (window.__consoleV3.cursorUsageSavedAt || 0) > 120000)) {
    loadConsoleCursorUsage({ silent: true });
  }

  const refreshBtn = `<button type="button" class="dashboard-refresh-btn" data-dashboard-refresh><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21.5 2v6h-6M2.5 22v-6h6M2 11.5a10 10 0 0 1 18.8-4.3M22 12.5a10 10 0 0 1-18.8 4.3"/></svg>${esc(appText('刷新'))}</button>`;

  if (!u) {
    if (el('pageSubtitle')) el('pageSubtitle').textContent = 'Cursor · ' + appText('正在读取本地 state.vscdb…');
    root.innerHTML = `<div class="dashboard-shell"><section class="dashboard-card dashboard-panel span-12"><div class="dashboard-empty-note">${esc(appText('正在读取 Cursor 本地数据…'))}</div></section></div>`;
    return;
  }
  if (u.supported === false || u.status === 'not_found') {
    if (el('pageSubtitle')) el('pageSubtitle').textContent = 'Cursor · ' + appText('未找到本地数据');
    root.innerHTML = `<div class="dashboard-shell">
      <div class="db3-toolbar db3-toolbar--page"><div class="db3-toolbar-status"></div><div style="display:flex;gap:8px">${refreshBtn}</div></div>
      <section class="dashboard-card dashboard-panel span-12"><div class="dashboard-empty-note">${esc(u.message || '未找到 Cursor 本地数据（state.vscdb）。')}</div></section>
    </div>`;
    return;
  }

  const t = u.totals || {};
  const acc = u.account || {};
  const ct = u.codeTracking || null;
  const est = u.estimate || null;
  const lastUpdated = formatDashboardUpdatedAt(u.generatedAt) || appText('统计已完成');
  if (el('pageSubtitle')) el('pageSubtitle').textContent = `Cursor · ${appText('本地估算')} · ${lastUpdated}`;

  const num = (v) => Number(v || 0).toLocaleString();
  const fmtTok = (v) => (Number(v || 0) > 0 ? formatDashboardMetric(Number(v || 0)) : '0');
  const fmtUsd = (v) => '$' + Number(v || 0).toFixed(2);
  const title = (txt) => `<div style="font-weight:600;font-size:13px;margin:0 0 10px;color:var(--text,#1c2430)">${esc(appText(txt))}</div>`;
  const statCard = (label, val, sub = '') => `<div class="dashboard-stat-card"><div class="dashboard-stat-label">${esc(appText(label))}</div><div class="dashboard-stat-value">${esc(String(val))}</div>${sub ? `<div class="dashboard-stat-sub">${esc(appText(sub))}</div>` : ''}</div>`;

  const accBits = [];
  if (acc.email) accBits.push(esc(acc.email));
  if (acc.plan) accBits.push(esc(String(acc.plan).toUpperCase()));
  if (acc.subscriptionStatus) accBits.push(esc(acc.subscriptionStatus));

  // ── 估算聚合（按 模型 + 时间窗口 客户端筛选） ──
  const allSessions = (est && Array.isArray(est.sessions)) ? est.sessions : [];
  const modelOptions = Array.from(new Set(allSessions.map((s) => s.model).filter(Boolean))).sort();
  const cutoff = filter.days > 0 ? new Date(Date.now() - filter.days * 86400000).toISOString().slice(0, 10) : '';
  const fsessions = allSessions.filter((s) => (filter.model === 'all' || s.model === filter.model) && (!cutoff || (s.date && s.date >= cutoff)));
  const agg = { input: 0, cacheRead: 0, output: 0, cost: 0, requests: 0, sessions: 0 };
  const byModel = {};
  const byDay = {};
  for (const s of fsessions) {
    agg.input += Number(s.input || 0); agg.cacheRead += Number(s.cacheRead || 0); agg.output += Number(s.output || 0);
    agg.cost += Number(s.costUsd || 0); agg.requests += Number(s.requests || 0); agg.sessions += 1;
    const m = byModel[s.model] || (byModel[s.model] = { model: s.model, input: 0, cacheRead: 0, output: 0, cost: 0, requests: 0 });
    m.input += Number(s.input || 0); m.cacheRead += Number(s.cacheRead || 0); m.output += Number(s.output || 0); m.cost += Number(s.costUsd || 0); m.requests += Number(s.requests || 0);
    if (s.date) { const d = byDay[s.date] || (byDay[s.date] = { date: s.date, total: 0, cost: 0 }); d.total += Number(s.input || 0) + Number(s.cacheRead || 0) + Number(s.output || 0); d.cost += Number(s.costUsd || 0); }
  }
  const estModels = Object.values(byModel).sort((a, b) => (b.input + b.cacheRead + b.output) - (a.input + a.cacheRead + a.output));
  const estDaily = Object.values(byDay).sort((a, b) => a.date.localeCompare(b.date));
  const estTotalTokens = agg.input + agg.cacheRead + agg.output;
  const hasEstimate = est && allSessions.length > 0;

  // ── 折线图（每日累计 token 估算） ──
  const trendSvg = (daily) => {
    if (!daily.length) return `<div class="dashboard-empty-note">${esc(appText('暂无趋势数据'))}</div>`;
    const vals = daily.map((d) => Number(d.total || 0));
    const max = Math.max(1, ...vals);
    const n = daily.length;
    const W = 100, H = 34;
    const pts = daily.map((d, i) => [n > 1 ? (i / (n - 1)) * W : 0, H - (Number(d.total || 0) / max) * H]);
    const line = pts.map((p, i) => `${i ? 'L' : 'M'}${p[0].toFixed(2)},${p[1].toFixed(2)}`).join(' ');
    const area = `M0,${H} ` + pts.map((p) => `L${p[0].toFixed(2)},${p[1].toFixed(2)}`).join(' ') + ` L${W},${H} Z`;
    return `<div>
      <svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" style="width:100%;height:130px;display:block">
        <defs><linearGradient id="curTrendG" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#5b8cff" stop-opacity="0.30"/><stop offset="1" stop-color="#5b8cff" stop-opacity="0"/></linearGradient></defs>
        <path d="${area}" fill="url(#curTrendG)"/>
        <path d="${line}" fill="none" stroke="#5b8cff" stroke-width="1" vector-effect="non-scaling-stroke"/>
      </svg>
      <div style="display:flex;justify-content:space-between;font-size:11px;color:var(--muted,#6b7787);margin-top:4px"><span>${esc(daily[0].date)}</span><span>${esc(appText('峰值'))} ${esc(formatDashboardMetric(max))}</span><span>${esc(daily[daily.length - 1].date)}</span></div>
    </div>`;
  };

  // ── 筛选（模型 + 时间窗口）：复用 db2-period 药丸下拉，和 Codex/Claude 完全一致 ──
  const dayLabels = { 1: '近 1 天', 7: '近 7 天', 30: '近 30 天', 90: '近 90 天', 0: '全部' };
  const truncLabel = (s, n = 18) => (String(s).length > n ? String(s).slice(0, n) + '…' : String(s));
  const modelTriggerLabel = filter.model === 'all' ? appText('全部模型') : truncLabel(formatModelLabel(filter.model) || filter.model);
  const daysTriggerLabel = appText(dayLabels[Number(filter.days)] || '近 30 天');
  const chevron = '<svg width="8" height="5" viewBox="0 0 8 5" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"><path d="M1 1l3 3 3-3"/></svg>';
  const pill = (which, triggerLabel, options) => `
    <span class="db2-period-wrap">
      <div class="db2-period-dropdown" data-cursor-dd="${which}">
        <button type="button" class="db2-period-trigger" data-cursor-dd-trigger>${esc(triggerLabel)}${chevron}</button>
        <div class="db2-period-menu">
          <div class="db2-period-presets" style="grid-template-columns:repeat(2,minmax(0,1fr))">
            ${options.map(([val, lab, active]) => `<button type="button" class="db2-period-option ${active ? 'active' : ''}" data-cursor-dd-value="${esc(String(val))}">${esc(lab)}</button>`).join('')}
          </div>
        </div>
      </div>
    </span>`;
  const modelOpts = [['all', appText('全部模型'), filter.model === 'all'], ...modelOptions.map((m) => [m, formatModelLabel(m) || m, filter.model === m])];
  const daysOpts = [[7, appText('近 7 天'), Number(filter.days) === 7], [30, appText('近 30 天'), Number(filter.days) === 30], [90, appText('近 90 天'), Number(filter.days) === 90], [1, appText('近 1 天'), Number(filter.days) === 1], [0, appText('全部'), Number(filter.days) === 0]];
  const filterPills = pill('model', modelTriggerLabel, modelOpts) + pill('days', daysTriggerLabel, daysOpts);

  // ── Hero（估算口径的累计 token / 输出 / 费用 / 请求） ──
  const heroStats = hasEstimate ? [
    { value: fmtTok(estTotalTokens), label: '累计 Token（估算）', emph: true },
    { value: fmtTok(agg.output), label: '输出 Token（估算）' },
    { value: fmtUsd(agg.cost), label: '预估费用', emph: true },
    { value: num(agg.requests), label: '请求次数（估算）' },
  ] : [
    { value: num(t.sessions), label: '本地会话', emph: true },
    { value: num(t.messages), label: '消息数' },
    { value: fmtTok(t.contextTokens), label: '上下文 Token（本地）', emph: true },
    { value: num(t.week), label: '近 7 天会话' },
  ];
  const heroHtml = `<section class="db3-hero"><div class="db3-hero-stats">${heroStats.map((s) => `<div class="db3-hero-stat ${s.emph ? 'db3-hero-stat-emph' : ''}"><div class="db3-hero-value">${esc(String(s.value))}</div><div class="db3-hero-label">${esc(appText(s.label))}</div></div>`).join('')}</div></section>`;

  // ── token 结构分解 ──
  const breakdownHtml = hasEstimate ? `<section class="dashboard-card dashboard-panel span-12">
    ${title('Token 结构（估算）')}
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:10px">
      ${statCard('输入（首次发送）', fmtTok(agg.input))}
      ${statCard('缓存读取（每轮重发）', fmtTok(agg.cacheRead))}
      ${statCard('输出', fmtTok(agg.output))}
      ${statCard('本地会话', num(agg.sessions))}
      ${statCard('上下文 Token（本地实测）', fmtTok(t.contextTokens))}
    </div>
  </section>` : '';

  // ── 趋势折线图 ──
  const trendHtml = hasEstimate ? `<section class="dashboard-card dashboard-panel span-12">
    ${title('Token 用量趋势（估算 · 按会话活动日归集）')}
    ${trendSvg(estDaily)}
  </section>` : '';

  // ── 按模型计费表 ──
  const tableGrid = 'display:grid;grid-template-columns:1.7fr .7fr 1fr 1fr .9fr 1fr;gap:8px;align-items:center';
  const tableHead = `<div style="${tableGrid};font-size:11px;color:var(--muted,#6b7787);padding-bottom:6px"><span>${esc(appText('模型'))}</span><span style="text-align:right">${esc(appText('请求'))}</span><span style="text-align:right">${esc(appText('输入'))}</span><span style="text-align:right">${esc(appText('缓存读取'))}</span><span style="text-align:right">${esc(appText('输出'))}</span><span style="text-align:right">${esc(appText('预估费用'))}</span></div>`;
  const tableRows = estModels.map((m) => `<div style="${tableGrid};font-size:12px;padding:7px 0;border-top:1px solid rgba(120,130,150,.12)">
      <span style="white-space:nowrap;overflow:hidden;text-overflow:ellipsis" title="${esc(m.model)}">${esc(formatModelLabel(m.model) || m.model)}</span>
      <span style="text-align:right;color:var(--muted,#6b7787)">${esc(num(m.requests))}</span>
      <span style="text-align:right">${esc(fmtTok(m.input))}</span>
      <span style="text-align:right">${esc(fmtTok(m.cacheRead))}</span>
      <span style="text-align:right">${esc(fmtTok(m.output))}</span>
      <span style="text-align:right;font-weight:600">${esc(fmtUsd(m.cost))}</span>
    </div>`).join('');
  const tableTotal = `<div style="${tableGrid};font-size:12px;padding:8px 0;border-top:2px solid rgba(120,130,150,.22);font-weight:600">
      <span>${esc(appText('合计'))}</span>
      <span style="text-align:right">${esc(num(agg.requests))}</span>
      <span style="text-align:right">${esc(fmtTok(agg.input))}</span>
      <span style="text-align:right">${esc(fmtTok(agg.cacheRead))}</span>
      <span style="text-align:right">${esc(fmtTok(agg.output))}</span>
      <span style="text-align:right">${esc(fmtUsd(agg.cost))}</span>
    </div>`;
  const tableHtml = hasEstimate ? `<section class="dashboard-card dashboard-panel span-12">
    ${title('模型计费明细（本地估算 · 单位 USD）')}
    ${estModels.length ? tableHead + tableRows + tableTotal : `<div class="dashboard-empty-note">${esc(appText('当前筛选无数据'))}</div>`}
  </section>` : '';

  // ── 代码采纳（真实本地记录） ──
  let codeHtml = '';
  if (ct && ct.totals) {
    const ctt = ct.totals;
    const accepted = Number(ctt.acceptedLines || 0);
    const suggested = Number(ctt.suggestedLines || 0);
    const daily = Array.isArray(ct.daily) ? ct.daily : [];
    const dailyHtml = daily.length ? `<div style="margin-top:12px;display:flex;flex-direction:column;gap:6px">${daily.slice(-14).map((d) => {
      const a = Number(d.acceptedLines || 0);
      const s = Number(d.suggestedLines || 0);
      const w = Math.max(a, s) > 0 ? Math.round((a / Math.max(a, s)) * 100) : 0;
      return `<div style="display:flex;align-items:center;gap:8px;font-size:12px"><span style="width:88px;color:var(--muted,#6b7787)">${esc(d.date)}</span><span style="flex:1;height:8px;border-radius:4px;background:rgba(120,130,150,.15);overflow:hidden"><span style="display:block;height:100%;width:${w}%;background:linear-gradient(90deg,#22c55e,#0891b2)"></span></span><span style="min-width:160px;text-align:right;color:var(--muted,#6b7787)">${esc(appText('采纳'))} ${a.toLocaleString()} / ${esc(appText('建议'))} ${s.toLocaleString()}</span></div>`;
    }).join('')}</div>` : '';
    codeHtml = `<section class="dashboard-card dashboard-panel span-12">
      ${title('代码采纳（本地真实记录 · aiCodeTracking）')}
      <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:10px">
        ${statCard('采纳代码行', accepted.toLocaleString())}
        ${statCard('建议代码行', suggested.toLocaleString())}
        ${statCard('Composer 采纳', Number(ctt.composerAcceptedLines || 0).toLocaleString())}
        ${statCard('Tab 采纳', Number(ctt.tabAcceptedLines || 0).toLocaleString())}
      </div>
      ${dailyHtml}
    </section>`;
  }

  // ── 最近会话 ──
  const recent = Array.isArray(u.recent) ? u.recent : [];
  const recentHtml = `<section class="dashboard-card dashboard-panel span-12">
    ${title('最近会话')}
    ${recent.length ? `<div style="display:flex;flex-direction:column;gap:8px">${recent.map((r) => {
      const modelLabel = formatModelLabel(r.model);
      const name = (r.name || '').trim() || '(未命名会话)';
      const mode = (r.mode || '').trim();
      const rc = Number(r.contextTokens || 0);
      const ctxLabel = rc > 0 ? ` · ${formatDashboardMetric(rc)} tok` : '';
      return `<div style="display:flex;align-items:center;gap:10px;padding:8px 10px;border:1px solid rgba(120,130,150,.14);border-radius:10px">
        <div style="flex:1;min-width:0"><div style="font-size:13px;font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(name)}</div>
        <div style="font-size:11.5px;color:var(--muted,#6b7787);margin-top:2px">${modelLabel ? `<span>${esc(modelLabel)}</span> · ` : ''}${mode ? `<span>${esc(mode)}</span> · ` : ''}${esc(String(r.messageCount || 0))} ${esc(appText('条'))}${esc(ctxLabel)} · ${esc(formatRelativeTime(r.lastActiveAt))}</div></div>
      </div>`;
    }).join('')}</div>` : `<div class="dashboard-empty-note">${esc(appText('暂无会话'))}</div>`}
  </section>`;

  root.innerHTML = `
    <div class="dashboard-shell">
      <div class="db3-toolbar db3-toolbar--page">
        <div class="db3-toolbar-status"><span class="dashboard-fetch-state">${esc('Cursor ' + appText('本地估算') + ' · ' + lastUpdated)}</span>${window.__consoleV3.cursorUsageLoading ? `<span class="dashboard-fetch-state" style="opacity:.7">· ${esc(appText('刷新中…'))}</span>` : ''}${accBits.length ? `<span class="dashboard-fetch-state" style="opacity:.75">${accBits.join(' · ')}</span>` : ''}</div>
        <div class="db3-toolbar-actions">${filterPills}${refreshBtn}</div>
      </div>
      <div class="cursor-est-banner">${esc(appText('本地估算 · Cursor 不保存逐条 token/账单，按“每轮重发上下文”累计并按公开定价估算，仅数量级参考，实际以 cursor.com 为准。'))}</div>
      ${heroHtml}
      <div class="dashboard-grid dashboard-grid-single" style="margin-top:14px">
        ${breakdownHtml}
        ${trendHtml}
        ${tableHtml}
        ${codeHtml}
        ${recentHtml}
      </div>
    </div>`;

  root.querySelectorAll('[data-cursor-dd]').forEach((dd) => {
    const key = dd.getAttribute('data-cursor-dd') === 'days' ? 'days' : 'model';
    dd.querySelector('[data-cursor-dd-trigger]')?.addEventListener('click', (e) => {
      e.stopPropagation();
      const willOpen = !dd.classList.contains('open');
      root.querySelectorAll('[data-cursor-dd]').forEach((other) => other.classList.remove('open'));
      if (willOpen) {
        dd.classList.add('open');
        setTimeout(() => {
          const onDoc = (ev) => {
            if (!dd.contains(ev.target)) {
              dd.classList.remove('open');
              document.removeEventListener('click', onDoc);
            }
          };
          document.addEventListener('click', onDoc);
        }, 0);
      }
    });
    dd.querySelectorAll('[data-cursor-dd-value]').forEach((opt) => {
      opt.addEventListener('click', (e) => {
        e.stopPropagation();
        const raw = opt.getAttribute('data-cursor-dd-value');
        state.cursorDash[key] = key === 'days' ? Number(raw) : raw;
        renderDashboardPage();
      });
    });
  });
}

function renderDashboardPage() {
  const root = el('dashboardPage');
  if (!root) return;

  renderDashboardToolRail();
  const codex = state.current || {};
  const claude = state.claudeCodeState || {};
  const openclaw = state.openclawState || {};
  const win = getDashboardWindow();
  let dashboardTool = getDashboardToolDef(state.dashboardTool)?.key || 'codex';
  state.dashboardTool = dashboardTool;
  if (dashboardTool === 'cursor') {
    renderCursorDashboard(root);
    return;
  }
  const dashboardDef = getDashboardToolDef(dashboardTool) || DASHBOARD_USAGE_TOOL_DEFS[0];
  const toolLabel = dashboardDef.label;
  const codexMetricsRaw = getDashboardMetricsForTool('codex', win) || { totals: { input: 0, cachedInput: 0, output: 0, reasoning: 0, total: 0 }, daily: [], providers: [], sessions: [], models: [] };
  const opencodeMetricsRaw = getDashboardMetricsForTool('opencode', win) || { totals: { input: 0, output: 0, reasoning: 0, cacheRead: 0, cacheCreation: 0, total: 0, cost: 0 }, daily: [], providers: [], sessions: [], models: [] };
  const genericMetricsRaw = isGenericUsageDashboardTool(dashboardTool) ? getDashboardUsageMetricsForTool(dashboardTool, win) : null;
  // 过滤后的数据：Codex / OpenCode / session-backed tools 共享 provider + model 筛选
  const codexMetrics = applyDashboardFilter(codexMetricsRaw, state.dashboardFilter, 'codex');
  const opencodeMetrics = applyDashboardFilter(opencodeMetricsRaw, state.dashboardFilter, 'opencode');
  const genericMetrics = genericMetricsRaw ? applyDashboardFilter(genericMetricsRaw, state.dashboardFilter, dashboardTool) : null;
  const openclawChannels = getOpenClawConsoleChannels(openclaw.config || {});
  const openclawProviders = getOpenClawConsoleProviders(openclaw.config || {});
  const hasCodexMetrics = Boolean(getDashboardMetricsForTool('codex', win));
  const hasOpenCodeMetrics = Boolean(getDashboardMetricsForTool('opencode', win));
  const hasGenericMetrics = Boolean(genericMetricsRaw);
  const isRouterProfileDashboard = false;
  const hasCurrentMetrics = dashboardTool === 'codex'
    ? hasCodexMetrics
    : dashboardTool === 'opencode'
      ? hasOpenCodeMetrics
      : dashboardTool === 'claudecode'
        ? hasClaudeDashboardData()
        : isGenericUsageDashboardTool(dashboardTool)
          ? hasGenericMetrics
          : isRouterProfileDashboard;
  const dashboardRefreshing = dashboardTool === 'claudecode' ? Boolean(state.dashboardRefreshing) : isDashboardRefreshingForTool(dashboardTool, win);
  const isLoading = dashboardTool === 'claudecode'
    ? Boolean(state.dashboardLoading)
    : Boolean((state.dashboardLoading && !hasCurrentMetrics) || (state.dashboardLoading && dashboardRefreshing) || (dashboardRefreshing && !hasCurrentMetrics));
  const lastUpdated = formatDashboardUpdatedAt(codexMetrics.generatedAt);
  const opencodeLastUpdated = formatDashboardUpdatedAt(opencodeMetrics.generatedAt);
  const claudeLastUpdated = formatDashboardUpdatedAt(claude.usage?.generatedAt);
  const genericLastUpdated = formatDashboardUpdatedAt(genericMetricsRaw?.generatedAt);
  const showDashboardRefresh = dashboardTool === 'claudecode' || isApiDashboardTool(dashboardTool) || isGenericUsageDashboardTool(dashboardTool);
  const daysWindow = win.days;
  const winFrom = win.from;
  const winTo = win.to;
  const winLabel = formatDashboardWindowLabel(win);
  const winRecentLabel = formatDashboardRecentWindowLabel(win);
  const genericUsageStatus = getDashboardUsageStatusMeta(genericMetricsRaw || {});
  const dashboardStatusText = dashboardTool === 'claudecode'
    ? (isLoading ? '正在统计本地 Claude Code token…' : (claudeLastUpdated || '统计已完成'))
    : dashboardTool === 'opencode'
      ? (isLoading ? '正在统计本地 OpenCode token…' : (opencodeLastUpdated || '统计已完成'))
      : isGenericUsageDashboardTool(dashboardTool)
        ? (isLoading ? `正在读取本地 ${toolLabel} 用量…` : `${genericUsageStatus.label}${genericLastUpdated ? ` · ${genericLastUpdated}` : ''}`)
        : (isLoading ? '正在统计本地 Codex token…' : (lastUpdated || '统计已完成'));
  if (el('pageTitle')) el('pageTitle').textContent = appText('数据看板');
  if (el('pageSubtitle')) {
    el('pageSubtitle').textContent = isRouterProfileDashboard
        ? `${toolLabel} · Router Profile、客户端接入与资产联动`
      : `${toolLabel} · ${appText(dashboardStatusText)} · ${isEnglishAppLanguage() ? winRecentLabel : (win.custom ? winLabel : '最近 ' + winLabel)}`;
  }

  // ── Stat strip ──
  const statStrip = (items = []) => `
    <div class="db2-stat-cards">
      ${items.map(({ label, value, sub, accent, isCost }) => `
        <div class="db2-stat-card ${accent ? 'db2-stat-card--accent' : ''} ${isCost ? 'db2-stat-card--cost' : ''}">
          <div class="db2-sc-label">${escapeHtml(appText(label))}</div>
          <div class="db2-sc-value">${escapeHtml(String(value))}</div>
          ${sub ? `<div class="db2-sc-sub">${escapeHtml(appText(String(sub)))}</div>` : ''}
        </div>
      `).join('')}
    </div>`;
  const heroStatsHtml = (stats) => `
    <div class="db3-hero-stats">
      ${stats.map((s) => `
        <div class="db3-hero-stat ${s.emphasis ? 'db3-hero-stat-emph' : ''}">
          <div class="db3-hero-value">${escapeHtml(String(s.value))}</div>
          <div class="db3-hero-label">${escapeHtml(appText(s.label))}</div>
        </div>`).join('')}
    </div>`;

  // ── Token mix ──
  const miniBars = (items = []) => renderDashboardTokenMix(items);

  // ── Key-Value list ──
  const kvList = (rows = []) => `
    <div class="db2-kv-list">
      ${rows.map(({ label, value, accent }) => `
        <div class="db2-kv-row">
          <span class="db2-kv-label">${escapeHtml(appText(label))}</span>
          <span class="db2-kv-value ${accent ? 'db2-kv-value--accent' : ''}">${escapeHtml(appText(String(value)))}</span>
        </div>
      `).join('')}
    </div>`;

  // ── Codex Token percentage bar ──
  // ── Filter daily data by calendar date cutoff ──
  // 区间过滤：同时尊重起点和终点，自定义日期范围支持任意 N 天聚合
  const codexDaily = (codexMetrics.daily || []).filter((d) => {
    const date = d.date || '';
    return date >= winFrom && date <= winTo;
  });

  const codexModels = codexMetrics.models || [];
  const codexModelTotal = codexModels.reduce((sum, entry) => sum + (entry.totals?.total || 0), 0);
  const codexModelTotals = codexModels.reduce((sum, entry) => {
    const totals = entry?.totals || {};
    sum.input += Number(totals.input || 0);
    sum.output += Number(totals.output || 0);
    sum.cachedInput += Number(totals.cachedInput || totals.cacheRead || 0);
    sum.cacheCreation += Number(totals.cacheCreation || 0);
    sum.reasoning += Number(totals.reasoning || 0);
    return sum;
  }, { input: 0, output: 0, cachedInput: 0, cacheCreation: 0, reasoning: 0 });
  const codexFallbackTotals = normalizeDashboardUsageTotals(codexMetrics.totals || {});
  const codexTotal = codexModelTotal || codexFallbackTotals.total;
  const codexInput = codexModels.length ? codexModelTotals.input : codexFallbackTotals.input;
  const codexOutput = codexModels.length ? codexModelTotals.output : codexFallbackTotals.output;
  const codexCached = codexModels.length ? codexModelTotals.cachedInput : codexFallbackTotals.cachedInput;
  const codexCacheCreation = codexModels.length ? codexModelTotals.cacheCreation : codexFallbackTotals.cacheCreation;
  const codexCacheCreationAvailable = codexModels.length
    ? codexModels.some((entry) => entry?.totals?.cacheCreationAvailable === true)
    : codexFallbackTotals.cacheCreationAvailable;
  const codexReasoning = codexModels.length ? codexModelTotals.reasoning : codexFallbackTotals.reasoning;

  // 顶部和模型计费明细必须使用同一滚动窗口、同一模型聚合口径。
  // 后端 days=1 表示最近 24 小时，不能再按本地/UTC 日历日期裁掉跨日部分。
  const codexTotalCost = codexModels.reduce((sum, entry) => sum + Number(calcModelCost(entry)?.totalCost || 0), 0);

  const codexCacheHitPct = codexTotal ? Math.round(codexCached / codexTotal * 100) : 0;
  const codexInputPct = codexTotal ? Math.round(codexInput / codexTotal * 100) : 0;
  const codexTopModel = codexModels[0] ? (lookupModelPricingEntry(codexModels[0].model)?.pricing?.label || codexModels[0].model) : '—';
  const codexHeroStats = [
    { label: '本期消耗 · USD', value: codexTotalCost ? formatDashboardUsd(codexTotalCost, { min: 2, max: 2 }) : '$0.00', emphasis: true },
    { label: '总 Token', value: formatDashboardMetric(codexTotal) },
    { label: codexReasoning ? '输出 / 推理' : '输出 Token', value: formatDashboardMetric(codexOutput + codexReasoning) },
    { label: '缓存读取率', value: codexTotal ? `${codexCacheHitPct}%` : '—' },
  ];
  const codexBreakdownItems = [
    { label: '输入', value: codexInputPct, meta: codexInput },
    { label: '输出', value: codexTotal ? Math.round(codexOutput / codexTotal * 100) : 0, meta: codexOutput },
    { label: '缓存读取', value: codexCacheHitPct, meta: codexCached },
    { label: codexCacheCreationAvailable ? '缓存创建' : '缓存创建不可用', value: codexCacheCreationAvailable && codexTotal ? Math.round(codexCacheCreation / codexTotal * 100) : 0, meta: codexCacheCreationAvailable ? codexCacheCreation : '—' },
    { label: '推理', value: codexTotal ? Math.round(codexReasoning / codexTotal * 100) : 0, meta: codexReasoning },
  ];

  const codexHtml = (!hasCodexMetrics && isLoading) ? renderDashboardLoadingCard() : `
    <div class="db2-layout">
      <section class="db3-hero db3-hero--codex">
        ${heroStatsHtml(codexHeroStats)}
        <div class="db3-hero-chart-wrap">
          <div class="db3-hero-chart-head">
            <span class="db3-hero-chart-title">${escapeHtml(appText('Token 用量趋势'))}</span>
            <span class="db3-hero-chart-meta">${escapeHtml(winRecentLabel)} · ${escapeHtml(formatDashboardModelCount(codexModels.length))} · ${escapeHtml(codexTopModel)}</span>
          </div>
          ${renderDashboardInteractiveChart(codexDaily.map((item) => ({ label: item.date.slice(5), value: item.total || 0, input: item.input || 0, output: item.output || 0, cached: item.cachedInput || 0 })), { stroke: '#5b8cff', showCost: true, models: codexModels })}
        </div>
      </section>

      <div class="db3-analytics-board">
        <section class="db2-section db3-panel db3-panel--standards">
          <div class="db2-card-head">
          <div class="db2-card-title">
              <svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"><path d="M8 1.5v13M11.5 4.5H6.25a2.25 2.25 0 1 0 0 4.5H9.75a2.25 2.25 0 0 1 0 4.5H4"/></svg>
              ${escapeHtml(appText('GPT 计费标准'))}
            </div>
            <div class="db2-card-meta">${escapeHtml(appText('GPT-5.4 / GPT-5.3 Codex 检测结果'))}</div>
          </div>
          ${renderPricingStandardsCards(codexModels, ['gpt-5.6-sol', 'gpt-5.6-terra', 'gpt-5.6-luna'])}
        </section>

        <section class="db2-section db3-panel db3-panel--primary">
          <div class="db2-card-head">
            <div class="db2-card-title">
              <svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><rect x="2" y="2" width="12" height="12" rx="2"/><path d="M6 6h4M6 8h4M6 10h2"/></svg>
              ${escapeHtml(appText('模型计费明细'))}
            </div>
            <div class="db2-card-meta">${escapeHtml(appText('按 OpenAI 官方定价估算 · 单位 USD / 1M tokens'))}</div>
          </div>
          ${renderModelCostRows(codexModels, codexModelTotal)}
        </section>

        <section class="db2-section db3-panel db3-panel--mix">
          <div class="db2-card-head">
            <div class="db2-card-title">
              <svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M2 10.5h12M3.5 8.5l2-2 2.5 2 4.5-4"/></svg>
              ${escapeHtml(appText('Token 构成'))}
            </div>
            <div class="db2-card-meta">${escapeHtml(appText('输入 / 输出 / 缓存创建 / 缓存读取 / 推理'))}</div>
          </div>
          ${miniBars(codexBreakdownItems)}
        </section>

        <section class="db2-section db3-panel db3-panel--trend">
          <div class="db2-card-head">
            <div class="db2-card-title">
              <svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"><path d="M8 1.5v13M11.5 4.5H6.25a2.25 2.25 0 1 0 0 4.5H9.75a2.25 2.25 0 0 1 0 4.5H4"/></svg>
              ${escapeHtml(appText('费用趋势'))}
            </div>
            <div class="db2-card-meta">${escapeHtml(appText('每日预估消耗'))}</div>
          </div>
          ${renderDashboardCostTrendChart(codexDaily, codexModels)}
        </section>

        <section class="db2-section db3-panel db3-panel--dist">
          <div class="db2-card-head">
            <div class="db2-card-title">
              <svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M2 5l6-3 6 3v6l-6 3-6-3z"/><path d="M2 5l6 3m0 6V8m6-3l-6 3"/></svg>
              ${escapeHtml(appText('模型分布'))}
            </div>
            <div class="db2-card-meta">${escapeHtml(isEnglishAppLanguage() ? `Scanned ${codexModels.length} models` : `累计扫描 ${codexModels.length} 个模型`)}</div>
          </div>
          ${renderDashboardModelDistChart(codexModels, codexModelTotal)}
        </section>
      </div>
    </div>`;

  const opencodeDaily = (opencodeMetrics.daily || []).filter((d) => {
    const date = d.date || '';
    return date >= winFrom && date <= winTo;
  });
  const opencodeTotal = opencodeDaily.reduce((sum, item) => sum + (item.total || 0), 0);
  const opencodeInput = opencodeDaily.reduce((sum, item) => sum + (item.input || 0), 0);
  const opencodeOutput = opencodeDaily.reduce((sum, item) => sum + (item.output || 0), 0);
  const opencodeReasoning = opencodeDaily.reduce((sum, item) => sum + (item.reasoning || 0), 0);
  const opencodeCacheRead = opencodeDaily.reduce((sum, item) => sum + (item.cacheRead || 0), 0);
  const opencodeCacheWrite = opencodeDaily.reduce((sum, item) => sum + (item.cacheCreation || 0), 0);
  const opencodeCost = opencodeDaily.reduce((sum, item) => sum + (item.cost || 0), 0);
  const opencodeModels = opencodeMetrics.models || [];
  const opencodeModelTotal = opencodeModels.reduce((sum, entry) => sum + (entry.totals?.total || 0), 0);
  const opencodeTopModel = opencodeModels[0]
    ? (lookupModelPricingEntry(opencodeModels[0].model)?.pricing?.label || opencodeModels[0].model)
    : '—';
  const opencodeCacheHitPct = opencodeTotal ? Math.round(opencodeCacheRead / opencodeTotal * 100) : 0;
  const opencodeHeroStats = [
    { label: '本期消耗 · USD', value: opencodeCost ? formatDashboardUsd(opencodeCost, { min: 2, max: 4 }) : '$0.00', emphasis: true },
    { label: '总 Token', value: formatDashboardMetric(opencodeTotal) },
    { label: opencodeReasoning ? '输出 / 推理' : '输出 Token', value: formatDashboardMetric(opencodeOutput + opencodeReasoning) },
    { label: '缓存读取率', value: opencodeTotal ? `${opencodeCacheHitPct}%` : '—' },
  ];
  const opencodeBreakdownItems = [
    { label: '输入', value: opencodeTotal ? Math.round(opencodeInput / opencodeTotal * 100) : 0, meta: opencodeInput },
    { label: '输出', value: opencodeTotal ? Math.round(opencodeOutput / opencodeTotal * 100) : 0, meta: opencodeOutput },
    { label: '推理', value: opencodeTotal ? Math.round(opencodeReasoning / opencodeTotal * 100) : 0, meta: opencodeReasoning },
    { label: '缓存读', value: opencodeTotal ? Math.round(opencodeCacheRead / opencodeTotal * 100) : 0, meta: opencodeCacheRead },
    { label: '缓存写', value: opencodeTotal ? Math.round(opencodeCacheWrite / opencodeTotal * 100) : 0, meta: opencodeCacheWrite },
  ];

  const opencodeHtml = (!hasOpenCodeMetrics && isLoading) ? renderDashboardLoadingCard() : `
    <div class="db2-layout">
      <section class="db3-hero db3-hero--codex">
        ${heroStatsHtml(opencodeHeroStats)}
        <div class="db3-hero-chart-wrap">
          <div class="db3-hero-chart-head">
            <span class="db3-hero-chart-title">${escapeHtml(appText('Token 用量趋势'))}</span>
            <span class="db3-hero-chart-meta">${escapeHtml(winRecentLabel)} · ${escapeHtml(formatDashboardModelCount(opencodeModels.length))} · ${escapeHtml(opencodeTopModel)}</span>
          </div>
          ${renderDashboardInteractiveChart(opencodeDaily.map((item) => ({ label: item.date.slice(5), value: item.total || 0, input: item.input || 0, output: (item.output || 0) + (item.reasoning || 0), cached: item.cacheRead || 0 })), { stroke: '#6b86ff' })}
        </div>
      </section>

      <div class="db3-analytics-board">
        <section class="db2-section db3-panel db3-panel--standards">
          <div class="db2-card-head">
            <div class="db2-card-title">
              <svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"><path d="M8 1.5v13M11.5 4.5H6.25a2.25 2.25 0 1 0 0 4.5H9.75a2.25 2.25 0 0 1 0 4.5H4"/></svg>
              ${escapeHtml(appText('官方计费标准'))}
            </div>
            <div class="db2-card-meta">${escapeHtml(appText('按已检测模型匹配 OpenAI / Anthropic 官方价目'))}</div>
          </div>
          ${renderPricingStandardsCards(opencodeModels, ['gpt-5.4', 'gpt-5.3-codex', 'gpt-5.2-codex'])}
        </section>

        <section class="db2-section db3-panel db3-panel--primary">
          <div class="db2-card-head">
            <div class="db2-card-title">
              <svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><rect x="2" y="2" width="12" height="12" rx="2"/><path d="M6 6h4M6 8h4M6 10h2"/></svg>
              ${escapeHtml(appText('模型计费明细'))}
            </div>
            <div class="db2-card-meta">${escapeHtml(appText('本地会话 token 统计 + 官方价目映射'))}</div>
          </div>
          ${renderModelCostRows(opencodeModels, opencodeModelTotal)}
        </section>

        <section class="db2-section db3-panel db3-panel--mix">
          <div class="db2-card-head">
            <div class="db2-card-title">
              <svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M2 10.5h12M3.5 8.5l2-2 2.5 2 4.5-4"/></svg>
              ${escapeHtml(appText('Token 构成'))}
            </div>
            <div class="db2-card-meta">${escapeHtml(appText('输入 / 输出 / 推理 / 缓存读写'))}</div>
          </div>
          ${miniBars(opencodeBreakdownItems)}
        </section>

        <section class="db2-section db3-panel db3-panel--trend">
          <div class="db2-card-head">
            <div class="db2-card-title">
              <svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"><path d="M8 1.5v13M11.5 4.5H6.25a2.25 2.25 0 1 0 0 4.5H9.75a2.25 2.25 0 0 1 0 4.5H4"/></svg>
              ${escapeHtml(appText('费用趋势'))}
            </div>
            <div class="db2-card-meta">${escapeHtml(appText('来自 OpenCode 本地会话的实际 cost 字段'))}</div>
          </div>
          ${renderCostTrendPanel(opencodeDaily.map((item) => ({ label: (item.date || '').slice(5), value: item.cost || 0 })), isEnglishAppLanguage() ? `${winRecentLabel} total` : `${winRecentLabel}合计`, '#5b8cff')}
        </section>

        <section class="db2-section db3-panel db3-panel--dist">
          <div class="db2-card-head">
            <div class="db2-card-title">
              <svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M2 5l6-3 6 3v6l-6 3-6-3z"/><path d="M2 5l6 3m0 6V8m6-3l-6 3"/></svg>
              ${escapeHtml(appText('模型分布'))}
            </div>
            <div class="db2-card-meta">${escapeHtml(isEnglishAppLanguage() ? `Scanned ${opencodeModels.length} models` : `累计扫描 ${opencodeModels.length} 个模型`)}</div>
          </div>
          ${renderDashboardModelDistChart(opencodeModels, opencodeModelTotal)}
        </section>
      </div>
    </div>`;

  // ── Claude Code HTML ──
  const claudeAllTotal = claude.usage?.totals?.total || 0;
  const claudeAllInput = claude.usage?.totals?.input || 0;
  const claudeAllOutput = claude.usage?.totals?.output || 0;
  const claudeAllCacheRead = claude.usage?.totals?.cacheRead || 0;
  const claudeAllCacheCreate = claude.usage?.totals?.cacheCreation || 0;
  const claudeAllCost = claude.usage?.totals?.cost || 0;
  const claudeOfficialCost = claude.usage?.officialCost || 0;
  const claudeAllModels = claude.usage?.models || [];
  const claudeDaily = claude.usage?.daily || [];
  const claudeDailyModelTokens = claude.usage?.dailyModelTokens || [];

  // 区间过滤，自定义日期范围下也走 from/to 两端
  const claudeDailySliced = claudeDaily.filter((d) => {
    const date = d.date || '';
    return date >= winFrom && date <= winTo;
  });

  // Windowed totals from filtered daily data (no fallback — show 0 if no activity in window)
  const ct = {
    total: claudeDailySliced.reduce((s, d) => s + (d.total || 0), 0),
    input: claudeDailySliced.reduce((s, d) => s + (d.input || 0), 0),
    output: claudeDailySliced.reduce((s, d) => s + (d.output || 0), 0),
    cacheRead: claudeDailySliced.reduce((s, d) => s + (d.cacheRead || 0), 0),
    cacheCreate: claudeDailySliced.reduce((s, d) => s + (d.cacheCreation || 0), 0),
    cost: claudeDailySliced.reduce((s, d) => s + (d.cost || 0), 0),
  };

  // ── 取窗口内出现过的模型集合（用作 claudeAllModels 的过滤器） ──
  // dailyModelTokens 只记每个模型的 total，没拆 input/cacheRead/cacheCreation。
  // 旧实现里用 `total * 0.85` 当 input、cache 全 0，再丢给 calcModelCost，
  // → 4.74B 假 input × $5 = $44K 这种离谱估算。
  // 现在改为：用 claudeAllModels（含真实 cacheRead / cacheCreation）作为基础，
  // dailyModelTokens 仅用来筛掉窗口外的模型。
  const claudeWindowedDMT = claudeDailyModelTokens.filter((d) => {
    const date = d.date || '';
    return date >= winFrom && date <= winTo;
  });
  let claudeModels;
  if (claudeWindowedDMT.length > 0) {
    const windowedSet = new Set();
    claudeWindowedDMT.forEach((entry) => {
      const byModel = entry.tokensByModel || {};
      Object.keys(byModel).forEach((m) => windowedSet.add(m));
    });
    // 优先保留窗口期内出现过的模型；若 claudeAllModels 没列全，
    // 还可以从 dailyModelTokens 兜底补一份 total（cache 仍未知，calcModelCost 会得到偏低值，
    // 但不会再出现"假 input × 全价 = 天价"这种灾难）。
    const fromAll = (claudeAllModels || []).filter((m) => windowedSet.has(m.model));
    const knownModels = new Set(fromAll.map((m) => m.model));
    const fallbackTokens = {};
    claudeWindowedDMT.forEach((entry) => {
      const byModel = entry.tokensByModel || {};
      for (const [model, tokens] of Object.entries(byModel)) {
        if (knownModels.has(model)) continue;
        fallbackTokens[model] = (fallbackTokens[model] || 0) + tokens;
      }
    });
    const fallbackEntries = Object.entries(fallbackTokens).map(([model, total]) => ({
      model,
      totals: { total, input: 0, output: 0, cacheRead: 0, cacheCreation: 0, cost: 0 },
    }));
    claudeModels = [...fromAll, ...fallbackEntries]
      .sort((a, b) => (b.totals?.total || 0) - (a.totals?.total || 0));
  } else {
    claudeModels = claudeAllModels;
  }
  const claudeModelTotal = claudeModels.reduce((s, m) => s + (m.totals?.total || 0), 0);

  // ── New Hero (Claude Code) ───────────────────────────────────
  const claudeCacheHitPct = ct.total ? Math.round(ct.cacheRead / ct.total * 100) : 0;
  const claudeHeroStats = [
    { key: 'cost',   label: '本期消耗 · USD', value: ct.cost ? '$' + ct.cost.toFixed(2) : '$0.00', emphasis: true },
    { key: 'total',  label: '总 TOKEN',        value: formatDashboardMetric(ct.total) },
    { key: 'output', label: '输出',             value: formatDashboardMetric(ct.output) },
    { key: 'cache',  label: '缓存读取率',       value: ct.total ? claudeCacheHitPct + '%' : '—' },
  ];

  // Build filled series once so the hero chart + subsequent renders share it.
  const claudeFilledSeries = (() => {
    const dailyMap = {};
    claudeDailySliced.forEach((d) => { if (d.date) dailyMap[d.date] = d; });
    const out = [];
    const fromMs = Date.parse(`${winFrom}T00:00:00Z`);
    for (let i = 0; i < daysWindow; i++) {
      const dt = new Date(fromMs + i * 86400000);
      const key = dt.toISOString().slice(0, 10);
      const d = dailyMap[key] || {};
      out.push({
        label: key.slice(5),
        value: d.total || 0,
        input: d.input || 0,
        output: d.output || 0,
        cached: d.cacheRead || 0,
        // tooltip 把 cacheCreation 也带上，否则 Claude 单日缓存写入那段会少算
        cacheCreation: d.cacheCreation || 0,
      });
    }
    return out;
  })();

  const claudeHtml = `
    <div class="db2-layout">

      <!-- HERO · 4 指标 + 主体折线图 -->
      <section class="db3-hero">
        ${heroStatsHtml(claudeHeroStats)}
        <div class="db3-hero-chart-wrap">
          <div class="db3-hero-chart-head">
            <span class="db3-hero-chart-title">${escapeHtml(appText('Token 用量趋势'))}</span>
            <span class="db3-hero-chart-meta">${escapeHtml(winRecentLabel)} · ${escapeHtml(appText('悬停看当日详情'))}</span>
          </div>
          ${renderDashboardInteractiveChart(claudeFilledSeries, { stroke: '#7c3aed', showCost: true, models: claudeModels })}
        </div>
      </section>

      <div class="db3-analytics-board db3-analytics-board--claude">
        <section class="db2-section db3-panel db3-panel--trend db3-panel--chart">
          <div class="db2-card-head">
            <div class="db2-card-title">
              <svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"><path d="M8 1.5v13M11.5 4.5H6.25a2.25 2.25 0 1 0 0 4.5H9.75a2.25 2.25 0 0 1 0 4.5H4"/></svg>
              ${escapeHtml(appText('费用趋势'))}
            </div>
            <div class="db2-card-meta">${escapeHtml(appText('按 Anthropic 官方定价估算'))}</div>
          </div>
          ${renderClaudeCostTrendChart(claudeDailySliced, daysWindow)}
        </section>

        <section class="db2-section db3-panel db3-panel--dist">
          <div class="db2-card-head">
            <div class="db2-card-title">
              <svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M2 5l6-3 6 3v6l-6 3-6-3z"/><path d="M2 5l6 3m0 6V8m6-3l-6 3"/></svg>
              ${escapeHtml(appText('模型分布'))}
            </div>
            <div class="db2-card-meta">${escapeHtml(winRecentLabel)} · ${escapeHtml(formatDashboardModelCount(claudeModels.length))}</div>
          </div>
          ${renderDashboardModelDistChart(claudeModels, claudeModelTotal)}
        </section>

        <section class="db2-section db3-panel db3-panel--primary db3-panel--pricing">
          <div class="db2-card-head">
            <div class="db2-card-title">
              <svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><rect x="2" y="2" width="12" height="12" rx="2"/><path d="M6 6h4M6 8h4M6 10h2"/></svg>
              ${escapeHtml(appText('模型消耗明细'))}
            </div>
            <div class="db2-card-meta">${escapeHtml(appText('按 Anthropic 定价估算'))}</div>
          </div>
          ${renderModelCostRows(claudeModels, claudeModelTotal)}
        </section>
      </div>
    </div>`;

  // ── OpenClaw HTML ──
  const openclawHtml = `
    <div class="db2-layout">
      ${statStrip([
        { label: 'Gateway', value: getOpenClawGatewayStatusLabel(openclaw), sub: openclaw.gatewayUrl || '–', accent: openclaw.gatewayReachable },
        { label: '渠道数', value: String(openclawChannels.length), sub: openclawChannels.slice(0, 3).map(c => c.label).join('、') || '–' },
        { label: 'Provider', value: String(openclawProviders.length), sub: '已配置接入' },
        { label: '端口监听', value: openclaw.gatewayPortListening ? '活跃' : '未检测', sub: '本地 Gateway 端口' },
        { label: '端口冲突', value: openclaw.gatewayPortConflict ? '⚠ 有冲突' : '无', sub: '' },
      ])}
      <div class="db2-main-grid">
        <!-- LEFT: Gateway details -->
        <div class="db2-col">
          <div class="db2-section">
            <div class="db2-card-head">
              <div class="db2-card-title">${escapeHtml(appText('Gateway 状态详情'))}</div>
            </div>
            ${kvList([
              { label: 'Gateway 状态', value: getOpenClawGatewayStatusLabel(openclaw) },
              { label: 'Gateway URL', value: openclaw.gatewayUrl || '–' },
              { label: '端口监听', value: openclaw.gatewayPortListening ? '是' : '否' },
              { label: '可达性', value: openclaw.gatewayReachable ? '✓ 已连通' : '✗ 不可达' },
              { label: '端口冲突', value: openclaw.gatewayPortConflict ? '⚠ 存在冲突' : '无' },
            ])}
          </div>
        </div>

        <!-- RIGHT: Channels + Providers -->
        <div class="db2-col">
          <div class="db2-section">
            <div class="db2-card-head">
              <div class="db2-card-title">${escapeHtml(appText('渠道列表'))}</div>
              <div class="db2-card-meta">${escapeHtml(isEnglishAppLanguage() ? `${openclawChannels.length} items` : `${openclawChannels.length} 个`)}</div>
            </div>
            ${openclawChannels.length ? kvList(openclawChannels.map(c => ({ label: c.label, value: c.key }))) : `<div class="db2-empty">${escapeHtml(appText('暂无已配置渠道'))}</div>`}
          </div>

          <div class="db2-section">
            <div class="db2-card-head">
              <div class="db2-card-title">${escapeHtml(appText('Provider 列表'))}</div>
              <div class="db2-card-meta">${escapeHtml(isEnglishAppLanguage() ? `${openclawProviders.length} items` : `${openclawProviders.length} 个`)}</div>
            </div>
            ${openclawProviders.length
    ? kvList(openclawProviders.slice(0, 12).map((provider) => ({
      label: provider.key,
	      value: provider.api || '未知协议',
	    })))
	    : `<div class="db2-empty">${escapeHtml(appText('暂无已配置 Provider'))}</div>`}
          </div>
        </div>
      </div>
    </div>`;

  const routerProfileHtml = (() => {
    const endpoint = getProviderRouterEndpoint(dashboardTool);
    const protocol = isProviderRouterAnthropicTool(dashboardTool) ? 'Anthropic' : 'OpenAI-compatible';
    const nativeFile = getConfigEditorShellMeta(dashboardTool).files;
    const writeMode = dashboardTool === 'hermes' ? 'config.yaml + .env + easyaiconfig.router' : 'easyaiconfig.router';
    const nativeProviderStatus = dashboardTool === 'hermes' ? '已接入 Hermes custom provider' : '安全 profile，等待官方原生字段确认';
    return `
    <div class="db2-layout">
      ${statStrip([
        { label: '接入模式', value: 'Router Profile', sub: protocol, accent: true },
        { label: 'Base URL', value: endpoint, sub: '本地网关客户端入口' },
        { label: 'API Key', value: PROVIDER_ROUTER_CLIENT_KEY, sub: '本机固定 key' },
        { label: '配置文件', value: nativeFile, sub: dashboardTool === 'hermes' ? '原生 Provider 写入' : '命名空间写入' },
      ])}
      <div class="db2-main-grid">
        <div class="db2-col">
          <div class="db2-section">
            <div class="db2-card-head">
              <div class="db2-card-title">${escapeHtml(appText('Router 客户端'))}</div>
              <div class="db2-card-meta">${escapeHtml(protocol)}</div>
            </div>
            ${kvList([
              { label: '客户端', value: toolLabel },
              { label: 'Base URL', value: endpoint },
              { label: 'API Key', value: PROVIDER_ROUTER_CLIENT_KEY },
              { label: '写入方式', value: writeMode },
            ])}
            <div class="editor-actions-inline">
              <button type="button" class="primary" data-cfg-router-apply="${escapeHtml(dashboardTool)}">写入 Router 配置</button>
              <button type="button" class="secondary" data-cfg-router-open="${escapeHtml(dashboardTool)}">打开 Router 面板</button>
            </div>
          </div>
        </div>
        <div class="db2-col">
          <div class="db2-section">
            <div class="db2-card-head">
              <div class="db2-card-title">${escapeHtml(appText('覆盖边界'))}</div>
              <div class="db2-card-meta">${escapeHtml(nativeFile)}</div>
            </div>
            ${kvList([
              { label: '现有配置', value: '保留' },
              { label: 'MCP / 原生字段', value: '不覆盖未知字段' },
              { label: '资产联动', value: 'Prompts / Sessions / Skills 层继续展开' },
              { label: '原生 provider 写入', value: nativeProviderStatus },
            ])}
          </div>
        </div>
      </div>
    </div>`;
  })();

  const content = dashboardTool === 'codex'
    ? codexHtml
    : dashboardTool === 'claudecode'
      ? claudeHtml
      : dashboardTool === 'opencode'
        ? opencodeHtml
        : isGenericUsageDashboardTool(dashboardTool)
          ? renderGenericUsageDashboard(dashboardTool, genericMetrics, win, { isLoading })
          : isRouterProfileDashboard
            ? routerProfileHtml
            : codexHtml;
  const filterMetricsRaw = dashboardTool === 'codex'
    ? codexMetricsRaw
    : dashboardTool === 'opencode'
      ? opencodeMetricsRaw
      : isGenericUsageDashboardTool(dashboardTool)
        ? genericMetricsRaw
        : null;

  // Sync the left-rail active state with the current dashboardTool.
  document.querySelectorAll('[data-dashboard-rail-tool]').forEach((btn) => {
    btn.classList.toggle('active', btn.getAttribute('data-dashboard-rail-tool') === dashboardTool);
  });

  root.innerHTML = `
    <div class="dashboard-shell ${isLoading ? 'is-loading' : ''}">
      <div class="db3-toolbar db3-toolbar--page">
        <div class="db3-toolbar-status">
	          ${showDashboardRefresh ? `<span class="dashboard-fetch-state ${isLoading ? 'loading' : ''}">${escapeHtml(appText(dashboardStatusText))}</span>` : ''}
        </div>
        <div class="db3-toolbar-actions">
          ${dashboardTool === 'claudecode' ? renderClaudeScopeDropdown() : ''}
          ${filterMetricsRaw ? renderDashboardProviderFilter(filterMetricsRaw) : ''}
          ${filterMetricsRaw ? renderDashboardModelFilter(filterMetricsRaw) : ''}
          <span class="db2-period-wrap">
            <div class="db2-period-dropdown ${state.dashboardPeriodOpen ? 'open' : ''}" data-period-dropdown>
	              <button type="button" class="db2-period-trigger" data-period-trigger>${escapeHtml(winLabel)} <svg width="8" height="5" viewBox="0 0 8 5" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"><path d="M1 1l3 3 3-3"/></svg></button>
              <div class="db2-period-menu" data-period-menu>
                <div class="db2-period-presets">
                  ${[7, 14, 30, 90, 180, 365].map((d) => {
	                    const labels = isEnglishAppLanguage()
	                      ? { 7: '7 days', 14: '14 days', 30: '30 days', 90: '3 months', 180: '6 months', 365: '1 year' }
	                      : { 7: '7 天', 14: '14 天', 30: '30 天', 90: '近 3 个月', 180: '近半年', 365: '近一年' };
                    const isActive = !state.dashboardRange && state.dashboardDays === d;
                    return `<button type="button" class="db2-period-option ${isActive ? 'active' : ''}" data-dashboard-days="${d}">${labels[d]}</button>`;
                  }).join('')}
                </div>
                <div class="db2-period-divider"></div>
                ${renderRangePickerPanel()}
              </div>
            </div>
          </span>
	          ${showDashboardRefresh ? `<button type="button" class="dashboard-refresh-btn ${dashboardRefreshing ? 'is-busy' : ''}" data-dashboard-refresh ${dashboardRefreshing ? 'disabled' : ''}><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21.5 2v6h-6M2.5 22v-6h6M2 11.5a10 10 0 0 1 18.8-4.3M22 12.5a10 10 0 0 1-18.8 4.3"/></svg>${escapeHtml(appText(dashboardRefreshing ? '刷新中' : '刷新'))}</button>` : ''}
        </div>
      </div>
      ${content}
    </div>
	  `;
  requestAnimationFrame(() => window.EasyAIConfigI18n?.apply?.(root));
}

function renderDashboardProviderFilter(metrics) {
  const opts = getDashboardFilterOptions(metrics);
  const currentRaw = state.dashboardFilter.provider || 'all';
  const current = currentRaw === 'all' || opts.providers.includes(currentRaw) ? currentRaw : 'all';
  const open = Boolean(state.dashboardFilter.providerOpen);
  if (!opts.providers.length) return '';
  const label = current === 'all' ? appText('全部 Provider') : current;
  return `
    <span class="db2-period-wrap">
      <div class="db2-period-dropdown ${open ? 'open' : ''}" data-dashboard-filter="provider">
        <button type="button" class="db2-period-trigger" data-dashboard-filter-trigger="provider" title="${escapeHtml(appText('按 provider 筛选 (基于 session.provider 字段)'))}">${escapeHtml(label)}<svg width="8" height="5" viewBox="0 0 8 5" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"><path d="M1 1l3 3 3-3"/></svg></button>
        <div class="db2-period-menu" data-dashboard-filter-menu="provider">
          <div class="db2-period-presets">
            <button type="button" class="db2-period-option ${current === 'all' ? 'active' : ''}" data-dashboard-filter-value="provider:all">${escapeHtml(appText('全部 Provider'))}</button>
            ${opts.providers.map((p) => `<button type="button" class="db2-period-option ${current === p ? 'active' : ''}" data-dashboard-filter-value="provider:${escapeHtml(p)}">${escapeHtml(p)}</button>`).join('')}
          </div>
        </div>
      </div>
    </span>`;
}

function renderDashboardModelFilter(metrics) {
  const opts = getDashboardFilterOptions(metrics);
  const currentRaw = state.dashboardFilter.model || 'all';
  const current = currentRaw === 'all' || opts.models.includes(currentRaw) ? currentRaw : 'all';
  const open = Boolean(state.dashboardFilter.modelOpen);
  if (!opts.models.length) return '';
  const label = current === 'all' ? appText('全部模型') : current;
  return `
    <span class="db2-period-wrap">
      <div class="db2-period-dropdown ${open ? 'open' : ''}" data-dashboard-filter="model">
        <button type="button" class="db2-period-trigger" data-dashboard-filter-trigger="model" title="${escapeHtml(appText('按 model 筛选 (基于 session.model 字段)'))}">${escapeHtml(label)}<svg width="8" height="5" viewBox="0 0 8 5" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"><path d="M1 1l3 3 3-3"/></svg></button>
        <div class="db2-period-menu" data-dashboard-filter-menu="model">
          <div class="db2-period-presets">
            <button type="button" class="db2-period-option ${current === 'all' ? 'active' : ''}" data-dashboard-filter-value="model:all">${escapeHtml(appText('全部模型'))}</button>
            ${opts.models.map((m) => `<button type="button" class="db2-period-option ${current === m ? 'active' : ''}" data-dashboard-filter-value="model:${escapeHtml(m)}">${escapeHtml(m)}</button>`).join('')}
          </div>
        </div>
      </div>
    </span>`;
}

// 账号筛选下拉:当 claudecode state 里有 availableScopes(>=2 个账号)时渲染,
// 否则返回空(只有默认账号时没必要给下拉)。选项顺序:当前 · 全部聚合 · 每个具体账号。
function renderClaudeScopeDropdown() {
  const st = state.claudeCodeState;
  const scopes = Array.isArray(st?.availableScopes) ? st.availableScopes : [];
  if (scopes.length < 2) return '';
  const current = st?.usageScope || 'active';
  const currentLabel = (() => {
    if (current === 'all') return appText('全部聚合');
    if (current === 'active') {
      const activeLabel = st?.activeProfile?.label || st?.activeProfile?.name || st?.activeProfile?.email || st?.activeProfile?.id || appText('默认');
      return isEnglishAppLanguage() ? `Current · ${escapeHtml(activeLabel)}` : `当前 · ${escapeHtml(activeLabel)}`;
    }
    const hit = scopes.find(s => s.scopeId === current);
    return hit ? escapeHtml(hit.label) : appText('当前');
  })();
  const items = [
    { id: 'active', label: appText('当前激活账号') },
    { id: 'all', label: isEnglishAppLanguage() ? `All profiles (${scopes.length})` : `全部聚合(${scopes.length})` },
    ...scopes.map(s => ({ id: s.scopeId, label: s.label })),
  ];
  return `
    <span class="db2-period-wrap">
      <div class="db2-period-dropdown" data-claude-scope-dropdown>
        <button type="button" class="db2-period-trigger" data-claude-scope-trigger>
          <svg width="12" height="12" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><circle cx="8" cy="5" r="2.5"/><path d="M3.5 14c0-2.5 2-4.5 4.5-4.5s4.5 2 4.5 4.5"/></svg>
          ${currentLabel}
          <svg width="8" height="5" viewBox="0 0 8 5" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"><path d="M1 1l3 3 3-3"/></svg>
        </button>
        <div class="db2-period-menu">
          ${items.map(it => `<div class="db2-period-option ${current === it.id ? 'active' : ''}" data-claude-scope="${escapeHtml(it.id)}">${escapeHtml(it.label)}</div>`).join('')}
        </div>
      </div>
    </span>`;
}

function renderDashboardStatCard(label, value, sub = '') {
  const compactValue = formatDashboardMetric(value);
  const fullValue = formatDashboardMetricFull(value);
  const subLabel = sub ? `${sub} · ${fullValue}` : fullValue;
  return `<div class="dashboard-stat-card"><div class="dashboard-stat-label">${escapeHtml(label)}</div><div class="dashboard-stat-value" title="${escapeHtml(fullValue)}">${escapeHtml(compactValue)}</div>${subLabel ? `<div class="dashboard-stat-sub">${escapeHtml(subLabel)}</div>` : ''}</div>`;
}

let __dbChartId = 0;

function renderDashboardInteractiveChart(series = [], { stroke = '#5b8cff', showCost = false, models = [] } = {}) {
  if (!series.length) return `<div class="dashboard-empty-note">${escapeHtml(appText('暂无趋势数据。'))}</div>`;
  const chartId = 'dbCanvas_' + (++__dbChartId);
  const tooltipId = chartId + '_tip';
  const dataAttr = `data-db-chart-series="${escapeHtml(JSON.stringify(series))}" data-db-chart-stroke="${escapeHtml(stroke)}" data-db-chart-show-cost="${showCost ? '1' : ''}" data-db-chart-models="${escapeHtml(JSON.stringify(models))}"`;

  // Deferred init via MutationObserver
  setTimeout(() => { _initDbInteractiveChart(chartId); }, 0);

  return `
    <div class="db2-ichart-wrap" id="${chartId}_wrap" ${dataAttr}>
      <canvas id="${chartId}" class="db2-ichart-canvas" height="196"></canvas>
      <div id="${tooltipId}" class="db2-ichart-tooltip" style="display:none"></div>
    </div>`;
}

function _initDbInteractiveChart(chartId) {
  const tryInit = () => {
    const canvas = document.getElementById(chartId);
    if (!canvas) return false;
    const wrap = canvas.closest('.db2-ichart-wrap');
    if (!wrap) return false;
    const series = JSON.parse(wrap.getAttribute('data-db-chart-series') || '[]');
    const stroke = wrap.getAttribute('data-db-chart-stroke') || '#5b8cff';
    const showCost = wrap.getAttribute('data-db-chart-show-cost') === '1';
    const models = JSON.parse(wrap.getAttribute('data-db-chart-models') || '[]');
    if (!series.length) return true;

    const dpr = window.devicePixelRatio || 1;
    const rect = wrap.getBoundingClientRect();
    const W = Math.round(rect.width) || 600;
    const H = 196;
    canvas.width = W * dpr;
    canvas.height = H * dpr;
    canvas.style.width = W + 'px';
    canvas.style.height = H + 'px';
    const ctx = canvas.getContext('2d');
    ctx.scale(dpr, dpr);

    const padL = 42, padR = 12, padT = 16, padB = 28;
    const cW = W - padL - padR;
    const cH = H - padT - padB;
    const values = series.map(s => Number(s.value || 0));
    const max = Math.max(...values, 1);
    const step = series.length > 1 ? cW / (series.length - 1) : 0;
    const pts = series.map((s, i) => ({
      x: padL + step * i,
      y: padT + cH - (values[i] / max) * cH
    }));
    const compositionMax = Math.max(
      ...series.map((s) => Number(s.input || 0) + Number(s.output || 0) + Number(s.cached || 0)),
      max,
      1
    );

    const isLight = document.documentElement.getAttribute('data-theme') === 'light';
    const gridColor = isLight ? 'rgba(15,23,42,0.055)' : 'rgba(255,255,255,0.055)';
    const textColor = isLight ? 'rgba(15,23,42,0.32)' : 'rgba(255,255,255,0.28)';
    const bgGradStart = stroke + '26';
    const bgGradEnd = stroke + '03';

    // Draw
    function draw(hoverIdx) {
      ctx.clearRect(0, 0, W, H);

      // Grid lines + labels
      ctx.font = '9.5px -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif';
      ctx.textAlign = 'right';
      for (let frac of [0, 0.25, 0.5, 0.75, 1.0]) {
        const y = padT + cH - frac * cH;
        ctx.strokeStyle = gridColor;
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(padL, y);
        ctx.lineTo(W - padR, y);
        ctx.stroke();
        ctx.fillStyle = textColor;
        ctx.fillText(formatDashboardMetric(max * frac), padL - 6, y + 3);
      }

      // X labels
      const labelStep = Math.max(1, Math.floor(series.length / 7));
      ctx.textAlign = 'center';
      pts.forEach((p, i) => {
        if (i % labelStep !== 0 && i !== series.length - 1) return;
        ctx.fillStyle = textColor;
        ctx.fillText(series[i].label, p.x, H - 6);
      });

      // Compact stacked bars behind the line: input / output / cached.
      const barW = Math.max(2, Math.min(10, cW / Math.max(8, series.length * 2.8)));
      pts.forEach((p, i) => {
        const s = series[i] || {};
        const parts = [
          { value: Number(s.cached || 0), color: isLight ? 'rgba(124,58,237,0.20)' : 'rgba(167,139,250,0.22)' },
          { value: Number(s.input || 0), color: isLight ? 'rgba(91,140,255,0.22)' : 'rgba(141,189,255,0.24)' },
          { value: Number(s.output || 0), color: isLight ? 'rgba(34,197,94,0.22)' : 'rgba(74,222,128,0.24)' },
        ];
        let yCursor = padT + cH;
        parts.forEach((part) => {
          if (!(part.value > 0)) return;
          const h = Math.max(1, part.value / compositionMax * cH * 0.72);
          ctx.fillStyle = part.color;
          ctx.beginPath();
          const x = p.x - barW / 2;
          const y = yCursor - h;
          const r = Math.min(3, barW / 2, h / 2);
          ctx.moveTo(x + r, y);
          ctx.lineTo(x + barW - r, y);
          ctx.quadraticCurveTo(x + barW, y, x + barW, y + r);
          ctx.lineTo(x + barW, y + h);
          ctx.lineTo(x, y + h);
          ctx.lineTo(x, y + r);
          ctx.quadraticCurveTo(x, y, x + r, y);
          ctx.closePath();
          ctx.fill();
          yCursor -= h + 1;
        });
      });

      // Area fill gradient
      if (pts.length > 1) {
        const grad = ctx.createLinearGradient(0, padT, 0, padT + cH);
        grad.addColorStop(0, bgGradStart);
        grad.addColorStop(1, bgGradEnd);
        ctx.beginPath();
        ctx.moveTo(pts[0].x, pts[0].y);
        for (let i = 1; i < pts.length; i++) {
          const cp1x = (pts[i-1].x + pts[i].x) / 2;
          ctx.bezierCurveTo(cp1x, pts[i-1].y, cp1x, pts[i].y, pts[i].x, pts[i].y);
        }
        ctx.lineTo(pts[pts.length-1].x, padT + cH);
        ctx.lineTo(pts[0].x, padT + cH);
        ctx.closePath();
        ctx.fillStyle = grad;
        ctx.fill();
      }

      // Line
      ctx.beginPath();
      ctx.moveTo(pts[0].x, pts[0].y);
      for (let i = 1; i < pts.length; i++) {
        const cp1x = (pts[i-1].x + pts[i].x) / 2;
        ctx.bezierCurveTo(cp1x, pts[i-1].y, cp1x, pts[i].y, pts[i].x, pts[i].y);
      }
      ctx.strokeStyle = stroke;
      ctx.lineWidth = 2.15;
      ctx.lineJoin = 'round';
      ctx.lineCap = 'round';
      ctx.stroke();

      // Dots
      pts.forEach((p, i) => {
        const isHover = i === hoverIdx;
        ctx.beginPath();
        ctx.arc(p.x, p.y, isHover ? 4.5 : 2.2, 0, Math.PI * 2);
        ctx.fillStyle = isHover ? '#fff' : stroke;
        ctx.fill();
        if (isHover) {
          ctx.strokeStyle = stroke;
          ctx.lineWidth = 2.15;
          ctx.stroke();
        }
      });

      // Hover crosshair
      if (hoverIdx >= 0 && hoverIdx < pts.length) {
        const p = pts[hoverIdx];
        ctx.setLineDash([4, 4]);
        ctx.strokeStyle = isLight ? 'rgba(15,23,42,0.15)' : 'rgba(255,255,255,0.15)';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(p.x, padT);
        ctx.lineTo(p.x, padT + cH);
        ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(padL, p.y);
        ctx.lineTo(W - padR, p.y);
        ctx.stroke();
        ctx.setLineDash([]);
      }
    }

    draw(-1);

    // Hover
    const tooltip = document.getElementById(chartId + '_tip');
    let lastIdx = -1;

    canvas.addEventListener('mousemove', (e) => {
      const r = canvas.getBoundingClientRect();
      const mx = e.clientX - r.left;
      // Find nearest
      let nearIdx = 0;
      let nearDist = Infinity;
      pts.forEach((p, i) => {
        const d = Math.abs(p.x - mx);
        if (d < nearDist) { nearDist = d; nearIdx = i; }
      });
      if (nearIdx === lastIdx) return;
      lastIdx = nearIdx;
      draw(nearIdx);

      if (tooltip && series[nearIdx]) {
        const s = series[nearIdx];
        const inp = formatDashboardMetric(s.input || 0);
        const out = formatDashboardMetric(s.output || 0);
        const cached = formatDashboardMetric(s.cached || 0);
        const total = formatDashboardMetricFull(s.value || 0);

        // Cost estimation
        let costLine = '';
        if (showCost && models.length) {
          // 直接按当日 input/output/cached 量算钱，不再用"窗口平均单价 × 当日 tokens"。
          // 用窗口平均会把高费用日的均价摊到所有日，得出像 $21K/天 这种离谱数字。
          // 多模型场景：以占比最大的模型（models 已按总量降序排）单价估算，
          // 单模型场景下就是该模型自身，结果精确。
          const dayInput = Number(s.input || 0);
          const dayOutput = Number(s.output || 0);
          const dayCached = Number(s.cached || 0);
          const dayCacheCreation = Number(s.cacheCreation || 0);
          if (dayInput + dayOutput + dayCached + dayCacheCreation > 0) {
            const primary = models[0];
            const pricing = primary && lookupModelPricing(primary.model);
            if (pricing) {
              const provider = pricing.provider || 'openai';
              let dayCost;
              if (provider === 'anthropic') {
                // Anthropic：input / output / cache_read / cache_creation 全是分离字段，
                // 跟 ccusage 一致地各乘各的单价。cache_creation 5m TTL 默认 1.25x input。
                const writeRate = Number.isFinite(pricing.cacheWrite) ? pricing.cacheWrite : pricing.input * 1.25;
                dayCost = (dayInput * pricing.input
                  + dayOutput * pricing.output
                  + dayCached * pricing.cached
                  + dayCacheCreation * writeRate) / 1e6;
              } else {
                // OpenAI：input_tokens 已含 cached，先扣 cached（和 ccusage 的
                // calculate_codex_model_cost 一致：non_cached = input - cached）
                const nonCached = Math.max(0, dayInput - dayCached);
                const writeRate = Number.isFinite(pricing.cacheWrite) ? pricing.cacheWrite : 0;
                dayCost = (nonCached * pricing.input
                  + dayCached * pricing.cached
                  + dayOutput * pricing.output
                  + dayCacheCreation * writeRate) / 1e6;
              }
              costLine = `<div class="db2-tip-row db2-tip-cost"><span>${escapeHtml(appText('预估费用'))}</span><strong>${escapeHtml(formatDashboardUsd(dayCost, { min: 2, max: 4 }))}</strong></div>`;
            }
          }
        }

        tooltip.innerHTML = `
          <div class="db2-tip-date">${escapeHtml(s.label)}</div>
          <div class="db2-tip-total">${escapeHtml(total)} tokens</div>
	          <div class="db2-tip-row"><span style="color:#5b8cff">● ${escapeHtml(appText('输入'))}</span><strong>${escapeHtml(inp)}</strong></div>
	          <div class="db2-tip-row"><span style="color:#22c55e">● ${escapeHtml(appText('输出'))}</span><strong>${escapeHtml(out)}</strong></div>
	          <div class="db2-tip-row"><span style="color:#7c3aed">● ${escapeHtml(appText('缓存'))}</span><strong>${escapeHtml(cached)}</strong></div>
          ${costLine}
        `;
        tooltip.style.display = '';
        const tipRect = tooltip.getBoundingClientRect();
        const wrapRect = wrap.getBoundingClientRect();
        let tx = pts[nearIdx].x + 14;
        if (tx + tipRect.width > W - 10) tx = pts[nearIdx].x - tipRect.width - 14;
        tooltip.style.left = tx + 'px';
        tooltip.style.top = Math.max(4, pts[nearIdx].y - tipRect.height / 2) + 'px';
      }
    });

    canvas.addEventListener('mouseleave', () => {
      lastIdx = -1;
      draw(-1);
      if (tooltip) tooltip.style.display = 'none';
    });

    return true;
  };

  if (!tryInit()) {
    // Retry with rAF
    let tries = 0;
    const retry = () => {
      if (tryInit() || tries++ > 20) return;
      requestAnimationFrame(retry);
    };
    requestAnimationFrame(retry);
  }
}

// Model contribution ranking
function renderDashboardModelDistChart(models = [], totalTokens = 0) {
  if (!models.length) return `<div class="dashboard-empty-note">${escapeHtml(appText('暂无模型分布数据。'))}</div>`;
  const chartId = 'dbModelDist_' + (++__dbChartId);
  const sorted = [...models].sort((a, b) => (b.totals?.total || 0) - (a.totals?.total || 0));
  const topRows = sorted.slice(0, 6);
  const overflowRows = sorted.slice(6);
  const overflowTokens = overflowRows.reduce((sum, item) => sum + (item.totals?.total || 0), 0);
  const overflowCost = overflowRows.reduce((sum, item) => sum + (calcModelCost(item)?.totalCost || 0), 0);
  const rows = overflowTokens > 0
    ? [...topRows, { model: appText('其他模型'), totals: { total: overflowTokens }, _overflow: true, _cost: overflowCost, events: overflowRows.reduce((sum, item) => sum + (item.events || 0), 0) }]
    : topRows;
  const resolvedTotal = totalTokens || sorted.reduce((sum, item) => sum + (item.totals?.total || 0), 0);
  const totalCost = sorted.reduce((sum, item) => sum + (calcModelCost(item)?.totalCost || 0), 0);
  const primary = sorted[0];
  const primaryCost = primary ? calcModelCost(primary) : null;
  const primaryTokens = primary?.totals?.total || 0;
  const primaryPct = resolvedTotal ? (primaryTokens / resolvedTotal * 100) : 0;
  const primaryLabel = primary ? (primaryCost?.pricing?.label || primary.model) : '—';

  const rowHtml = rows.map((m, i) => {
    const tokens = m.totals?.total || 0;
    const pct = resolvedTotal ? (tokens / resolvedTotal * 100) : 0;
    const cost = m._overflow ? { totalCost: m._cost || 0, pricing: null } : calcModelCost(m);
    const costStr = cost ? formatDashboardUsd(cost.totalCost, { min: 2, max: 3 }) : '–';
    const label = m._overflow ? appText('其他模型') : (cost?.pricing?.label || m.model);
    const color = DASHBOARD_ANALYTIC_COLORS[i % DASHBOARD_ANALYTIC_COLORS.length];
    const pctLabel = pct > 0 && pct < 1 ? '<1%' : `${Math.round(pct)}%`;
    const events = Number(m.events || 0);
    const rawLabel = m._overflow
      ? (isEnglishAppLanguage() ? `${overflowRows.length} models` : `${overflowRows.length} 个模型`)
      : m.model;
    return `<div class="db3-model-rank-row" style="--rank-color:${color}">
      <span class="db3-model-rank-index">${String(i + 1).padStart(2, '0')}</span>
      <div class="db3-model-rank-main">
        <div class="db3-model-rank-name" title="${escapeHtml(rawLabel)}"><i></i><strong>${escapeHtml(label)}</strong></div>
        <div class="db3-model-rank-meter"><span style="width:${Math.max(2, pct)}%"></span></div>
      </div>
      <div class="db3-model-rank-stat">
        <strong>${escapeHtml(pctLabel)}</strong>
        <span>${escapeHtml(appText('占比'))}</span>
      </div>
      <div class="db3-model-rank-stat">
        <strong title="${escapeHtml(formatDashboardMetricFull(tokens))}">${escapeHtml(formatDashboardMetric(tokens))}</strong>
        <span>${escapeHtml(events ? (isEnglishAppLanguage() ? `${events} runs` : `${events} 次`) : appText('Token'))}</span>
      </div>
      <div class="db3-model-rank-stat db3-model-rank-cost">
        <strong>${escapeHtml(costStr)}</strong>
        <span>${escapeHtml(appText('费用'))}</span>
      </div>
    </div>`;
  }).join('');

  return `<div class="db3-model-rank" id="${chartId}">
    <div class="db3-model-rank-summary">
      <div>
        <span>${escapeHtml(appText('主模型'))}</span>
        <strong title="${escapeHtml(primary?.model || '')}">${escapeHtml(primaryLabel)}</strong>
      </div>
      <div>
        <span>${escapeHtml(appText('贡献'))}</span>
        <strong>${escapeHtml(primaryPct > 0 && primaryPct < 1 ? '<1%' : `${Math.round(primaryPct)}%`)}</strong>
      </div>
      <div>
        <span>${escapeHtml(appText('模型数'))}</span>
        <strong>${escapeHtml(String(sorted.length))}</strong>
      </div>
      <div>
        <span>${escapeHtml(appText('费用'))}</span>
        <strong>${escapeHtml(totalCost ? formatDashboardUsd(totalCost, { min: 2, max: 3 }) : '–')}</strong>
      </div>
    </div>
    <div class="db3-model-rank-list">${rowHtml}</div>
  </div>`;
}

// 重做版费用趋势图：放弃丑陋的柱状条，改成柔和 SVG 面积图（和 Token 用量趋势同风格）。
// 三条参数：data 数组、汇总文案、主色（默认蓝紫，可被覆盖）。
function renderCostTrendPanel(costSeries = [], summaryLabel = '', accentColor = '#7c3aed') {
  if (!costSeries.length) return `<div class="dashboard-empty-note">${escapeHtml(appText('暂无费用趋势数据。'))}</div>`;
  const chartId = `costTrend_${Math.random().toString(36).slice(2, 9)}`;
  const values = costSeries.map((s) => Number(s.value || 0));
  const maxCost = Math.max(...values, 0.001);
  const totalCost = values.reduce((sum, v) => sum + v, 0);
  const activeDays = values.filter((v) => v > 0).length;
  const avgCost = totalCost / Math.max(1, activeDays || values.length);
  const usdFmt = (value) => formatDashboardUsd(value, { min: value < 1 ? 3 : 2, max: value < 1 ? 3 : 2 });

  // 画布尺寸用 viewBox 自适应，外层容器固定高度，由 CSS 控制宽度
  const W = 720;
  const H = 168;
  const padL = 46;
  const padR = 12;
  const padT = 10;
  const padB = 22;
  const innerW = W - padL - padR;
  const innerH = H - padT - padB;

  // 等距点：x 用 index 等分，y 按 cost 反向映射
  const n = costSeries.length;
  const stepX = n > 1 ? innerW / (n - 1) : innerW;
  const pts = costSeries.map((item, i) => {
    const x = padL + i * stepX;
    const y = padT + innerH - (Number(item.value || 0) / maxCost) * innerH;
    return { x, y, value: Number(item.value || 0), label: item.label };
  });

  // Catmull-Rom → Bezier 路径，得到柔和曲线（与主趋势图相同感觉）
  const smoothPath = (points) => {
    if (!points.length) return '';
    let d = `M ${points[0].x} ${points[0].y}`;
    for (let i = 0; i < points.length - 1; i++) {
      const p0 = points[i - 1] || points[i];
      const p1 = points[i];
      const p2 = points[i + 1];
      const p3 = points[i + 2] || p2;
      const cp1x = p1.x + (p2.x - p0.x) / 6;
      const cp1y = p1.y + (p2.y - p0.y) / 6;
      const cp2x = p2.x - (p3.x - p1.x) / 6;
      const cp2y = p2.y - (p3.y - p1.y) / 6;
      d += ` C ${cp1x} ${cp1y}, ${cp2x} ${cp2y}, ${p2.x} ${p2.y}`;
    }
    return d;
  };

  const linePath = smoothPath(pts);
  const baselineY = padT + innerH;
  const areaPath = pts.length
    ? `${linePath} L ${pts[pts.length - 1].x} ${baselineY} L ${pts[0].x} ${baselineY} Z`
    : '';

  // Y 轴 4 个 tick：max / 2/3 max / 1/3 max / 0
  const yTickValues = [maxCost, maxCost * 2 / 3, maxCost / 3, 0];
  const yTicks = yTickValues.map((value) => {
    const y = padT + innerH - (value / maxCost) * innerH;
    return { y, label: usdFmt(value) };
  });

  // X 轴只标几个关键点
  const xTickStep = Math.max(1, Math.floor((n - 1) / 6));
  const xTicks = pts
    .map((p, i) => ({ p, i }))
    .filter(({ i }) => i === 0 || i === n - 1 || i % xTickStep === 0)
    .map(({ p, i }) => ({ x: p.x, label: costSeries[i].label }));

  const gradientId = `${chartId}_grad`;
  const barWidth = Math.max(4, Math.min(14, innerW / Math.max(8, n * 2.4)));
  const bars = pts.map((p) => {
    const h = p.value > 0 ? Math.max(2, (p.value / maxCost) * innerH * 0.76) : 0;
    const x = p.x - barWidth / 2;
    const y = baselineY - h;
    return `<rect x="${x.toFixed(1)}" y="${y.toFixed(1)}" width="${barWidth.toFixed(1)}" height="${h.toFixed(1)}" rx="${Math.min(4, barWidth / 2).toFixed(1)}" fill="${accentColor}" opacity="0.2" class="db3-cost-area-bar"/>`;
  }).join('');
  const dots = pts.map((p, i) => `<circle data-i="${i}" cx="${p.x.toFixed(1)}" cy="${p.y.toFixed(1)}" r="2.4" fill="${accentColor}" opacity="0" class="db3-cost-area-dot"/>`).join('');
  const gridLines = yTicks.map((t) => `<line x1="${padL}" x2="${W - padR}" y1="${t.y.toFixed(1)}" y2="${t.y.toFixed(1)}" stroke="currentColor" stroke-width="0.5" stroke-dasharray="2 3" opacity="0.18"/>`).join('');
  const yLabels = yTicks.map((t) => `<text x="${padL - 8}" y="${(t.y + 3).toFixed(1)}" text-anchor="end" font-size="10" fill="currentColor" opacity="0.55">${escapeHtml(t.label)}</text>`).join('');
  const xLabels = xTicks.map((t) => `<text x="${t.x.toFixed(1)}" y="${(H - 4).toFixed(1)}" text-anchor="middle" font-size="10" fill="currentColor" opacity="0.55">${escapeHtml(t.label)}</text>`).join('');

  return `
    <div class="db3-cost-area" id="${chartId}">
      <svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" class="db3-cost-area-svg">
        <defs>
          <linearGradient id="${gradientId}" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stop-color="${accentColor}" stop-opacity="0.32"/>
            <stop offset="100%" stop-color="${accentColor}" stop-opacity="0"/>
          </linearGradient>
        </defs>
        ${gridLines}
        ${bars}
        ${areaPath ? `<path d="${areaPath}" fill="url(#${gradientId})"/>` : ''}
        ${linePath ? `<path d="${linePath}" fill="none" stroke="${accentColor}" stroke-width="1.6" stroke-linejoin="round" stroke-linecap="round"/>` : ''}
        ${yLabels}
        ${xLabels}
        ${dots}
      </svg>
      <div class="db3-cost-area-foot">
        <span class="db3-cost-area-summary">${escapeHtml(summaryLabel)}</span>
        <div class="db3-cost-area-totals">
          <em>${escapeHtml(appText('日均'))} ${escapeHtml(usdFmt(avgCost))}</em>
          <em>${escapeHtml(appText('峰值'))} ${escapeHtml(usdFmt(maxCost))}</em>
          <strong>${escapeHtml(usdFmt(totalCost))}</strong>
        </div>
      </div>
    </div>`;
}

// Claude cost trend uses actual cost from telemetry (not estimated)
function renderClaudeCostTrendChart(dailySlice = [], windowDays = 30) {
  if (!dailySlice.length) return `<div class="dashboard-empty-note">${escapeHtml(appText('暂无费用趋势数据。'))}</div>`;
  const costSeries = dailySlice.map((item) => ({
    label: (item.date || '').slice(5),
    value: item.cost || 0,
  }));
  return renderCostTrendPanel(
    costSeries,
	    isEnglishAppLanguage() ? `Last ${windowDays} days total` : `近 ${windowDays} 天合计`,
    '#7c3aed'
  );
}

function renderDashboardCostTrendChart(daily = [], models = []) {
  if (!daily.length || !models.length) return `<div class="dashboard-empty-note">${escapeHtml(appText('暂无费用趋势数据。'))}</div>`;
  // 改用 estimateCostByDaily 单点直算（每个 daily item 走一次主模型单价），
  // 跟 tooltip / hero stat 同口径。旧实现用"占比 × 总量"会双计 cached 段。
  const costSeries = daily.map((item) => ({
    label: (item.date || '').slice(5),
    value: estimateCostByDaily([item], models),
  }));
  return renderCostTrendPanel(
    costSeries,
	    isEnglishAppLanguage() ? `Last ${costSeries.length} days total` : `近 ${costSeries.length} 天合计`,
    '#5b8cff'
  );
}

// Keep legacy function as wrapper
function renderDashboardLineChart(series = [], { stroke = '#5b8cff' } = {}) {
  return renderDashboardInteractiveChart(series, { stroke });
}

function renderDashboardStackChart(items = []) {
  if (!items.length) return `<div class="dashboard-empty-note">${escapeHtml(appText('暂无结构分布数据。'))}</div>`;
  const total = items.reduce((sum, item) => sum + Number(item.value || 0), 0) || 1;
  return `
    <div class="dashboard-chart">
      <div class="dashboard-stack-track">${items.map((item, index) => `<div class="dashboard-stack-segment" style="width:${(Number(item.value || 0) / total) * 100}%;background:${['#5b8cff','#7c3aed','#22c55e','#f59e0b'][index % 4]}" title="${escapeHtml(formatDashboardMetricFull(item.value || 0))}"></div>`).join('')}</div>
      <div class="dashboard-chart-legend">${items.map((item, index) => `<span title="${escapeHtml(formatDashboardMetricFull(item.value || 0))}"><span class="dashboard-legend-dot" style="background:${['#5b8cff','#7c3aed','#22c55e','#f59e0b'][index % 4]}"></span>${escapeHtml(item.label)} · ${escapeHtml(formatDashboardMetric(item.value || 0))}</span>`).join('')}</div>
    </div>`;
}

async function refreshDashboardData({ force = false, silent = false, tool = state.dashboardTool || 'codex' } = {}) {
  tool = getDashboardToolDef(tool)?.key || 'codex';
  if (isCursorDashboardTool(tool)) {
    await loadConsoleCursorUsage({ force });
    return;
  }
  const isGenericUsage = isGenericUsageDashboardTool(tool);
  if (!isApiDashboardTool(tool) && !isGenericUsage) return;
  const win = getDashboardWindow();
  const codexHome = tool === 'codex' ? getDashboardCodexHome() : '';
  const cacheKey = isGenericUsage ? getDashboardUsageCacheKey(tool, win) : getDashboardMetricsCacheKey(tool, win, codexHome);
  const isCurrentRequest = () => (
    (state.dashboardTool || 'codex') === tool &&
    (isGenericUsage ? getDashboardUsageCacheKey(tool) : getDashboardMetricsCacheKey(tool)) === cacheKey
  );
  const cachedMetrics = isGenericUsage
    ? getDashboardUsageMetricsForTool(tool, win)
    : getDashboardMetricsForTool(tool, win, codexHome);

  if (!state.dashboardRefreshingByWindow) state.dashboardRefreshingByWindow = {};
  if (state.dashboardRefreshingByWindow[cacheKey]) {
    if (isCurrentRequest()) {
      state.dashboardRefreshing = true;
      state.dashboardLoading = !silent || !cachedMetrics;
      if (state.activePage === 'dashboard') renderDashboardPage();
    }
    return;
  }

  state.dashboardRefreshingByWindow[cacheKey] = true;
  if (isCurrentRequest()) {
    state.dashboardRefreshing = true;
    state.dashboardLoading = !silent || !cachedMetrics;
    if (state.activePage === 'dashboard') renderDashboardPage();
  }

  try {
    // 用当前 dashboard window 需要覆盖的天数请求后端，自定义历史区间也能拿到足够远的数据。
    const requestDays = String(getDashboardRequestDays(win));
    const params = new URLSearchParams({ days: requestDays });
    if (tool === 'codex') {
      params.set('codexHome', codexHome);
    }
    if (force) params.set('force', '1');
    if (isGenericUsage) {
      params.set('tools', tool);
      params.set('limit', '240');
      let json = await api(`/api/usage/inventory?${params.toString()}`, { timeoutMs: force ? 120000 : 30000 });
      if (json?.ok && json.data) {
        setDashboardUsageInventoryForTool(tool, json.data, win);
      }
    } else {
      const route = tool === 'opencode' ? '/api/dashboard/opencode-usage' : '/api/dashboard/codex-usage';
      let json = await api(`${route}?${params.toString()}`, { timeoutMs: force ? 120000 : 20000 });
      if (json?.ok && json.data?.cacheMiss && !force) {
        params.set('force', '1');
        json = await api(`${route}?${params.toString()}`, { timeoutMs: 120000 });
      }
      if (json?.ok && json.data && !json.data.cacheMiss && json.data.totals && typeof json.data.totals === 'object') {
        setDashboardMetricsForTool(tool, json.data, win, codexHome);
      }
    }
  } catch { /* ignore */ } finally {
    if (state.dashboardRefreshingByWindow) delete state.dashboardRefreshingByWindow[cacheKey];
    if (isCurrentRequest()) {
      state.dashboardLoading = false;
      state.dashboardRefreshing = false;
    } else if (isApiDashboardTool(state.dashboardTool || '') || isGenericUsageDashboardTool(state.dashboardTool || '')) {
      state.dashboardRefreshing = isDashboardRefreshingForTool(state.dashboardTool);
      if (!state.dashboardRefreshing) state.dashboardLoading = false;
    }
    if (state.activePage === 'dashboard') renderDashboardPage();
  }
}

function getToolConsoleLabel(tool = 'codex') {
  return TOOL_CONSOLE_META[tool]?.label || tool;
}

const TC_STAT_ICONS = {
  install: '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><path d="M2.5 8a5.5 5.5 0 0 1 11 0 5.5 5.5 0 0 1-11 0z"/><path d="M8 5v6M5.5 8.5L8 11l2.5-2.5"/></svg>',
  scope: '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><rect x="2" y="2" width="12" height="12" rx="2"/><path d="M6 6h4M6 8h4M6 10h2"/></svg>',
  provider: '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><path d="M6.5 9.5a3.5 3.5 0 0 0 5 0l1-1a3.54 3.54 0 0 0-5-5l-.5.5"/><path d="M9.5 6.5a3.5 3.5 0 0 0-5 0l-1 1a3.54 3.54 0 0 0 5 5l.5-.5"/></svg>',
  health: '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><path d="M8 14s-5.5-3.5-5.5-7A3.5 3.5 0 0 1 8 4.5 3.5 3.5 0 0 1 13.5 7C13.5 10.5 8 14 8 14z"/></svg>',
  auth: '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><rect x="3" y="7" width="10" height="7" rx="1.5"/><path d="M5 7V5a3 3 0 0 1 6 0v2"/></svg>',
  model: '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><path d="M2 5l6-3 6 3v6l-6 3-6-3z"/><path d="M2 5l6 3m0 6V8m6-3l-6 3"/></svg>',
  history: '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><circle cx="8" cy="8" r="6"/><path d="M8 5v3.5l2.5 1.5"/></svg>',
  dashboard: '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><rect x="2" y="2" width="12" height="12" rx="2"/><path d="M2 6h12M6 6v8"/></svg>',
  agent: '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><circle cx="8" cy="5" r="2.5"/><path d="M3.5 14c0-2.5 2-4.5 4.5-4.5s4.5 2 4.5 4.5"/></svg>',
  channel: '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><path d="M2 12l3-3h7a2 2 0 0 0 2-2V4a2 2 0 0 0-2-2H4a2 2 0 0 0-2 2v8z"/></svg>',
};

const TC_CARD_ICONS = {
  status: '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><rect x="2" y="2" width="12" height="12" rx="2"/><path d="M6 6h4M6 8h4M6 10h2"/></svg>',
  providers: '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><path d="M6.5 9.5a3.5 3.5 0 0 0 5 0l1-1a3.54 3.54 0 0 0-5-5l-.5.5"/><path d="M9.5 6.5a3.5 3.5 0 0 0-5 0l-1 1a3.54 3.54 0 0 0 5 5l.5-.5"/></svg>',
  issues: '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><path d="M8 2l6 11H2L8 2z"/><path d="M8 7v3M8 12v.5"/></svg>',
  actions: '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><path d="M8 2v12M2 8h12"/></svg>',
  models: '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><path d="M2 5l6-3 6 3v6l-6 3-6-3z"/><path d="M2 5l6 3m0 6V8m6-3l-6 3"/></svg>',
  agent: '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><circle cx="8" cy="5" r="2.5"/><path d="M3.5 14c0-2.5 2-4.5 4.5-4.5s4.5 2 4.5 4.5"/></svg>',
  channels: '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><path d="M2 12l3-3h7a2 2 0 0 0 2-2V4a2 2 0 0 0-2-2H4a2 2 0 0 0-2 2v8z"/></svg>',
  runtime: '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><rect x="2" y="2" width="12" height="12" rx="2"/><path d="M2 6h12M6 6v8"/></svg>',
};

const TC_ISSUE_ICONS = {
  warn: '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><path d="M8 2l6 11H2L8 2z"/><path d="M8 7v3"/><circle cx="8" cy="12" r="0.5" fill="currentColor" stroke="none"/></svg>',
  error: '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><circle cx="8" cy="8" r="6"/><path d="M10 6L6 10M6 6l4 4"/></svg>',
  ok: '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><circle cx="8" cy="8" r="6"/><path d="M5.5 8l2 2 3.5-4"/></svg>',
};

function renderToolConsoleStat(label, value, sub = '', { icon = '' } = {}) {
  const iconHtml = icon && TC_STAT_ICONS[icon]
    ? `<span class="tc-stat-icon">${TC_STAT_ICONS[icon]}</span>`
    : '';
  return `
    <div class="tool-console-stat">
      <div class="tool-console-stat-label">${iconHtml}${escapeHtml(label)}</div>
      <div class="tool-console-stat-value">${escapeHtml(value || '-')}</div>
      ${sub ? `<div class="tool-console-stat-sub">${sub}</div>` : ''}
    </div>
  `;
}

function renderToolConsoleAction(action = {}) {
  const attrs = [
    `data-console-action="${escapeHtml(action.type || '')}"`,
    action.page ? `data-console-page="${escapeHtml(action.page)}"` : '',
    action.tool ? `data-console-tool-target="${escapeHtml(action.tool)}"` : '',
    action.provider ? `data-console-provider="${escapeHtml(action.provider)}"` : '',
    action.method ? `data-console-method="${escapeHtml(action.method)}"` : '',
    action.authKey ? `data-console-auth-key="${escapeHtml(action.authKey)}"` : '',
  ].filter(Boolean).join(' ');
  const klass = action.primary ? 'tiny-btn' : 'secondary tiny-btn';
  return `<button type="button" class="${klass}" ${attrs}>${escapeHtml(action.label || '操作')}</button>`;
}

function renderToolConsoleIssue(issue = {}) {
  const tone = issue.tone || 'warn';
  const iconSvg = TC_ISSUE_ICONS[tone] || TC_ISSUE_ICONS.warn;
  return `
    <div class="tool-console-issue ${escapeHtml(tone)}">
      <div class="tc-issue-indicator">${iconSvg}</div>
      <div class="tc-issue-body">
        <div class="tool-console-issue-title">${escapeHtml(issue.title || '提醒')}</div>
        <div class="tool-console-issue-copy">${escapeHtml(issue.copy || '')}</div>
        ${issue.action ? `<div class="tool-console-actions">${renderToolConsoleAction(issue.action)}</div>` : ''}
      </div>
    </div>
  `;
}

function renderToolConsoleIssueList(issues = [], emptyText = '暂未发现明显异常。') {
  if (!issues.length) return `<div class="tool-console-empty">${escapeHtml(emptyText)}</div>`;
  return `<div class="tool-console-issues">${issues.map(renderToolConsoleIssue).join('')}</div>`;
}

function renderToolConsoleRow(label, value, { html = false } = {}) {
  const renderedValue = html ? value : escapeHtml(value || '-');
  return `<div class="tool-console-row"><div class="tool-console-row-label">${escapeHtml(label)}</div><div class="tool-console-row-value">${renderedValue}</div></div>`;
}

function renderToolConsoleCard(title, copy, body, { icon = '', iconTone = '' } = {}) {
  const iconKey = icon || '';
  const iconSvg = TC_CARD_ICONS[iconKey] || '';
  const iconHtml = iconSvg
    ? `<span class="tc-card-icon ${escapeHtml(iconTone)}">${iconSvg}</span>`
    : '';
  return `
    <section class="tool-console-card">
      <div class="tool-console-card-head">
        <div class="tool-console-card-title">${iconHtml}${escapeHtml(title)}</div>
        ${copy ? `<div class="tool-console-card-copy">${escapeHtml(copy)}</div>` : ''}
      </div>
      ${body}
    </section>
  `;
}

function renderToolConsoleGroupLabel(text) {
  return `<div class="tool-console-group-label">${escapeHtml(text)}</div>`;
}

function renderToolConsoleItem({ title = '', meta = '', chips = [], body = '' } = {}) {
  return `
    <div class="tool-console-item">
      <div class="tool-console-item-head">
        <div>
          <div class="tool-console-item-title">${escapeHtml(title)}</div>
          ${meta ? `<div class="tool-console-item-meta">${escapeHtml(meta)}</div>` : ''}
        </div>
      </div>
      ${chips.length ? `<div class="tool-console-badges">${chips.map(renderToolConsoleChip).join('')}</div>` : ''}
      ${body ? `<div class="tool-console-item-body">${body}</div>` : ''}
    </div>
  `;
}

function renderToolConsoleChip(text) {
  return `<span class="tool-console-chip">${escapeHtml(text)}</span>`;
}

function getOpenClawConsoleChannels(config = {}) {
  return Object.entries(config.channels || {})
    .filter(([key, value]) => !['defaults', 'modelByChannel'].includes(key) && value && (typeof value !== 'object' || Object.keys(value).length > 0))
    .map(([key]) => ({ key, label: OPENCLAW_CHANNEL_LABELS[key] || key }));
}

function getOpenClawConsoleProviders(config = {}) {
  return Object.entries(config.models?.providers || {}).map(([key, provider]) => ({
    key,
    api: provider?.api || '-',
    baseUrl: provider?.baseUrl || '',
    modelCount: Array.isArray(provider?.models) ? provider.models.length : 0,
  }));
}

function getOpenClawConsoleAgents(config = {}) {
  const agents = config.agents || {};
  const defaults = agents.defaults || {};
  const customAgents = Object.entries(agents)
    .filter(([key, value]) => key !== 'defaults' && value && typeof value === 'object')
    .map(([key, value]) => ({
      key,
      model: value?.model?.primary || value?.model || '-',
      workspace: value?.workspace || '默认',
    }));
  return {
    defaults,
    customAgents,
  };
}

function deriveOpenClawDashboardAuthDiagnostics(data = {}, lastRepair = null) {
  const authMode = String(data.gatewayAuthMode || data.config?.gateway?.auth?.mode || 'token');
  const dashboardUrl = String(data.dashboardUrl || '');
  const hasTokenizedUrl = /[?&]token=/.test(dashboardUrl);
  const tokenReady = Boolean(data.gatewayTokenReady);
  const repairNotes = Array.isArray(lastRepair?.notes) ? lastRepair.notes.filter(Boolean) : [];

  if (!data.gatewayReachable) {
    return {
      tone: 'error',
      summary: getOpenClawGatewayStatusLabel(data),
      detail: 'Gateway 尚未运行，Dashboard 认证还没有开始。',
      session: '不可用',
      issues: [],
    };
  }

  if (authMode === 'none') {
    return {
      tone: 'ok',
      summary: '无需认证',
      detail: '当前 Control UI 不要求 token 或密码。',
      session: '无需会话',
      issues: [],
    };
  }

  if (authMode === 'password') {
    return {
      tone: 'warn',
      summary: '需手动输入密码',
      detail: '应用无法替你填写浏览器里的密码框。',
      session: '待人工确认',
      issues: [{ tone: 'warn', title: 'Dashboard 需要密码认证', copy: 'Gateway 已在线，但 Control UI 还需要你在浏览器里输入密码后才能连上。', action: { type: 'open-openclaw-dashboard', label: '打开 Dashboard' } }],
    };
  }

  if (!tokenReady) {
    return {
      tone: 'error',
      summary: '缺少 token',
      detail: 'Gateway 已启用 token 认证，但当前没有检测到可用 token。',
      session: '认证失败',
      issues: [{ tone: 'error', title: 'Gateway 缺少令牌', copy: '当前启用了 token 鉴权，但没有检测到可用 token，Dashboard 会提示 unauthorized / 4008。', action: { type: 'repair-openclaw-dashboard', label: '一键修复并打开' } }],
    };
  }

  if (!hasTokenizedUrl) {
    return {
      tone: 'error',
      summary: '缺少令牌化 URL',
      detail: '当前没有拿到带 token 的 Dashboard 启动链接。',
      session: '认证失败',
      issues: [{ tone: 'error', title: 'Dashboard 启动链接缺少 token', copy: 'Control UI 需要令牌化 URL 才能引导浏览器建立认证会话。', action: { type: 'repair-openclaw-dashboard', label: '重新生成并打开' } }],
    };
  }

  const copy = lastRepair
    ? '已执行自动修复，但应用无法直接读取外部浏览器会话；如果浏览器仍报 4008，通常是旧会话/旧 token 残留。'
    : '应用无法直接读取外部浏览器会话；如果浏览器仍报 4008，请重新打开令牌化 URL。';

  return {
    tone: 'warn',
    summary: '待浏览器确认',
    detail: copy,
    session: lastRepair ? '已修复待确认' : '未验证',
    issues: [{ tone: 'warn', title: 'Dashboard 认证需浏览器确认', copy, action: { type: 'repair-openclaw-dashboard', label: '重新打开认证链接' } }],
    notes: repairNotes,
  };
}

function buildCodexConsoleView() {
  const data = state.current || {};
  const codexBinary = getToolBinaryStatus('codex', data.codexBinary);
  const providers = data.providers || [];
  const active = data.activeProvider || null;
  const login = data.login || {};
  const health = active ? state.providerHealth[active.key] : null;
  const issues = [];

  if (!codexBinary.installed) {
    issues.push({ tone: 'error', title: 'Codex 未安装', copy: '还没检测到 codex 命令，先去"工具安装"里安装。', action: { type: 'goto-page', page: 'tools', label: '去安装' } });
  }
  if (!data.configExists) {
    issues.push({ tone: 'warn', title: '还没有 Codex 配置', copy: '当前作用域尚未写入 config.toml，建议先完成一次快速配置。', action: { type: 'goto-quick-tool', tool: 'codex', label: '去快速配置' } });
  }
  if (!providers.length && !login.loggedIn) {
    issues.push({ tone: 'error', title: '没有可用 Provider', copy: '当前配置里还没有保存任何 Provider，Codex 启动后通常无法正常请求模型。', action: { type: 'goto-config-editor-tool', tool: 'codex', label: '去配 Provider' } });
  }
  if (active && !active.hasApiKey) {
    issues.push({ tone: 'error', title: '当前 Provider 缺少密钥', copy: `活动 Provider "${active.name}" 已选中，但没有检测到可用 API Key。`, action: { type: 'goto-quick-tool', tool: 'codex', label: '去补 Key' } });
  }
  if (!active && login.loggedIn) {
    issues.push({ tone: 'warn', title: '已识别官方登录态', copy: '当前检测到 Codex 官方登录，可直接使用 OpenAI 官方线路；如果你想改成代理/中转，再单独保存 Provider。', action: { type: 'goto-quick-tool', tool: 'codex', label: '去快速配置' } });
  }
  if (health?.checked && !health.ok) {
    issues.push({ tone: 'warn', title: '当前 Provider 连通性异常', copy: `已对 "${active?.name || '当前 Provider'}" 做过检测，但结果不通过。`, action: { type: 'refresh-console', label: '重新检测' } });
  }

  const summary = [
    renderToolConsoleStat('安装状态', codexBinary.installed ? (codexBinary.version || '已安装') : '未安装', codexBinary.path ? `<span class="tool-console-code">${escapeHtml(codexBinary.path)}</span>` : '', { icon: 'install' }),
    renderToolConsoleStat('作用域', data.scope === 'project' ? '项目级' : '全局', data.rootPath ? `<span class="tool-console-code">${escapeHtml(data.rootPath)}</span>` : '', { icon: 'scope' }),
    renderToolConsoleStat('活动 Provider', active?.name || (login.loggedIn ? 'OpenAI 官方登录' : '未选择'), active?.baseUrl ? `<span class="tool-console-code">${escapeHtml(active.baseUrl)}</span>` : login.loggedIn ? (login.plan || login.email || 'ChatGPT / OpenAI 认证已就绪') : '还没有可用 Provider', { icon: 'provider' }),
    renderToolConsoleStat('健康检测', active ? (health?.loading ? '检测中' : health?.checked ? (health.ok ? '通过' : '失败') : '未检测') : login.loggedIn ? '已登录' : '未检测', active ? `模型：${escapeHtml(data.summary?.model || '-')}` : login.loggedIn ? '官方登录模式通常无需额外 Provider' : '先保存 Provider 再检测', { icon: 'health' }),
  ].join('');

  const providerBody = providers.length
    ? `<div class="tool-console-item-list">${providers.map((provider) => {
        const itemHealth = state.providerHealth[provider.key];
        const chips = [
          provider.isActive ? '当前使用' : '已保存',
          provider.hasApiKey ? 'Key 就绪' : '缺少 Key',
          itemHealth?.loading ? '检测中' : itemHealth?.checked ? (itemHealth.ok ? '连通通过' : '连通失败') : '待检测',
        ];
        return renderToolConsoleItem({
          title: provider.name,
          meta: provider.isActive ? '当前活动 Provider' : '已保存 Provider',
          chips,
          body: `<div class="tool-console-list compact">${renderToolConsoleRow('Base URL', `<span class="tool-console-code">${escapeHtml(provider.baseUrl || '-')}</span>`, { html: true })}${renderToolConsoleRow('密钥来源', provider.keySource || provider.resolvedKeyName || '-')}</div>`,
        });
      }).join('')}</div>`
    : login.loggedIn ? '<div class="tool-console-empty">当前未保存自定义 Provider，但已识别到 Codex 官方登录态，可直接使用官方 OpenAI 线路。</div>' : '<div class="tool-console-empty">当前没有已保存的 Codex Provider。</div>';

  const main = [
    renderToolConsoleCard('状态总览', '安装、配置与当前模型', `<div class="tool-console-list">${renderToolConsoleRow('配置文件', `<span class="tool-console-code">${escapeHtml(data.configPath || '-')}</span>`, { html: true })}${renderToolConsoleRow('环境变量文件', `<span class="tool-console-code">${escapeHtml(data.envPath || '-')}</span>`, { html: true })}${renderToolConsoleRow('Sandbox', data.summary?.sandboxMode || '默认')}${renderToolConsoleRow('审批策略', data.summary?.approvalPolicy || '默认')}${renderToolConsoleRow('推理强度', data.summary?.reasoningEffort || '默认')}</div>`, { icon: 'status' }),
    renderToolConsoleCard('Provider 检测', '已保存 Provider 与密钥状态', providerBody, { icon: 'providers' }),
    renderToolConsoleCard('异常检测', '会优先指出最影响启动与请求的问题', renderToolConsoleIssueList(issues, 'Codex 侧暂未发现明显阻塞项。'), { icon: 'issues', iconTone: issues.length ? (issues.some(i => i.tone === 'error') ? 'error' : 'warn') : 'ok' }),
  ].join('');

  const side = [
    renderToolConsoleCard('推荐操作', '常用排错入口', `<div class="tool-console-actions">${[
      { type: 'refresh-console', label: '重新检测', primary: true },
      { type: 'goto-config-editor-tool', tool: 'codex', label: '查看 Provider' },
      { type: 'goto-config-editor-tool', tool: 'codex', label: '打开配置编辑' },
      { type: 'goto-quick-tool', tool: 'codex', label: '切到快速配置' },
    ].map(renderToolConsoleAction).join('')}</div>`, { icon: 'actions' }),
  ].join('');

  return { summary, main, side, activity: '' };
}

function buildClaudeConsoleView() {
  const data = state.claudeCodeState || {};
  const login = data.login || {};
  const issues = [];

  if (!data.binary?.installed) issues.push({ tone: 'error', title: 'Claude Code 未安装', copy: '还没检测到 Claude Code 命令，先去"工具安装"完成安装。', action: { type: 'goto-page', page: 'tools', label: '去安装' } });
  if (!login.loggedIn && !data.hasApiKey) issues.push({ tone: 'error', title: 'Claude Code 尚未认证', copy: '当前既没有登录态，也没有检测到可用 API Key。', action: { type: 'goto-quick-tool', tool: 'claudecode', label: '去快速配置' } });
  if (!data.model) issues.push({ tone: 'warn', title: '默认模型未显式指定', copy: 'Claude Code 会回退到自身默认模型；如果你想可控，建议手动指定。', action: { type: 'goto-quick-tool', tool: 'claudecode', label: '设置模型' } });

  const summary = [
    renderToolConsoleStat('安装状态', data.binary?.installed ? (data.binary.version || '已安装') : '未安装', data.binary?.path ? `<span class="tool-console-code">${escapeHtml(data.binary.path)}</span>` : '', { icon: 'install' }),
    renderToolConsoleStat('认证状态', login.loggedIn ? (login.method === 'oauth' ? 'OAuth 已登录' : 'API Key 已就绪') : '未认证', login.email || login.orgName ? escapeHtml([login.email, login.orgName].filter(Boolean).join(' · ')) : '建议先完成认证', { icon: 'auth' }),
    renderToolConsoleStat('默认模型', data.model || '由 Claude Code 决定', data.alwaysThinkingEnabled ? 'Always thinking 已开启' : '按默认推理策略运行', { icon: 'model' }),
    renderToolConsoleStat('历史模型', String((data.usedModels || []).length || 0), (data.usedModels || []).length ? `${data.usedModels.length} 个历史模型别名/全名` : '还没有历史模型记录', { icon: 'history' }),
  ].join('');

  const modelsBody = (data.usedModels || []).length
    ? `<div class="tool-console-badges">${data.usedModels.map(renderToolConsoleChip).join('')}</div>`
    : '<div class="tool-console-empty">当前还没有历史模型记录。</div>';

  const main = [
    renderToolConsoleCard('状态总览', '登录、配置与行为开关', `<div class="tool-console-list">${renderToolConsoleRow('settings.json', `<span class="tool-console-code">${escapeHtml(data.settingsPath || '-')}</span>`, { html: true })}${renderToolConsoleRow('登录方式', login.loggedIn ? (login.method || '已登录') : '未登录')}${renderToolConsoleRow('Always thinking', data.alwaysThinkingEnabled ? '开启' : '关闭')}${renderToolConsoleRow('危险权限提示', data.skipDangerousModePermissionPrompt ? '已跳过' : '保持提示')}</div>`, { icon: 'status' }),
    renderToolConsoleCard('历史模型', '便于回看最近用过什么模型', modelsBody, { icon: 'models' }),
    renderToolConsoleCard('异常检测', '优先指出安装、登录和模型配置问题', renderToolConsoleIssueList(issues, 'Claude Code 侧暂未发现明显阻塞项。'), { icon: 'issues', iconTone: issues.length ? (issues.some(i => i.tone === 'error') ? 'error' : 'warn') : 'ok' }),
  ].join('');

  const side = [
    renderToolConsoleCard('推荐操作', '常用入口', `<div class="tool-console-actions">${[
      { type: 'refresh-console', label: '重新检测', primary: true },
      { type: 'goto-quick-tool', tool: 'claudecode', label: '切到快速配置' },
      { type: 'goto-page', page: 'tools', label: '查看安装状态' },
    ].map(renderToolConsoleAction).join('')}</div>`, { icon: 'actions' }),
  ].join('');

  return { summary, main, side, activity: '' };
}

function buildOpenCodeConsoleView() {
  const data = state.opencodeState || {};
  const active = data.activeProvider || null;
  const providers = data.providers || [];
  const authEntries = data.authEntries || [];
  const activeAuth = data.activeAuth || null;
  const issues = [];

  if (!data.binary?.installed) issues.push({ tone: 'error', title: 'OpenCode 未安装', copy: '当前还没检测到 opencode 命令，先去“工具安装”完成安装。', action: { type: 'goto-page', page: 'tools', label: '去安装' } });
  if (!data.configExists) issues.push({ tone: 'warn', title: '还没有 OpenCode 配置', copy: '当前作用域还没有写入 `opencode.json` / `opencode.jsonc`。', action: { type: 'goto-quick-tool', tool: 'opencode', label: '去快速配置' } });
  if (!data.model) issues.push({ tone: 'warn', title: '默认模型未设置', copy: 'OpenCode 模型格式通常是 `provider/model`，建议先固定默认模型。', action: { type: 'goto-quick-tool', tool: 'opencode', label: '去设置模型' } });
  if (!providers.length) issues.push({ tone: 'warn', title: '未配置 Provider', copy: '当前配置中还没有可用的 provider 节点。', action: { type: 'goto-config-editor-tool', tool: 'opencode', label: '去配置' } });
  if (active && !active.hasCredential) issues.push({ tone: 'warn', title: '当前 Provider 缺少凭证', copy: `活动 Provider "${active.name || active.key}" 还没有保存 API Key，也没有 auth 登录。`, action: { type: 'goto-quick-tool', tool: 'opencode', label: '去补凭证' } });
  if (!authEntries.length && !providers.some((provider) => provider.hasApiKey)) issues.push({ tone: 'warn', title: '尚未登录 OpenCode Provider', copy: '当前没发现 auth.json 凭证，也没发现已保存 API Key。', action: { type: 'opencode-auth-login', provider: active?.key || '', label: '启动 auth login' } });

  const summary = [
    renderToolConsoleStat('安装状态', data.binary?.installed ? (data.binary.version || '已安装') : '未安装', data.binary?.path ? `<span class="tool-console-code">${escapeHtml(data.binary.path)}</span>` : '', { icon: 'install' }),
    renderToolConsoleStat('作用域', data.scope === 'project' ? '项目级' : '全局', data.rootPath ? `<span class="tool-console-code">${escapeHtml(data.rootPath)}</span>` : '', { icon: 'scope' }),
    renderToolConsoleStat('默认模型', data.model || '未设置', data.smallModel || '未设置 small_model', { icon: 'model' }),
    renderToolConsoleStat('认证状态', activeAuth ? `${activeAuth.type || 'auth'} 已登录` : (active?.hasApiKey ? 'API Key 已保存' : '未认证'), activeAuth?.key || active?.baseUrl || '等待配置', { icon: 'auth' }),
  ].join('');

  const providerBody = providers.length
    ? `<div class="tool-console-item-list">${providers.map((provider) => renderToolConsoleItem({
        title: provider.name || provider.key,
        meta: provider.key,
        chips: [provider.hasCredential ? '凭证就绪' : '缺少凭证', provider.hasAuth ? `${provider.authType || 'auth'} 登录` : '未登录', `${(provider.modelIds || []).length} models`],
        body: `<div class="tool-console-list compact">${renderToolConsoleRow('Base URL', provider.baseUrl ? `<span class="tool-console-code">${escapeHtml(provider.baseUrl)}</span>` : '-', { html: Boolean(provider.baseUrl) })}${renderToolConsoleRow('npm', provider.npm || '@ai-sdk/openai-compatible')}${renderToolConsoleRow('模型', (provider.modelIds || []).join(', ') || '未显式声明')}</div>`,
      })).join('')}</div>`
    : '<div class="tool-console-empty">当前还没有配置任何 OpenCode Provider。</div>';

  const authBody = authEntries.length
    ? `<div class="tool-console-item-list">${authEntries.map((entry) => renderToolConsoleItem({
        title: entry.key,
        meta: entry.type || 'unknown',
        chips: [entry.hasCredential ? '已就绪' : '缺失', entry.expiresAt ? `到期 ${formatOpenCodeAuthExpiry(entry.expiresAt)}` : '长期有效'],
        body: `<div class="tool-console-list compact">${renderToolConsoleRow('凭证', entry.maskedSecret || '-')}${renderToolConsoleRow('到期', entry.expiresAt ? formatOpenCodeAuthExpiry(entry.expiresAt) : '-')}</div>`,
      })).join('')}</div>`
    : '<div class="tool-console-empty">当前还没有检测到 OpenCode auth.json 凭证。</div>';

  const actions = [
    { type: 'refresh-console', label: '重新检测', primary: true },
    { type: 'goto-quick-tool', tool: 'opencode', label: '切到快速配置' },
    { type: 'goto-config-editor-tool', tool: 'opencode', label: '打开配置编辑' },
    { type: 'goto-page', page: 'tools', label: '查看安装状态' },
  ];
  if (data.binary?.installed) actions.splice(1, 0, { type: 'opencode-auth-login', provider: active?.key || '', label: '启动 auth login' });
  if (activeAuth?.key) actions.splice(2, 0, { type: 'opencode-auth-remove', authKey: activeAuth.key, label: '移除当前凭证' });

  const main = [
    renderToolConsoleCard('状态总览', '安装、配置和当前模型', `<div class="tool-console-list">${renderToolConsoleRow('配置文件', `<span class="tool-console-code">${escapeHtml(data.configPath || '-')}</span>`, { html: true })}${renderToolConsoleRow('鉴权文件', `<span class="tool-console-code">${escapeHtml(data.authPath || '-')}</span>`, { html: true })}${renderToolConsoleRow('默认模型', data.model || '-')}${renderToolConsoleRow('Small model', data.smallModel || '-')}${renderToolConsoleRow('当前 Provider', active?.key || '-')}${renderToolConsoleRow('当前 auth', activeAuth?.key || '-')}</div>`, { icon: 'status' }),
    renderToolConsoleCard('Provider 列表', '按源码字段展示 provider / options / models', providerBody, { icon: 'providers' }),
    renderToolConsoleCard('认证状态', '来自 auth.json 的 Provider 登录凭证', authBody, { icon: 'actions' }),
    renderToolConsoleCard('异常检测', '优先提示安装、模型和凭证问题', renderToolConsoleIssueList(issues, 'OpenCode 侧暂未发现明显阻塞项。'), { icon: 'issues', iconTone: issues.length ? (issues.some(i => i.tone === 'error') ? 'error' : 'warn') : 'ok' }),
  ].join('');

  const side = [
    renderToolConsoleCard('推荐操作', '常用入口', `<div class="tool-console-actions">${actions.map(renderToolConsoleAction).join('')}</div>`, { icon: 'actions' }),
  ].join('');

  return { summary, main, side, activity: '' };
}

function buildOpenClawConsoleView() {
  const data = state.openclawState || {};
  const lastRepair = state.openClawLastRepair || null;
  const quick = deriveOpenClawQuickConfig(data);
  const config = data.config || {};
  const channels = getOpenClawConsoleChannels(config);
  const providers = getOpenClawConsoleProviders(config);
  const agentInfo = getOpenClawConsoleAgents(config);
  const defaults = agentInfo.defaults || {};
  const gatewayBind = String(config.gateway?.bind || 'local');
  const gatewayAuth = String(data.gatewayAuthMode || config.gateway?.auth?.mode || 'token');
  const dashboardAuth = deriveOpenClawDashboardAuthDiagnostics(data, lastRepair);
  const issues = [];

  if (!data.binary?.installed) issues.push({ tone: 'error', title: 'OpenClaw 未安装', copy: '当前还没检测到 openclaw 命令，先去"工具安装"完成安装。', action: { type: 'goto-page', page: 'tools', label: '去安装' } });
  if (!data.configExists) issues.push({ tone: 'warn', title: 'openclaw.json 尚未生成', copy: '说明还没完成初始化或还没真正保存过配置。', action: { type: 'goto-quick-tool', tool: 'openclaw', label: '去快速配置' } });
  if (data.needsOnboarding) issues.push({ tone: 'warn', title: 'OpenClaw 仍需初始化', copy: '当前还没有生成 `openclaw.json`，先完成首次初始化。', action: { type: 'launch-openclaw', label: '启动并初始化' } });
  if (!data.gatewayReachable && !data.gatewayPortListening) issues.push({ tone: 'warn', title: 'Dashboard 未在线', copy: '当前没探测到本地 Gateway，很多渠道回调和控制面板操作都会失效。', action: { type: 'launch-openclaw', label: '启动 Gateway' } });
  if (!data.gatewayReachable && data.gatewayPortListening) issues.push({ tone: 'warn', title: 'Gateway 正在启动中', copy: '端口已经监听，但控制面板还没完全就绪。通常再等几秒就会恢复。', action: { type: 'refresh-console', label: '重新检测' } });
  if (data.gatewayPortConflict) issues.push({ tone: 'error', title: `端口 ${data.gatewayPort || '18789'} 已被其他进程占用`, copy: '这会导致 OpenClaw Gateway 无法正常启动或一直显示启动中。', action: { type: 'kill-openclaw-port', label: '结束占用进程' } });
  if (!providers.length) issues.push({ tone: 'error', title: '没有配置模型 Provider', copy: 'OpenClaw 已安装，但 `models.providers` 里还没有可用模型源。', action: { type: 'goto-config-editor-tool', tool: 'openclaw', label: '去配置 Provider' } });
  if (!quick.model) issues.push({ tone: 'error', title: '默认 Agent 模型未设置', copy: '当前没有检测到 `agents.defaults.model.primary`，聊天入口通常无法正常出结果。', action: { type: 'goto-config-editor-tool', tool: 'openclaw', label: '去设置模型' } });
  if (providers.length && !quick.hasApiKey) issues.push({ tone: 'error', title: '默认 Provider 缺少 API Key', copy: `已检测到默认模型 ${quick.model || '-'}，但没有找到它对应的 API Key。`, action: { type: 'goto-quick-tool', tool: 'openclaw', label: '去补 Key' } });
  if ((gatewayBind === 'lan' || gatewayBind === '0.0.0.0') && gatewayAuth === 'none') issues.push({ tone: 'error', title: '网络已暴露但未启用认证', copy: '当前 Gateway 允许局域网/公网访问，但认证模式为 none，风险较高。', action: { type: 'goto-config-editor-tool', tool: 'openclaw', label: '去修安全配置' } });
  if (channels.some((item) => ['wechat', 'wechatWork', 'wechatwork', 'webhook'].includes(item.key)) && !config.gateway?.tls && !config.gateway?.trustProxy) issues.push({ tone: 'warn', title: '公网回调场景建议补 HTTPS / 反代', copy: '你已经在配公众号、企微或 Webhook，一般需要公网 HTTPS 或反向代理才能稳定接入。', action: { type: 'goto-config-editor-tool', tool: 'openclaw', label: '去配网关' } });
  issues.push(...(dashboardAuth.issues || []));

  const summary = [
    renderToolConsoleStat('安装状态', data.binary?.installed ? (data.binary.version || '已安装') : '未安装', data.binary?.path ? `<span class="tool-console-code">${escapeHtml(data.binary.path)}</span>` : '', { icon: 'install' }),
    renderToolConsoleStat('Dashboard', getOpenClawGatewayStatusLabel(data), (data.dashboardUrl || data.gatewayUrl) ? `<span class="tool-console-code">${escapeHtml(data.dashboardUrl || data.gatewayUrl)}</span>` : '等待本地 Gateway 启动', { icon: 'dashboard' }),
    renderToolConsoleStat('常驻服务', getOpenClawDaemonStatusLabel(data), data.daemon?.detail || '当前未启用常驻服务', { icon: 'runtime' }),
    renderToolConsoleStat('默认 Agent', quick.model || defaults.model?.primary || '未设置', defaults.thinkingDefault ? `thinking=${escapeHtml(defaults.thinkingDefault)}` : '建议先固定默认模型', { icon: 'agent' }),
  ].join('');

  const customAgentsBody = agentInfo.customAgents.length
    ? `<div class="tool-console-item-list">${agentInfo.customAgents.map((agent) => renderToolConsoleItem({
        title: agent.key,
        meta: '自定义 Agent',
        body: `<div class="tool-console-list compact">${renderToolConsoleRow('模型', agent.model)}${renderToolConsoleRow('Workspace', agent.workspace)}</div>`,
      })).join('')}</div>`
    : '<div class="tool-console-empty">当前只有默认 Agent，没有单独定义的命名 Agent。</div>';

  const providerBody = providers.length
    ? `<div class="tool-console-item-list">${providers.map((provider) => renderToolConsoleItem({
        title: provider.key,
        meta: provider.api,
        body: `<div class="tool-console-list compact">${renderToolConsoleRow('Base URL', provider.baseUrl ? `<span class="tool-console-code">${escapeHtml(provider.baseUrl)}</span>` : '-', { html: Boolean(provider.baseUrl) })}${renderToolConsoleRow('模型数量', provider.modelCount ? String(provider.modelCount) : '未显式配置')}</div>`,
      })).join('')}</div>`
    : '<div class="tool-console-empty">当前还没有配置任何 OpenClaw Provider。</div>';

  const channelBody = channels.length
    ? `<div class="tool-console-badges">${channels.map((item) => renderToolConsoleChip(item.label)).join('')}</div>`
    : '<div class="tool-console-empty">当前还没有接入聊天渠道。</div>';

  const main = [
    renderToolConsoleCard('Gateway 状态', '进程、认证与 Dashboard 引导链接', `<div class="tool-console-list">${renderToolConsoleRow('配置文件', `<span class="tool-console-code">${escapeHtml(data.configPath || '-')}</span>`, { html: true })}${renderToolConsoleRow('Gateway 状态', getOpenClawGatewayStatusLabel(data))}${renderToolConsoleRow('常驻服务', getOpenClawDaemonStatusLabel(data))}${renderToolConsoleRow('Gateway HTTP', data.gatewayReachable ? '在线' : data.gatewayPortListening ? '等待面板就绪' : '未就绪')}${renderToolConsoleRow('端口占用', renderOpenClawPortOccupants(data), { html: true })}${renderToolConsoleRow('Bind', gatewayBind)}${renderToolConsoleRow('Auth', gatewayAuth)}${renderToolConsoleRow('Token', data.gatewayTokenReady ? '已就绪' : '缺失')}${renderToolConsoleRow('Dashboard URL', data.dashboardUrl ? `<span class="tool-console-code">${escapeHtml(data.dashboardUrl)}</span>` : '-', { html: Boolean(data.dashboardUrl) })}${renderToolConsoleRow('Onboarding', data.needsOnboarding ? '待完成' : '已完成')}</div>`, { icon: 'runtime' }),
    renderToolConsoleCard('Dashboard 认证状态', 'Control UI 认证、令牌化链接与浏览器会话', `<div class="tool-console-list">${renderToolConsoleRow('状态', dashboardAuth.summary)}${renderToolConsoleRow('认证模式', gatewayAuth)}${renderToolConsoleRow('令牌化 URL', /[?&]token=/.test(String(data.dashboardUrl || '')) ? '已就绪' : '缺失')}${renderToolConsoleRow('浏览器会话', dashboardAuth.session)}${renderToolConsoleRow('诊断', dashboardAuth.detail)}${renderToolConsoleRow('修复备注', (dashboardAuth.notes || []).length ? (dashboardAuth.notes || []).join(' | ') : '无')}</div>`, { icon: 'issues', iconTone: dashboardAuth.tone === 'error' ? 'error' : dashboardAuth.tone === 'ok' ? 'ok' : 'warn' }),
    renderToolConsoleCard('修复结果', '最近一次一键修复的执行结果', lastRepair ? `<div class="tool-console-list">${renderToolConsoleRow('Token 生成', lastRepair.tokenGenerated ? '是' : '否')}${renderToolConsoleRow('要求重启', lastRepair.restartRequired ? '是' : '否')}${renderToolConsoleRow('修复后 Gateway', getOpenClawGatewayStatusLabel(lastRepair))}${renderToolConsoleRow('修复后 URL', lastRepair.dashboardUrl ? `<span class="tool-console-code">${escapeHtml(lastRepair.dashboardUrl)}</span>` : '-', { html: Boolean(lastRepair.dashboardUrl) })}${renderToolConsoleRow('备注', (lastRepair.notes || []).length ? escapeHtml(lastRepair.notes.join(' | ')) : '无')}</div>` : '<div class="tool-console-empty">还没有执行过“一键修复并打开”。</div>', { icon: 'actions' }),
  ].join('');

  const side = [
    renderToolConsoleCard('启动提醒', '是否已启动与优先处理事项', `<div class="tool-console-list">${renderToolConsoleRow('当前状态', getOpenClawGatewayStatusLabel(data))}${renderToolConsoleRow('是否可打开 Dashboard', data.gatewayReachable ? '可以' : data.gatewayPortListening ? '稍等片刻' : '还不行')}${renderToolConsoleRow('异常数量', issues.length ? String(issues.length) : '0')}</div>${renderToolConsoleIssueList(issues.slice(0, 3), '当前没有明显异常。')}`, { icon: 'issues', iconTone: issues.length ? (issues.some(i => i.tone === 'error') ? 'error' : 'warn') : 'ok' }),
    renderToolConsoleCard('快速操作', '检测、启动、停止', `<div class="tool-console-actions">${[
      { type: 'refresh-console', label: '重新检测', primary: true },
      data.gatewayReachable ? { type: 'open-openclaw-dashboard', label: '打开 Dashboard' } : data.gatewayPortListening ? { type: 'refresh-console', label: '查看启动状态' } : { type: 'launch-openclaw', label: '启动 OpenClaw' },
      { type: 'repair-openclaw-dashboard', label: '一键修复并打开' },
      data.gatewayPortOccupants?.length ? { type: 'kill-openclaw-port', label: '结束端口占用' } : null,
      { type: 'toggle-openclaw-daemon', label: data.daemonInstalled ? '关闭常驻服务' : '开启常驻服务' },
      { type: 'stop-openclaw', label: '停止 Gateway' },
      { type: 'goto-config-editor-tool', tool: 'openclaw', label: '打开配置编辑' },
      { type: 'goto-quick-tool', tool: 'openclaw', label: '切到快速配置' },
    ].filter(Boolean).map(renderToolConsoleAction).join('')}</div>`, { icon: 'actions' }),
    renderToolConsoleCard('渠道与 Provider', '接入的渠道和模型源', `${channelBody}${renderToolConsoleGroupLabel('Provider')}${providerBody}`, { icon: 'channels' }),
  ].join('');

  // Build activity panel (agent grid + issues log)
  const activitySections = [];

  // Error / Issue log (always show if issues exist)
  if (issues.length) {
    const logItems = issues.map((issue) => {
      const level = issue.tone === 'error' ? 'error' : issue.tone === 'ok' ? 'ok' : 'warn';
      return `<div class="tc-log-item"><div class="tc-log-level ${level}"></div><div class="tc-log-message">${escapeHtml(issue.title)}: ${escapeHtml(issue.copy)}</div></div>`;
    }).join('');
    activitySections.push(`
      <details class="tc-activity-section" open>
        <summary class="tc-activity-summary">
          <span class="tc-activity-icon logs"><svg width="12" height="12" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><path d="M8 2l6 11H2L8 2z"/><path d="M8 7v3"/><circle cx="8" cy="12" r="0.5" fill="currentColor" stroke="none"/></svg></span>
          错误与告警
          <span class="tc-activity-badge">${issues.length} 项</span>
        </summary>
        <div class="tc-activity-body"><div class="tc-log-list">${logItems}</div></div>
      </details>
    `);
  }

  // Agent activity
  const allAgents = [
    { key: 'defaults', model: quick.model || defaults.model?.primary || '-', workspace: defaults.workspace || '~' },
    ...agentInfo.customAgents,
  ];
  if (allAgents.length) {
    const agentCards = allAgents.map((agent) => `
      <div class="tc-agent-card">
        <div class="tc-agent-name">${escapeHtml(agent.key)}</div>
        <div class="tc-agent-meta">模型: ${escapeHtml(agent.model)}<br>目录: ${escapeHtml(agent.workspace || '~')}</div>
      </div>
    `).join('');
    activitySections.push(`
      <details class="tc-activity-section">
        <summary class="tc-activity-summary">
          <span class="tc-activity-icon agents"><svg width="12" height="12" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><circle cx="8" cy="5" r="2.5"/><path d="M3.5 14c0-2.5 2-4.5 4.5-4.5s4.5 2 4.5 4.5"/></svg></span>
          Agent 活动
          <span class="tc-activity-badge info">${allAgents.length} 个</span>
        </summary>
        <div class="tc-activity-body"><div class="tc-agent-grid">${agentCards}</div></div>
      </details>
    `);
  }

  // Channel listing (detailed)
  if (channels.length) {
    const channelItems = channels.map((ch) => `
      <div class="tc-log-item">
        <div class="tc-log-level ok"></div>
        <div class="tc-log-message">${escapeHtml(ch.label)}</div>
        <div class="tc-log-time">${escapeHtml(ch.key)}</div>
      </div>
    `).join('');
    activitySections.push(`
      <details class="tc-activity-section">
        <summary class="tc-activity-summary">
          <span class="tc-activity-icon channels"><svg width="12" height="12" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><path d="M2 12l3-3h7a2 2 0 0 0 2-2V4a2 2 0 0 0-2-2H4a2 2 0 0 0-2 2v8z"/></svg></span>
          接入渠道
          <span class="tc-activity-badge info">${channels.length} 个</span>
        </summary>
        <div class="tc-activity-body"><div class="tc-log-list">${channelItems}</div></div>
      </details>
    `);
  }

  return { summary, main, side, activity: activitySections.join('') };
}

function getToolStatusDot(tool) {
  if (tool === 'codex') {
    const data = state.current || {};
    if (!getToolBinaryStatus('codex', data.codexBinary).installed) return 'error';
    const active = data.activeProvider;
    const login = data.login || {};
    if (active) {
      const health = state.providerHealth[active.key];
      if (health?.checked && !health.ok) return 'warning';
      if (health?.checked && health.ok) return 'online';
    }
    if (login.loggedIn) return 'online';
    return data.configExists ? 'online' : 'warning';
  }
  if (tool === 'claudecode') {
    const data = state.claudeCodeState || {};
    if (!data.binary?.installed) return 'error';
    const login = data.login || {};
    if (login.loggedIn || data.hasApiKey) return 'online';
    return 'warning';
  }
  if (tool === 'opencode') {
    const data = state.opencodeState || {};
    if (!data.binary?.installed) return 'error';
    if (data.activeProvider?.hasApiKey && data.model) return 'online';
    if (data.configExists) return 'warning';
    return 'offline';
  }
  if (tool === 'openclaw') {
    const data = state.openclawState || {};
    if (!data.binary?.installed) return 'error';
    if (data.gatewayReachable) return 'online';
    if (data.configExists) return 'warning';
    return 'offline';
  }
  return 'offline';
}

function renderToolConsole() {
  const tool = state.consoleTool || 'codex';

  // v2 page uses the hub-style lean layout; if the v2 container exists we
  // render into it and stop. Legacy tabs + 4-stat-card layout is retained
  // behind hidden DOM only to keep any ancient event listeners happy.
  const v2 = document.getElementById('toolConsolePage');
  if (v2 && v2.classList.contains('console-v2')) {
    // Sync the left-rail tool list active state.
    document.querySelectorAll('[data-console-rail-tool]').forEach((btn) => {
      btn.classList.toggle('active', btn.getAttribute('data-console-rail-tool') === tool);
    });
    renderConsoleV2(tool);
    return;
  }

  // ─── Legacy render path (kept for safety; not reachable with v2 DOM) ───
  const summary = el('toolConsoleSummary');
  const main = el('toolConsoleMain');
  const side = el('toolConsoleSide');
  const activityEl = el('toolConsoleActivity');
  if (!summary || !main || !side) return;

  document.querySelectorAll('[data-console-tool]').forEach((button) => {
    button.classList.toggle('active', button.dataset.consoleTool === tool);
  });
  const dotCodex = el('tcDotCodex');
  const dotClaude = el('tcDotClaude');
  const dotOpenCode = el('tcDotOpenCode');
  const dotOpenClaw = el('tcDotOpenClaw');
  if (dotCodex) dotCodex.className = `tc-tab-dot ${getToolStatusDot('codex')}`;
  if (dotClaude) dotClaude.className = `tc-tab-dot ${getToolStatusDot('claudecode')}`;
  if (dotOpenCode) dotOpenCode.className = `tc-tab-dot ${getToolStatusDot('opencode')}`;
  if (dotOpenClaw) dotOpenClaw.className = `tc-tab-dot ${getToolStatusDot('openclaw')}`;

  const view = tool === 'openclaw'
    ? buildOpenClawConsoleView()
    : tool === 'opencode'
      ? buildOpenCodeConsoleView()
      : tool === 'claudecode'
        ? buildClaudeConsoleView()
        : buildCodexConsoleView();

  summary.innerHTML = view.summary;
  main.innerHTML = view.main;
  side.innerHTML = view.side;

  if (activityEl) {
    if (view.activity) {
      activityEl.innerHTML = view.activity;
      activityEl.classList.add('has-content');
    } else {
      activityEl.innerHTML = '';
      activityEl.classList.remove('has-content');
    }
  }
}

// ─── Console v3 — cross-tool: IP firewall + procs + usage + meta ─
// Caches of async-loaded data (populated by loadConsoleSideData()). Each
// render uses the latest snapshot; stale-but-present beats flicker-and-empty.
window.__consoleV3 = window.__consoleV3 || {
  network: null,          // { ok, ip, country, countryCode, verdict, verdictCopy, ... }
  networkLoading: false,
  latency: null,          // { rows:[{label,ms,ok}], summary:{avgMs,reachable,total} }
  latencyLoading: false,
  procsByTool: {},        // { codex: [...], claudecode: [...], ... }
  procsLoading: {},
  codexStats: null,       // { total, today, week, latestMtime, recent, modelDistribution }
  claudeUsage: null,      // { messagesInWindow, windowFirstMessageAt, recent, ... }
  cursorUsage: null,      // { account, totals, modelDistribution, recent, ... } 本地 state.vscdb
  // 会话详情展开：哪一行当前展开，以及已 fetch 过的 detail 缓存
  expandedSession: null,  // { tool, sessionId }
  sessionDetails: {},     // { '<tool>:<sessionId>': { loading, error, data } }
};

// Persistent preference — lives on disk at
//   ~/.codex-config-ui/app-settings.json :: ipGateBlock
// NOT in localStorage; safety-critical toggles must survive browser storage
// wipes. Frontend holds a read-through cache; writes go through the backend
// and the cache is updated on success.
window.__appSettings = window.__appSettings || { loaded: false, data: null };

async function loadAppSettings() {
  try {
    const res = await api('/api/app-settings', { method: 'GET' });
    if (res?.ok) {
      window.__appSettings = { loaded: true, data: res.data || {} };
    } else {
      window.__appSettings = { loaded: true, data: {} };
    }
  } catch (_) {
    window.__appSettings = { loaded: true, data: {} };
  }
  return window.__appSettings.data;
}

async function patchAppSettings(patch) {
  try {
    const res = await api('/api/app-settings', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(patch || {}),
    });
    if (res?.ok) {
      window.__appSettings = { loaded: true, data: res.data || {} };
      return true;
    }
  } catch (err) {
    console.warn('[app-settings] patch failed', err);
  }
  return false;
}

function isIpGateEnabled() {
  return Boolean(window.__appSettings?.data?.ipGateBlock);
}
async function setIpGateEnabled(enabled) {
  // Optimistic update so the toggle flips immediately; backend patch follows.
  window.__appSettings = window.__appSettings || { loaded: true, data: {} };
  window.__appSettings.data = { ...(window.__appSettings.data || {}), ipGateBlock: Boolean(enabled) };
  if (state.activePage === 'console') renderToolConsole();
  await patchAppSettings({ ipGateBlock: Boolean(enabled) });
}

// Called by launchCodex / launchClaudeCodeOnly / launchCodexLogin before
// actually spawning the terminal. Returns true when the caller should proceed.
// Never throws; degrades to "proceed" when the IP check itself errors out.
async function preLaunchIpFirewallCheck(toolLabel) {
  try {
    if (!window.__consoleV3?.network) {
      const res = await api('/api/network/status', { method: 'GET' });
      window.__consoleV3 = window.__consoleV3 || {};
      window.__consoleV3.network = res?.ok ? (res.data || null) : null;
    }
    const n = window.__consoleV3?.network;
    if (!n || n.ok === false) return true; // no IP = no verdict, let the user decide
    if (n.verdict !== 'block') return true;

    // Backend-persisted gate preference (NOT localStorage — must survive
    // browser-storage wipes since this is a safety toggle).
    if (!window.__appSettings?.loaded) await loadAppSettings();
    const gate = isIpGateEnabled();

    if (gate) {
      flash?.(`🚫 启动被防火墙拦截：${n.verdictCopy || '当前 IP 风险高'}`, 'error');
      return false;
    }
    const msg = `🛡 ${n.verdictCopy || '当前 IP 被判定为高风险。'}\n\n出口 IP: ${n.ip} (${n.countryCode})\n\n继续启动 ${toolLabel}？(建议 "取消" 并切换线路)`;
    return window.confirm(msg);
  } catch (_) {
    return true;
  }
}

const OAUTH_IP_WARNING_LS = 'easyaiconfig_oauth_ip_warning_last_at';
const OAUTH_IP_WARNING_INTERVAL_MS = 60 * 60 * 1000;

function getOauthIpRiskMeta(network) {
  if (!network || network.ok === false) return { risky: false, reason: '' };
  const countryCode = String(network.countryCode || network.country || '').trim().toUpperCase();
  const verdict = String(network.verdict || '').trim().toLowerCase();
  if (countryCode && countryCode !== 'US') {
    const label = countryCode === 'CN' ? '中国大陆出口 IP' : `${countryCode} 出口 IP`;
    return { risky: true, reason: `${label}，不是美国线路` };
  }
  if (verdict && verdict !== 'ok') {
    return { risky: true, reason: network.verdictCopy || `当前网络 verdict=${verdict}` };
  }
  return { risky: false, reason: '' };
}

async function confirmOauthIpRiskBeforeRequest(actionLabel = 'Codex OAuth 请求', options = {}) {
  try {
    const silent = Boolean(options?.silent);
    if (!window.__consoleV3?.network) {
      const res = await api('/api/network/status', { method: 'GET' });
      window.__consoleV3 = window.__consoleV3 || {};
      window.__consoleV3.network = res?.ok ? (res.data || null) : null;
    }
    const network = window.__consoleV3?.network;
    const risk = getOauthIpRiskMeta(network);
    if (!risk.risky) return true;

    const lastAt = Number(localStorage.getItem(OAUTH_IP_WARNING_LS) || 0);
    if (lastAt && Date.now() - lastAt < OAUTH_IP_WARNING_INTERVAL_MS) return true;
    if (silent) return false;

    const ip = network?.ip || '未知';
    const country = network?.countryCode || network?.country || '未知';
    const body = `
      <div class="update-line">当前出口 IP：${escapeHtml(ip)} (${escapeHtml(country)})</div>
      <div class="update-line">风险原因：${escapeHtml(risk.reason || '当前线路不适合直接访问官方 OAuth')}</div>
      <div class="update-line">操作：${escapeHtml(actionLabel)}</div>
      <div class="update-line">建议先切到稳定美国线路；继续不会绕过官方风控，只是按你的选择发起请求。</div>`;
    const ok = await openUpdateDialog({
      eyebrow: 'OAuth IP',
      title: '出口 IP 风险确认',
      body,
      confirmText: '继续请求',
      cancelText: '取消',
      tone: 'warning',
    });
    if (ok) {
      try { localStorage.setItem(OAUTH_IP_WARNING_LS, String(Date.now())); } catch {}
    }
    return Boolean(ok);
  } catch (_) {
    return true;
  }
}

async function loadConsoleNetworkStatus({ force = false } = {}) {
  if (window.__consoleV3.networkLoading) return;
  window.__consoleV3.networkLoading = true;
  try {
    const path = force ? '/api/network/check' : '/api/network/status';
    const res = await api(path, force ? {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ force: true }),
    } : { method: 'GET' });
    window.__consoleV3.network = res?.ok ? (res.data || {}) : { ok: false, error: res?.error || 'network error' };
  } catch (err) {
    window.__consoleV3.network = { ok: false, error: String(err) };
  } finally {
    window.__consoleV3.networkLoading = false;
    if (state.activePage === 'console') renderToolConsole();
  }
}

async function loadConsoleLatency() {
  if (window.__consoleV3.latencyLoading) return;
  window.__consoleV3.latencyLoading = true;
  try {
    const res = await api('/api/network/latency', { method: 'GET', timeoutMs: 8000 });
    window.__consoleV3.latency = res?.ok ? (res.data || null) : null;
  } catch (_) {
    window.__consoleV3.latency = null;
  } finally {
    window.__consoleV3.latencyLoading = false;
    if (state.activePage === 'console') renderToolConsole();
  }
}

async function loadConsoleProcs(tool) {
  if (window.__consoleV3.procsLoading[tool]) return;
  window.__consoleV3.procsLoading[tool] = true;
  try {
    const res = await api(`/api/system/processes?tool=${encodeURIComponent(tool)}`, { method: 'GET' });
    window.__consoleV3.procsByTool[tool] = res?.ok ? (res.data?.rows || []) : [];
  } catch (err) {
    window.__consoleV3.procsByTool[tool] = [];
  } finally {
    window.__consoleV3.procsLoading[tool] = false;
    if (state.activePage === 'console' && (state.consoleTool || 'codex') === tool) renderToolConsole();
  }
}

// 会话详情：从 detail map 里拿出当前会话的状态，render 折叠面板。
// Codex 有 /api/codex/session-detail 真接口；Claude 暂无后端，渲染已知字段。
function renderSessionDetailPanel(tool, sessionId, fallbackRow = null) {
  const key = `${tool}:${sessionId}`;
  const entry = window.__consoleV3.sessionDetails[key] || {};
  const esc = escapeHtml;
  if (entry.loading) {
    return `<div class="cv3-session-detail"><div class="cv3-session-detail-loading">读取会话内容…</div></div>`;
  }
  if (entry.error) {
    return `<div class="cv3-session-detail"><div class="cv3-session-detail-error">读取失败：${esc(entry.error)}</div></div>`;
  }
  const data = entry.data;
  if (!data && tool === 'codex') {
    return `<div class="cv3-session-detail"><div class="cv3-session-detail-loading">准备读取…</div></div>`;
  }
  if (tool === 'claudecode') {
    const r = fallbackRow || {};
    const projDisplay = r.project ? String(r.project).replace(/^-+/, '').replace(/-+/g, '/') : '';
    return `
      <div class="cv3-session-detail">
        <div class="cv3-session-detail-grid">
          ${sessionId ? `<div class="cv3-session-detail-row"><span>会话 ID</span><code>${esc(sessionId)}</code></div>` : ''}
          ${r.model ? `<div class="cv3-session-detail-row"><span>模型</span><code>${esc(r.model)}</code></div>` : ''}
          ${projDisplay ? `<div class="cv3-session-detail-row"><span>项目</span><code>${esc(projDisplay)}</code></div>` : ''}
          ${r.startedAt ? `<div class="cv3-session-detail-row"><span>起始</span><code>${esc(formatRelativeTime(r.startedAt))}</code></div>` : ''}
          ${r.lastActiveAt ? `<div class="cv3-session-detail-row"><span>最近</span><code>${esc(formatRelativeTime(r.lastActiveAt))}</code></div>` : ''}
          ${r.path ? `<div class="cv3-session-detail-row"><span>文件</span><code class="cv3-session-detail-path">${esc(r.path)}</code></div>` : ''}
        </div>
        <div class="cv3-session-detail-firstmsg">
          <span class="cv3-session-detail-firstmsg-label">首句</span>
          <p>${esc((r.firstMessage || '').trim() || '（无用户消息）')}</p>
        </div>
      </div>`;
  }
  // Codex
  const summary = data.summary || {};
  const stats = data.stats || {};
  const events = Array.isArray(data.recentEvents) ? data.recentEvents : [];
  const trimmedEvents = events.slice(-20).reverse();
  const eventsHtml = trimmedEvents.length ? trimmedEvents.map((evt) => {
    const role = String(evt.role || '').trim();
    const type = String(evt.type || '').trim();
    const preview = (evt.preview || '').trim();
    const meta = [role && `角色 ${role}`, type && `类型 ${type}`].filter(Boolean).join(' · ');
    return `
      <div class="cv3-session-event">
        <div class="cv3-session-event-meta">
          <span>#${esc(String(evt.line || ''))}</span>
          ${meta ? `<span>${esc(meta)}</span>` : ''}
          ${evt.timestamp ? `<span>${esc(formatRelativeTime(evt.timestamp))}</span>` : ''}
        </div>
        ${preview ? `<div class="cv3-session-event-body">${esc(preview)}</div>` : ''}
      </div>`;
  }).join('') : '<div class="cv3-session-detail-empty">没有可显示的事件</div>';
  return `
    <div class="cv3-session-detail">
      <div class="cv3-session-detail-grid">
        ${summary.sessionId ? `<div class="cv3-session-detail-row"><span>会话 ID</span><code>${esc(summary.sessionId)}</code></div>` : ''}
        ${summary.model ? `<div class="cv3-session-detail-row"><span>模型</span><code>${esc(summary.model)}</code></div>` : ''}
        ${summary.provider && summary.provider !== 'unknown' ? `<div class="cv3-session-detail-row"><span>Provider</span><code>${esc(summary.provider)}</code></div>` : ''}
        ${summary.cwd ? `<div class="cv3-session-detail-row"><span>CWD</span><code class="cv3-session-detail-path">${esc(summary.cwd)}</code></div>` : ''}
        <div class="cv3-session-detail-row"><span>事件</span><code>${esc(String(stats.parsedEvents || 0))} / ${esc(String(stats.totalLines || 0))} 行</code></div>
        ${summary.filePath ? `<div class="cv3-session-detail-row"><span>文件</span><code class="cv3-session-detail-path">${esc(summary.filePath)}</code></div>` : ''}
      </div>
      <div class="cv3-session-detail-events">
        <div class="cv3-session-detail-events-head">最新 ${trimmedEvents.length} 条事件（倒序）</div>
        ${eventsHtml}
      </div>
    </div>`;
}

async function fetchCodexSessionDetail(sessionId, filePath) {
  const key = `codex:${sessionId}`;
  window.__consoleV3.sessionDetails[key] = { loading: true };
  if (state.activePage === 'console') renderToolConsole();
  try {
    const params = new URLSearchParams();
    if (filePath) params.set('filePath', filePath);
    const res = await api(`/api/codex/session-detail?${params.toString()}`);
    if (res?.ok && res.data) {
      window.__consoleV3.sessionDetails[key] = { loading: false, data: res.data };
    } else {
      window.__consoleV3.sessionDetails[key] = { loading: false, error: res?.error || '读取会话详情失败' };
    }
  } catch (error) {
    window.__consoleV3.sessionDetails[key] = { loading: false, error: error?.message || String(error) };
  }
  if (state.activePage === 'console') renderToolConsole();
}

// 跨 CODEX_HOME 迁移会话历史：让用户挑一个源 home，把 sessions/*.jsonl 拷到当前 home。
// 同名跳过，不删源。用 prompt + confirm 起步，避免重新搞一个 modal。
async function runCodexSessionMigration() {
  const listRes = await api('/api/codex/session-homes');
  if (!listRes?.ok) {
    flash(listRes?.error || '读取 CODEX_HOME 列表失败', 'error');
    return;
  }
  const homes = Array.isArray(listRes.data?.homes) ? listRes.data.homes : [];
  if (!homes.length) {
    flash('没有可用的 CODEX_HOME', 'error');
    return;
  }
  // 用当前 codexHomeInput 作为目标；没有就用默认
  const currentTarget = (el('codexHomeInput')?.value || '').trim() || homes[0].codexHome || '';
  const candidates = homes.filter((h) => h.codexHome !== currentTarget);
  if (!candidates.length) {
    flash('没有别的 CODEX_HOME 可以迁移（已经在用唯一的 home）', 'info');
    return;
  }
  const listText = candidates.map((h, i) => `  ${i + 1}. ${h.label}  —  ${h.sessionCount} 个会话\n     ${h.codexHome}`).join('\n');
  const picked = window.prompt(
    `从哪个 CODEX_HOME 把会话历史复制到当前 home？\n\n目标：${currentTarget}\n\n${listText}\n\n输入序号（1-${candidates.length}），取消请清空：`,
    '1',
  );
  if (!picked) return;
  const idx = parseInt(picked, 10) - 1;
  if (Number.isNaN(idx) || idx < 0 || idx >= candidates.length) {
    flash('序号无效', 'error');
    return;
  }
  const source = candidates[idx];
  // 先 dry-run 看会动多少文件
  const preview = await api('/api/codex/sessions/migrate', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      sourceCodexHome: source.codexHome,
      targetCodexHome: currentTarget,
      dryRun: true,
    }),
  });
  if (!preview?.ok) {
    flash(preview?.error || '扫描失败', 'error');
    return;
  }
  const willCopy = Number(preview.data?.copied || 0);
  const willSkip = Number(preview.data?.skipped || 0);
  const total = Number(preview.data?.total || 0);
  if (total === 0) {
    flash('源 home 下没有 .jsonl 会话文件', 'info');
    return;
  }
  if (willCopy === 0) {
    flash(`所有 ${total} 个会话目标都已存在，无需复制`, 'info');
    return;
  }
  const ok = window.confirm(
    `准备从「${source.label}」复制 ${willCopy} 个新会话到当前 CODEX_HOME（${willSkip} 个同名跳过）。\n\n源会话**不会**被删除，是 copy 不是 move。\n\n继续？`,
  );
  if (!ok) return;
  const result = await api('/api/codex/sessions/migrate', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      sourceCodexHome: source.codexHome,
      targetCodexHome: currentTarget,
      dryRun: false,
    }),
  });
  if (!result?.ok) {
    flash(result?.error || '迁移失败', 'error');
    return;
  }
  const copied = Number(result.data?.copied || 0);
  const skipped = Number(result.data?.skipped || 0);
  const errCount = (Array.isArray(result.data?.errors) ? result.data.errors.length : 0);
  flash(`已迁移：复制 ${copied} 个 · 跳过 ${skipped} 个${errCount ? ` · 失败 ${errCount} 个` : ''}`, errCount ? 'warning' : 'success');
  // 拿到新文件后立刻刷新会话列表
  window.__consoleV3.codexStats = null;
  loadConsoleCodexStats();
}

async function loadConsoleCodexStats() {
  try {
    const res = await api('/api/codex/session-stats', { method: 'GET' });
    window.__consoleV3.codexStats = res?.ok ? (res.data || null) : null;
  } catch (_) { window.__consoleV3.codexStats = null; }
  if (state.activePage === 'console' && state.consoleTool === 'codex') renderToolConsole();
}

async function loadConsoleClaudeUsage() {
  try {
    const res = await api('/api/claudecode/local-usage', { method: 'GET' });
    window.__consoleV3.claudeUsage = res?.ok ? (res.data || null) : null;
  } catch (_) { window.__consoleV3.claudeUsage = null; }
  if (state.activePage === 'console' && state.consoleTool === 'claudecode') renderToolConsole();
}

function rerenderCursorSurfaces() {
  if (state.activePage === 'console' && state.consoleTool === 'cursor') renderToolConsole();
  if (state.activePage === 'dashboard' && (state.dashboardTool || '') === 'cursor') renderDashboardPage();
}

// 持久化在后端 SQLite（~/.codex-config-ui/cache/cursor_usage.db），指纹未变则秒回；
// 前端只做会话内内存缓存 + stale-while-revalidate，不落 localStorage（与其他工具一致）。
async function loadConsoleCursorUsage({ silent = false, force = false } = {}) {
  if (window.__consoleV3.cursorUsageLoading) return;
  window.__consoleV3.cursorUsageLoading = true;
  if (!silent) rerenderCursorSurfaces(); // 展示“刷新中”角标（有缓存时不挡内容）
  try {
    const url = '/api/cursor/local-usage' + (force ? '?force=1' : '');
    const res = await api(url, { method: 'GET', timeoutMs: 40000 });
    if (res?.ok && res.data) {
      window.__consoleV3.cursorUsage = res.data;
      window.__consoleV3.cursorUsageSavedAt = Date.now();
    } else if (!window.__consoleV3.cursorUsage && res?.data) {
      window.__consoleV3.cursorUsage = res.data;
    }
    // 请求失败但已有内存缓存：保留旧数据，不清空
  } catch (_) {
    // 保留缓存
  } finally {
    window.__consoleV3.cursorUsageLoading = false;
  }
  rerenderCursorSurfaces();
}

async function primeConsoleV3(tool) {
  // Fire in parallel; each updates render-on-arrival.
  if (!window.__appSettings.loaded) loadAppSettings();
  if (!window.__consoleV3.network) loadConsoleNetworkStatus({ force: false });
  if (!window.__consoleV3.latency) loadConsoleLatency();
  if (hasEmbeddedTerminalSupport() && !state.embeddedTerminal.sessionId) loadEmbeddedTerminalSessions({ force: false });
  if (!window.__consoleV3.procsByTool[tool]) loadConsoleProcs(tool);
  if (tool === 'codex' && !window.__consoleV3.codexStats) loadConsoleCodexStats();
  if (tool === 'claudecode' && !window.__consoleV3.claudeUsage) loadConsoleClaudeUsage();
  if (tool === 'cursor') {
    if (!window.__consoleV3.cursorUsage) loadConsoleCursorUsage();
    else if (Date.now() - (window.__consoleV3.cursorUsageSavedAt || 0) > 120000) loadConsoleCursorUsage({ silent: true });
  }
}

function invalidateConsoleV3Tool(tool, { usage = true, procs = true } = {}) {
  if (!window.__consoleV3) return;
  if (procs) window.__consoleV3.procsByTool[tool] = null;
  if (!usage) return;
  if (tool === 'codex') window.__consoleV3.codexStats = null;
  if (tool === 'claudecode') window.__consoleV3.claudeUsage = null;
  if (tool === 'cursor') window.__consoleV3.cursorUsage = null;
}

function hasEmbeddedTerminalSupport() {
  return Boolean(tauriInvoke) && isCodexLaunchPlatformSupported(state.current?.launch?.platform || '');
}

function getEmbeddedTerminalToolLabel(tool) {
  if (tool === 'claudecode') return 'Claude Code';
  if (tool === 'codex') return 'Codex';
  return tool || '终端';
}

function sortEmbeddedTerminalSessions(rows = []) {
  return [...rows].sort((left, right) => {
    const leftTime = Date.parse(left?.createdAt || '');
    const rightTime = Date.parse(right?.createdAt || '');
    if (Number.isFinite(leftTime) && Number.isFinite(rightTime) && leftTime !== rightTime) {
      return rightTime - leftTime;
    }
    if (Number.isFinite(rightTime) && !Number.isFinite(leftTime)) return 1;
    if (Number.isFinite(leftTime) && !Number.isFinite(rightTime)) return -1;
    return String(right?.sessionId || '').localeCompare(String(left?.sessionId || ''));
  });
}

function findEmbeddedTerminalSessionForTool(rows, tool, { allowFallback = true } = {}) {
  const sorted = sortEmbeddedTerminalSessions(rows);
  return sorted.find((row) => row?.running && row.tool === tool)
    || sorted.find((row) => row?.tool === tool)
    || (allowFallback ? (sorted.find((row) => row?.running) || sorted[0] || null) : null);
}

function isEmbeddedTerminalVisible(info = state.embeddedTerminal.info, tool = state.consoleTool || 'codex') {
  return state.activePage === 'console'
    && Boolean(info?.sessionId)
    && (!info?.tool || info.tool === tool);
}

async function loadEmbeddedTerminalSessions({ force = false, preferredTool = '' } = {}) {
  if (!hasEmbeddedTerminalSupport()) return;
  if (state.embeddedTerminal.listLoading) return;
  const targetTool = preferredTool || state.consoleTool || state.activeTool || 'codex';
  const currentTool = state.embeddedTerminal.info?.tool || state.embeddedTerminal.tool || '';
  if (!force && state.embeddedTerminal.sessionId && currentTool === targetTool) return;
  state.embeddedTerminal.listLoading = true;
  try {
    const res = await api('/api/terminal/list', { method: 'GET', timeoutMs: 10000 });
    if (!res?.ok) return;
    const rows = Array.isArray(res.data?.rows) ? res.data.rows : [];
    const preferred = findEmbeddedTerminalSessionForTool(rows, targetTool, {
      allowFallback: !state.embeddedTerminal.sessionId,
    });
    if (!preferred?.sessionId) return;
    if (state.embeddedTerminal.sessionId === preferred.sessionId) {
      state.embeddedTerminal.tool = preferred.tool || targetTool || state.embeddedTerminal.tool;
      state.embeddedTerminal.info = preferred;
      if (state.activePage === 'console') {
        renderConsoleV3Terminal(targetTool, getEmbeddedTerminalToolLabel(targetTool));
      }
      return;
    }
    if (!state.embeddedTerminal.sessionId || force || currentTool !== targetTool) {
      setEmbeddedTerminalSession(preferred, preferred.tool || targetTool);
      if (state.activePage === 'console') renderToolConsole();
    }
  } catch (err) {
    console.warn('[embedded-terminal] list failed', err);
  } finally {
    state.embeddedTerminal.listLoading = false;
  }
}

function stopEmbeddedTerminalPolling() {
  if (state.embeddedTerminal.pollTimer) {
    clearTimeout(state.embeddedTerminal.pollTimer);
    state.embeddedTerminal.pollTimer = 0;
  }
  state.embeddedTerminal.pendingRead = false;
}

function scheduleEmbeddedTerminalPoll(delay = 120) {
  if (!state.embeddedTerminal.sessionId || !isEmbeddedTerminalVisible()) return;
  if (state.embeddedTerminal.pollTimer) clearTimeout(state.embeddedTerminal.pollTimer);
  state.embeddedTerminal.pollTimer = window.setTimeout(() => {
    state.embeddedTerminal.pollTimer = 0;
    pollEmbeddedTerminal();
  }, Math.max(40, delay));
}

async function pollEmbeddedTerminal() {
  const sessionId = state.embeddedTerminal.sessionId;
  if (!sessionId || state.embeddedTerminal.pendingRead || !isEmbeddedTerminalVisible()) return;
  state.embeddedTerminal.pendingRead = true;
  try {
    const res = await api(`/api/terminal/read?sessionId=${encodeURIComponent(sessionId)}&cursor=${encodeURIComponent(String(state.embeddedTerminal.cursor || 0))}`, {
      method: 'GET',
      timeoutMs: 15000,
    });
    if (!res?.ok) throw new Error(res?.error || '读取终端输出失败');
    const data = res.data || {};
    if (state.embeddedTerminal.sessionId !== sessionId) return;
    const nextInfo = data.session || state.embeddedTerminal.info;
    state.embeddedTerminal.info = nextInfo;
    if (!isEmbeddedTerminalVisible(nextInfo)) return;
    if (typeof data.cursor === 'number') state.embeddedTerminal.cursor = data.cursor;
    if (data.data && state.embeddedTerminal.instance) {
      state.embeddedTerminal.instance.write(String(data.data));
    }
    if (state.activePage === 'console') renderConsoleV3Terminal(state.consoleTool || 'codex', getEmbeddedTerminalToolLabel(state.consoleTool || 'codex'));
    scheduleEmbeddedTerminalPoll((data.session?.running === false && !data.data) ? 900 : 120);
  } catch (err) {
    console.warn('[embedded-terminal] poll failed', err);
    scheduleEmbeddedTerminalPoll(800);
  } finally {
    state.embeddedTerminal.pendingRead = false;
  }
}

async function flushEmbeddedTerminalWriteQueue() {
  const sessionId = state.embeddedTerminal.sessionId;
  const payload = state.embeddedTerminal.writeQueue;
  state.embeddedTerminal.writeQueue = '';
  state.embeddedTerminal.writeTimer = 0;
  if (!sessionId || !payload) return;
  try {
    await api('/api/terminal/write', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ sessionId, data: payload }),
      timeoutMs: 10000,
    });
  } catch (err) {
    console.warn('[embedded-terminal] write failed', err);
  }
}

function queueEmbeddedTerminalWrite(data) {
  if (!data || !state.embeddedTerminal.sessionId) return;
  state.embeddedTerminal.writeQueue += data;
  if (state.embeddedTerminal.writeTimer) return;
  state.embeddedTerminal.writeTimer = window.setTimeout(() => {
    flushEmbeddedTerminalWriteQueue().catch((err) => console.warn('[embedded-terminal] flush failed', err));
  }, 16);
}

async function resizeEmbeddedTerminal() {
  const host = state.embeddedTerminal.host;
  const fitAddon = state.embeddedTerminal.fitAddon;
  const terminal = state.embeddedTerminal.instance;
  const sessionId = state.embeddedTerminal.sessionId;
  if (!host || !fitAddon || !terminal || !sessionId || host.offsetParent === null) return;
  try {
    fitAddon.fit();
  } catch (err) {
    console.warn('[embedded-terminal] fit failed', err);
  }
  const cols = terminal.cols || 120;
  const rows = terminal.rows || 32;
  try {
    await api('/api/terminal/resize', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ sessionId, cols, rows }),
      timeoutMs: 10000,
    });
  } catch (err) {
    console.warn('[embedded-terminal] resize failed', err);
  }
}

function disposeEmbeddedTerminalInstance() {
  stopEmbeddedTerminalPolling();
  if (state.embeddedTerminal.writeTimer) {
    clearTimeout(state.embeddedTerminal.writeTimer);
    state.embeddedTerminal.writeTimer = 0;
  }
  state.embeddedTerminal.writeQueue = '';
  if (state.embeddedTerminal.resizeObserver) {
    state.embeddedTerminal.resizeObserver.disconnect();
    state.embeddedTerminal.resizeObserver = null;
  }
  if (state.embeddedTerminal.instance) {
    try { state.embeddedTerminal.instance.dispose(); } catch {}
  }
  state.embeddedTerminal.instance = null;
  state.embeddedTerminal.fitAddon = null;
  state.embeddedTerminal.host = null;
}

function ensureEmbeddedTerminalMounted() {
  if (!hasEmbeddedTerminalSupport()) return;
  const info = state.embeddedTerminal.info;
  if (!info || !state.embeddedTerminal.sessionId) return;
  const visibleForTool = !info.tool || info.tool === (state.consoleTool || 'codex');
  if (!visibleForTool) return;
  const host = document.getElementById('embeddedTerminalHost');
  if (!host) return;
  if (state.embeddedTerminal.host === host && state.embeddedTerminal.instance) {
    resizeEmbeddedTerminal().catch((err) => console.warn('[embedded-terminal] resize sync failed', err));
    return;
  }

  disposeEmbeddedTerminalInstance();

  const terminal = new Terminal({
    cursorBlink: true,
    fontFamily: 'SF Mono, Menlo, Consolas, monospace',
    fontSize: 12,
    lineHeight: 1.2,
    scrollback: 5000,
    convertEol: false,
    theme: {
      background: '#091018',
      foreground: '#eef4ff',
      cursor: '#8dc0ff',
      cursorAccent: '#091018',
      black: '#081018',
      red: '#ff8f8f',
      green: '#7be1b2',
      yellow: '#ffd08a',
      blue: '#8dc0ff',
      magenta: '#b8a8ff',
      cyan: '#6de2ff',
      white: '#eef4ff',
      brightBlack: '#6b7280',
      brightRed: '#ffb2b2',
      brightGreen: '#b5ffd9',
      brightYellow: '#ffe1a6',
      brightBlue: '#c7e0ff',
      brightMagenta: '#d6cbff',
      brightCyan: '#b9f5ff',
      brightWhite: '#ffffff',
    },
  });
  const fitAddon = new FitAddon();
  terminal.loadAddon(fitAddon);
  terminal.open(host);
  terminal.onData((data) => queueEmbeddedTerminalWrite(data));

  state.embeddedTerminal.instance = terminal;
  state.embeddedTerminal.fitAddon = fitAddon;
  state.embeddedTerminal.host = host;

  if (window.ResizeObserver) {
    const observer = new ResizeObserver(() => {
      resizeEmbeddedTerminal().catch((err) => console.warn('[embedded-terminal] resize observer failed', err));
    });
    observer.observe(host);
    state.embeddedTerminal.resizeObserver = observer;
  }

  resizeEmbeddedTerminal().catch((err) => console.warn('[embedded-terminal] initial resize failed', err));
  scheduleEmbeddedTerminalPoll(0);
  setTimeout(() => terminal.focus(), 30);
}

function setEmbeddedTerminalSession(session, tool = '') {
  if (!session?.sessionId) return;
  const isNewSession = state.embeddedTerminal.sessionId !== session.sessionId;
  if (state.embeddedTerminal.sessionId && isNewSession) {
    disposeEmbeddedTerminalInstance();
  }
  state.embeddedTerminal.sessionId = session.sessionId;
  state.embeddedTerminal.tool = tool || session.tool || state.embeddedTerminal.tool || 'codex';
  state.embeddedTerminal.info = session;
  if (isNewSession) state.embeddedTerminal.cursor = 0;
}

async function activateEmbeddedTerminalSession(session, { tool = '', reveal = true } = {}) {
  if (!session?.sessionId) return false;
  setEmbeddedTerminalSession(session, tool);
  if (tool) {
    state.consoleTool = tool;
    if (typeof setActiveTool === 'function') setActiveTool(tool);
  }
  if (reveal) setPage?.('console');
  if (state.activePage === 'console') {
    renderToolConsole();
    ensureEmbeddedTerminalMounted();
  }
  scheduleEmbeddedTerminalPoll(0);
  return true;
}

async function closeEmbeddedTerminalSession({ remove = false, silent = false } = {}) {
  const sessionId = state.embeddedTerminal.sessionId;
  if (!sessionId) return false;
  try {
    const res = await api('/api/terminal/close', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ sessionId, remove }),
      timeoutMs: 10000,
    });
    if (!res?.ok) throw new Error(res?.error || '关闭终端失败');
    state.embeddedTerminal.info = res.data?.session || state.embeddedTerminal.info;
    if (remove) {
      disposeEmbeddedTerminalInstance();
      state.embeddedTerminal.sessionId = '';
      state.embeddedTerminal.tool = '';
      state.embeddedTerminal.info = null;
      state.embeddedTerminal.cursor = 0;
    } else {
      scheduleEmbeddedTerminalPoll(0);
    }
    if (!silent) flash('应用内终端已关闭', 'success');
    if (state.activePage === 'console') renderToolConsole();
    return true;
  } catch (err) {
    if (!silent) flash(err instanceof Error ? err.message : '关闭终端失败', 'error');
    return false;
  }
}

function renderConsoleV3Terminal(tool, toolLabel) {
  const el = document.getElementById('consoleV2Terminal');
  if (!el) return;
  if (!hasEmbeddedTerminalSupport()) {
    el.innerHTML = '';
    el.hidden = true;
    return;
  }
  el.hidden = false;

  if (!el.dataset.ready) {
    el.innerHTML = `
      ${cv3SectionHead(CV3_ICONS.cpu, '应用内终端', { extras: '<button type="button" class="cv3-link-btn" data-console-v3-terminal-close>关闭</button>' })}
      <div class="ev3-terminal-shell">
        <div class="ev3-terminal-meta">
          <div class="ev3-terminal-title" id="embeddedTerminalTitle">等待会话</div>
          <div class="ev3-terminal-sub" id="embeddedTerminalSub">Windows 会在这里直接显示 CLI 会话，不再弹外部终端窗口。</div>
        </div>
        <div class="ev3-terminal-empty" id="embeddedTerminalEmpty"></div>
        <div class="ev3-terminal-host-wrap" id="embeddedTerminalHostWrap" hidden>
          <div class="ev3-terminal-host" id="embeddedTerminalHost"></div>
        </div>
      </div>`;
    el.dataset.ready = '1';
  }

  const info = state.embeddedTerminal.info;
  const titleEl = document.getElementById('embeddedTerminalTitle');
  const subEl = document.getElementById('embeddedTerminalSub');
  const emptyEl = document.getElementById('embeddedTerminalEmpty');
  const hostWrap = document.getElementById('embeddedTerminalHostWrap');
  const closeBtn = el.querySelector('[data-console-v3-terminal-close]');
  const visibleForTool = Boolean(info?.sessionId) && (!info?.tool || info.tool === tool);
  const activeToolLabel = getEmbeddedTerminalToolLabel(info?.tool || '');

  if (titleEl) {
    titleEl.textContent = visibleForTool
      ? `${activeToolLabel} · ${info.title || '终端会话'}`
      : info?.sessionId
        ? `${activeToolLabel} 会话运行中`
        : `${toolLabel} · 应用内终端`;
  }
  if (subEl) {
    const status = info?.running === false
      ? `已结束${typeof info.exitCode === 'number' ? ` · 退出码 ${info.exitCode}` : ''}`
      : info?.sessionId
        ? `会话 ID · ${info.sessionId.slice(0, 8)}`
        : 'Windows 会在这里直接显示 CLI 会话，不再弹外部终端窗口。';
    subEl.textContent = status;
  }
  if (closeBtn) closeBtn.disabled = !info?.sessionId;

  if (emptyEl) {
    emptyEl.hidden = visibleForTool;
    emptyEl.textContent = info?.sessionId
      ? visibleForTool
        ? ''
        : `当前打开的是 ${activeToolLabel} 会话，切到对应工具页就能继续查看。`
      : `${toolLabel} 还没有打开应用内终端。`;
  }
  if (hostWrap) hostWrap.hidden = !visibleForTool;

  if (!visibleForTool) disposeEmbeddedTerminalInstance();
  if (visibleForTool) ensureEmbeddedTerminalMounted();
}

function formatRelativeTime(iso) {
  if (!iso) return '';
  const then = new Date(iso).getTime();
  if (!Number.isFinite(then)) return '';
  const diff = Date.now() - then;
  if (diff < 0) return '刚刚';
  const min = Math.floor(diff / 60000);
  if (min < 1) return '刚刚';
  if (min < 60) return `${min} 分钟前`;
  const hr = Math.floor(min / 60);
  if (hr < 24) return `${hr} 小时前`;
  const day = Math.floor(hr / 24);
  return `${day} 天前`;
}

// Collapse verbose vendor model IDs into something a human reads at a glance.
//   claude-sonnet-4-5-20250929  → Sonnet 4.5
//   claude-3-7-opus-20250229    → Opus 3.7
//   gpt-5.4                     → GPT-5.4
//   gpt-4o-mini-2024-07-18      → GPT-4o mini
// Falls back to the raw string when the shape isn't recognized.
function formatModelLabel(raw) {
  if (!raw) return '';
  const s = String(raw).trim();
  // Claude: claude-<tier>-<version>[-date]  (tier + version order varies)
  const c = s.match(/^claude[-_ ](?:(\d[\d-]*)[-_ ])?(sonnet|haiku|opus)[-_ ]?(\d[\d-]*)?(?:[-_ ]\d{6,})?$/i);
  if (c) {
    const tier = c[2][0].toUpperCase() + c[2].slice(1).toLowerCase();
    const ver = (c[1] || c[3] || '').replace(/-/g, '.');
    return ver ? `${tier} ${ver}` : tier;
  }
  // GPT: gpt-4o-mini-xxxx, gpt-5.4, gpt-4-turbo-xxxx
  const g = s.match(/^gpt[-_ ]?([\d.]+)(?:[-_ ](o|turbo|mini))?(?:[-_ ](mini|nano|turbo|pro))?/i);
  if (g) {
    const ver = g[1];
    const suffix = [g[2], g[3]].filter(Boolean).map((x) => x.toLowerCase()).join(' ');
    return suffix ? `GPT-${ver} ${suffix}` : `GPT-${ver}`;
  }
  return s;
}

// Minimal one-line SVGs reused across the strip. Outline / line style, not
// emoji — keeps the strip dense and consistent with the rest of the hub.
const CV3_ICONS = {
  shield: '<svg class="cv3-ico" viewBox="0 0 16 16" width="12" height="12" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M8 1.5 3 3.5v4c0 3.2 2.1 6 5 7 2.9-1 5-3.8 5-7v-4L8 1.5z"/></svg>',
  proxy:  '<svg class="cv3-ico" viewBox="0 0 16 16" width="12" height="12" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M2 6a6 6 0 0 1 12 0M4 8a4 4 0 0 1 8 0M6 10a2 2 0 0 1 4 0"/><circle cx="8" cy="12.5" r="0.9" fill="currentColor" stroke="none"/></svg>',
  lock:   '<svg class="cv3-ico" viewBox="0 0 16 16" width="12" height="12" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><rect x="3.5" y="7" width="9" height="6.5" rx="1.5"/><path d="M5.5 7V5a2.5 2.5 0 0 1 5 0v2"/></svg>',
  unlock: '<svg class="cv3-ico" viewBox="0 0 16 16" width="12" height="12" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><rect x="3.5" y="7" width="9" height="6.5" rx="1.5"/><path d="M5.5 7V5a2.5 2.5 0 0 1 5 0"/></svg>',
  refresh:'<svg class="cv3-ico" viewBox="0 0 16 16" width="12" height="12" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M14 8A6 6 0 0 1 3.4 11.8L2 13M2 8a6 6 0 0 1 10.6-3.8L14 3"/><path d="M14 3v3.5h-3.5M2 13V9.5h3.5"/></svg>',
  // Section-head icons (14px, matched line style).
  globe:  '<svg class="cv3-sec-ico" viewBox="0 0 16 16" width="13" height="13" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"><circle cx="8" cy="8" r="6"/><path d="M2 8h12M8 2c2 2.2 3 5 3 6s-1 3.8-3 6c-2-2.2-3-5-3-6s1-3.8 3-6z"/></svg>',
  cpu:    '<svg class="cv3-sec-ico" viewBox="0 0 16 16" width="13" height="13" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"><rect x="4" y="4" width="8" height="8" rx="1.5"/><path d="M6 4V2M10 4V2M6 14v-2M10 14v-2M4 6H2M4 10H2M14 6h-2M14 10h-2"/></svg>',
  clock:  '<svg class="cv3-sec-ico" viewBox="0 0 16 16" width="13" height="13" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"><circle cx="8" cy="8" r="6"/><path d="M8 5v3.5l2.2 1.3"/></svg>',
  sliders:'<svg class="cv3-sec-ico" viewBox="0 0 16 16" width="13" height="13" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"><path d="M3 4h10M3 8h10M3 12h10"/><circle cx="6" cy="4" r="1.4" fill="currentColor" stroke="none"/><circle cx="11" cy="8" r="1.4" fill="currentColor" stroke="none"/><circle cx="5" cy="12" r="1.4" fill="currentColor" stroke="none"/></svg>',
  alert:  '<svg class="cv3-sec-ico" viewBox="0 0 16 16" width="13" height="13" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"><path d="M8 2 1.5 13.5h13L8 2z"/><path d="M8 6.5v3M8 11.5v.5"/></svg>',
};

// Helper to render a section head with icon + label + optional count + extras.
function cv3SectionHead(icon, label, { count, extras = '' } = {}) {
  const esc = escapeHtml;
  const countHtml = (count || count === 0) ? `<span class="count">· ${esc(String(count))}</span>` : '';
  return `<div class="console-v2-section-head">${icon || ''}<span class="cv3-sec-label">${esc(label)}</span>${countHtml}${extras}</div>`;
}

// Slim one-line IP strip embedded inside the hero card. Dense, no emoji
// decorations — just the IP, geo, verdict color, proxy hint, and the two
// control buttons. Target: 1 line on normal widths, wrapping to 2 lines
// only when the hero is very narrow.
function renderHeroIpStripHTML() {
  const esc = escapeHtml;
  const n = window.__consoleV3.network;
  if (!n) {
    return `<div class="cv3-ipstrip loading">${CV3_ICONS.shield}<span class="cv3-ipstrip-msg">正在检测出口 IP…</span></div>`;
  }
  const gateOn = isIpGateEnabled();
  const gateBtn = `<button type="button" class="cv3-ipstrip-toggle ${gateOn ? 'on' : ''}" data-console-v3-toggle-gate-btn title="${gateOn ? '硬拦截已开启 — 高风险 IP 时阻止启动' : '硬拦截已关闭 — 高风险仅弹窗提醒'}">${gateOn ? CV3_ICONS.lock + '硬拦截' : CV3_ICONS.unlock + '仅提醒'}</button>`;
  const refreshBtn = `<button type="button" class="cv3-ipstrip-refresh" data-console-v3-refresh-ip title="重新检测">${CV3_ICONS.refresh}</button>`;

  if (n.ok === false) {
    const proxyHint = n.proxy?.hasProxy
      ? `<span class="cv3-ipstrip-proxy" title="${esc((n.proxy.hints || []).join(' | '))}">${CV3_ICONS.proxy}代理</span>`
      : `<span class="cv3-ipstrip-proxy dim" title="没有识别到任何代理配置">${CV3_ICONS.proxy}无代理</span>`;
    return `
      <div class="cv3-ipstrip bad">
        <div class="cv3-ipstrip-left">
          ${CV3_ICONS.shield}
          <span class="cv3-ipstrip-label">无法获取 IP</span>
          ${proxyHint}
          <span class="cv3-ipstrip-err" title="${esc(n.error || '')}">${esc((n.error || '').slice(0, 60))}</span>
        </div>
        <div class="cv3-ipstrip-right">${gateBtn}${refreshBtn}</div>
      </div>`;
  }

  const verdict = n.verdict || 'warn';
  const cc = (n.countryCode || '').toUpperCase();
  const flagMap = { CN: '🇨🇳', US: '🇺🇸', SG: '🇸🇬', JP: '🇯🇵', HK: '🇭🇰', TW: '🇹🇼', KR: '🇰🇷', DE: '🇩🇪', GB: '🇬🇧', FR: '🇫🇷', CA: '🇨🇦', AU: '🇦🇺' };
  const flag = flagMap[cc] || '';
  const splitTag = n.splitTunnel ? `<span class="cv3-ipstrip-split" title="多个视角看到不同 IP（分流）">分流</span>` : '';
  const hasProxy = Boolean(n.proxy?.hasProxy);
  const locBits = [flag && flag, n.country, n.city, n.isp].filter(Boolean).join(' · ');

  return `
    <div class="cv3-ipstrip ${esc(verdict)}">
      <div class="cv3-ipstrip-left">
        ${CV3_ICONS.shield}
        <span class="cv3-ipstrip-ip"><code>${esc(n.ip || '-')}</code></span>
        <span class="cv3-ipstrip-geo">${esc(locBits)}</span>
        ${splitTag}
        ${hasProxy ? `<span class="cv3-ipstrip-proxy" title="${esc((n.proxy.hints || [])[0] || '')}">${CV3_ICONS.proxy}代理</span>` : ''}
      </div>
      <div class="cv3-ipstrip-right">${gateBtn}${refreshBtn}</div>
    </div>`;
}

// Multi-vantage matrix — mimics ip111.cn's "从国内测试 / 从国外测试 / 从谷歌测试"
// columns. Shows the IP each probe saw. When any row disagrees with the
// primary IP we highlight the mismatching cells so split-tunneling is
// obvious at a glance.
function renderConsoleV3Vantages() {
  const el = document.getElementById('consoleV2Vantages');
  if (!el) return;
  const esc = escapeHtml;
  const n = window.__consoleV3.network;
  if (!n) {
    el.innerHTML = `<div class="console-v2-section-head">网络视角</div><div class="cv3-proc-empty">检测中…</div>`;
    return;
  }

  const vantages = Array.isArray(n.vantages) ? n.vantages : [];
  if (!vantages.length) {
    el.innerHTML = `<div class="console-v2-section-head">网络视角
      <button type="button" class="cv3-link-btn" data-console-v3-refresh-ip>重测</button>
    </div>
    <div class="cv3-proc-empty">${esc(n.error || '无法获取视角数据')}</div>
    ${renderLatencyStripHTML()}`;
    return;
  }

  const primaryIp = n.ip || '';
  const rowsHtml = vantages.map((v) => {
    const okCell = v.ok === true;
    const ip = v.query || v.ip || '';
    const mismatch = okCell && primaryIp && ip && ip !== primaryIp;
    const statusCls = !okCell ? 'bad' : mismatch ? 'warn' : 'ok';
    const ipText = okCell ? (ip || '—') : '失败';
    const geo = okCell
      ? ((v.country ? esc(v.country) : '') + (v.city ? ' · ' + esc(v.city) : ''))
      : esc((v.error || '').slice(0, 40));
    const latency = v.ms ? `${v.ms}ms` : '';
    const transport = v.transport && v.transport !== 'none' ? v.transport : '';
    return `
      <div class="cv3-vantage ${statusCls}">
        <div class="cv3-vantage-head">
          <span class="cv3-vantage-label">${esc(v.label || '—')}</span>
          ${latency ? `<span class="cv3-vantage-ms">${esc(latency)}</span>` : ''}
        </div>
        <div class="cv3-vantage-ip"><code>${esc(ipText)}</code></div>
        <div class="cv3-vantage-geo">${geo || '&nbsp;'}</div>
        ${transport ? `<div class="cv3-vantage-via">via ${esc(transport)}</div>` : ''}
      </div>`;
  }).join('');

  const splitChip = n.splitTunnel ? '<span class="cv3-vantage-alert" title="多视角看到的 IP 不一致">⚠ 分流</span>' : '';
  const refreshBtn = '<button type="button" class="cv3-link-btn" data-console-v3-refresh-ip>重测</button>';
  el.innerHTML = `
    ${cv3SectionHead(CV3_ICONS.globe, '网络视角', {
      count: `${vantages.length} 路`,
      extras: splitChip + refreshBtn,
    })}
    <div class="cv3-vantage-grid">${rowsHtml}</div>
    ${renderLatencyStripHTML()}`;
}

// Small inline latency strip — shown inside the firewall card so users see
// network quality alongside the verdict.
function renderLatencyStripHTML() {
  const esc = escapeHtml;
  const l = window.__consoleV3.latency;
  if (!l) {
    return `<div class="cv3-latency-strip"><span class="cv3-latency-label">网络时延</span><span class="cv3-latency-hint">测量中…</span></div>`;
  }
  const rows = Array.isArray(l.rows) ? l.rows : [];
  if (!rows.length) return '';
  const pills = rows.map((r) => {
    if (!r.ok) {
      return `<span class="cv3-latency-pill bad" title="${esc(r.error || '')}">${esc(r.label)}: —</span>`;
    }
    const cls = r.ms > 500 ? 'warn' : r.ms > 150 ? 'okish' : 'ok';
    return `<span class="cv3-latency-pill ${cls}" title="${esc(r.host)} · ${esc(r.why || '')}">${esc(r.label)}: ${esc(String(r.ms))}ms</span>`;
  }).join('');
  const summary = l.summary ? `<span class="cv3-latency-sum">${l.summary.reachable}/${l.summary.total} 可达 · 平均 ${l.summary.avgMs}ms</span>` : '';
  return `<div class="cv3-latency-strip"><span class="cv3-latency-label">网络时延</span>${pills}${summary}<button type="button" class="cv3-link-btn cv3-latency-refresh" data-console-v3-refresh-latency>重测</button></div>`;
}

function inferCodexProcessMeta(command = '', rawKind = '') {
  const lower = String(command || '').toLowerCase();
  const base = {
    kind: rawKind || 'cli',
    processKind: 'codex-cli',
    processLabel: 'CLI',
    processDetail: 'Codex CLI 会话',
    processGroup: 'cli',
    processGroupLabel: 'Codex CLI 会话',
    processGroupShort: 'CLI',
    processOrder: 11,
  };
  const asMeta = (overrides) => ({ ...base, ...overrides });

  if (lower.includes('skycomputeruseservice') || lower.includes('/codex computer use.app/contents/')) {
    return asMeta({ kind: 'service', processKind: 'codex-computer-use', processLabel: 'COMPUTER USE', processDetail: 'Codex Computer Use 服务', processGroup: 'service', processGroupLabel: 'Codex 后台服务', processGroupShort: '服务', processOrder: 30 });
  }
  if (lower.includes('/contents/resources/codex app-server') || lower.includes(' codex app-server')) {
    return asMeta({ kind: 'service', processKind: 'codex-app-server', processLabel: 'APP SERVER', processDetail: 'Codex 桌面 app-server', processGroup: 'service', processGroupLabel: 'Codex 后台服务', processGroupShort: '服务', processOrder: 31 });
  }
  if (lower.includes('/contents/resources/cua_node/bin/node_repl')) {
    return asMeta({ kind: 'service', processKind: 'codex-cua-node-repl', processLabel: 'CUA NODE', processDetail: 'Codex CUA Node REPL', processGroup: 'service', processGroupLabel: 'Codex 后台服务', processGroupShort: '服务', processOrder: 32 });
  }
  if (lower.includes('bare-modifier-monitor')) {
    return asMeta({ kind: 'service', processKind: 'codex-hotkey-monitor', processLabel: 'HOTKEY', processDetail: 'Codex 快捷键监听', processGroup: 'service', processGroupLabel: 'Codex 后台服务', processGroupShort: '服务', processOrder: 33 });
  }
  if (lower.includes('sparkle.framework') || lower.includes('autoupdate com.openai.codex')) {
    return asMeta({ kind: 'service', processKind: 'codex-updater', processLabel: 'UPDATER', processDetail: 'Codex 自动更新进程', processGroup: 'service', processGroupLabel: 'Codex 后台服务', processGroupShort: '服务', processOrder: 34 });
  }
  if (lower.includes('browser_crashpad_handler') || lower.includes('crashpad')) {
    return asMeta({ kind: 'helper', processKind: 'codex-crashpad', processLabel: 'CRASHPAD', processDetail: 'Codex 崩溃报告辅助进程', processGroup: 'helper', processGroupLabel: 'Codex 桌面辅助进程', processGroupShort: '辅助', processOrder: 50 });
  }
  if (lower.includes('--type=gpu-process')) {
    return asMeta({ kind: 'helper', processKind: 'codex-desktop-gpu', processLabel: 'GPU', processDetail: 'Codex 桌面 GPU 进程', processGroup: 'helper', processGroupLabel: 'Codex 桌面辅助进程', processGroupShort: '辅助', processOrder: 51 });
  }
  if (lower.includes('--type=renderer') || lower.includes('codex (renderer)')) {
    return asMeta({ kind: 'helper', processKind: 'codex-desktop-renderer', processLabel: 'RENDERER', processDetail: 'Codex 桌面渲染进程', processGroup: 'helper', processGroupLabel: 'Codex 桌面辅助进程', processGroupShort: '辅助', processOrder: 52 });
  }
  if (lower.includes('network.mojom.networkservice')) {
    return asMeta({ kind: 'helper', processKind: 'codex-desktop-network', processLabel: 'NETWORK', processDetail: 'Codex 桌面网络服务', processGroup: 'helper', processGroupLabel: 'Codex 桌面辅助进程', processGroupShort: '辅助', processOrder: 53 });
  }
  if (lower.includes('storage.mojom.storageservice')) {
    return asMeta({ kind: 'helper', processKind: 'codex-desktop-storage', processLabel: 'STORAGE', processDetail: 'Codex 桌面存储服务', processGroup: 'helper', processGroupLabel: 'Codex 桌面辅助进程', processGroupShort: '辅助', processOrder: 54 });
  }
  if (lower.includes('audio.mojom.audioservice')) {
    return asMeta({ kind: 'helper', processKind: 'codex-desktop-audio', processLabel: 'AUDIO', processDetail: 'Codex 桌面音频服务', processGroup: 'helper', processGroupLabel: 'Codex 桌面辅助进程', processGroupShort: '辅助', processOrder: 55 });
  }
  if (lower.includes('video_capture.mojom.videocaptureservice')) {
    return asMeta({ kind: 'helper', processKind: 'codex-desktop-video', processLabel: 'VIDEO', processDetail: 'Codex 桌面视频采集服务', processGroup: 'helper', processGroupLabel: 'Codex 桌面辅助进程', processGroupShort: '辅助', processOrder: 56 });
  }
  if (lower.includes('--type=utility') || lower.includes('codex (service)')) {
    return asMeta({ kind: 'helper', processKind: 'codex-desktop-utility', processLabel: 'UTILITY', processDetail: 'Codex 桌面 Utility 服务', processGroup: 'helper', processGroupLabel: 'Codex 桌面辅助进程', processGroupShort: '辅助', processOrder: 57 });
  }
  if (lower.includes('/codex.app/contents/macos/codex')) {
    return asMeta({ kind: 'desktop', processKind: 'codex-desktop-main', processLabel: 'DESKTOP', processDetail: 'Codex 桌面主进程', processGroup: 'desktop', processGroupLabel: 'Codex 桌面应用', processGroupShort: '桌面', processOrder: 20 });
  }
  if (lower.includes('/codex.app/contents/') || lower.includes('.app/contents/')) {
    return asMeta({ kind: 'desktop', processKind: 'codex-desktop-app', processLabel: 'APP', processDetail: 'Codex 桌面应用进程', processGroup: 'desktop', processGroupLabel: 'Codex 桌面应用', processGroupShort: '桌面', processOrder: 21 });
  }
  if (lower.includes('@openai/codex') || lower.includes('openai-codex')) {
    return asMeta({ kind: 'cli', processKind: 'codex-node-cli', processLabel: 'NODE CLI', processDetail: 'Node 包装的 Codex CLI', processGroup: 'cli', processGroupLabel: 'Codex CLI 会话', processGroupShort: 'CLI', processOrder: 10 });
  }
  return base;
}

function normalizeConsoleProcess(tool, row = {}) {
  const rawKind = String(row.kind || '').toLowerCase();
  const fallback = tool === 'codex'
    ? inferCodexProcessMeta(row.command || '', rawKind)
    : {
        kind: rawKind === 'app' ? 'app' : 'cli',
        processKind: rawKind === 'app' ? 'desktop-app' : 'cli',
        processLabel: rawKind === 'app' ? 'APP' : 'CLI',
        processDetail: rawKind === 'app' ? '桌面 GUI 应用' : '命令行 CLI',
        processGroup: rawKind === 'app' ? 'app' : 'cli',
        processGroupLabel: rawKind === 'app' ? '桌面应用' : 'CLI 会话',
        processGroupShort: rawKind === 'app' ? 'App' : 'CLI',
        processOrder: rawKind === 'app' ? 20 : 10,
      };
  const hasBackendMeta = Boolean(row.processKind || row.processLabel || row.processGroup);
  const kind = String((hasBackendMeta ? row.kind : fallback.kind) || row.kind || 'cli').toLowerCase();
  const processGroup = String((hasBackendMeta ? row.processGroup : fallback.processGroup) || fallback.processGroup || kind || 'cli').toLowerCase();
  return {
    ...row,
    kind,
    processKind: row.processKind || fallback.processKind,
    processLabel: row.processLabel || fallback.processLabel,
    processDetail: row.processDetail || fallback.processDetail,
    processGroup,
    processGroupLabel: row.processGroupLabel || fallback.processGroupLabel,
    processGroupShort: row.processGroupShort || fallback.processGroupShort,
    processOrder: Number.isFinite(Number(row.processOrder)) ? Number(row.processOrder) : fallback.processOrder,
  };
}

function groupConsoleProcesses(rows, tool, toolLabel) {
  const normalized = rows.map((row) => normalizeConsoleProcess(tool, row));
  normalized.sort((a, b) => {
    const orderDiff = (a.processOrder || 99) - (b.processOrder || 99);
    if (orderDiff) return orderDiff;
    const cpuDiff = Number(b.cpu || 0) - Number(a.cpu || 0);
    if (cpuDiff) return cpuDiff;
    return Number(a.pid || 0) - Number(b.pid || 0);
  });
  const groups = [];
  const byKey = new Map();
  normalized.forEach((row) => {
    const key = row.processGroup || row.kind || 'other';
    if (!byKey.has(key)) {
      const label = row.processGroupLabel || (key === 'app' ? `${toolLabel} App` : key === 'cli' ? `${toolLabel} CLI` : `${toolLabel} 进程`);
      const short = row.processGroupShort || (key === 'app' ? 'App' : key === 'cli' ? 'CLI' : '其他');
      const group = { key, label, short, order: row.processOrder || 99, rows: [] };
      byKey.set(key, group);
      groups.push(group);
    }
    byKey.get(key).rows.push(row);
  });
  groups.sort((a, b) => (a.order || 99) - (b.order || 99) || a.label.localeCompare(b.label));
  return groups;
}

function consoleProcessKindClass(row = {}) {
  const kind = String(row.kind || '').toLowerCase();
  const group = String(row.processGroup || '').toLowerCase();
  const key = ['cli', 'app', 'desktop', 'service', 'helper'].includes(kind) ? kind : group;
  return ['cli', 'app', 'desktop', 'service', 'helper'].includes(key) ? `is-${key}` : 'is-other';
}

function renderConsoleV3Procs(tool, toolLabel) {
  const el = document.getElementById('consoleV2Procs');
  if (!el) return;
  const esc = escapeHtml;
  const rows = window.__consoleV3.procsByTool[tool] || null;
  const refreshProcsBtn = '<button type="button" class="cv3-link-btn" data-console-v3-refresh-procs>刷新</button>';
  const headLabel = `运行中的 ${toolLabel}`;
  if (rows === null) {
    el.innerHTML = `
      ${cv3SectionHead(CV3_ICONS.cpu, headLabel, { count: '…', extras: refreshProcsBtn })}
      <div class="cv3-proc-empty">正在扫描进程…</div>`;
    return;
  }
  if (!rows.length) {
    el.innerHTML = `
      ${cv3SectionHead(CV3_ICONS.cpu, headLabel, { count: 0, extras: refreshProcsBtn })}
      <div class="cv3-proc-empty">当前没有在跑的 ${esc(toolLabel)} 进程</div>`;
    return;
  }
  const groups = groupConsoleProcesses(rows, tool, toolLabel);
  const renderRow = (p) => {
    const mem = p.memMB ? `${p.memMB} MB` : (p.memPct ? `${p.memPct.toFixed(1)}%` : '—');
    const cpu = (typeof p.cpu === 'number') ? `${p.cpu.toFixed(1)}%` : '—';
    const cmdClean = (p.command || '').replace(/^\S*\/node\s+/, 'node ').trim();
    const kindClass = consoleProcessKindClass(p);
    const processLabel = p.processLabel || (p.kind === 'app' ? 'APP' : 'CLI');
    const processDetail = p.processDetail || (p.kind === 'app' ? '桌面 GUI 应用' : '命令行 CLI');
    const accountBadge = p.accountLabel
      ? `<span class="cv3-proc-account" title="${esc(p.accountHome ? `${p.accountLabel} · ${p.accountHome}` : p.accountLabel)}">${esc(p.accountLabel)}</span>`
      : '';
    const cwd = p.cwd ? `<span class="cv3-proc-cwd" title="${esc(p.cwd)}">${esc(p.cwd)}</span>` : '';
    const kindBadge = `<span class="cv3-proc-kind ${kindClass}" title="${esc(processDetail)}">${esc(processLabel)}</span>`;
    const roleBadge = processDetail ? `<span class="cv3-proc-role" title="${esc(processDetail)}">${esc(processDetail)}</span>` : '';
    return `
      <div class="cv3-proc-row ${kindClass}">
        <div class="cv3-proc-head">
          <span class="cv3-proc-dot"></span>
          ${kindBadge}
          ${roleBadge}
          <span class="cv3-proc-pid">PID ${esc(String(p.pid))}</span>
          ${accountBadge}
          <span class="cv3-proc-elapsed" title="已运行">${esc(p.elapsed || '—')}</span>
          <span class="cv3-proc-cpu" title="CPU 占用">CPU ${esc(cpu)}</span>
          <span class="cv3-proc-mem" title="内存占用">MEM ${esc(mem)}</span>
          <span class="cv3-proc-actions">
            ${p.cwd ? `<button type="button" class="cv3-proc-btn" data-cv3-proc-reveal="${esc(p.cwd)}" title="在 Finder 打开该目录">打开目录</button>` : ''}
            <button type="button" class="cv3-proc-btn cv3-proc-btn-danger" data-cv3-proc-kill="${esc(String(p.pid))}" title="结束该进程 (SIGTERM)">结束</button>
          </span>
        </div>
        ${cmdClean ? `<div class="cv3-proc-cmd" title="${esc(cmdClean)}">${esc(cmdClean)}</div>` : ''}
        ${cwd ? `<div class="cv3-proc-cwd-row"><span class="cv3-proc-cwd-label">cwd</span>${cwd}</div>` : ''}
      </div>`;
  };
  const sectionFor = (group) => group.rows.length
    ? `<div class="cv3-proc-group kind-${esc(group.key)}">
         <div class="cv3-proc-group-head"><span class="cv3-proc-group-title">${esc(group.label)}</span><span class="cv3-proc-group-count">${esc(String(group.rows.length))}</span></div>
         <div class="cv3-proc-list">${group.rows.map(renderRow).join('')}</div>
       </div>`
    : '';
  const summary = groups.map((group) => `${group.rows.length} ${group.short}`).join(' · ');
  el.innerHTML = `
    ${cv3SectionHead(CV3_ICONS.cpu, headLabel, { count: summary, extras: refreshProcsBtn })}
    ${groups.map(sectionFor).join('')}`;
}

function renderConsoleV3Usage(tool) {
  const el = document.getElementById('consoleV2Usage');
  if (!el) return;
  const esc = escapeHtml;

  if (tool === 'codex') {
    const s = window.__consoleV3.codexStats;
    if (!s) {
      el.innerHTML = `${cv3SectionHead(CV3_ICONS.clock, '本地会话')}<div class="cv3-proc-empty">读取 ~/.codex/sessions/ 中…</div>`;
      return;
    }
    const dist = Array.isArray(s.modelDistribution) ? s.modelDistribution : [];
    const distHtml = dist.length ? `
      <div class="cv3-session-dist">
        <span class="cv3-session-dist-label">近 7 天模型分布</span>
        ${dist.map((d) => `<span class="cv3-session-dist-chip">${esc(d.model)} <em>${esc(String(d.count))}</em></span>`).join('')}
      </div>` : '';

    const recent = Array.isArray(s.recent) ? s.recent : [];
    const expandedKey = window.__consoleV3?.expandedSession?.tool === 'codex'
      ? window.__consoleV3.expandedSession.sessionId : '';
    const recentHtml = recent.length ? `
      <div class="cv3-session-list">
        ${recent.map((r) => {
          const modelLabel = formatModelLabel(r.model);
          const preview = (r.firstMessage || '').trim() || '(无用户消息)';
          const sessionId = String(r.sessionId || '').trim();
          const isExpanded = expandedKey && sessionId === expandedKey;
          const detailHtml = isExpanded ? renderSessionDetailPanel('codex', sessionId) : '';
          return `
          <div class="cv3-session-row ${isExpanded ? 'is-expanded' : ''}" data-cv3-session-tool="codex" data-cv3-session-id="${esc(sessionId)}" data-cv3-session-path="${esc(r.path || '')}" tabindex="0" role="button" aria-expanded="${isExpanded ? 'true' : 'false'}">
            <div class="cv3-session-row-main">
              <div class="cv3-session-title">${esc(preview)}</div>
              <div class="cv3-session-meta">
                ${modelLabel ? `<span class="cv3-session-chip">${esc(modelLabel)}</span>` : ''}
                <span class="cv3-session-count">${esc(String(r.messageCount || 0))} 条</span>
                <span class="cv3-session-when">${esc(formatRelativeTime(r.lastActiveAt))}</span>
              </div>
            </div>
            <svg class="cv3-session-chevron" width="10" height="10" viewBox="0 0 10 10" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M3 1.5L7 5L3 8.5"/></svg>
          </div>
          ${detailHtml}`;
        }).join('')}
      </div>` : '<div class="cv3-proc-empty">暂无会话</div>';

    const refreshUsage = '<button type="button" class="cv3-link-btn" data-console-v3-refresh-usage>刷新</button>'
      + ' <button type="button" class="cv3-link-btn" data-codex-sessions-migrate>迁移历史</button>';
    el.innerHTML = `
      ${cv3SectionHead(CV3_ICONS.clock, '本地会话', { extras: refreshUsage })}
      <div class="cv3-usage-grid">
        <div class="cv3-usage-cell">
          <div class="cv3-usage-label">总数</div>
          <div class="cv3-usage-value">${esc(String(s.total || 0))}</div>
        </div>
        <div class="cv3-usage-cell">
          <div class="cv3-usage-label">近 24h</div>
          <div class="cv3-usage-value">${esc(String(s.today || 0))}</div>
        </div>
        <div class="cv3-usage-cell">
          <div class="cv3-usage-label">近 7 天</div>
          <div class="cv3-usage-value">${esc(String(s.week || 0))}</div>
        </div>
        <div class="cv3-usage-cell">
          <div class="cv3-usage-label">最近活动</div>
          <div class="cv3-usage-value">${s.latestMtime ? esc(formatRelativeTime(s.latestMtime)) : '无'}</div>
        </div>
      </div>
      ${distHtml}
      <div class="cv3-session-head">最近会话</div>
      ${recentHtml}`;
    return;
  }

  if (tool === 'claudecode') {
    const u = window.__consoleV3.claudeUsage;
    if (!u) {
      el.innerHTML = `${cv3SectionHead(CV3_ICONS.clock, '本地 5h 窗口 (估算)')}<div class="cv3-proc-empty">读取 ~/.claude/projects/ 中…</div>`;
      return;
    }
    const firstAt = u.windowFirstMessageAt ? new Date(u.windowFirstMessageAt) : null;
    const remainingMs = firstAt ? (firstAt.getTime() + 5 * 3600 * 1000) - Date.now() : 0;
    const remainingText = (!firstAt || remainingMs <= 0) ? '—' : (() => {
      const min = Math.max(0, Math.floor(remainingMs / 60000));
      const hr = Math.floor(min / 60);
      const rem = min % 60;
      return hr > 0 ? `${hr}h ${rem}m` : `${rem}m`;
    })();
    const recent = Array.isArray(u.recent) ? u.recent : [];
    const expandedKey = window.__consoleV3?.expandedSession?.tool === 'claudecode'
      ? window.__consoleV3.expandedSession.sessionId : '';
    const recentHtml = recent.length ? `
      <div class="cv3-session-list">
        ${recent.map((r) => {
          const modelLabel = formatModelLabel(r.model);
          const preview = (r.firstMessage || '').trim() || '(无用户消息)';
          const projDisplay = r.project ? r.project.replace(/^-+/, '').replace(/-+/g, '/') : '';
          const sessionId = String(r.sessionId || '').trim();
          const isExpanded = expandedKey && sessionId === expandedKey;
          const detailHtml = isExpanded ? renderSessionDetailPanel('claudecode', sessionId, r) : '';
          return `
          <div class="cv3-session-row ${isExpanded ? 'is-expanded' : ''}" data-cv3-session-tool="claudecode" data-cv3-session-id="${esc(sessionId)}" data-cv3-session-path="${esc(r.path || '')}" tabindex="0" role="button" aria-expanded="${isExpanded ? 'true' : 'false'}">
            <div class="cv3-session-row-main">
              <div class="cv3-session-title">${esc(preview)}</div>
              <div class="cv3-session-meta">
                ${modelLabel ? `<span class="cv3-session-chip">${esc(modelLabel)}</span>` : ''}
                ${projDisplay ? `<span class="cv3-session-proj" title="${esc(r.project || '')}">${esc(projDisplay)}</span>` : ''}
                <span class="cv3-session-count">${esc(String(r.messageCount || 0))} 条</span>
                <span class="cv3-session-when">${esc(formatRelativeTime(r.lastActiveAt))}</span>
              </div>
            </div>
            <svg class="cv3-session-chevron" width="10" height="10" viewBox="0 0 10 10" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M3 1.5L7 5L3 8.5"/></svg>
          </div>
          ${detailHtml}`;
        }).join('')}
      </div>` : '<div class="cv3-proc-empty">暂无会话</div>';

    const refreshUsageClaude = '<button type="button" class="cv3-link-btn" data-console-v3-refresh-usage>刷新</button>';
    el.innerHTML = `
      ${cv3SectionHead(CV3_ICONS.clock, '本地 5h 窗口 (估算)', { extras: refreshUsageClaude })}
      <div class="cv3-usage-grid">
        <div class="cv3-usage-cell">
          <div class="cv3-usage-label">本机消息</div>
          <div class="cv3-usage-value">${esc(String(u.messagesInWindow || 0))}</div>
          <div class="cv3-usage-hint">窗口内</div>
        </div>
        <div class="cv3-usage-cell">
          <div class="cv3-usage-label">窗口起点</div>
          <div class="cv3-usage-value">${firstAt ? esc(firstAt.toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' })) : '—'}</div>
          <div class="cv3-usage-hint">${firstAt ? esc(formatRelativeTime(u.windowFirstMessageAt)) : '无活动'}</div>
        </div>
        <div class="cv3-usage-cell">
          <div class="cv3-usage-label">窗口剩余</div>
          <div class="cv3-usage-value">${esc(remainingText)}</div>
          <div class="cv3-usage-hint">到期后计数重置</div>
        </div>
        <div class="cv3-usage-cell">
          <div class="cv3-usage-label">近 24h 会话</div>
          <div class="cv3-usage-value">${esc(String(u.todaySessions || 0))}</div>
          <div class="cv3-usage-hint">共 ${esc(String(u.totalSessions || 0))} 个</div>
        </div>
      </div>
      <div class="cv3-session-head">最近会话</div>
      ${recentHtml}
      <div class="cv3-usage-note">⚠ 只统计本机 jsonl 历史；跨机 / web claude.ai 用量不在内，以账号服务端为准。</div>`;
    return;
  }

  if (tool === 'cursor') {
    const u = window.__consoleV3.cursorUsage;
    if (!u) {
      el.innerHTML = `${cv3SectionHead(CV3_ICONS.clock, 'Cursor 本地用量')}<div class="cv3-proc-empty">读取 Cursor state.vscdb 中…</div>`;
      return;
    }
    const refreshBtn = '<button type="button" class="cv3-link-btn" data-console-v3-refresh-usage>刷新</button>';
    if (u.supported === false || u.status === 'not_found') {
      el.innerHTML = `${cv3SectionHead(CV3_ICONS.clock, 'Cursor 本地用量', { extras: refreshBtn })}<div class="cv3-proc-empty">${esc(u.message || '未找到 Cursor 本地数据（state.vscdb）。')}</div>`;
      return;
    }
    const t = u.totals || {};
    const acc = u.account || {};
    const accBits = [];
    if (acc.email) accBits.push(esc(acc.email));
    if (acc.plan) accBits.push(esc(String(acc.plan).toUpperCase()));
    if (acc.subscriptionStatus) accBits.push(esc(acc.subscriptionStatus));
    const accLine = accBits.length ? `<div class="cv3-usage-note">账号 · ${accBits.join(' · ')}</div>` : '';

    const dist = Array.isArray(u.modelDistribution) ? u.modelDistribution : [];
    const distHtml = dist.length ? `
      <div class="cv3-session-dist">
        <span class="cv3-session-dist-label">模型分布</span>
        ${dist.map((d) => `<span class="cv3-session-dist-chip">${esc(formatModelLabel(d.model) || d.model)} <em>${esc(String(d.count))}</em></span>`).join('')}
      </div>` : '';

    const recent = Array.isArray(u.recent) ? u.recent : [];
    const recentHtml = recent.length ? `
      <div class="cv3-session-list">
        ${recent.map((r) => {
          const modelLabel = formatModelLabel(r.model);
          const title = (r.name || '').trim() || '(未命名会话)';
          const modeLabel = (r.mode || '').trim();
          const costLabel = (typeof r.costUsd === 'number') ? `$${r.costUsd.toFixed(2)}` : '';
          return `
          <div class="cv3-session-row cv3-session-row-static">
            <div class="cv3-session-row-main">
              <div class="cv3-session-title">${esc(title)}</div>
              <div class="cv3-session-meta">
                ${modelLabel ? `<span class="cv3-session-chip">${esc(modelLabel)}</span>` : ''}
                ${modeLabel ? `<span class="cv3-session-chip">${esc(modeLabel)}</span>` : ''}
                <span class="cv3-session-count">${esc(String(r.messageCount || 0))} 条</span>
                ${costLabel ? `<span class="cv3-session-count">${esc(costLabel)}</span>` : ''}
                <span class="cv3-session-when">${esc(formatRelativeTime(r.lastActiveAt))}</span>
              </div>
            </div>
          </div>`;
        }).join('')}
      </div>` : '<div class="cv3-proc-empty">暂无会话</div>';

    const costNote = (t.costRecorded && typeof t.costUsd === 'number')
      ? `<div class="cv3-usage-note">本地记录花费 $${esc(t.costUsd.toFixed(2))}（Cursor 多数会话不在本地记账，以官网账单为准）。</div>`
      : '';

    el.innerHTML = `
      ${cv3SectionHead(CV3_ICONS.clock, 'Cursor 本地用量', { extras: refreshBtn })}
      ${accLine}
      <div class="cv3-usage-grid">
        <div class="cv3-usage-cell">
          <div class="cv3-usage-label">会话总数</div>
          <div class="cv3-usage-value">${esc(String(t.sessions || 0))}</div>
        </div>
        <div class="cv3-usage-cell">
          <div class="cv3-usage-label">近 24h</div>
          <div class="cv3-usage-value">${esc(String(t.today || 0))}</div>
        </div>
        <div class="cv3-usage-cell">
          <div class="cv3-usage-label">近 7 天</div>
          <div class="cv3-usage-value">${esc(String(t.week || 0))}</div>
        </div>
        <div class="cv3-usage-cell">
          <div class="cv3-usage-label">消息数</div>
          <div class="cv3-usage-value">${esc(String(t.messages || 0))}</div>
        </div>
      </div>
      ${distHtml}
      <div class="cv3-session-head">最近会话</div>
      ${recentHtml}
      ${costNote}
      <div class="cv3-usage-note">⚠ 只读解析本机 Cursor state.vscdb，未联网；跨机 / 网页端用量不计入。</div>`;
    return;
  }

  // Other tools: just hide
  el.innerHTML = '';
}

// Reuse existing data sources but emit a leaner meta list.
function buildConsoleV2Model(tool) {
  const esc = typeof escapeHtml === 'function' ? escapeHtml : ((s) => String(s ?? ''));

  if (tool === 'codex') {
    const data = state.current || {};
    const codexBinary = typeof getToolBinaryStatus === 'function'
      ? getToolBinaryStatus('codex', data.codexBinary)
      : (data.codexBinary || {});
    const login = data.login || {};
    const active = data.activeProvider || null;
    const providers = Array.isArray(data.providers) ? data.providers : [];
    const health = active ? state.providerHealth[active.key] : null;

    const heroName = active?.name || (login.loggedIn ? (login.orgName || login.email || 'OpenAI 官方登录') : '尚未激活 Provider');
    const heroBase = active?.baseUrl || (login.loggedIn ? 'ChatGPT / OpenAI 官方' : '');
    const heroModel = data.summary?.model || '';
    const heroMode = active ? 'apikey' : (login.loggedIn ? 'oauth' : '');

    const issues = [];
    if (!codexBinary.installed) issues.push({ tone: 'error', title: 'Codex 未安装', copy: '还没检测到 codex 命令，先去「工具安装」页面。' });
    if (!data.configExists) issues.push({ tone: 'warn', title: '还没有 config.toml', copy: '当前作用域尚未写入 Codex 配置；建议先完成一次快速配置。' });
    if (!providers.length && !login.loggedIn) issues.push({ tone: 'error', title: '没有可用 Provider', copy: '既没有保存任何 Provider，也没有官方登录。' });
    if (active && !active.hasApiKey) issues.push({ tone: 'error', title: '当前 Provider 缺 Key', copy: `活动 Provider「${active.name}」未检测到可用 API Key。` });
    if (health?.checked && !health.ok) issues.push({ tone: 'warn', title: '连通性检测失败', copy: `最近一次对「${active?.name || '当前 Provider'}」的检测未通过。` });

    // Only fields that actually affect user decisions. Install path / env path
    // / reasoning strength etc. are one-click-away in the config editor.
    const meta = [
      { label: '版本', value: codexBinary.installed ? (codexBinary.version || '已安装') : '未安装' },
      { label: '作用域', value: data.scope === 'project' ? '项目级' : '全局' },
      { label: 'Sandbox', value: data.summary?.sandboxMode || '默认',
        tone: /danger/i.test(data.summary?.sandboxMode || '') ? 'warn' : '' },
      { label: '审批策略', value: data.summary?.approvalPolicy || '默认' },
    ];

    return {
      tool,
      toolLabel: 'Codex',
      hero: {
        name: heroName,
        baseUrl: heroBase,
        mode: heroMode,
        model: heroModel,
        plan: login.loggedIn ? (login.plan || '') : '',
        healthTxt: active ? (health?.loading ? '检测中' : health?.ok ? '已通' : health?.checked ? '失败' : '未检测') : (login.loggedIn ? '当前' : '未激活'),
        healthCls: active ? (health?.loading ? 'warn' : health?.ok ? 'ok' : health?.checked ? 'bad' : 'muted') : (login.loggedIn ? 'ok' : 'muted'),
      },
      meta,
      issues,
      providers: [],
      canLaunch: Boolean(codexBinary.installed),
    };
  }

  if (tool === 'claudecode') {
    const data = state.claudeCodeState || {};
    const login = data.login || {};
    const activeProfile = data.activeProfile || {};
    const installed = Boolean(data.binary?.installed);

    const issues = [];
    if (!installed) issues.push({ tone: 'error', title: 'Claude Code 未安装', copy: '还没检测到 claude 命令，请先完成安装。' });
    if (!login.loggedIn && !data.hasApiKey) issues.push({ tone: 'error', title: '未认证', copy: '当前既没有 OAuth 登录，也没有检测到 ANTHROPIC_API_KEY。' });
    if (!data.model) issues.push({ tone: 'warn', title: '未显式指定模型', copy: '未设置默认模型时 Claude Code 会回退到内置默认值。' });
    const heroName = activeProfile.email || activeProfile.organizationName || login.email || login.orgName || (login.loggedIn ? activeProfile.label || '官方登录' : (installed ? '未登录' : '未安装'));
    const homePath = data.configHome || activeProfile.configDir || '';
    const scopeHint = activeProfile.kind === 'profile'
      ? '当前使用独立 Claude profile'
      : '当前使用默认 ~/.claude';

    // Hero already shows account + plan + model. Meta should be the
    // behavior-affecting switches only.
    const meta = [
      { label: '版本', value: installed ? (data.binary?.version || '已安装') : '未安装' },
      { label: '认证', value: login.loggedIn ? (login.method === 'oauth' ? 'OAuth' : 'API Key') : '未认证' },
      { label: 'Always thinking', value: data.alwaysThinkingEnabled ? '开启' : '关闭' },
      { label: '危险权限提示', value: data.skipDangerousModePermissionPrompt ? '已跳过' : '保持提示',
        tone: data.skipDangerousModePermissionPrompt ? 'warn' : '' },
    ];

    const historyModels = (data.usedModels || []).slice(0, 10);

    return {
      tool,
      toolLabel: 'Claude Code',
      hero: {
        name: heroName,
        baseUrl: scopeHint,
        home: homePath,
        mode: login.method === 'oauth' ? 'oauth' : 'apikey',
        model: data.model || '',
        plan: login.plan || activeProfile.plan || '',
        healthTxt: login.loggedIn ? '已登录' : (data.hasApiKey ? 'Key 就绪' : '未认证'),
        healthCls: login.loggedIn ? 'ok' : (data.hasApiKey ? 'ok' : 'muted'),
      },
      meta,
      issues,
      providers: [], // Claude providers are surfaced in the hub; console stays meta-only.
      historyModels,
      canLaunch: installed && (login.loggedIn || data.hasApiKey),
    };
  }

  if (tool === 'opencode') {
    const data = state.opencodeState || {};
    const active = data.activeProvider || null;
    const activeAuth = data.activeAuth || null;
    const installed = Boolean(data.binary?.installed);

    const issues = [];
    if (!installed) issues.push({ tone: 'error', title: 'OpenCode 未安装', copy: '没有检测到 opencode 命令，先到「工具安装」。' });
    if (!data.configExists) issues.push({ tone: 'warn', title: '还没有 opencode.json', copy: '当前作用域没有写入配置。' });
    if (!data.model) issues.push({ tone: 'warn', title: '默认模型未设置', copy: 'OpenCode 模型格式是 provider/model。' });
    if (active && !active.hasCredential) issues.push({ tone: 'warn', title: '当前 Provider 缺凭证', copy: `活动 Provider「${active.name || active.key}」还没有 Key / auth 登录。` });

    const meta = [
      { label: '版本', value: installed ? (data.binary?.version || '已安装') : '未安装' },
      { label: '作用域', value: data.scope === 'project' ? '项目级' : '全局' },
      { label: '默认模型', value: data.model || '—' },
      { label: '当前 Provider', value: active?.key || '—' },
    ];

    return {
      tool,
      toolLabel: 'OpenCode',
      hero: {
        name: active?.name || active?.key || '尚未激活 Provider',
        baseUrl: active?.baseUrl || '',
        mode: (activeAuth && String(activeAuth.type || '').toLowerCase().includes('oauth')) ? 'oauth' : 'apikey',
        model: data.model || '',
        plan: '',
        healthTxt: active?.hasCredential ? '凭证就绪' : '缺凭证',
        healthCls: active?.hasCredential ? 'ok' : 'warn',
      },
      meta,
      issues,
      providers: [],
      canLaunch: installed,
    };
  }

  if (tool === 'cursor') {
    const u = window.__consoleV3.cursorUsage || {};
    const acc = u.account || {};
    const totals = u.totals || {};
    const notFound = u.supported === false || u.status === 'not_found';
    const email = acc.email || '';
    const plan = acc.plan || '';
    const meta = [
      { label: '账号', value: email || '未检测到登录' },
      { label: '会员', value: plan ? String(plan).toUpperCase() : '—' },
      { label: '本地会话', value: notFound ? '—' : String(totals.sessions ?? 0) },
      { label: '数据源', code: 'globalStorage/state.vscdb' },
    ];
    return {
      tool,
      toolLabel: 'Cursor',
      hero: {
        name: email || 'Cursor（本地）',
        baseUrl: 'Cursor 本地用量 · 只读解析 state.vscdb',
        mode: '',
        model: '',
        plan: plan || '',
        healthTxt: notFound ? '无本地数据' : '本地已读',
        healthCls: notFound ? 'muted' : 'ok',
      },
      meta,
      issues: [],
      providers: [],
      canLaunch: false,
    };
  }

  // openclaw
  const data = state.openclawState || {};
  const installed = Boolean(data.binary?.installed);
  const gatewayUp = Boolean(data.gatewayStatus?.ok || data.gatewayRunning);
  const issues = [];
  if (!installed) issues.push({ tone: 'error', title: 'OpenClaw 未安装', copy: '请先在「工具安装」完成安装。' });
  else if (!gatewayUp) issues.push({ tone: 'warn', title: 'Gateway 未运行', copy: '点击启动后 Dashboard 才能用。' });

  const meta = [
    { label: '版本', value: installed ? (data.binary?.version || '已安装') : '未安装' },
    { label: 'Gateway', value: gatewayUp ? `运行中 · :${data.gatewayPort || '—'}` : '未运行',
      tone: gatewayUp ? '' : 'warn' },
    { label: 'Dashboard', code: data.dashboardUrl || '—' },
  ];

  return {
    tool: 'openclaw',
    toolLabel: 'OpenClaw',
    hero: {
      name: installed ? 'OpenClaw' : '未安装',
      baseUrl: data.dashboardUrl || '',
      mode: '',
      model: '',
      plan: '',
      healthTxt: gatewayUp ? '运行中' : '未运行',
      healthCls: gatewayUp ? 'ok' : 'warn',
    },
    meta,
    issues,
    providers: [],
    canLaunch: installed,
  };
}

function renderConsoleV2(tool) {
  const esc = typeof escapeHtml === 'function' ? escapeHtml : ((s) => String(s ?? ''));
  const model = buildConsoleV2Model(tool);

  // Kick off any data loads the v3 sections depend on. Safe to call each
  // render — each loader guards itself against re-entry.
  primeConsoleV3(tool);

  const titleToolEl = document.getElementById('consoleV2TitleTool');
  if (titleToolEl) titleToolEl.textContent = model.toolLabel;

  // v3 sections (vantage matrix replaces the old standalone firewall card).
  renderConsoleV3Procs(tool, model.toolLabel);
  renderConsoleV3Usage(tool);
  renderConsoleV3Vantages();
  renderConsoleV3Terminal(tool, model.toolLabel);

  const heroEl = document.getElementById('consoleV2Hero');
  if (heroEl) {
    const h = model.hero;
    const modeTxt = h.mode === 'oauth' ? 'OAUTH' : h.mode === 'apikey' ? 'API KEY' : '';
    heroEl.innerHTML = `
      <div class="console-v2-hero-top">
        <div class="console-v2-hero-info">
          <div class="console-v2-hero-eyebrow">
            <span>${esc(model.toolLabel.toUpperCase())} · SESSION</span>
            <span class="ch-status ${esc(h.healthCls)}">${esc(h.healthTxt)}</span>
          </div>
          <h2 class="console-v2-hero-name">${esc(h.name)}</h2>
          <div class="console-v2-hero-badges">
            ${modeTxt ? `<span class="ch-mode ${esc(h.mode)}">${modeTxt}</span>` : ''}
            ${h.plan ? `<span class="ch-row-plan" data-plan="${esc(String(h.plan).toLowerCase())}">${esc(String(h.plan).toUpperCase())}</span>` : ''}
            ${h.model ? `<span class="ch-hero-model">${esc(h.model)}</span>` : ''}
          </div>
        </div>
        <div class="console-v2-hero-actions">
          <button type="button" class="ch-hero-ghost" data-console-v2-refresh>
            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 12a9 9 0 0 1-15.36 6.36L3 21M3 12a9 9 0 0 1 15.36-6.36L21 3"/></svg>
            重新检测
          </button>
          <button type="button" class="ch-hero-ghost" data-console-v2-goto-quick>
            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 12h16M4 6h16M4 18h10"/></svg>
            快速配置
          </button>
          <button type="button" class="ch-hero-ghost" data-console-v2-goto-editor>
            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14.5 3.5l6 6-11 11H3.5v-6l11-11z"/></svg>
            配置编辑
          </button>
        </div>
      </div>
      <div class="console-v2-hero-details">
        ${h.baseUrl ? `<div class="console-v2-hero-url">${esc(h.baseUrl)}</div>` : ''}
        ${h.home ? `<div class="console-v2-hero-url">${esc(`CLAUDE_CONFIG_DIR · ${h.home}`)}</div>` : ''}
        ${renderHeroIpStripHTML()}
      </div>
      `;
  }

  const metaEl = document.getElementById('consoleV2Meta');
  if (metaEl) {
    if (!model.meta.length) {
      metaEl.innerHTML = '';
    } else {
      metaEl.innerHTML = `
        ${cv3SectionHead(CV3_ICONS.sliders, '当前配置')}
        <div class="console-v2-meta-list">
          ${model.meta.map((m) => `
            <div class="console-v2-meta-row${m.tone ? ' cv3-meta-' + esc(m.tone) : ''}">
              <span class="console-v2-meta-label">${esc(m.label)}</span>
              <span class="console-v2-meta-value">
                ${m.value ? `<span>${esc(m.value)}</span>` : ''}
                ${m.code ? `<span class="console-v2-code">${esc(m.code)}</span>` : ''}
              </span>
            </div>`).join('')}
        </div>`;
    }
  }

  const issuesEl = document.getElementById('consoleV2Issues');
  if (issuesEl) {
    if (!model.issues.length) {
      issuesEl.innerHTML = '';
      issuesEl.classList.add('hide');
    } else {
      issuesEl.classList.remove('hide');
      issuesEl.innerHTML = `
        ${cv3SectionHead(CV3_ICONS.alert, '异常检测', { count: model.issues.length })}
        <div class="console-v2-issue-list">
          ${model.issues.map((i) => `
            <div class="console-v2-issue ${esc(i.tone || 'warn')}">
              <div class="console-v2-issue-title">${esc(i.title)}</div>
              <div class="console-v2-issue-copy">${esc(i.copy)}</div>
            </div>`).join('')}
        </div>`;
    }
  }

  const providersEl = document.getElementById('consoleV2Providers');
  if (providersEl) {
    if (!model.providers.length) {
      providersEl.innerHTML = '';
      providersEl.classList.add('hide');
    } else {
      providersEl.classList.remove('hide');
      providersEl.innerHTML = `
        <div class="console-v2-section-head">已保存 Provider<span class="count">· ${model.providers.length}</span></div>
        <div class="console-v2-provider-list">
          ${model.providers.map((p) => `
            <div class="console-v2-provider ${p.isActive ? 'current' : ''}">
              <span class="console-v2-provider-dot ${esc(p.statusCls)}"></span>
              <span class="console-v2-provider-body">
                <span class="console-v2-provider-name">${esc(p.name)}</span>
                ${p.baseUrl ? `<span class="console-v2-provider-url">${esc(p.baseUrl)}</span>` : ''}
              </span>
              <span class="ch-status ${esc(p.statusCls)}">${esc(p.statusTxt)}</span>
            </div>`).join('')}
        </div>`;
    }
  }
}



async function stopOpenClawGateway({ manual = true } = {}) {
  const result = await api('/api/openclaw/stop', { method: 'POST' });
  if (!result.ok) {
    if (manual) flash(result.error || '停止 Gateway 失败', 'error');
    return result;
  }
  await sleep(400);
  await refreshToolRuntimeAfterMutation('openclaw');
  if (manual) flash(result.data?.message || 'OpenClaw 已停止', 'success');
  return result;
}

async function setOpenClawDaemonEnabled(enabled, { manual = true } = {}) {
  const result = await api('/api/openclaw/daemon', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ enabled: Boolean(enabled) }),
  });
  if (!result.ok) {
    if (manual) flash(result.error || (enabled ? '开启常驻服务失败' : '关闭常驻服务失败'), 'error');
    return result;
  }
  await sleep(400);
  await refreshToolRuntimeAfterMutation('openclaw');
  if (manual) flash(result.data?.message || (enabled ? 'OpenClaw 常驻服务已开启' : 'OpenClaw 常驻服务已关闭'), 'success');
  return result;
}

async function killOpenClawPortOccupants({ manual = true } = {}) {
  const data = state.openclawState || await fetchOpenClawStateData();
  const occupants = Array.isArray(data.gatewayPortOccupants) ? data.gatewayPortOccupants : [];
  if (!occupants.length) {
    if (manual) flash(`未检测到 ${data.gatewayPort || '18789'} 端口占用进程`, 'info');
    return { ok: true, data: { killed: [] } };
  }

  const confirmed = await openUpdateDialog({
    eyebrow: 'OpenClaw',
    title: `结束 ${data.gatewayPort || '18789'} 端口占用`,
    body: `<p>将尝试结束以下进程：</p><div class="install-cmd-block">${occupants.map((item) => escapeHtml(item.label || `${item.name || '未知进程'} (PID ${item.pid || '-'})`)).join('<br>')}</div>`,
    confirmText: '结束进程',
    cancelText: '取消',
    tone: 'danger',
  });
  if (!confirmed) return { ok: false, cancelled: true };

  const result = await api('/api/openclaw/port-kill', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({}),
  });
  if (!result.ok) {
    if (manual) flash(result.error || '结束端口占用进程失败', 'error');
    return result;
  }
  await loadOpenClawQuickState();
  if (manual) flash(result.data?.message || '端口占用进程已结束', 'success');
  return result;
}

async function repairOpenClawDashboard({ silent = false } = {}) {
  const data = state.openclawState || await fetchOpenClawStateData();
  if (!data.binary?.installed) {
    if (!silent) flash('OpenClaw 尚未安装', 'error');
    return;
  }
  const json = await api('/api/openclaw/repair-dashboard-auth', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ cwd: state.current?.launch?.cwd || '' }),
  });
  if (!json.ok || !json.data?.dashboardUrl) {
    throw new Error(json.error || '修复 Gateway 认证失败');
  }
  state.openClawLastRepair = json.data;
  await fetchOpenClawStateData();
  await openOpenClawDashboard(json.data.dashboardUrl);
  if (!silent) {
    flash(json.data.tokenGenerated ? '已生成新 token 并重新打开 Dashboard' : '已重新打开带令牌的 Dashboard', 'success');
  }
}

async function refreshToolConsoleData({ manual = false } = {}) {
  if (state.consoleRefreshing) return;
  state.consoleRefreshing = true;
  const btn = el('toolConsoleRefreshBtn');
  const original = btn?.textContent || '↻ 刷新检测';
  if (btn) {
    btn.disabled = true;
    btn.textContent = '检测中...';
  }
  try {
    await loadState({ preserveForm: true });
    await loadClaudeCodeQuickState();
    await loadOpenCodeQuickState();
    await loadOpenClawQuickState();
    invalidateConsoleV3Tool(state.consoleTool || 'codex');
    renderToolConsole();
    if (manual) flash(`${getToolConsoleLabel(state.consoleTool)} 控制台已刷新`, 'success');
  } finally {
    state.consoleRefreshing = false;
    if (btn) {
      btn.disabled = false;
      btn.textContent = original;
    }
  }
}

async function handleToolConsoleAction(button) {
  const action = button?.dataset.consoleAction;
  const targetTool = button?.dataset.consoleToolTarget || '';
  if (!action) return;

  if (action === 'refresh-console') {
    await refreshToolConsoleData({ manual: true });
    return;
  }

  if (action === 'goto-page') {
    setPage(button.dataset.consolePage || 'quick');
    return;
  }

  if (action === 'goto-quick-tool') {
    if (targetTool && !setActiveTool(targetTool)) return;
    if (targetTool === 'codex') {
      const login = state.current?.login || {};
      if (login.loggedIn && String(login.method || '').toLowerCase() === 'chatgpt') {
        state.codexAuthView = 'official';
        localStorage.setItem('easyaiconfig_codex_auth_view', state.codexAuthView);
      }
    }
    setPage('quick');
    return;
  }

  if (action === 'goto-config-editor-tool') {
    if (flashTemporarilyDisabledTool(targetTool)) return;
    if (targetTool === 'openclaw' && !state.openclawState) {
      await loadOpenClawQuickState();
    }
    if (targetTool === 'claudecode' && !state.claudeCodeState) {
      await loadClaudeCodeQuickState();
    }
    if (targetTool !== 'openclaw' && !state.current) {
      await loadState({ preserveForm: true });
    }
    state.configEditorTool = normalizeConfigEditorTool(targetTool);
    syncConfigEditorForTool();
    populateConfigEditor();
    if (window.refreshCustomSelects) window.refreshCustomSelects();
    setPage('configEditor');
    return;
  }

  if (action === 'opencode-auth-login') {
    const provider = button.dataset.consoleProvider || state.opencodeState?.activeProviderKey || '';
    const method = button.dataset.consoleMethod || '';
    const original = button.textContent || '启动 auth login';
    button.disabled = true;
    button.textContent = '启动中...';
    try {
      const json = await api('/api/opencode/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          cwd: el('launchCwdInput')?.value?.trim() || el('projectPathInput')?.value?.trim() || '',
          provider,
          method,
        }),
      });
      if (!json.ok) {
        flash(json.error || '启动 OpenCode 登录失败', 'error');
        return;
      }
      flash('已在终端打开 OpenCode auth login，请完成登录后点击刷新状态', 'success');
    } finally {
      button.disabled = false;
      button.textContent = original;
    }
    return;
  }

  if (action === 'opencode-auth-remove') {
    const provider = button.dataset.consoleAuthKey || button.dataset.consoleProvider || state.opencodeState?.activeAuth?.key || '';
    if (!provider) {
      flash('未找到可移除的 OpenCode 凭证', 'error');
      return;
    }
    if (!window.confirm(`确认移除 OpenCode 凭证「${provider}」吗？`)) return;
    const original = button.textContent || '移除当前凭证';
    button.disabled = true;
    button.textContent = '移除中...';
    try {
      const json = await api('/api/opencode/auth-remove', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          scope: el('scopeSelect')?.value || 'global',
          projectPath: el('projectPathInput')?.value?.trim() || '',
          provider,
        }),
      });
      if (!json.ok) {
        flash(json.error || '移除 OpenCode 凭证失败', 'error');
        return;
      }
      await loadOpenCodeQuickState();
      if (state.activePage === 'configEditor' && getConfigEditorTool() === 'opencode') {
        populateConfigEditor();
      }
      renderToolConsole();
      renderCurrentConfig();
      flash('OpenCode 凭证已移除', 'success');
    } finally {
      button.disabled = false;
      button.textContent = original;
    }
    return;
  }

  if (action === 'launch-openclaw') {
    await launchOpenClawOnly();
    renderToolConsole();
    return;
  }

  if (action === 'open-openclaw-dashboard') {
    const data = state.openclawState || await fetchOpenClawStateData();
    if (!data.gatewayReachable) {
      flash('Dashboard 还没准备好，请先启动 OpenClaw', 'info');
      return;
    }
    await repairOpenClawDashboard({ silent: true });
    return;
  }

  if (action === 'repair-openclaw-dashboard') {
    await repairOpenClawDashboard();
    renderToolConsole();
    return;
  }

  if (action === 'kill-openclaw-port') {
    await killOpenClawPortOccupants({ manual: true });
    renderToolConsole();
    return;
  }

  if (action === 'stop-openclaw') {
    await stopOpenClawGateway({ manual: true });
    renderToolConsole();
    return;
  }

  if (action === 'toggle-openclaw-daemon') {
    const data = state.openclawState || await fetchOpenClawStateData();
    await setOpenClawDaemonEnabled(!data.daemonInstalled, { manual: true });
    renderToolConsole();
    return;
  }
}

function parseApiRequest(url, options = {}) {
  const target = new URL(url, window.location.origin);
  const query = Object.fromEntries(target.searchParams.entries());
  let body = undefined;
  if (options.body !== undefined) {
    if (typeof options.body === 'string') {
      try {
        body = JSON.parse(options.body);
      } catch {
        body = options.body;
      }
    } else if (typeof options.body === 'object') {
      body = options.body;
    } else {
      body = options.body;
    }
  }
  return {
    path: target.pathname,
    method: options.method || 'GET',
    query,
    body,
  };
}

let localApiAuth = { token: '', header: 'x-local-token' };

async function ensureLocalApiAuth() {
  if (tauriInvoke || localApiAuth.token) return localApiAuth;
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 8000);
  let json;
  try {
    const response = await fetch('/api/bootstrap', { cache: 'no-store', signal: controller.signal });
    json = await response.json();
  } catch (error) {
    if (error?.name === 'AbortError') throw new Error('本地服务无响应，请稍后再试');
    throw error;
  } finally {
    clearTimeout(timer);
  }
  if (!json?.ok || !json?.data?.token) {
    throw new Error(json?.error || '本地服务鉴权初始化失败');
  }
  localApiAuth = {
    token: String(json.data.token),
    header: String(json.data.header || 'x-local-token'),
  };
  return localApiAuth;
}

async function api(url, options = {}) {
  const timeoutMs = options.timeoutMs || 20000;

  if (tauriInvoke) {
    let timeoutId;
    try {
      const result = await Promise.race([
        tauriInvoke('backend_request', parseApiRequest(url, options)),
        new Promise((_, reject) => {
          timeoutId = setTimeout(() => reject(new Error('请求超时')), timeoutMs);
        }),
      ]);
      clearTimeout(timeoutId);
      return result;
    } catch (error) {
      clearTimeout(timeoutId);
      return { ok: false, error: error instanceof Error ? error.message : String(error) };
    }
  }

  const auth = await ensureLocalApiAuth();
  const headers = new Headers(options.headers || {});
  headers.set(auth.header, auth.token);
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const response = await fetch(url, { ...options, headers, signal: controller.signal });
    return await response.json();
  } catch (error) {
    if (error?.name === 'AbortError') return { ok: false, error: '请求超时，请稍后再试' };
    return { ok: false, error: error instanceof Error ? error.message : String(error) };
  } finally {
    clearTimeout(timer);
  }
}

function normalizeProviderRemoteUsageCacheEntry(entry = {}) {
  const result = entry?.result && typeof entry.result === 'object' ? entry.result : null;
  const error = entry?.error ? String(entry.error).slice(0, 500) : '';
  const fetchedAt = Number(entry?.fetchedAt) || Date.now();
  return { result, error, fetchedAt };
}

function providerRemoteUsageCacheParts(cacheKey = '', fallback = {}) {
  const text = String(cacheKey || '').trim();
  const sep = text.indexOf(':');
  const tool = (sep >= 0 ? text.slice(0, sep) : fallback.tool || 'codex').trim().toLowerCase() || 'codex';
  const providerKey = (fallback.providerKey || (sep >= 0 ? text.slice(sep + 1) : text)).trim();
  return { tool, providerKey };
}

async function persistProviderRemoteUsageCacheRecord(cacheKey, normalized, options = {}) {
  const { tool, providerKey } = providerRemoteUsageCacheParts(cacheKey, options);
  if (!providerKey) return null;
  return api('/api/provider/remote-usage/cache', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      cacheKey,
      tool,
      providerKey,
      result: normalized.result,
      error: normalized.error,
      fetchedAt: normalized.fetchedAt,
    }),
    timeoutMs: 12000,
  }).catch(() => null);
}

function setProviderRemoteUsageCache(cacheKey, entry, options = {}) {
  const key = String(cacheKey || '').trim();
  if (!key) return null;
  const normalized = normalizeProviderRemoteUsageCacheEntry(entry);
  state.providerRemoteUsageByKey[key] = normalized;
  if (options.persist !== false) {
    void persistProviderRemoteUsageCacheRecord(key, normalized, options);
  }
  return normalized;
}

async function saveProviderRemoteUsageCache(cacheKey, entry, options = {}) {
  const key = String(cacheKey || '').trim();
  if (!key) return null;
  const normalized = setProviderRemoteUsageCache(key, entry, { ...options, persist: false });
  await persistProviderRemoteUsageCacheRecord(key, normalized, options);
  return normalized;
}

async function loadProviderRemoteUsageCache() {
  try {
    const res = await api('/api/provider/remote-usage/cache?limit=120', { timeoutMs: 12000 });
    if (!res?.ok || !res.data?.entries || typeof res.data.entries !== 'object') return;
    for (const [key, entry] of Object.entries(res.data.entries)) {
      if (!key) continue;
      state.providerRemoteUsageByKey[key] = normalizeProviderRemoteUsageCacheEntry(entry);
    }
    try { window.renderConnectionHub?.(); } catch (_) {}
    if (state.providerDetail?.open) renderProviderDetail({ force: true });
  } catch (_) {}
}

function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

/* ── TOML / JSON Syntax Highlighter ── */
function highlightToml(toml) {
  if (!toml) return '<span class="toml-hl-comment"># 暂无配置</span>';
  return toml.split('\n').map(line => {
    // Comment
    if (/^\s*#/.test(line)) return `<span class="toml-hl-comment">${escapeHtml(line)}</span>`;
    // Section header  [section] or [[array]]
    const secMatch = line.match(/^(\s*\[{1,2})([^\]]+)(\]{1,2})/);
    if (secMatch) return `<span class="toml-hl-section">${escapeHtml(line)}</span>`;
    // Key = value
    const kvMatch = line.match(/^(\s*)([A-Za-z0-9_.\-]+)(\s*=\s*)(.*)/);
    if (kvMatch) {
      const [, indent, key, eq, val] = kvMatch;
      return `${escapeHtml(indent)}<span class="toml-hl-key">${escapeHtml(key)}</span><span class="toml-hl-eq">${escapeHtml(eq)}</span>${highlightTomlValue(val)}`;
    }
    return escapeHtml(line);
  }).join('\n');
}

function highlightTomlValue(val) {
  const trimmed = val.trim();
  // String (double or single quoted)
  if (/^".*"$/.test(trimmed) || /^'.*'$/.test(trimmed)) return `<span class="toml-hl-str">${escapeHtml(val)}</span>`;
  // Multi-line string start
  if (/^"""/.test(trimmed) || /^'''/.test(trimmed)) return `<span class="toml-hl-str">${escapeHtml(val)}</span>`;
  // Boolean
  if (trimmed === 'true' || trimmed === 'false') return `<span class="toml-hl-bool">${escapeHtml(val)}</span>`;
  // Number
  if (/^-?\d[\d_.]*$/.test(trimmed) || /^0x[\da-fA-F]+$/.test(trimmed)) return `<span class="toml-hl-num">${escapeHtml(val)}</span>`;
  // Array
  if (trimmed.startsWith('[')) return `<span class="toml-hl-str">${escapeHtml(val)}</span>`;
  // Inline table
  if (trimmed.startsWith('{')) return `<span class="toml-hl-str">${escapeHtml(val)}</span>`;
  return escapeHtml(val);
}

function highlightJson(json) {
  if (!json) return '<span class="toml-hl-comment">// 暂无配置</span>';
  return json.split('\n').map(line => {
    // String key: "key":
    let result = line.replace(/"([^"]+)"\s*:/g, '<span class="toml-hl-key">"$1"</span><span class="toml-hl-eq">:</span>');
    // String values
    result = result.replace(/:\s*"([^"]*)"/g, ': <span class="toml-hl-str">"$1"</span>');
    // Booleans
    result = result.replace(/\b(true|false|null)\b/g, '<span class="toml-hl-bool">$1</span>');
    // Numbers
    result = result.replace(/:\s*(-?\d[\d.]*)/g, ': <span class="toml-hl-num">$1</span>');
    return result;
  }).join('\n');
}

function getRawCodeEditorTheme() {
  return state.theme === 'light' ? 'ace/theme/github' : 'ace/theme/tomorrow_night_eighties';
}

function ensureRawCodeEditor({ editorId, textareaId, mode }) {
  const host = el(editorId);
  const textarea = el(textareaId);
  if (!host || !textarea || !window.ace) return null;
  if (rawCodeEditors.has(textareaId)) return rawCodeEditors.get(textareaId);

  window.ace.config.set('basePath', '/vendor/ace');
  const editor = window.ace.edit(editorId);
  editor.session.setMode(mode);
  editor.session.setUseWorker(false);
  editor.session.setTabSize(2);
  editor.session.setUseSoftTabs(true);
  editor.setTheme(getRawCodeEditorTheme());
  editor.setOptions({
    fontSize: '12px',
    showPrintMargin: false,
    wrap: false,
    highlightActiveLine: true,
    scrollPastEnd: 0.15,
    animatedScroll: true,
  });
  editor.setValue(textarea.value || '', -1);
  editor.session.on('change', () => {
    textarea.value = editor.getValue();
  });
  rawCodeEditors.set(textareaId, editor);
  return editor;
}

function getRawTextareaValue(textareaId) {
  const textarea = el(textareaId);
  const editor = rawCodeEditors.get(textareaId);
  if (editor) {
    const value = editor.getValue();
    if (textarea && textarea.value !== value) textarea.value = value;
    return value;
  }
  return textarea?.value || '';
}

function getCodexRawTomlValue() {
  return getRawTextareaValue('cfgRawTomlTextarea');
}

function getCodexRawAuthValue() {
  return getRawTextareaValue('cfgRawAuthTextarea');
}

function getCodexRawAuthBaseline() {
  return state.current?.authJsonRaw || '{}';
}

function isCodexRawTomlEdited() {
  const value = getCodexRawTomlValue();
  return Boolean(value.trim() && value !== (state.current?.configToml || ''));
}

function isCodexRawAuthEdited() {
  const value = getCodexRawAuthValue();
  return Boolean(value.trim() && value !== getCodexRawAuthBaseline());
}

function buildCodexRawSavePayload() {
  const payload = {
    scope: el('scopeSelect')?.value || 'global',
    projectPath: el('projectPathInput')?.value?.trim() || '',
    codexHome: el('codexHomeInput')?.value?.trim() || '',
    configToml: getCodexRawTomlValue(),
  };
  const authJson = getCodexRawAuthValue();
  if (authJson.trim() && isCodexRawAuthEdited()) {
    payload.authJson = authJson;
  }
  return payload;
}

async function saveCodexConfigEditorRequest({ forceRaw = false } = {}) {
  const rawEdited = isCodexRawTomlEdited() || isCodexRawAuthEdited();
  if (forceRaw || rawEdited) {
    return api('/api/config/raw-save', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(buildCodexRawSavePayload()),
    });
  }

  return api('/api/config/settings-save', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      scope: el('scopeSelect')?.value || 'global',
      projectPath: el('projectPathInput')?.value?.trim() || '',
      codexHome: el('codexHomeInput')?.value?.trim() || '',
      settings: buildSettingsPatch(),
    }),
  });
}

