function renderAssetActiveTab(activeTab, context = {}) {
  if (activeTab === 'skills') return renderAssetSkillsTab(context.skills);
  if (activeTab === 'prompts') return renderAssetPromptsTab(context.prompts);
  if (activeTab === 'sessions') return renderAssetSessionsTab(context.sessions, context.sessionTrash);
  if (activeTab === 'sync') return renderAssetSyncTab(context.syncTargets, context.syncSnapshots);
  if (activeTab === 'import') return renderAssetImportTab(context.ac);
  return renderAssetMcpTab(context.mcp, context.mcpPlan);
}

function renderAssetCenterPage() {
  const root = el('assetCenterPage');
  if (!root) return;
  const ac = state.assetCenter || {};
  const index = ac.index || {};
  const sessions = index.sessionInventory || {};
  const providerCatalog = index.providerCatalog || {};
  const sessionTrash = ac.sessionTrash || {};
  const mcp = index.mcpInventory || {};
  const prompts = index.promptInventory || {};
  const skills = index.skillInventory || {};
  const usage = index.usageInventory || {};
  const syncTargets = ac.syncTargets || {};
  const syncSnapshots = ac.syncSnapshots || {};
  const mcpPlan = ac.mcpPlan || {};
  const loading = Boolean(ac.loading);
  const error = ac.error || '';
  const softLoading = loading && !ac.index;
  const activeTab = ASSET_CENTER_TAB_IDS.includes(ac.activeTab) ? ac.activeTab : 'mcp';
  ac.activeTab = activeTab;
  const counts = {
    mcp: assetItems(mcp.servers).length,
    skills: assetItems(skills.skills).length,
    prompts: assetItems(prompts.files).length,
    sessions: assetNumber(sessions.summary?.sessions) || assetItems(sessions.items).length,
    sync: assetNumber(syncTargets.summary?.targets) || assetItems(syncTargets.targets).length,
    import: ac.importPreview || ac.importResult || ac.deepLinkLastUrl ? 1 : '',
  };
  const tabPanel = renderAssetActiveTab(activeTab, {
    ac,
    mcp,
    mcpPlan,
    providerCatalog,
    prompts,
    skills,
    sessions,
    sessionTrash,
    syncTargets,
    syncSnapshots,
    usage,
  });

  root.innerHTML = `
    <div class="asset-center-head">
      <div>
        <div class="asset-center-kicker">Assets</div>
        <h2>资产中心</h2>
        <p>只把能闭环的内容放进资产统计：已验证的本地 JSONL / SQLite 用量会进入数据分析；没稳定 token 来源的工具只保留配置、安装或接入包入口。</p>
      </div>
      <div class="asset-center-actions">
        <button type="button" class="secondary tiny-btn" data-asset-refresh ${loading ? 'disabled' : ''}>${loading ? '刷新中' : '刷新'}</button>
        <button type="button" class="secondary tiny-btn" data-asset-copy-catalog ${ac.copyingLink ? 'disabled' : ''}>${ac.copyingLink ? '打包中' : '打包分享'}</button>
      </div>
    </div>
    ${error ? `<div class="asset-error">${escapeHtml(error)}</div>` : ''}
    ${softLoading ? '<div class="asset-loading-strip">正在读取本地资产...</div>' : loading ? '<div class="asset-loading-strip">正在刷新资产索引...</div>' : ''}
    ${renderAssetPurposeBar(counts)}
    ${renderAssetToolCapabilityList({ providerCatalog, mcp, prompts, skills, sessions, usage })}
    ${renderAssetTabs(activeTab, counts)}
    ${tabPanel}
    ${ac.fetchedAt ? `<div class="asset-foot">Updated ${escapeHtml(assetDate(ac.fetchedAt))}</div>` : ''}
  `;
}

async function loadAssetCenter({ force = false } = {}) {
  if (state.assetCenter.loading && !force) return;
  const requestId = `${Date.now()}-${Math.random().toString(16).slice(2)}`;
  state.assetCenter.loading = true;
  state.assetCenter.error = '';
  state.assetCenter.loadRequestId = requestId;
  renderAssetCenterPage();
  const params = new URLSearchParams({
    usage: '1',
    days: String(state.dashboardDays || 30),
    limit: '80',
  });
  const cwd = state.current?.launch?.cwd || '';
  if (cwd) {
    params.set('cwd', cwd);
    params.set('projectPath', cwd);
  }

  const failures = [];
  let loadedAny = false;
  const stillCurrent = () => state.assetCenter.loadRequestId === requestId;
  const recordFailure = (label, error) => {
    const message = error instanceof Error ? error.message : String(error || '读取失败');
    failures.push(`${label}: ${message}`);
    state.assetCenter.error = failures.join('；');
  };
  const requests = [
    {
      label: '资产索引',
      run: () => api(`/api/assets/index?${params.toString()}`, { timeoutMs: 45000 }),
      apply: (data) => { state.assetCenter.index = data || {}; },
    },
    {
      label: 'MCP 同步计划',
      run: () => api('/api/mcp/sync-plan', { timeoutMs: 30000 }),
      apply: (data) => { state.assetCenter.mcpPlan = data || null; },
    },
    {
      label: '同步目标',
      run: () => api('/api/sync/targets', { timeoutMs: 30000 }),
      apply: (data) => { state.assetCenter.syncTargets = data || null; },
    },
    {
      label: '同步快照',
      run: () => api('/api/sync/snapshots', { timeoutMs: 30000 }),
      apply: (data) => { state.assetCenter.syncSnapshots = data || null; },
    },
    {
      label: '会话回收站',
      run: () => api('/api/sessions/trash', { timeoutMs: 30000 }),
      apply: (data) => { state.assetCenter.sessionTrash = data || null; },
    },
  ];

  const settleOne = async (request) => {
    try {
      const json = await request.run();
      if (!stillCurrent()) return;
      if (!json?.ok) {
        recordFailure(request.label, json?.error || '读取失败');
        renderAssetCenterPage();
        return;
      }
      request.apply(json.data);
      loadedAny = true;
      state.assetCenter.fetchedAt = Date.now();
      renderAssetCenterPage();
    } catch (error) {
      if (!stillCurrent()) return;
      recordFailure(request.label, error);
      renderAssetCenterPage();
    }
  };

  await Promise.allSettled(requests.map(settleOne));
  if (!stillCurrent()) return;
  state.assetCenter.loading = false;
  state.assetCenter.error = failures.join('；');
  if (loadedAny && !state.assetCenter.fetchedAt) state.assetCenter.fetchedAt = Date.now();
  renderAssetCenterPage();
}

function assetSessionKey(item = {}) {
  return item.id || `${item.tool || ''}:${item.sessionId || ''}:${item.sourcePath || ''}`;
}

function assetSessionArchivePayload(item = {}, dryRun = true) {
  return {
    tool: item.tool || '',
    sessionId: item.sessionId || '',
    title: item.title || '',
    sourcePath: item.sourcePath || '',
    sourceLabel: item.sourceLabel || '',
    dryRun,
  };
}

function assetSessionRestorePayload(entry = {}, dryRun = true, overwrite = false) {
  return {
    archiveId: entry.id || '',
    tool: entry.tool || '',
    targetPath: entry.originalPath || '',
    dryRun,
    overwrite,
  };
}

async function archiveAssetSession(index) {
  const ac = state.assetCenter || {};
  const sessions = ac.index?.sessionInventory?.items || [];
  const item = sessions[Number(index)];
  if (!item || !item.sourcePath || !item.actions?.delete) {
    flash('这个会话暂不支持归档', 'error');
    return;
  }
  const key = assetSessionKey(item);
  if (ac.sessionArchiving) return;
  ac.sessionArchiving = key;
  renderAssetCenterPage();
  try {
    const previewJson = await api('/api/sessions/archive', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(assetSessionArchivePayload(item, true)),
      timeoutMs: 30000,
    });
    if (!previewJson.ok) throw new Error(previewJson.error || '会话归档预览失败');
    const entry = previewJson.data?.entry || {};
    const confirmed = await openUpdateDialog({
      eyebrow: 'Session Archive',
      title: '归档这个会话？',
      body: `<p>会话会先移动到 EasyAIConfig session trash，可从 trash manifest 恢复。</p>
        <div class="update-line"><code>${escapeHtml(entry.originalPath || item.sourcePath || '')}</code></div>`,
      confirmText: '归档',
      cancelText: '取消',
      tone: 'danger',
    });
    if (!confirmed) return;
    const archiveJson = await api('/api/sessions/archive', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(assetSessionArchivePayload(item, false)),
      timeoutMs: 30000,
    });
    if (!archiveJson.ok) throw new Error(archiveJson.error || '会话归档失败');
    flash('会话已归档，可从 session trash 恢复', 'success');
    await loadAssetCenter({ force: true });
  } catch (error) {
    flash(error instanceof Error ? error.message : '会话归档失败', 'error');
  } finally {
    ac.sessionArchiving = '';
    renderAssetCenterPage();
  }
}

async function restoreAssetSession(index) {
  const ac = state.assetCenter || {};
  const entries = ac.sessionTrash?.entries || [];
  const entry = entries[Number(index)];
  if (!entry || !entry.id || !entry.exists || entry.restoredAt) {
    flash('这个归档会话暂不可恢复', 'error');
    return;
  }
  const key = String(entry.id);
  if (ac.sessionRestoring) return;
  ac.sessionRestoring = key;
  renderAssetCenterPage();
  try {
    const previewJson = await api('/api/sessions/restore', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(assetSessionRestorePayload(entry, true, false)),
      timeoutMs: 30000,
    });
    if (!previewJson.ok) throw new Error(previewJson.error || '会话恢复预览失败');
    const operation = previewJson.data?.operations?.[0] || {};
    const hasConflict = operation.status === 'conflict' || previewJson.data?.summary?.conflicts;
    const confirmed = await openUpdateDialog({
      eyebrow: 'Session Restore',
      title: hasConflict ? '覆盖恢复这个会话？' : '恢复这个会话？',
      body: `<p>${hasConflict ? '目标路径已存在，确认后会覆盖原文件。' : '会话会恢复到原始 session 路径。'}</p>
        <div class="update-line"><code>${escapeHtml(entry.originalPath || operation.targetPath || '')}</code></div>`,
      confirmText: hasConflict ? '覆盖恢复' : '恢复',
      cancelText: '取消',
      tone: hasConflict ? 'danger' : 'default',
    });
    if (!confirmed) return;
    const restoreJson = await api('/api/sessions/restore', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(assetSessionRestorePayload(entry, false, Boolean(hasConflict))),
      timeoutMs: 30000,
    });
    if (!restoreJson.ok) throw new Error(restoreJson.error || '会话恢复失败');
    if (restoreJson.data?.summary?.conflicts) {
      throw new Error('目标路径仍有冲突，未恢复');
    }
    flash('会话已恢复', 'success');
    await loadAssetCenter({ force: true });
  } catch (error) {
    flash(error instanceof Error ? error.message : '会话恢复失败', 'error');
  } finally {
    ac.sessionRestoring = '';
    renderAssetCenterPage();
  }
}

function assetSyncTargetPayload(item = {}, dryRun = true) {
  return {
    targetId: item.id || '',
    dryRun,
    includeLocal: true,
    cwd: state.current?.launch?.cwd || '',
    projectPath: state.current?.launch?.cwd || '',
    label: `Asset Center ${new Date().toISOString()}`,
  };
}

async function pushAssetSyncTarget(index) {
  const ac = state.assetCenter || {};
  const targets = ac.syncTargets?.targets || [];
  const item = targets[Number(index)];
  if (!item || !item.id || (!item.path && !item.url)) {
    flash('这个同步目标暂不支持推送', 'error');
    return;
  }
  const key = `push:${item.id}`;
  if (ac.syncBusy) return;
  ac.syncBusy = key;
  renderAssetCenterPage();
  try {
    const previewJson = await api('/api/sync/push', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(assetSyncTargetPayload(item, true)),
      timeoutMs: 45000,
    });
    if (!previewJson.ok) throw new Error(previewJson.error || '同步推送预览失败');
    const entry = previewJson.data?.entry || {};
    const confirmed = await openUpdateDialog({
      eyebrow: 'Cloud Sync',
      title: '推送资产快照？',
      body: `<p>会把当前资产包写入同步目录的 snapshots，并更新 manifest。</p>
        <div class="update-line"><code>${escapeHtml(item.path || '')}</code></div>
        <div class="update-line">大小：${escapeHtml(assetFmt(entry.bytes || 0))} bytes</div>`,
      confirmText: '推送',
      cancelText: '取消',
    });
    if (!confirmed) return;
    const pushJson = await api('/api/sync/push', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(assetSyncTargetPayload(item, false)),
      timeoutMs: 45000,
    });
    if (!pushJson.ok) throw new Error(pushJson.error || '同步推送失败');
    flash('同步快照已推送', 'success');
    await loadAssetCenter({ force: true });
  } catch (error) {
    flash(error instanceof Error ? error.message : '同步推送失败', 'error');
  } finally {
    ac.syncBusy = '';
    renderAssetCenterPage();
  }
}

function assetSyncPullPayload(item = {}, dryRun = true) {
  const snapshot = syncSnapshotForTarget(item);
  return {
    targetId: item.id || '',
    snapshotId: snapshot?.summary?.latestSnapshotId || '',
    dryRun,
    targetTool: 'all',
    includeCatalogPresets: true,
    overwrite: false,
    append: false,
    installMode: 'copy',
    projectPath: state.current?.launch?.cwd || '',
  };
}

async function pullAssetSyncTarget(index) {
  const ac = state.assetCenter || {};
  const targets = ac.syncTargets?.targets || [];
  const item = targets[Number(index)];
  const snapshot = item ? syncSnapshotForTarget(item) : null;
  if (!item || !item.id || !snapshot?.summary?.latestSnapshotId) {
    flash('这个同步目标没有可拉取快照', 'error');
    return;
  }
  const key = `pull:${item.id}`;
  if (ac.syncBusy) return;
  ac.syncBusy = key;
  renderAssetCenterPage();
  try {
    const previewJson = await api('/api/sync/pull', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(assetSyncPullPayload(item, true)),
      timeoutMs: 45000,
    });
    if (!previewJson.ok) throw new Error(previewJson.error || '同步拉取预览失败');
    const summary = previewJson.data?.importResult?.summary || {};
    const confirmed = await openUpdateDialog({
      eyebrow: 'Cloud Sync',
      title: '拉取并应用同步快照？',
      body: `<p>会读取最新快照并按资产导入规则应用到本机。默认不覆盖冲突项。</p>
        <div class="update-line">快照：<code>${escapeHtml(snapshot.summary.latestSnapshotId || '')}</code></div>
        <div class="update-line">变更：${escapeHtml(assetFmt(Number(summary.created || 0) + Number(summary.updated || 0) + Number(summary.appended || 0)))} / 冲突：${escapeHtml(assetFmt(summary.conflicts || 0))}</div>`,
      confirmText: '拉取应用',
      cancelText: '取消',
      tone: summary.conflicts ? 'danger' : 'default',
    });
    if (!confirmed) return;
    const pullJson = await api('/api/sync/pull', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(assetSyncPullPayload(item, false)),
      timeoutMs: 45000,
    });
    if (!pullJson.ok) throw new Error(pullJson.error || '同步拉取失败');
    const applied = pullJson.data?.importResult?.summary || {};
    flash(`同步拉取完成：${assetFmt(applied.created || 0)} 新增，${assetFmt(applied.conflicts || 0)} 冲突`, applied.conflicts ? 'warning' : 'success');
    await loadAssetCenter({ force: true });
  } catch (error) {
    flash(error instanceof Error ? error.message : '同步拉取失败', 'error');
  } finally {
    ac.syncBusy = '';
    renderAssetCenterPage();
  }
}

async function copyAssetProviderCatalogLink() {
  if (state.assetCenter.copyingLink) return;
  state.assetCenter.copyingLink = true;
  renderAssetCenterPage();
  try {
    const bundleJson = await api('/api/assets/export', { timeoutMs: 30000 });
    if (!bundleJson.ok) throw new Error(bundleJson.error || '导出失败');
    const linkJson = await api('/api/assets/deep-link/build', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ payload: bundleJson.data }),
      timeoutMs: 30000,
    });
    if (!linkJson.ok) throw new Error(linkJson.error || '链接生成失败');
    await copyText(linkJson.data?.url || '');
    flash('资产 Deep Link 已复制', 'success');
  } catch (error) {
    flash(error instanceof Error ? error.message : '复制失败', 'error');
  } finally {
    state.assetCenter.copyingLink = false;
    renderAssetCenterPage();
  }
}

function assetImportRequestBody({ dryRun = true } = {}) {
  const ac = state.assetCenter || {};
  return {
    text: ac.importText || '',
    codexHome: ac.importCodexHome || '',
    projectPath: ac.importProjectPath || state.current?.launch?.cwd || '',
    targetTool: assetImportTargetTool(ac.importTargetTool || 'all'),
    installMode: ac.importInstallMode || 'copy',
    includeCatalogPresets: Boolean(ac.importIncludeCatalogPresets),
    overwrite: Boolean(ac.importOverwrite),
    append: Boolean(ac.importAppendPrompts),
    dryRun,
  };
}

function syncAssetImportStateFromForm() {
  const ac = state.assetCenter || {};
  ac.importText = document.querySelector('[data-asset-import-text]')?.value || ac.importText || '';
  ac.importCodexHome = document.querySelector('[data-asset-import-codex-home]')?.value?.trim() || '';
  ac.importProjectPath = document.querySelector('[data-asset-import-project-path]')?.value?.trim() || '';
  ac.importTargetTool = assetImportTargetTool(document.querySelector('[data-asset-import-target]')?.value || 'all');
  ac.importInstallMode = document.querySelector('[data-asset-import-install-mode]')?.value || 'copy';
  ac.importIncludeCatalogPresets = Boolean(document.querySelector('[data-asset-import-include-catalog]')?.checked);
  ac.importOverwrite = Boolean(document.querySelector('[data-asset-import-overwrite]')?.checked);
  ac.importAppendPrompts = Boolean(document.querySelector('[data-asset-import-append-prompts]')?.checked);
  ac.importConfirmApply = Boolean(document.querySelector('[data-asset-import-confirm]')?.checked);
}

async function previewAssetImportText(text = '', { syncForm = false } = {}) {
  const ac = state.assetCenter;
  if (ac.importLoading || ac.importApplying) return;
  if (syncForm) {
    syncAssetImportStateFromForm();
  } else if (typeof text === 'string' && text.trim()) {
    ac.importText = text.trim();
  }
  if (!ac.importText.trim()) {
    flash('请先粘贴 Deep Link 或 JSON bundle', 'error');
    return;
  }
  ac.importLoading = true;
  ac.importError = '';
  ac.importResult = null;
  renderAssetCenterPage();
  try {
    const previewJson = await api('/api/assets/import/preview', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ text: ac.importText }),
      timeoutMs: 30000,
    });
    if (!previewJson.ok) throw new Error(previewJson.error || '导入包解析失败');
    const dryRunJson = await api('/api/assets/import/apply', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(assetImportRequestBody({ dryRun: true })),
      timeoutMs: 30000,
    });
    if (!dryRunJson.ok) throw new Error(dryRunJson.error || '资产 dry-run 失败');
    ac.importPreview = {
      bundle: previewJson.data,
      apply: dryRunJson.data,
    };
    const summary = dryRunJson.data?.summary || {};
    flash(`预览完成：${summary.created || 0} 新增，${summary.conflicts || 0} 冲突`, summary.conflicts ? 'warning' : 'success');
  } catch (error) {
    ac.importError = error instanceof Error ? error.message : String(error);
    flash(ac.importError, 'error');
  } finally {
    ac.importLoading = false;
    renderAssetCenterPage();
  }
}

async function previewAssetImportFromInput() {
  return previewAssetImportText('', { syncForm: true });
}

async function applyAssetImportFromInput() {
  const ac = state.assetCenter;
  if (ac.importLoading || ac.importApplying) return;
  syncAssetImportStateFromForm();
  if (!ac.importText.trim()) {
    flash('请先粘贴 Deep Link 或 JSON bundle', 'error');
    return;
  }
  if (!ac.importConfirmApply) {
    flash('应用前需要勾选确认写入本机配置', 'error');
    return;
  }
  ac.importApplying = true;
  ac.importError = '';
  renderAssetCenterPage();
  try {
    const applyJson = await api('/api/assets/import/apply', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(assetImportRequestBody({ dryRun: false })),
      timeoutMs: 30000,
    });
    if (!applyJson.ok) throw new Error(applyJson.error || '资产导入失败');
    ac.importResult = applyJson.data;
    ac.importConfirmApply = false;
    const summary = applyJson.data?.summary || {};
    if (summary.written === false) {
      flash('导入包已解析；桌面端当前未写入本机配置。', 'warning');
    } else {
      flash(`资产导入完成：${summary.created || 0} 新增，${summary.updated || 0} 更新，${summary.conflicts || 0} 冲突`, summary.conflicts ? 'warning' : 'success');
    }
    if (summary.written) {
      void loadAssetCenter({ force: true });
      void loadState({ preserveForm: true });
    }
  } catch (error) {
    ac.importError = error instanceof Error ? error.message : String(error);
    flash(ac.importError, 'error');
  } finally {
    ac.importApplying = false;
    renderAssetCenterPage();
  }
}

function clearAssetImportInput() {
  Object.assign(state.assetCenter, {
    importText: '',
    importCodexHome: '',
    importProjectPath: '',
    importTargetTool: 'all',
    importInstallMode: 'copy',
    importIncludeCatalogPresets: false,
    importOverwrite: false,
    importAppendPrompts: false,
    importConfirmApply: false,
    importPreview: null,
    importResult: null,
    importError: '',
  });
  renderAssetCenterPage();
}

function normalizeAssetDeepLinkEventPayload(payload = {}) {
  if (typeof payload === 'string') return [payload];
  if (Array.isArray(payload)) return payload.map(String).filter(Boolean);
  if (Array.isArray(payload.urls)) return payload.urls.map(String).filter(Boolean);
  if (typeof payload.url === 'string') return [payload.url];
  if (typeof payload.text === 'string') return [payload.text];
  return [];
}

async function handleAssetDeepLinkOpened(payload = {}) {
  const urls = normalizeAssetDeepLinkEventPayload(payload);
  const url = urls.find((item) => /^(easyai|easyaiconfig|ccswitch):\/\//i.test(item.trim())) || urls[0] || '';
  if (!url.trim()) return;
  Object.assign(state.assetCenter, {
    activeTab: 'import',
    importText: url.trim(),
    importPreview: null,
    importResult: null,
    importError: '',
    deepLinkLastUrl: url.trim(),
    deepLinkLastSource: payload.source || 'desktop',
    deepLinkLastAt: Date.now(),
  });
  setPage('assets');
  renderAssetCenterPage();
  if (!state.assetCenter.index && !state.assetCenter.loading) {
    void loadAssetCenter({ force: false });
  }
  flash('已接收资产 Deep Link，正在预览', 'info');
  await previewAssetImportText(url.trim(), { syncForm: false });
}

const SECONDARY_META = {
  quick:          { sub: '选择要配置的工具，或为同一工具保存多份预设。' },
  console:        { sub: '集中监控各 CLI 工具的运行状态与异常检测结果。' },
  dashboard:      { sub: '查看各工具的模型用量、会话趋势与耗时分布。' },
  assets:         { sub: '按工具拆分可迁移资产与同步状态。' },
  providerRouter: { sub: '启动本地网关，选择主 provider 和 API Key 候选池。' },
  configEditor:   { sub: '搜索配置项，直接编辑底层配置文件。' },
  tools:          { sub: '安装、更新或卸载已接入的 AI 编程工具。' },
  tasks:          { sub: '查看当前进行中和历史的安装/更新任务。' },
  about:          { sub: '本地优先、开源透明的 AI 工具配置中心。' },
  systemSettings: { sub: '外观、语言、安装包与存储。' },
};

function syncSecondaryPanel(page, meta) {
  const eyebrow = el('secondaryEyebrow');
  const title = el('secondaryTitle');
  const sub = el('secondarySub');
  if (eyebrow) eyebrow.textContent = meta.eyebrow || '';
  if (title) title.textContent = meta.title || '';
  if (sub) sub.textContent = (SECONDARY_META[page] && SECONDARY_META[page].sub) || meta.subtitle || '';
  let matched = false;
  document.querySelectorAll('.sec-group[data-sec-for]').forEach((grp) => {
    const target = grp.dataset.secFor;
    const hit = target === page;
    if (hit) matched = true;
    if (target !== '__fallback') grp.style.display = hit ? '' : 'none';
  });
  const fallback = document.querySelector('.sec-group[data-sec-for="__fallback"]');
  if (fallback) fallback.style.display = matched ? 'none' : '';
  const fbTitle = el('secondaryFallbackTitle');
  const fbSub = el('secondaryFallbackSub');
  if (fbTitle) fbTitle.textContent = meta.title || '当前页面';
  if (fbSub) fbSub.textContent = (SECONDARY_META[page] && SECONDARY_META[page].sub) || meta.subtitle || '';
  hydrateStaticToolIcons(el('secondaryBody') || document);
}

function setPage(page = 'quick') {
  const meta = PAGE_META[page] || PAGE_META.quick;
  state.activePage = page;
  if (state.activeTool) state.toolLastPage[state.activeTool] = page;
  document.body.dataset.page = page;
  document.querySelectorAll('[data-page-target]').forEach((node) => {
    node.classList.toggle('active', node.dataset.pageTarget === page);
  });
  document.querySelectorAll('[data-page]').forEach((node) => {
    node.classList.toggle('active', node.dataset.page === page);
  });
  if (page !== 'configEditor') closeCfg3Drawer();
  if (el('pageEyebrow')) el('pageEyebrow').textContent = meta.eyebrow;
  if (el('pageTitle')) el('pageTitle').textContent = meta.title;
  if (el('pageSubtitle')) el('pageSubtitle').textContent = meta.subtitle;
  syncSecondaryPanel(page, meta);

  // Toggle action buttons
  const defaultActions = el('defaultActions');
  const configActions = el('configEditorActions');
  if (defaultActions) defaultActions.classList.toggle('hide', page === 'configEditor');
  if (configActions) configActions.classList.toggle('hide', page !== 'configEditor');
  el('secondaryThemeToggleBtn')?.classList.toggle('hide', page !== 'dashboard');
  el('themeToggleBtn')?.classList.toggle('hide', page === 'dashboard');

  // Render tasks page on navigate
  if (page === 'terminal') {
    // 终端页依赖二级栏会话列表，进入时自动展开侧栏
    document.body.classList.remove('sec-collapsed');
  } else if (page === 'systemSettings' || page === 'about') {
    document.body.classList.add('sec-collapsed');
  } else {
    try {
      document.body.classList.toggle('sec-collapsed', localStorage.getItem('ea_sec_collapsed') === '1');
    } catch (_) {}
  }
  if (page !== 'dashboard') stopDashboardAutoRefresh();
  if (page !== 'console') disposeEmbeddedTerminalInstance();
  if (page !== 'terminal' && typeof window.disposeTerminalInstances === 'function') {
    try { window.disposeTerminalInstances(); } catch (_) {}
  }
  if (page === 'terminal') {
    try {
      window.state = state;
      window.api = api;
      window.flash = flash;
      window.escapeHtml = escapeHtml;
      window.openExternalUrl = openExternalUrl;
      window.pickDirectoryPath = pickDirectoryPath;
    } catch (_) {}
    try {
      if (typeof window.renderTerminalPage === 'function') {
        Promise.resolve(window.renderTerminalPage()).catch(() => {});
      }
    } catch (_) {}
  }
  if (page === 'remote') {
    try {
      window.state = state;
      window.api = api;
      window.flash = flash;
      window.escapeHtml = escapeHtml;
      window.openExternalUrl = openExternalUrl;
    } catch (_) {}
    try {
      if (typeof window.renderRemotePage === 'function') {
        Promise.resolve(window.renderRemotePage()).catch(() => {});
      }
    } catch (_) {}
  }
  if (page === 'tasks') renderTasksPage();
  if (page === 'console') {
    renderToolConsole();
    loadEmbeddedTerminalSessions({
      preferredTool: state.consoleTool || state.activeTool || 'codex',
    }).catch((err) => console.warn('[embedded-terminal] page sync failed', err));
    if (!state.consoleRefreshing) void refreshToolConsoleData();
  }
  if (page === 'dashboard') {
    const dashboardTool = state.dashboardTool || 'codex';
    const isClaudeDashboard = dashboardTool === 'claudecode';
    const isApiDashboard = isApiDashboardTool(dashboardTool);
    const isGenericDashboard = isGenericUsageDashboardTool(dashboardTool);
    const hasCachedMetrics = hasDashboardCachedDataForTool(dashboardTool);
    if ((!hasCachedMetrics && (isApiDashboard || isGenericDashboard)) || (isClaudeDashboard && !hasClaudeDashboardData())) {
      state.dashboardLoading = true;
    }
    renderDashboardPage();
    startDashboardAutoRefresh();
    const sideP = loadDashboardSideStates();
    sideP.then(() => {
      if (state.activePage === 'dashboard') renderDashboardPage();
    });
    if (isClaudeDashboard) {
      void ensureClaudeDashboardData({ force: !hasClaudeDashboardData() });
    } else if (isApiDashboard || isGenericDashboard) {
      void refreshDashboardData({ silent: hasCachedMetrics, tool: dashboardTool });
    }
  }
  if (page === 'assets') {
    renderAssetCenterPage();
    if (!state.assetCenter.index && !state.assetCenter.loading) {
      void loadAssetCenter({ force: false });
    }
  }
  if (page === 'providerRouter') {
    renderProviderRouterPage();
    ensureProviderRouterEvents();
    fetchProviderRouterStatus().catch(() => {});
  }
  if (page === 'configEditor') {
    applyConfigEditorSearch();
    renderConfigEditorShell(getConfigEditorTool());
  }
  if (page === 'systemSettings') {
    renderSystemSettingsPage();
    if (!state.systemStorageLoading) {
      void loadSystemStorageState({ silent: true });
    }
  }
  if (page === 'tools') {
    renderToolsPage();
    void loadToolUpdates({ force: false, render: true });
    void loadCodexAppState({ render: true });
    void loadOpenCodeDesktopState({ render: true });
    void loadOpenCodeEcosystemState({ render: true });
  }
  requestAnimationFrame(() => {
    window.EasyAIConfigI18n?.apply?.(document.querySelector(`[data-page="${page}"]`));
    window.EasyAIConfigI18n?.apply?.(el('secondaryPanel') || el('secondaryBody'));
    window.EasyAIConfigI18n?.apply?.(document.querySelector('.page-head'));
  });
}

function syncAboutUpdateActions() {
  const info = state.appUpdate || {};
  const installBtn = el('aboutInstallUpdateBtn');
  const checkBtn = el('aboutCheckUpdateBtn');
  if (!installBtn || !checkBtn) return;
  const progress = state.appUpdateProgress || {};
  const progressStatus = String(progress.status || '');
  const updating = ['checking', 'downloading', 'installing'].includes(progressStatus);
  const panel = document.querySelector('.about-update-panel');
  const setButtonLabel = (button, text) => {
    const label = button.querySelector('span');
    if (label) label.textContent = text;
    else button.textContent = text;
  };
  if (panel) {
    panel.classList.toggle('is-updating', updating);
    if (updating) panel.dataset.updateStatus = progressStatus;
    else delete panel.dataset.updateStatus;
  }
  installBtn.hidden = !Boolean(info.available || progressStatus === 'downloading' || progressStatus === 'installing');
  installBtn.disabled = updating;
  checkBtn.disabled = updating;
  checkBtn.classList.toggle('about-update-btn-secondary', Boolean(info.available));
  checkBtn.classList.toggle('checking', progressStatus === 'checking');
  checkBtn.classList.toggle('is-updating', updating);
  installBtn.classList.toggle('is-updating', updating);
  setButtonLabel(checkBtn, progressStatus === 'checking' ? '检查中' : '检查更新');
  setButtonLabel(
    installBtn,
    progressStatus === 'downloading' ? '下载中' : progressStatus === 'installing' ? '安装中' : '立即更新',
  );
}

function renderAboutUpdateProgress() {
  const wrap = el('aboutUpdateProgressWrap');
  const bar = el('aboutUpdateProgressBar');
  const meta = el('aboutUpdateProgressMeta');
  if (!wrap || !bar || !meta) return;
  const progress = state.appUpdateProgress || {};
  const status = String(progress.status || '');
  const active = ['checking', 'downloading', 'installing'].includes(status);
  if (!active) {
    wrap.classList.add('hide');
    wrap.classList.remove('is-checking', 'is-downloading', 'is-installing', 'is-indeterminate');
    delete wrap.dataset.updateStatus;
    bar.style.width = '0%';
    meta.textContent = '';
    return;
  }
  const pct = Math.max(0, Math.min(100, Number(progress.percent || 0)));
  const downloaded = Number(progress.downloadedBytes || 0);
  const total = Number(progress.totalBytes || 0);
  const indeterminate = status !== 'downloading' || total <= 0;
  wrap.classList.remove('hide');
  wrap.dataset.updateStatus = status;
  wrap.classList.toggle('is-checking', status === 'checking');
  wrap.classList.toggle('is-downloading', status === 'downloading');
  wrap.classList.toggle('is-installing', status === 'installing');
  wrap.classList.toggle('is-indeterminate', indeterminate);
  bar.style.width = indeterminate ? '42%' : `${pct.toFixed(1)}%`;
  if (status === 'downloading') {
    meta.textContent = total > 0
      ? `${pct.toFixed(1)}% · ${formatBytes(downloaded)} / ${formatBytes(total)}`
      : `${formatBytes(downloaded)} · 正在下载`;
    return;
  }
  if (status === 'checking') {
    meta.textContent = '正在检查可用更新包…';
    return;
  }
  meta.textContent = '下载完成，正在安装…';
}

const APP_DOWNLOAD_BASE = 'https://download.cursorxyz.it.com';
const APP_UPDATE_FEED_URL = `${APP_DOWNLOAD_BASE}/latest.json`;

function detectDesktopUpdaterPlatform() {
  const ua = String(navigator.userAgent || '').toLowerCase();
  const platform = String(navigator.platform || '').toLowerCase();
  if (platform.includes('mac') || ua.includes('mac os')) {
    return (ua.includes('arm') || ua.includes('aarch64')) ? 'darwin-aarch64' : 'darwin-x86_64';
  }
  if (platform.includes('win') || ua.includes('windows')) return 'windows-x86_64';
  if (platform.includes('linux') || ua.includes('linux')) return 'linux-x86_64';
  return '';
}

function normalizeAppDownloadUrl(url = '') {
  const raw = String(url || '').trim();
  if (!raw) return '';
  try {
    const parsed = new URL(raw);
    const host = parsed.hostname.toLowerCase();
    if (
      host === 'download.betternanobanana.com'
      || host === 'download.cursorxyz.it.com'
      || host.endsWith('.r2.cloudflarestorage.com')
    ) {
      return `${APP_DOWNLOAD_BASE}${parsed.pathname}${parsed.search}`;
    }
  } catch (_) {
    // fall through
  }
  return raw;
}

function aboutDownloadEntriesFromFeed(feed = {}) {
  const platforms = feed.platforms && typeof feed.platforms === 'object' ? feed.platforms : {};
  const current = detectDesktopUpdaterPlatform();
  const catalog = [
    { key: 'darwin-aarch64', title: 'macOS Apple Silicon', meta: '更新包 .app.tar.gz' },
    { key: 'darwin-x86_64', title: 'macOS Intel', meta: '更新包 .app.tar.gz' },
    { key: 'windows-x86_64', title: 'Windows', meta: '安装器 .exe' },
    { key: 'linux-x86_64', title: 'Linux', meta: 'AppImage' },
    { key: 'android-arm64', title: 'Android APK', meta: '手机安装包', altKeys: ['android'] },
  ];
  const entries = [];
  for (const item of catalog) {
    const keys = [item.key, ...(item.altKeys || [])];
    let url = '';
    for (const key of keys) {
      const hit = platforms[key];
      if (hit && typeof hit === 'object' && hit.url) {
        url = normalizeAppDownloadUrl(hit.url);
        break;
      }
    }
    if (!url) continue;
    entries.push({
      ...item,
      url,
      current: item.key === current,
    });
  }
  return entries;
}

function renderAboutDownloadLinks(feed) {
  const targets = [
    { box: el('aboutDownloadLinks'), hint: el('aboutDownloadHint') },
    { box: el('sysDownloadLinks'), hint: el('sysDownloadHint') },
  ].filter((item) => item.box);
  if (!targets.length) return;

  const version = String(feed?.version || '').trim();
  const entries = aboutDownloadEntriesFromFeed(feed || {});
  const feedCard = `
    <button type="button" class="about-link-card" data-external-url="${escapeHtml(APP_UPDATE_FEED_URL)}">
      <span class="about-link-title">更新清单 latest.json</span>
      <small>桌面端 / APK 下载地址总表</small>
    </button>`;
  const emptyHint = '暂未读到安装包清单。可打开 latest.json 查看。';
  const okHint = version
    ? `当前分发版本 v${version} · ${APP_DOWNLOAD_BASE}`
    : `下载源 ${APP_DOWNLOAD_BASE}`;
  const html = entries.length
    ? entries.map((item) => `
    <button type="button" class="about-link-card${item.current ? ' is-current-platform' : ''}" data-external-url="${escapeHtml(item.url)}">
      <span class="about-link-title">${escapeHtml(item.title)}${item.current ? ' · 本机' : ''}</span>
      <small>${escapeHtml(version ? `${item.meta} · v${version}` : item.meta)}</small>
    </button>
  `).join('') + feedCard
    : feedCard;

  for (const target of targets) {
    if (target.hint) target.hint.textContent = entries.length ? okHint : emptyHint;
    target.box.innerHTML = html;
    bindAboutDownloadClicks(target.box);
  }
}

function bindAboutDownloadClicks(box) {
  if (!box || box._downloadBound) return;
  box._downloadBound = true;
  box.addEventListener('click', (event) => {
    const card = event.target.closest('[data-external-url]');
    if (!card) return;
    event.preventDefault();
    void openExternalUrl(card.getAttribute('data-external-url') || '');
  });
}

async function loadAboutDownloadFeed({ force = false } = {}) {
  const hints = [el('aboutDownloadHint'), el('sysDownloadHint')].filter(Boolean);
  if (!force && state.appDownloadFeed) {
    renderAboutDownloadLinks(state.appDownloadFeed);
    return state.appDownloadFeed;
  }
  hints.forEach((hint) => {
    hint.textContent = '正在读取更新清单…';
  });
  try {
    const res = await fetch(APP_UPDATE_FEED_URL, { cache: 'no-store' });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const feed = await res.json();
    state.appDownloadFeed = feed && typeof feed === 'object' ? feed : {};
    renderAboutDownloadLinks(state.appDownloadFeed);
    return state.appDownloadFeed;
  } catch (error) {
    const message = `读取失败：${error?.message || error}。可稍后重试或直接打开清单。`;
    hints.forEach((hint) => {
      hint.textContent = message;
    });
    renderAboutDownloadLinks({});
    return null;
  }
}

function manualAppDownloadUrl() {
  const feed = state.appDownloadFeed || {};
  const current = detectDesktopUpdaterPlatform();
  const platforms = feed.platforms && typeof feed.platforms === 'object' ? feed.platforms : {};
  const hit = current && platforms[current] && platforms[current].url
    ? normalizeAppDownloadUrl(platforms[current].url)
    : '';
  return hit || APP_UPDATE_FEED_URL;
}

function populateAboutPanel() {
  const info = state.appUpdate || {};
  const appVersion = info.currentVersion || '1.0.0';
  const progress = state.appUpdateProgress || {};
  const progressStatus = String(progress.status || '');
  const status = el('aboutUpdaterStatus');
  el('aboutAppVersion').textContent = appVersion;
  el('aboutCodexVersion').textContent = appVersion;
  if (progressStatus === 'checking') {
    status.textContent = '正在准备更新…';
    status.className = 'about-status';
  } else if (progressStatus === 'downloading') {
    const pct = Number(progress.percent || 0);
    status.textContent = `正在下载更新 ${pct.toFixed(1)}%`;
    status.className = 'about-status about-status-update';
  } else if (progressStatus === 'installing') {
    status.textContent = '正在安装更新…';
    status.className = 'about-status about-status-update';
  } else if (progressStatus === 'error') {
    const errMsg = progress.error || '更新失败';
    const isSigOrNet = /签名|signature|verify|网络|network|dns|timeout|connect/i.test(errMsg);
    if (isSigOrNet) {
      const url = escapeHtml(manualAppDownloadUrl());
      status.innerHTML = `${escapeHtml(errMsg)} <a href="${url}" target="_blank" rel="noopener" style="color:var(--accent);text-decoration:underline;margin-left:6px;white-space:nowrap">手动下载</a>`;
    } else {
      status.textContent = errMsg;
    }
    status.className = 'about-status about-status-error';
  } else if (info.available) {
    status.textContent = `可更新到 v${info.version || '-'}`;
    status.className = 'about-status about-status-update';
  } else if (info.networkBlocked) {
    status.textContent = info.statusMessage || '更新源暂时不可用，可改用下方安装包下载。';
    status.className = 'about-status about-status-error';
  } else if (info.enabled) {
    status.textContent = '已是最新';
    status.className = 'about-status about-status-ok';
  } else {
    status.textContent = '';
    status.className = 'about-status';
  }
  renderAboutUpdateProgress();
  syncAboutUpdateActions();
  el('aboutRepo').textContent = info.repository || '-';
  el('aboutEndpoint').textContent = info.endpoint || APP_UPDATE_FEED_URL;
  el('aboutPubkeyStatus').textContent = info.publicKeyConfigured ? '已配置' : '未配置';
  void loadAboutDownloadFeed();
}

function setAboutTrustOpen(open = false) {
  const dialog = el('aboutTrustDialog');
  if (!dialog) return;
  dialog.classList.toggle('hide', !open);
  document.body.classList.toggle('about-trust-open', Boolean(open));
  if (open) requestAnimationFrame(() => el('aboutTrustCloseBtn')?.focus?.());
}

function formatBytes(bytes = 0) {
  const value = Number(bytes || 0);
  if (!Number.isFinite(value) || value <= 0) return '0 B';
  const units = ['B', 'KB', 'MB', 'GB', 'TB'];
  let size = value;
  let idx = 0;
  while (size >= 1024 && idx < units.length - 1) {
    size /= 1024;
    idx += 1;
  }
  const fixed = size >= 100 || idx === 0 ? 0 : size >= 10 ? 1 : 2;
  return `${size.toFixed(fixed)} ${units[idx]}`;
}

function getUiLocalStorageUsageBytes() {
  try {
    let total = 0;
    for (let i = 0; i < localStorage.length; i += 1) {
      const key = localStorage.key(i) || '';
      const value = localStorage.getItem(key) || '';
      total += (key.length + value.length) * 2;
    }
    return total;
  } catch {
    return 0;
  }
}

function syncSystemThemeButtons() {
  const group = el('sysThemeModes');
  if (!group) return;
  group.querySelectorAll('[data-sys-theme]').forEach((button) => {
    button.classList.toggle('active', button.dataset.sysTheme === state.themePreference);
  });
}

function renderSystemStorageState() {
  const localUsage = el('sysLocalStorageUsage');
  const localUsageBytes = getUiLocalStorageUsageBytes();
  if (localUsage) {
    localUsage.textContent = formatBytes(localUsageBytes);
  }

  const localTotal = el('sysStorageLocalTotal');
  const localFiles = el('sysStorageLocalFiles');
  const toolsTotal = el('sysStorageToolsTotal');
  const toolsFiles = el('sysStorageToolsFiles');
  const payload = state.systemStorage || {};
  const entries = Array.isArray(payload.entries) ? payload.entries : [];

  const isToolEntry = (item = {}) => ['codex_home', 'claude_home', 'openclaw_home'].includes(String(item.key || ''));
  const localEntries = entries.filter((item) => !isToolEntry(item));
  const toolEntries = entries.filter((item) => isToolEntry(item));
  const localBytes = localEntries.reduce((sum, item) => sum + Number(item.bytes || 0), 0) + localUsageBytes;
  const localFileCount = localEntries.reduce((sum, item) => sum + Number(item.fileCount || 0), 0);
  const toolBytes = toolEntries.reduce((sum, item) => sum + Number(item.bytes || 0), 0);
  const toolFileCount = toolEntries.reduce((sum, item) => sum + Number(item.fileCount || 0), 0);

  if (localTotal) localTotal.textContent = state.systemStorageLoading && !entries.length ? '…' : formatBytes(localBytes);
  if (localFiles) localFiles.textContent = state.systemStorageLoading && !entries.length ? '-' : Number(localFileCount).toLocaleString('en-US');
  if (toolsTotal) toolsTotal.textContent = state.systemStorageLoading && !entries.length ? '…' : formatBytes(toolBytes);
  if (toolsFiles) toolsFiles.textContent = state.systemStorageLoading && !entries.length ? '-' : Number(toolFileCount).toLocaleString('en-US');
}

function renderSystemSettingsPage() {
  syncSystemThemeButtons();
  renderSystemStorageState();
  void loadAboutDownloadFeed();
}

async function openExternalUrl(url) {
  const target = String(url || '').trim();
  if (!target) return false;
  const result = await api('/api/open-url', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ url: target }),
  });
  if (!result?.ok) {
    window.open(target, '_blank');
  }
  return true;
}

async function loadSystemStorageState({ silent = false } = {}) {
  state.systemStorageLoading = true;
  renderSystemStorageState();
  const json = await api('/api/system/storage');
  state.systemStorageLoading = false;
  if (!json.ok) {
    if (!silent) flash(json.error || '读取存储占用失败', 'error');
    renderSystemStorageState();
    return { ok: false, error: json.error || '读取失败' };
  }
  state.systemStorage = json.data || {};
  renderSystemStorageState();
  return { ok: true, data: state.systemStorage };
}

async function cleanupSystemStorage({ clearCache = true, clearBackups = false } = {}) {
  const json = await api('/api/system/cleanup', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ clearCache, clearBackups }),
  });
  if (!json.ok) return { ok: false, error: json.error || '清理失败' };
  if (json.data?.state) state.systemStorage = json.data.state;
  renderSystemStorageState();
  return { ok: true, data: json.data || {} };
}

async function uninstallToolForSystemSettings(toolId) {
  const endpointMap = {
    codex: '/api/codex/uninstall',
    claudecode: '/api/claudecode/uninstall',
    opencode: '/api/opencode/uninstall',
    openclaw: '/api/openclaw/uninstall',
  };
  const labelMap = {
    codex: 'Codex',
    claudecode: 'Claude Code',
    opencode: 'OpenCode',
    openclaw: 'OpenClaw',
  };
  const endpoint = endpointMap[toolId];
  if (!endpoint) return { ok: false, error: '未知工具' };
  const json = await api(endpoint, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: toolId === 'openclaw' ? JSON.stringify({ purge: false }) : undefined,
    timeoutMs: 120000,
  });
  if (!json.ok || json.data?.ok === false) {
    return { ok: false, error: json.error || json.data?.stderr || `${labelMap[toolId]} 卸载失败` };
  }
  return { ok: true, label: labelMap[toolId] || toolId };
}

function openSystemUninstallEntry() {
  const platform = String(navigator.platform || '').toLowerCase();
  if (platform.includes('mac')) return openExternalUrl('file:///Applications');
  if (platform.includes('win')) return openExternalUrl('ms-settings:appsfeatures');
  return openExternalUrl('https://github.com/lmk1010/EasyAIConfig');
}

function clearUiStorageCache() {
  const keys = [];
  for (let i = 0; i < localStorage.length; i += 1) {
    const key = localStorage.key(i) || '';
    if (key.startsWith('easyaiconfig_') && key !== 'easyaiconfig_theme') {
      keys.push(key);
    }
  }
  keys.forEach((key) => localStorage.removeItem(key));
  renderSystemStorageState();
  flash(`已清理 ${keys.length} 项界面缓存`, 'success');
}

function setAboutOpen(open) {
  const panel = el('aboutView');
  if (!panel) return;
  clearTimeout(state.aboutTimer);
  state.aboutOpen = open;

  if (open) {
    populateAboutPanel();
    panel.classList.remove('hide');
    panel.setAttribute('aria-hidden', 'false');
    requestAnimationFrame(() => panel.classList.add('open'));
    document.body.classList.add('about-open');
    return;
  }

  panel.classList.remove('open');
  panel.setAttribute('aria-hidden', 'true');
  document.body.classList.remove('about-open');
  state.aboutTimer = setTimeout(() => panel.classList.add('hide'), 180);
}

function setAdvancedOpen(open) {
  const panel = el('advancedView');
  if (!panel) return;

  clearTimeout(state.advancedTimer);
  state.advancedOpen = open;

  if (open) {
    panel.classList.remove('hide');
    panel.setAttribute('aria-hidden', 'false');
    requestAnimationFrame(() => panel.classList.add('open'));
    document.body.classList.add('advanced-open');
    return;
  }

  panel.classList.remove('open');
  panel.setAttribute('aria-hidden', 'true');
  document.body.classList.remove('advanced-open');
  state.advancedTimer = setTimeout(() => panel.classList.add('hide'), 180);
}

