function buildCfgGrid(toolId) {
  const grid = document.getElementById('cfgGrid');
  if (!grid) return;
  const sections = getCfgSectionsForTool(toolId);
  if (!sections.length) {
    grid.classList.add('hide');
    return;
  }
  sections.forEach((sec, idx) => {
    if (!sec.id) sec.id = `cfgSec_${toolId}_${idx}`;
    // 给 section 一次性挂上"关于这一节"的提示卡，子页打开时不会再空荡荡
    const summary = sec.querySelector(':scope > summary.cfg-section-header');
    const headingTxt = (summary?.textContent || '').replace(/\s+/g, ' ').trim().split(/[·：:|]/)[0].trim() || '配置';
    const tip = CFG_SECTION_TIPS[headingTxt];
    if (tip && !sec.querySelector(':scope > .cfg-section-body > .cfg-tip-block')) {
      const body = sec.querySelector(':scope > .cfg-section-body');
      if (body) {
        const aside = document.createElement('aside');
        aside.className = 'cfg-tip-block';
        aside.innerHTML = `
          <div class="cfg-tip-head">
            <svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><circle cx="8" cy="8" r="6"/><path d="M8 6v3M8 4.5h.01"/></svg>
            关于 ${escapeHtml(headingTxt)}
          </div>
          <p class="cfg-tip-intro">${tip.intro}</p>
          <ul class="cfg-tip-list">
            ${tip.bullets.map((b) => `<li>${b}</li>`).join('')}
          </ul>`;
        body.appendChild(aside);
      }
    }
  });

  // 顶部 hero：当前关键值速览（模型 / provider / 推理强度 / 启用开关数）
  const heroHtml = buildCfgHero(toolId);

  const cards = sections.map((sec) => {
    const summary = sec.querySelector(':scope > summary.cfg-section-header');
    const text = (summary?.textContent || '').replace(/\s+/g, ' ').trim();
    const heading = text.split(/[·：:|]/)[0].trim() || '配置';
    const icon = CFG_CARD_ICONS[heading] || CFG_CARD_FALLBACK;
    // 真正在 section 里去数已填写的字段值 + 启用的开关数（之前都是 0 也写"可配置"）
    const checks = sec.querySelectorAll('input[type="checkbox"]');
    const enabledCount = Array.from(checks).filter((c) => c.checked).length;
    const inputs = sec.querySelectorAll('input[type="text"], input[type="number"], input[type="url"], select, textarea');
    const filledCount = Array.from(inputs).filter((i) => {
      const v = (i.value || '').toString().trim();
      return v && v !== '0';
    }).length;
    const subParts = [];
    if (inputs.length) subParts.push(`<span class="cfg-card-pill">${filledCount}/${inputs.length} 项已填</span>`);
    if (checks.length) subParts.push(`<span class="cfg-card-pill ${enabledCount > 0 ? 'is-on' : ''}">${enabledCount}/${checks.length} 开关启用</span>`);
    if (!subParts.length) subParts.push('<span class="cfg-card-pill">可配置</span>');
    return `
      <div role="button" tabindex="0" class="cfg-card" data-cfg-card="${sec.id}">
        <span class="cfg-card-icon">${icon}</span>
        <span class="cfg-card-body">
          <span class="cfg-card-title">${escapeHtml(heading)}</span>
          <span class="cfg-card-pills">${subParts.join('')}</span>
        </span>
        <span class="cfg-card-arrow">
          <svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M6 3l5 5-5 5"/></svg>
        </span>
      </div>`;
  }).join('');

  // 底部快捷操作：备份 / 重置 / 检查 / 商店
  const footerHtml = buildCfgQuickActions(toolId);

  grid.innerHTML = `
    ${heroHtml}
    <div class="cfg-grid-cards">${cards}</div>
    ${footerHtml}
  `;
  grid.classList.remove('hide');
  exitCfgSubpage();
}

function buildCfgHero(toolId) {
  const esc = escapeHtml;
  // 同步页面标题区
  const titleEl = document.getElementById('cfgPageTool');
  if (titleEl) titleEl.textContent = cfgToolLabel(toolId) || 'Codex';
  // 计算每个 tool 的元信息：配置文件名 + 完整大小（如果能拿到）
  if (toolId === 'codex') {
    const cfg = state.current?.config || {};
    const summary = state.current?.summary || {};
    const model = summary.model || cfg.model || '—';
    const provider = cfg.model_provider || '—';
    const effort = cfg.model_reasoning_effort || 'medium';
    const codexHome = state.current?.codexHome || '~/.codex';
    // 统计：N 项已配置 / M 开关启用
    const totalInputs = document.querySelectorAll('.config-editor-main[data-tool-editor="codex"] input[type="text"], .config-editor-main[data-tool-editor="codex"] input[type="number"], .config-editor-main[data-tool-editor="codex"] input[type="url"], .config-editor-main[data-tool-editor="codex"] select, .config-editor-main[data-tool-editor="codex"] textarea').length;
    const filledInputs = Array.from(document.querySelectorAll('.config-editor-main[data-tool-editor="codex"] input[type="text"], .config-editor-main[data-tool-editor="codex"] input[type="number"], .config-editor-main[data-tool-editor="codex"] input[type="url"], .config-editor-main[data-tool-editor="codex"] select, .config-editor-main[data-tool-editor="codex"] textarea')).filter((i) => (i.value || '').toString().trim()).length;
    const totalChecks = document.querySelectorAll('.config-editor-main[data-tool-editor="codex"] input[type="checkbox"]').length;
    const onChecks = Array.from(document.querySelectorAll('.config-editor-main[data-tool-editor="codex"] input[type="checkbox"]')).filter((c) => c.checked).length;
    const metaEl = document.getElementById('cfgPageMeta');
    if (metaEl) {
      metaEl.innerHTML = `
        <span class="cfg-page-pill"><em>${esc(String(filledInputs))}/${esc(String(totalInputs))}</em>已配置</span>
        <span class="cfg-page-pill ${onChecks > 0 ? 'is-on' : ''}"><em>${esc(String(onChecks))}/${esc(String(totalChecks))}</em>开关启用</span>
      `;
    }
    return `
      <div class="cfg-hero">
        <div class="cfg-hero-eyebrow">CURRENT CODEX</div>
        <div class="cfg-hero-grid">
          <div class="cfg-hero-item">
            <span>默认模型</span>
            <strong>${esc(model)}</strong>
          </div>
          <div class="cfg-hero-divider"></div>
          <div class="cfg-hero-item">
            <span>默认 Provider</span>
            <strong>${esc(provider)}</strong>
          </div>
          <div class="cfg-hero-divider"></div>
          <div class="cfg-hero-item">
            <span>推理强度</span>
            <strong class="cfg-hero-effort">${esc(effort)}</strong>
          </div>
          <div class="cfg-hero-divider"></div>
          <div class="cfg-hero-item">
            <span>CODEX_HOME</span>
            <code>${esc(codexHome)}</code>
          </div>
        </div>
      </div>`;
  }
  const metaEl = document.getElementById('cfgPageMeta');
  if (metaEl) metaEl.innerHTML = '';
  return `
    <div class="cfg-hero">
      <div class="cfg-hero-eyebrow">CURRENT ${esc((toolId || '').toUpperCase())}</div>
      <div class="cfg-hero-grid">
        <div class="cfg-hero-item"><span>工具</span><strong>${esc(cfgToolLabel(toolId))}</strong></div>
      </div>
    </div>`;
}

function buildCfgQuickActions(toolId) {
  // 备份 / 重置 / 校验 / 商店 — 都是 hub 上现有 button 的 alias
  const actions = [
    { id: 'cfgQuickValidate',  label: '校验配置', icon: '<svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M14 3l-8.5 8.5L2 8"/></svg>' },
    { id: 'cfgQuickStore',     label: '配置商店', icon: '<svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M2 6l6-4 6 4v8a1 1 0 0 1-1 1H3a1 1 0 0 1-1-1z"/><path d="M5 13V9h6v4"/></svg>' },
    { id: 'cfgQuickRaw',       label: '原始文件', icon: '<svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M5 3L1 8l4 5M11 3l4 5-4 5"/></svg>' },
    { id: 'cfgQuickReset',     label: '重置当前',  icon: '<svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M1 3v4h4M14.5 9a6 6 0 0 1-11.2 2.5M1.5 7a6 6 0 0 1 11.2-2.5"/></svg>' },
  ];
  return `
    <div class="cfg-quick">
      <div class="cfg-quick-head">快捷操作</div>
      <div class="cfg-quick-row">
        ${actions.map((a) => `
          <button type="button" class="cfg-quick-btn" data-cfg-quick="${a.id}">
            <span class="cfg-quick-icon">${a.icon}</span>
            <span class="cfg-quick-label">${escapeHtml(a.label)}</span>
          </button>`).join('')}
      </div>
    </div>`;
}

function enterCfgSubpage(sectionId) {
  const sec = document.getElementById(sectionId);
  if (!sec) return;
  // 主动 blur 当前焦点，避免点完卡片回到网格态时仍带蓝边
  if (document.activeElement instanceof HTMLElement) document.activeElement.blur();
  const tool = sec.closest('.config-editor-main')?.dataset?.toolEditor || '';
  // 同 tool 下所有 section：只让点中的那一节显示并展开，其他全藏
  const peers = sec.parentElement?.querySelectorAll(':scope > details.cfg-section') || [];
  peers.forEach((p) => {
    p.open = (p === sec);
    p.classList.toggle('cfg-sec-active', p === sec);
    p.classList.toggle('cfg-sec-hidden', p !== sec);
  });
  document.getElementById('cfgGrid')?.classList.add('hide');
  const subhead = document.getElementById('cfgSubhead');
  const crumb = document.getElementById('cfgSubCrumb');
  if (subhead) subhead.classList.remove('hide');
  if (crumb) {
    const head = sec.querySelector(':scope > summary.cfg-section-header');
    const title = (head?.textContent || '').replace(/\s+/g, ' ').trim().split(/[·：:|]/)[0].trim() || '配置';
    crumb.innerHTML = `${escapeHtml(cfgToolLabel(tool))} <em>/</em> <strong>${escapeHtml(title)}</strong>`;
  }
  sec.scrollIntoView({ behavior: 'smooth', block: 'start' });
}

function exitCfgSubpage() {
  // 默认网格态：所有 section 一律隐藏 + 折叠；显示卡片网格、藏返回 head
  document.querySelectorAll('.config-editor-main details.cfg-section').forEach((p) => {
    p.classList.add('cfg-sec-hidden');
    p.classList.remove('cfg-sec-active');
    p.open = false;
  });
  document.getElementById('cfgGrid')?.classList.remove('hide');
  document.getElementById('cfgSubhead')?.classList.add('hide');
  if (document.activeElement instanceof HTMLElement) document.activeElement.blur();
}

// 卡片 div[role=button] 支持键盘触发
document.addEventListener('keydown', (e) => {
  if (e.key !== 'Enter' && e.key !== ' ') return;
  const target = e.target instanceof Element ? e.target : null;
  const card = target?.closest('[data-cfg-card]');
  if (card) {
    e.preventDefault();
    enterCfgSubpage(card.dataset.cfgCard);
  }
});

// 事件代理：卡片点击 + 返回按钮 + 快捷操作转发
document.addEventListener('click', (e) => {
  const target = e.target instanceof Element ? e.target : null;
  if (!target) return;
  const card = target.closest('[data-cfg-card]');
  if (card) {
    enterCfgSubpage(card.dataset.cfgCard);
    return;
  }
  if (target.closest('#cfgBackBtn')) {
    exitCfgSubpage();
    return;
  }
  const quick = target.closest('[data-cfg-quick]');
  if (quick) {
    const aliasMap = {
      cfgQuickValidate: 'validateConfigBtn',
      cfgQuickStore:    'openConfigStoreBtn',
      cfgQuickRaw:      null, // 直接切到原始文件视图
      cfgQuickReset:    'resetConfigEditorBtn',
    };
    const id = quick.dataset.cfgQuick;
    if (id === 'cfgQuickRaw' && typeof switchConfigEditorView === 'function') {
      switchConfigEditorView('code');
      return;
    }
    const targetId = aliasMap[id];
    const orig = targetId ? document.getElementById(targetId) : null;
    if (orig) {
      orig.click();
    } else {
      flash(`暂不支持：${id}`, 'warning');
    }
  }
});

function getConfigEditorTool() {
  return normalizeConfigEditorTool(state.configEditorTool);
}

async function setConfigEditorOpen(open, preferredTool = '') {
  state.configEditorOpen = open;
  if (open) {
    const nextTool = normalizeConfigEditorTool(preferredTool || state.activeTool || state.configEditorTool);
    if (flashTemporarilyDisabledTool(nextTool)) {
      state.configEditorOpen = false;
      return false;
    }
    state.configEditorTool = nextTool;
    if (getConfigEditorTool() === 'openclaw' && !state.openclawState) {
      await loadOpenClawQuickState();
    }
    if (getConfigEditorTool() === 'claudecode' && !state.claudeCodeState) {
      await loadClaudeCodeQuickState();
    }
    if (getConfigEditorTool() === 'opencode' && !state.opencodeState) {
      await loadOpenCodeQuickState();
    }
    if (getConfigEditorTool() === 'claudecode') {
      state.claudeProviderDetailKey = '';
    }
    populateConfigEditor();
    setPage('configEditor');
    if (window.refreshCustomSelects) window.refreshCustomSelects();
    refreshRawCodeEditors();
    return true;
  } else {
    setPage('quick');
    return true;
  }
}

function configValue(path, fallback = '') {
  return path.split('.').reduce((obj, key) => (obj && obj[key] !== undefined ? obj[key] : undefined), state.current?.config) ?? fallback;
}

function hasConfigValue(path) {
  return path.split('.').reduce((obj, key) => (obj && obj[key] !== undefined ? obj[key] : undefined), state.current?.config) !== undefined;
}

function setSelectValuePreservingUnknown(selectId, value, label = '当前配置') {
  const select = el(selectId);
  if (!select) return;
  const text = value === null || value === undefined ? '' : String(value);
  Array.from(select.options)
    .filter((option) => option.dataset.dynamicUnknown === 'true')
    .forEach((option) => option.remove());
  if (text && !Array.from(select.options).some((option) => option.value === text)) {
    const option = document.createElement('option');
    option.value = text;
    option.textContent = `${text} (${label})`;
    option.dataset.dynamicUnknown = 'true';
    select.appendChild(option);
  }
  select.value = text;
}

function setBooleanSelectValue(selectId, value) {
  if (value === true) {
    setSelectValuePreservingUnknown(selectId, 'true');
  } else if (value === false) {
    setSelectValuePreservingUnknown(selectId, 'false');
  } else {
    setSelectValuePreservingUnknown(selectId, '');
  }
}

function readBooleanSelectValue(selectId) {
  const value = el(selectId)?.value || '';
  if (value === 'true') return true;
  if (value === 'false') return false;
  return null;
}

function setCheckboxFromConfig(inputId, path, defaultValue = false) {
  const input = el(inputId);
  if (!input) return;
  input.checked = Boolean(hasConfigValue(path) ? configValue(path, defaultValue) : defaultValue);
}

function checkboxPatchValue(inputId, path, defaultValue = false) {
  const input = el(inputId);
  if (!input) return null;
  const checked = Boolean(input.checked);
  if (!hasConfigValue(path) && checked === Boolean(defaultValue)) return null;
  return checked;
}

function compactPromptEnabled(value = configValue('compact_prompt', null)) {
  if (value === null || value === undefined || value === '') return true;
  if (typeof value === 'string') return value.trim().toLowerCase() !== 'false';
  return Boolean(value);
}

function buildCompactPromptSetting() {
  if (!el('cfgCompactPromptCheck').checked) return 'false';

  const currentValue = configValue('compact_prompt', null);
  if (typeof currentValue === 'string' && currentValue.trim() && currentValue.trim().toLowerCase() !== 'false') {
    return currentValue;
  }

  return null;
}

const CODEX_CONTEXT_EFFECTIVE_RATIO = 0.95;
const CODEX_AUTO_COMPACT_LIMIT_RATIO = 0.9;
const CODEX_APPROVAL_POLICY_VALUES = new Set(['untrusted', 'on-request', 'never']);
const CODEX_SANDBOX_MODE_VALUES = new Set(['read-only', 'workspace-write', 'danger-full-access']);
const CODEX_REASONING_EFFORT_VALUES = new Set(['none', 'minimal', 'low', 'medium', 'high', 'xhigh', 'max', 'ultra']);
const CODEX_REASONING_SUMMARY_VALUES = new Set(['auto', 'concise', 'detailed', 'none']);
const CODEX_VERBOSITY_VALUES = new Set(['low', 'medium', 'high']);
const CODEX_SERVICE_TIER_VALUES = new Set(['fast', 'flex']);
const CODEX_PERSONALITY_VALUES = new Set(['none', 'friendly', 'pragmatic']);
const CODEX_WEB_SEARCH_VALUES = new Set(['cached', 'live', 'disabled']);
const CODEX_APPROVALS_REVIEWER_VALUES = new Set(['user', 'auto_review']);

function getCodexContextWindowForUi() {
  return getConfigNumberValue('cfgContextWindowInput') || getCodexSelectedModelContextCap() || 272000;
}

function calcCodexEffectiveContextWindow(contextWindow) {
  return Math.round(Number(contextWindow || 0) * CODEX_CONTEXT_EFFECTIVE_RATIO);
}

function calcCodexAutoCompactCap(contextWindow) {
  return Math.round(Number(contextWindow || 0) * CODEX_AUTO_COMPACT_LIMIT_RATIO);
}

const CONFIG_NUMBER_FIELDS = {
  cfgContextWindowInput: {
    rangeId: 'cfgContextWindowRange',
    resetId: 'cfgContextWindowResetBtn',
    hintId: 'cfgContextWindowHint',
    min: 32000,
    max: 1048576,
    step: 1000,
    defaultValue: () => getCodexSelectedModelContextCap() || 272000,
    defaultPlaceholder: () => {
      const modelCap = getCodexSelectedModelContextCap();
      const model = getCodexSelectedModelValue();
      if (modelCap) return `默认 ${modelCap.toLocaleString('en-US')}（${model || '当前模型'} 上限）`;
      return '默认 272000';
    },
    hint: (value, empty) => {
      const modelCap = getCodexSelectedModelContextCap();
      const model = getCodexSelectedModelValue();
      const effective = calcCodexEffectiveContextWindow(value);
      const valueText = Number(value || 0).toLocaleString('en-US');
      const effectiveText = Number(effective || 0).toLocaleString('en-US');
      if (modelCap) {
        const capText = Number(modelCap).toLocaleString('en-US');
        return empty
          ? `${model || '当前模型'} 最大上下文 ${capText}；Codex 实际可用约 95%（≈ ${effectiveText}）。`
          : `当前设置 ${valueText}；模型上限 ${capText}，Codex 实际可用约 ${effectiveText} (95%)`;
      }
      return empty
        ? `拖动滑杆快速调整，也可直接输入数字。Codex 实际可用约为设置值的 95%（≈ ${effectiveText}）。`
        : `当前设置 ${valueText}；Codex 实际可用约 ${effectiveText} (95%)`;
    },
  },
  cfgCompactLimitInput: {
    rangeId: 'cfgCompactLimitRange',
    resetId: 'cfgCompactLimitResetBtn',
    hintId: 'cfgCompactLimitHint',
    min: 16000,
    max: 1048576,
    step: 1000,
    defaultValue: () => calcCodexAutoCompactCap(getCodexContextWindowForUi()),
    defaultPlaceholder: () => {
      const contextWindow = getCodexContextWindowForUi();
      const compactCap = calcCodexAutoCompactCap(contextWindow);
      const effective = calcCodexEffectiveContextWindow(contextWindow);
      return `默认 上下文90% ≈ ${compactCap}（有效窗口95%≈${effective}）`;
    },
    hint: (value, empty) => {
      const contextWindow = getCodexContextWindowForUi();
      const compactCap = calcCodexAutoCompactCap(contextWindow);
      const effective = calcCodexEffectiveContextWindow(contextWindow);
      return empty
        ? `默认使用上下文 90%（上限≈ ${compactCap}），有效窗口约 ${effective} (95%)。`
        : `当前设置 ${value}；建议不高于 ${compactCap}（上下文90%）`;
    },
  },
  cfgToolLimitInput: {
    rangeId: 'cfgToolLimitRange',
    resetId: 'cfgToolLimitResetBtn',
    hintId: 'cfgToolLimitHint',
    min: 1024,
    max: 65536,
    step: 512,
    defaultValue: () => 8192,
    defaultPlaceholder: () => '默认 无限制',
    hint: (value, empty) => empty ? '留空表示不限制；拖动后会写入具体上限。' : `当前设置 ${value}`,
  },
};

function sanitizeNumericText(value) {
  return String(value || '').replace(/[^\d]/g, '');
}

function getConfigNumberValue(inputId) {
  const input = el(inputId);
  if (!input) return null;
  const clean = sanitizeNumericText(input.value);
  if (!clean) return null;
  const parsed = Number(clean);
  return Number.isFinite(parsed) ? parsed : null;
}

function clampConfigNumber(value, spec) {
  return Math.min(spec.max, Math.max(spec.min, value));
}

function syncConfigNumberField(inputId, source = 'init') {
  const spec = CONFIG_NUMBER_FIELDS[inputId];
  if (!spec) return;

  const input = el(inputId);
  const range = el(spec.rangeId);
  const hint = el(spec.hintId);
  if (range && !range.dataset.baseMax) {
    range.dataset.baseMax = String(range.max || spec.max);
  }
  if (inputId === 'cfgContextWindowInput') {
    const modelCap = getCodexSelectedModelContextCap();
    const baseMax = Number(range.dataset.baseMax || spec.max);
    range.max = String(Math.max(spec.min, modelCap || baseMax));
  }
  if (inputId === 'cfgCompactLimitInput') {
    const contextLimit = getCodexContextWindowForUi();
    const compactCap = calcCodexAutoCompactCap(contextLimit);
    range.max = String(Math.max(spec.min, compactCap));
  }
  const runtimeSpec = {
    ...spec,
    min: Number(range.min || spec.min),
    max: Number(range.max || spec.max),
  };
  const defaultValue = clampConfigNumber(spec.defaultValue(), runtimeSpec);

  input.placeholder = spec.defaultPlaceholder();

  if (source === 'range') {
    input.value = String(range.value);
  } else if (source === 'input') {
    const clean = sanitizeNumericText(input.value);
    input.value = clean;
    if (clean) {
      range.value = String(clampConfigNumber(Number(clean), runtimeSpec));
    }
  }

  const currentValue = getConfigNumberValue(inputId);
  const isEmpty = currentValue === null;
  const nextValue = isEmpty ? defaultValue : clampConfigNumber(currentValue, runtimeSpec);
  if (!isEmpty && currentValue !== nextValue) {
    input.value = String(nextValue);
  }
  range.value = String(nextValue);
  updateRangeFill(range);
  if (hint) {
    hint.textContent = spec.hint(nextValue, isEmpty);
  }
}

function updateRangeFill(range) {
  if (!range) return;
  const min = Number(range.min) || 0;
  const max = Number(range.max) || 100;
  const val = Number(range.value) || 0;
  const pct = max === min ? 0 : ((val - min) / (max - min)) * 100;
  const safePct = Math.max(0, Math.min(100, pct));
  range.style.setProperty('--range-progress', `${safePct}%`);
}

function refreshConfigNumberFields() {
  Object.keys(CONFIG_NUMBER_FIELDS).forEach((inputId) => syncConfigNumberField(inputId, 'refresh'));
}

function applySqliteHomePreset(mode = 'default') {
  const input = el('cfgSqliteHomeInput');
  if (!input) return;
  if (mode === 'default') {
    input.value = '';
    return;
  }
  input.value = el('codexHomeInput').value.trim() || state.current?.codexHome || '~/.codex';
}

async function pickDirectoryPath(targetInputId, { title = '选择目录' } = {}) {
  if (!tauriInvoke) {
    flash('Web 模式暂不支持原生目录选择，请手动输入路径', 'error');
    return;
  }

  const target = el(targetInputId);
  if (!target) return;

  const initialPath = target.value.trim() || el('codexHomeInput').value.trim() || state.current?.codexHome || '';
  const json = await api('/api/path/pick-directory', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ title, initialPath }),
  });
  if (!json.ok) {
    flash(json.error || '打开目录选择器失败', 'error');
    return;
  }
  if (!json.data?.selected) return;
  target.value = json.data.path || '';
}

function openCfg3Drawer() {
  const drawer = document.getElementById('cfg3Drawer');
  const scrim = document.getElementById('cfg3DrawerScrim');
  if (!drawer) return;
  drawer.classList.add('open');
  if (scrim) scrim.classList.remove('hide');
  document.body.classList.add('cfg3-drawer-active');
}
function closeCfg3Drawer() {
  const drawer = document.getElementById('cfg3Drawer');
  const scrim = document.getElementById('cfg3DrawerScrim');
  if (!drawer) return;
  drawer.classList.remove('open');
  if (scrim) scrim.classList.add('hide');
  document.body.classList.remove('cfg3-drawer-active');
}
window.openCfg3Drawer = openCfg3Drawer;
window.closeCfg3Drawer = closeCfg3Drawer;

