/* ── Window drag support ── */
(function initWindowDrag() {
  // Try multiple API access paths for Tauri v2
  const appWindow =
    window.__TAURI__?.window?.getCurrentWindow?.() ||
    window.__TAURI__?.window?.Window?.getCurrent?.() ||
    null;

  if (!appWindow || typeof appWindow.startDragging !== 'function') {
    console.log('[drag] Tauri window API not available, skip drag init');
    return;
  }

  console.log('[drag] Tauri window API found, initializing drag regions');

  const INTERACTIVE_TAGS = new Set(['BUTTON', 'INPUT', 'SELECT', 'TEXTAREA', 'A', 'LABEL']);
  const INTERACTIVE_CLASSES = ['nav-item', 'badge', 'ghost-btn', 'subtle-btn', 'tiny-btn', 'tiny-icon-btn', 'chip', 'provider-option'];

  function isInteractive(target) {
    let node = target;
    while (node && node !== document.body) {
      if (INTERACTIVE_TAGS.has(node.tagName)) return true;
      if (node.classList) {
        for (const cls of INTERACTIVE_CLASSES) {
          if (node.classList.contains(cls)) return true;
        }
      }
      if (node.getAttribute('role') === 'button') return true;
      if (node.hasAttribute('data-load-provider')) return true;
      if (node.hasAttribute('data-load-claude-provider')) return true;
      node = node.parentElement;
    }
    return false;
  }

  function handleDrag(e) {
    if (e.button !== 0) return;
    if (isInteractive(e.target)) return;
    e.preventDefault();
    appWindow.startDragging();
  }

  // Attach to all explicit drag regions
  document.querySelectorAll('[data-tauri-drag-region]').forEach((region) => {
    region.addEventListener('mousedown', handleDrag);
  });

  // Also listen on the entire document for top-area drags (top 48px)
  document.addEventListener('mousedown', (e) => {
    if (e.button !== 0) return;
    if (e.clientY > 48) return;
    if (isInteractive(e.target)) return;
    e.preventDefault();
    appWindow.startDragging();
  });
})();

/* ── Custom Select Dropdown ── */
(function initCustomSelects() {
  function buildCustomSelect(selectEl) {
    const wrap = selectEl.closest('.select-wrap');
    if (!wrap) return;
    // Skip if already enhanced
    if (wrap.querySelector('.custom-select-trigger')) return;

    const container = document.createElement('div');
    container.className = 'custom-select';

    // Move select inside container
    wrap.parentNode.insertBefore(container, wrap);
    container.appendChild(wrap);
    // Hide the .select-wrap (we keep it for the hidden select)
    wrap.style.position = 'absolute';
    wrap.style.opacity = '0';
    wrap.style.width = '0';
    wrap.style.height = '0';
    wrap.style.overflow = 'hidden';
    wrap.style.pointerEvents = 'none';

    // Trigger button
    const trigger = document.createElement('div');
    trigger.className = 'custom-select-trigger';
    trigger.innerHTML = `<span class="cs-value"></span><span class="cs-arrow">▾</span>`;
    container.insertBefore(trigger, wrap);

    // Dropdown panel
    const dropdown = document.createElement('div');
    dropdown.className = 'custom-select-dropdown';
    container.appendChild(dropdown);

    function renderOptions() {
      const opts = Array.from(selectEl.options);
      const disabled = Boolean(selectEl.disabled);
      container.classList.toggle('disabled', disabled);
      trigger.setAttribute('aria-disabled', disabled ? 'true' : 'false');
      if (disabled) container.classList.remove('open');
      dropdown.innerHTML = opts.map((opt, i) => {
        const sel = selectEl.selectedIndex === i ? ' selected' : '';
        return `<div class="custom-select-option${sel}" data-value="${opt.value}" data-index="${i}">${opt.textContent}</div>`;
      }).join('');

      // Update trigger text
      const selectedOpt = opts[selectEl.selectedIndex];
      const valSpan = trigger.querySelector('.cs-value');
      if (selectedOpt) {
        valSpan.textContent = selectedOpt.textContent;
        valSpan.classList.toggle('placeholder', selectEl.dataset.emptyPlaceholder === 'true' && !selectedOpt.value);
      }
    }

    renderOptions();

    // Toggle open
    trigger.addEventListener('click', (e) => {
      e.stopPropagation();
      if (selectEl.disabled) return;
      const wasOpen = container.classList.contains('open');
      closeAllCustomSelects();
      if (!wasOpen) {
        container.classList.add('open');
        renderOptions(); // refresh options
      }
    });

    // Option click
    dropdown.addEventListener('click', (e) => {
      if (selectEl.disabled) return;
      const opt = e.target.closest('.custom-select-option');
      if (!opt) return;
      selectEl.value = opt.dataset.value;
      selectEl.dispatchEvent(new Event('change', { bubbles: true }));
      container.classList.remove('open');
      renderOptions();
    });

    // Watch for programmatic changes to the select
    const observer = new MutationObserver(() => renderOptions());
    observer.observe(selectEl, { childList: true, subtree: true, attributes: true });

    // Store ref for later re-render
    selectEl._customSelect = { renderOptions, container };
  }

  function closeAllCustomSelects() {
    document.querySelectorAll('.custom-select.open').forEach(cs => cs.classList.remove('open'));
  }

  // Close on click outside
  document.addEventListener('click', (e) => {
    if (!e.target.closest('.custom-select')) {
      closeAllCustomSelects();
    }
  });

  // Close on Escape
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') closeAllCustomSelects();
  });

  // Initialize all existing selects inside .select-wrap
  document.querySelectorAll('.select-wrap > select').forEach(buildCustomSelect);

  // Expose for dynamic selects
  window.initCustomSelect = buildCustomSelect;
  window.refreshCustomSelects = function () {
    document.querySelectorAll('.select-wrap > select').forEach(sel => {
      if (sel._customSelect) {
        sel._customSelect.renderOptions();
      } else {
        buildCustomSelect(sel);
      }
    });
  };
})();

/* ══════════════════════════════════════════════════════════════════════════
   CONNECTION HUB — render + wiring.
   Reuses existing state + quickSwitchXxxProvider() functions.
   ══════════════════════════════════════════════════════════════════════════ */
(function connectionHub() {
  'use strict';

  const TOOL_LABELS = {
    codex: 'Codex',
    claudecode: 'Claude Code',
    opencode: 'OpenCode',
    openclaw: 'OpenClaw',
  };
  const LAUNCH_LABELS = {
    codex: '启动 Codex',
    claudecode: '启动 Claude Code',
    opencode: '启动 OpenCode',
    openclaw: '启动 OpenClaw',
  };

  function safeEscape(v) {
    if (typeof escapeHtml === 'function') return escapeHtml(v);
    return String(v == null ? '' : v).replace(/[&<>"']/g, (c) => ({
      '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
    }[c]));
  }

  function hubState() {
    // `state` is the module-level object declared at the top of app.js; accessible via closure.
    if (typeof state === 'undefined' || !state) return null;
    if (typeof state.chSearch !== 'string') state.chSearch = '';
    if (typeof state.chFilter !== 'string') state.chFilter = 'all';
    return state;
  }

  function isConnectionHubLocalRouterRow(row) {
    if (!row || row.tool !== 'codex') return false;
    if (String(row.key || '').trim().toLowerCase() === PROVIDER_ROUTER_CLIENT_PROVIDER_KEY) return true;
    if (typeof isLoopbackHttpEndpoint === 'function' && isLoopbackHttpEndpoint(row.baseUrl || '')) return true;
    return false;
  }

  // ── Provider row model (tool-agnostic) ──────────────────────────────
  function buildProviderRows(tool) {
    const s = hubState();
    if (!s) return [];

    if (tool === 'codex') {
      if (typeof isCodexInstalled === 'function' && !isCodexInstalled()) return [];
      const providers = Array.isArray(s.current?.providers) ? s.current.providers : [];
      const login = s.current?.login || {};
      const health = s.providerHealth || {};
      // Hide template / placeholder providers that don't have a real key set
      // — they clutter the list as "缺 KEY" ghost rows. Keep if active, keep
      // if marked history (old key got deleted, still useful to see).
      const rows = providers
        .filter((p) => p.isActive || p.hasApiKey || p.historyOnly)
        .map((p) => {
          const h = health[p.key];
          return {
            key: p.key,
            name: p.name || p.key,
            baseUrl: p.baseUrl || '',
            model: p.isActive ? (s.current?.summary?.model || '') : '',
            mode: 'apikey',
            kind: 'codex-apikey',
            isActive: Boolean(p.isActive),
            hasCredential: Boolean(p.hasApiKey),
            historyOnly: Boolean(p.historyOnly),
            health: h || null,
            ref: p,
            tool,
          };
        });

      const oauthCache = window.__chOauthProfiles || { loaded: false, data: null };
      const oauthData = oauthCache.data || { profiles: [], active: '', live: {}, liveHasUnsavedTokens: false };
      const savedProfiles = Array.isArray(oauthData.profiles) ? oauthData.profiles : [];
      const oauthIsChosen = login.loggedIn && !providers.some((p) => p.isActive);

      for (const prof of savedProfiles) {
        const id = prof.id || '';
        const hasTokens = Boolean(prof.hasTokens);
        const isActiveProfile = Boolean(oauthData.active && oauthData.active === id);
        const isChosen = isActiveProfile && oauthIsChosen;
        rows.push({
          key: `__codex_oauth_profile:${id}`,
          name: prof.name || prof.email || 'OAuth 账号',
          baseUrl: hasTokens ? 'ChatGPT 官方登录' : '未完成登录 · 等待授权',
          model: isChosen ? (login.plan || prof.plan || '') : '',
          mode: 'oauth',
          kind: 'codex-oauth-profile',
          isActive: isChosen,
          hasCredential: hasTokens,
          health: isActiveProfile && hasTokens ? { ok: true, checked: true } : null,
          ref: prof,
          plan: prof.plan || '',
          email: prof.email || '',
          profileId: id,
          homePath: prof.codexHome || '',
          homeLabel: 'CODEX_HOME',
          tool,
        });
      }

      // Live tokens exist but don't map to any saved profile → offer "save as profile".
      if (oauthCache.loaded && oauthData.liveHasUnsavedTokens) {
        rows.push({
          key: '__codex_oauth_unsaved__',
          name: '未保存的官方登录',
          baseUrl: 'ChatGPT 官方登录 · 尚未存入 profile',
          model: (oauthData.live && oauthData.live.plan) || login.plan || '',
          mode: 'oauth',
          kind: 'codex-oauth-unsaved',
          isActive: oauthIsChosen,
          hasCredential: true,
          health: { ok: true, checked: true },
          ref: null,
          plan: (oauthData.live && oauthData.live.plan) || '',
          email: (oauthData.live && oauthData.live.email) || '',
          homePath: getDashboardCodexHome(),
          homeLabel: 'CODEX_HOME',
          tool,
        });
      }

      // Fallback synthetic row: no cache yet, but login exists — show legacy pill
      // so the hub never blinks empty on the very first render.
      if (!oauthCache.loaded && login.loggedIn && savedProfiles.length === 0) {
        rows.push({
          key: '__codex_oauth_unsaved__',
          name: login.orgName || login.email || '官方登录',
          baseUrl: 'ChatGPT 官方登录',
          model: login.plan || '',
          mode: 'oauth',
          kind: 'codex-oauth-unsaved',
          isActive: oauthIsChosen,
          hasCredential: true,
          health: { ok: true, checked: true },
          ref: null,
          plan: login.plan || '',
          email: login.email || '',
          homePath: getDashboardCodexHome(),
          homeLabel: 'CODEX_HOME',
          tool,
        });
      }

      return rows;
    }

    if (tool === 'claudecode') {
      const cc = s.claudeCodeState || {};
      if (typeof isClaudeCodeInstalled === 'function' && !isClaudeCodeInstalled(cc)) return [];
      const profiles = typeof getClaudeProviderProfiles === 'function' ? (getClaudeProviderProfiles(cc) || []) : [];
      const selectedKey = s.claudeSelectedProviderKey;
      const oauthAuthInUse = typeof isClaudeOauthLoggedIn === 'function' && isClaudeOauthLoggedIn(cc);
      // Render Claude providers as API-KEY rows. Two filters:
      //   1. When the user's official-Anthropic auth is OAuth, hide the
      //      official API-KEY row (OAuth profile rows represent it).
      //   2. Hide template / placeholder providers with no API key set
      //      (they appear as "缺 KEY" ghosts otherwise).
      const rows = profiles
        .filter((p) => {
          const isOfficial = typeof isClaudeOfficialProvider === 'function' ? isClaudeOfficialProvider(p) : false;
          if (isOfficial && oauthAuthInUse) return false;
          if (p.key === selectedKey) return true; // always keep whatever's active
          if (!p.hasApiKey) return false;
          return true;
        })
        .map((p) => {
          const hasCredential = Boolean(p.hasApiKey);
          return {
            key: p.key,
            name: p.name || p.key,
            baseUrl: p.baseUrl || 'https://api.anthropic.com',
            model: (p.key === selectedKey) ? (cc.model || '') : '',
            mode: 'apikey',
            kind: 'claudecode-apikey',
            isActive: p.key === selectedKey,
            hasCredential,
            health: hasCredential ? { ok: true, checked: true } : null,
            ref: p,
            tool,
          };
        });

      // Our OAuth profile store → one row per saved profile + one "default"
      // row representing the un-managed ~/.claude/ login.
      const ccCache = window.__chClaudeOauthProfiles || { loaded: false, data: null };
      const ccData = ccCache.data || { active: '', profiles: [], lastSwitchAt: 0 };
      const savedProfiles = Array.isArray(ccData.profiles) ? ccData.profiles : [];
      const activeId = ccData.active || '';
      const ccLogin = cc.login || {};
      const availableScopes = Array.isArray(cc.availableScopes) ? cc.availableScopes : [];
      const defaultScope = availableScopes.find((scope) => scope.scopeId === 'default') || null;
      const cliLoggedIn = typeof isClaudeOauthLoggedIn === 'function' && isClaudeOauthLoggedIn(cc);

      // "默认" row — represents ~/.claude/ (Claude Code's default CONFIG_DIR).
      // We render it whenever we have *any* signal of a default login. To
      // avoid the first-paint flicker (cc.login often races the profile list
      // fetch), we combine three independent signals:
      //   1. isClaudeOauthLoggedIn(cc)        — from load_claudecode_state
      //   2. ccData.defaultPlan.subscriptionType  — from our profiles list
      //                                              (reads Keychain)
      //   3. ccData.defaultPlan.hasDefault    — future flag for "file exists"
      // As long as any one is set, the row is stable across renders.
      const defaultPlanObj = ccData.defaultPlan || {};
      const defaultPlan = defaultPlanObj.plan || '';
      const defaultHasTokens = Boolean(defaultPlanObj.subscriptionType || defaultPlanObj.email || defaultPlanObj.organizationName)
        || (activeId === '' && cliLoggedIn);

      if (defaultHasTokens) {
        // Name prefers our own backend's defaultPlan.email (read directly from
        // ~/.claude.json by /api/claudecode/oauth/profiles) over cc.login.email
        // (populated by the slower load_claudecode_state path). This way the
        // hero shows the right identity on the very first paint instead of
        // flashing "默认账号" until cc.login arrives.
        const defaultEmail = defaultPlanObj.email || defaultScope?.email || (activeId === '' ? ccLogin.email : '') || '';
        const defaultOrg = defaultPlanObj.organizationName || defaultScope?.organizationName || (activeId === '' ? ccLogin.orgName : '') || '';
        rows.push({
          key: '__claudecode_oauth_default__',
          name: defaultEmail || defaultOrg || '默认账号',
          baseUrl: '~/.claude/ · Claude Code 默认',
          model: activeId === '' ? defaultPlan : '',
          mode: 'oauth',
          kind: 'claudecode-oauth-default',
          isActive: activeId === '',
          hasCredential: true,
          health: { ok: true, checked: true },
          ref: null,
          plan: defaultPlan,
          email: defaultEmail,
          homePath: defaultScope?.configDir || (activeId === '' ? cc.configHome || '' : ''),
          homeLabel: 'CLAUDE_CONFIG_DIR',
          tool,
        });
      }

      // One row per saved profile.
      for (const prof of savedProfiles) {
        const id = prof.id || '';
        const profHasTokens = Boolean(prof.hasTokens);
        const isActiveProfile = activeId === id;
        rows.push({
          key: `__claudecode_oauth_profile:${id}`,
          name: prof.name || prof.email || 'Claude 账号',
          baseUrl: profHasTokens
            ? `${prof.organizationName || 'Claude 官方'}${prof.email ? ' · ' + prof.email : ''}`
            : '未完成登录 · 点击重新登录',
          model: isActiveProfile ? (prof.plan || '') : '',
          mode: 'oauth',
          kind: 'claudecode-oauth-profile',
          isActive: isActiveProfile,
          hasCredential: profHasTokens,
          health: profHasTokens ? { ok: true, checked: true } : null,
          ref: prof,
          plan: prof.plan || '',
          email: prof.email || '',
          profileId: id,
          profileConfigDir: prof.configDir || '',
          homePath: prof.configDir || '',
          homeLabel: 'CLAUDE_CONFIG_DIR',
          tool,
        });
      }

      return rows;
    }

    if (tool === 'opencode') {
      const data = s.opencodeState || {};
      if (typeof isOpenCodeInstalled === 'function' && !isOpenCodeInstalled(data)) return [];
      const providers = Array.isArray(data.providers) ? data.providers : [];
      return providers.map((p) => {
        const authType = String(p.authType || '').toLowerCase();
        const isOauth = Boolean(p.hasAuth) && authType.includes('oauth');
        return {
          key: p.key,
          name: p.name || p.key,
          baseUrl: p.baseUrl || '',
          model: (p.key === data.activeProviderKey) ? (data.model || '') : '',
          mode: isOauth ? 'oauth' : 'apikey',
          isActive: p.key === data.activeProviderKey,
          hasCredential: Boolean(p.hasCredential),
          health: p.hasCredential ? { ok: true, checked: true } : null,
          ref: p,
          tool,
        };
      });
    }

    // openclaw: no provider concept
    return [];
  }

  // ── Codex 启动命令构造 ─────────────────────────────────────────
  // POSIX 单引号转义：用 '\'' 把字符串里的单引号 break/escape/重启 起来。
  function posixQuote(value) {
    return `'${String(value || '').replace(/'/g, `'\\''`)}'`;
  }
  function winCmdQuote(value) {
    return `"${String(value || '').replace(/"/g, '""')}"`;
  }

  // 7 个常用启动预设。description 写"什么时候用"，flag 简短
  const CODEX_LAUNCH_PRESETS = [
    { id: 'default',          title: '标准启动',                   desc: '默认交互模式，每条命令都需要审批',     flags: [] },
    { id: 'bypass-all',       title: '跳过审批 + 沙盒（危险）',     desc: '完全无防护：所有命令直接跑',         flags: ['--dangerously-bypass-approvals-and-sandbox'], danger: true },
    { id: 'auto-approve',     title: '全自动审批',                 desc: '自动通过审批，仍在沙盒里跑',         flags: ['--ask-for-approval', 'untrusted'] },
    { id: 'sandbox-read',     title: '只读沙盒',                   desc: '最严格：只能读文件，不能写',         flags: ['--sandbox', 'read-only'] },
    { id: 'sandbox-write',    title: '允许写工作区',               desc: '常用日常档：项目目录内可读写',       flags: ['--sandbox', 'workspace-write'] },
    { id: 'resume-last',      title: '恢复最近会话',               desc: '接着上一次的对话继续聊',             flags: ['resume', '--last'] },
    { id: 'oauth-login',      title: 'OAuth 官方登录',             desc: '打开浏览器走 ChatGPT 登录流程',     flags: ['login'] },
  ];

  function primaryAddMode() {
    const s = hubState();
    const tool = s?.activeTool || 'codex';
    const filter = s?.chFilter || 'all';
    if ((tool === 'codex' || tool === 'claudecode') && filter === 'all') return 'choice';
    if (tool === 'claudecode' && filter === 'oauth') return 'claudecode-oauth';
    if (tool === 'codex' && filter === 'oauth') return 'codex-oauth';
    return 'provider';
  }

  function primaryAddCopy() {
    const mode = primaryAddMode();
    if (mode === 'choice') {
      return {
        label: '新增',
        title: '选择新增方式',
        emptyTitle: '还没有连接配置',
        emptySub: '点击右上角新增，选择浏览器授权或 API Key Provider。',
        emptyAction: '新增',
      };
    }
    if (mode === 'claudecode-oauth') {
      return {
        label: '浏览器授权',
        title: '新增 Claude Code OAuth 账号 (claude auth login)',
        emptyTitle: '还没有 Claude 账号',
        emptySub: '点击右上角浏览器授权，创建独立 profile 并完成授权。',
        emptyAction: '浏览器授权',
      };
    }
    if (mode === 'codex-oauth') {
      return {
        label: '浏览器授权',
        title: '新增 Codex OAuth 账号 (codex login)',
        emptyTitle: '还没有 OAuth 账号',
        emptySub: '点击右上角浏览器授权，完成官方 OAuth 登录。',
        emptyAction: '浏览器授权',
      };
    }
    return {
      label: '新增 Provider',
      title: '新增 API Key Provider',
      emptyTitle: '还没有 provider',
      emptySub: '点击右上角新增 Provider 开始配置。',
      emptyAction: '新增',
    };
  }

  function syncPrimaryAddUi() {
    const copy = primaryAddCopy();
    const addBtn = document.getElementById('chAddBtn');
    if (addBtn) {
      addBtn.title = copy.title;
      addBtn.setAttribute('aria-label', copy.title);
      addBtn.innerHTML = `
        <svg width="13" height="13" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true">
          <path d="M8 3v10M3 8h10"/>
        </svg>
        <span class="ch-add-btn-label">${safeEscape(copy.label)}</span>`;
    }

    const s = hubState();
    const tool = s?.activeTool || 'codex';
    const filter = s?.chFilter || 'all';
    const search = document.getElementById('chSearchInput');
    if (search) {
      search.placeholder = (tool === 'claudecode' && filter !== 'apikey')
        ? '搜索账号 / URL / 模型'
        : '搜索 provider / URL / 模型';
    }

    const emptyEl = document.getElementById('chEmpty');
    if (emptyEl) {
      emptyEl.innerHTML = `
        <div class="ch-empty-title">${safeEscape(copy.emptyTitle)}</div>
        <div class="ch-empty-sub">${safeEscape(copy.emptySub)}</div>`;
    }
  }

  async function handlePrimaryAdd() {
    const mode = primaryAddMode();
    if (mode === 'choice') {
      const chosen = await openAddChoiceDialog();
      if (chosen === 'oauth') {
        const tool = hubState()?.activeTool || 'codex';
        if (tool === 'claudecode') await addNewClaudeCodeOauthProfile();
        else await addNewOauthAccount();
      } else if (chosen === 'provider') {
        openSlideover('add');
      }
      return;
    }
    if (mode === 'claudecode-oauth') {
      await addNewClaudeCodeOauthProfile();
      return;
    }
    if (mode === 'codex-oauth') {
      await addNewOauthAccount();
      return;
    }
    openSlideover('add');
  }

  async function openAddChoiceDialog() {
    const s = hubState();
    const tool = s?.activeTool || 'codex';
    const toolLabel = TOOL_LABELS[tool] || tool;
    const oauthLabel = tool === 'claudecode' ? 'Claude Code OAuth' : '官方 OAuth';
    const oauthDesc = tool === 'claudecode'
      ? '浏览器授权，保存为独立 Claude profile'
      : '浏览器授权，保存为独立 Codex profile';
    const providerDesc = tool === 'claudecode'
      ? 'Base URL / API Key / 模型配置'
      : 'Base URL / API Key / 默认模型配置';
    const body = `
      <div class="ch-add-choice" role="radiogroup" aria-label="新增方式">
        <label class="ch-add-choice-card">
          <input type="radio" name="ch-add-kind-choice" value="oauth" checked />
          <span class="ch-add-choice-icon oauth" aria-hidden="true">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round">
              <path d="M12 2v4M12 18v4M4.93 4.93l2.83 2.83M16.24 16.24l2.83 2.83M2 12h4M18 12h4M4.93 19.07l2.83-2.83M16.24 7.76l2.83-2.83"/>
              <circle cx="12" cy="12" r="3.4"/>
            </svg>
          </span>
          <span class="ch-add-choice-text">
            <span class="ch-add-choice-title">${safeEscape(oauthLabel)}</span>
            <span class="ch-add-choice-desc">${safeEscape(oauthDesc)}</span>
          </span>
        </label>
        <label class="ch-add-choice-card">
          <input type="radio" name="ch-add-kind-choice" value="provider" />
          <span class="ch-add-choice-icon provider" aria-hidden="true">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round">
              <path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"/>
              <path d="M3.29 7 12 12l8.71-5M12 22V12"/>
            </svg>
          </span>
          <span class="ch-add-choice-text">
            <span class="ch-add-choice-title">API Key Provider</span>
            <span class="ch-add-choice-desc">${safeEscape(providerDesc)}</span>
          </span>
        </label>
      </div>`;
    const ok = await openUpdateDialog({
      eyebrow: toolLabel,
      title: '新增连接',
      body,
      confirmText: '继续',
      cancelText: '取消',
    });
    if (!ok) return '';
    return document.querySelector('input[name="ch-add-kind-choice"]:checked')?.value || 'oauth';
  }

  // 默认输出最短形式：`codex <flags>`。
  // 当 withPrefix=true 时才补全安全前缀（用于多账号 / OPENAI_API_KEY 残留场景）：
  //   - OAuth profile：unset OPENAI_API_KEY OPENAI_BASE_URL + 内联 CODEX_HOME
  //   - API key：仅当 codexHome 不是默认 `~/.codex` 时内联 CODEX_HOME
  // 永远不带 `cd '...'`，用户自己在终端里管理工作目录。
  function buildCodexLaunchCommand({ codexHome, isOauth, flags = [], isWindows = false, withPrefix = false, usesLocalRouter = false }) {
    const trimmedHome = String(codexHome || '').trim();
    const codexCmd = ['codex', ...flags].join(' ');
    if (!withPrefix && !usesLocalRouter) {
      return codexCmd;
    }
    if (isWindows) {
      const parts = [];
      if (isOauth) {
        parts.push('set "OPENAI_API_KEY="');
        parts.push('set "OPENAI_BASE_URL="');
      }
      if (usesLocalRouter) {
        parts.push(`set "NO_PROXY=${PROVIDER_ROUTER_NO_PROXY}"`);
        parts.push(`set "no_proxy=${PROVIDER_ROUTER_NO_PROXY}"`);
      }
      if (trimmedHome) parts.push(`set "CODEX_HOME=${trimmedHome}"`);
      parts.push(codexCmd);
      return parts.join(' && ');
    }
    // POSIX
    const parts = [];
    if (isOauth) parts.push('unset OPENAI_API_KEY OPENAI_BASE_URL');
    const envPrefix = [];
    if (usesLocalRouter) {
      envPrefix.push(`NO_PROXY=${posixQuote(PROVIDER_ROUTER_NO_PROXY)}`);
      envPrefix.push(`no_proxy=${posixQuote(PROVIDER_ROUTER_NO_PROXY)}`);
    }
    if (trimmedHome) envPrefix.push(`CODEX_HOME=${posixQuote(trimmedHome)}`);
    const cmdWithEnv = envPrefix.length ? `${envPrefix.join(' ')} ${codexCmd}` : codexCmd;
    parts.push(cmdWithEnv);
    return parts.join(' && ');
  }

  function renderCodexCmdPalette(active, tool) {
    if (tool !== 'codex' || !active) return '';
    const isOauth = active.mode === 'oauth';
    const codexHome = active.homePath || state.current?.codexHome || '';
    const isWindows = String(state.current?.launch?.platform || '').toLowerCase() === 'win32';
    const withPrefix = Boolean(state.codexCmdShowPrefix);
    const usesLocalRouter = isConnectionHubLocalRouterRow(active);
    const items = CODEX_LAUNCH_PRESETS.map((preset, idx) => {
      const cmd = buildCodexLaunchCommand({ codexHome, isOauth, flags: preset.flags, isWindows, withPrefix, usesLocalRouter });
      const danger = preset.danger ? ' is-danger' : '';
      return `
        <div class="ch-cmd-row${danger}">
          <div class="ch-cmd-meta">
            <div class="ch-cmd-title">${safeEscape(preset.title)}${preset.danger ? '<span class="ch-cmd-warn">⚠</span>' : ''}</div>
            <div class="ch-cmd-desc">${safeEscape(preset.desc)}</div>
          </div>
          <code class="ch-cmd-line">${safeEscape(cmd)}</code>
          <button type="button" class="ch-cmd-copy" data-codex-cmd-copy="${idx}" title="复制">
            <svg width="13" height="13" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><rect x="4" y="4" width="9" height="9" rx="1.5"/><path d="M11 4V2.5A1 1 0 0 0 10 1.5H3.5A1 1 0 0 0 2.5 2.5V10A1 1 0 0 0 3.5 11h1.5"/></svg>
          </button>
        </div>
      `;
    }).join('');
    return `
      <div class="ch-cmd-palette ${state.codexCmdPaletteOpen ? 'open' : ''}">
        <div class="ch-cmd-palette-head">
          <span class="ch-cmd-palette-title">启动命令</span>
          <label class="ch-cmd-prefix-toggle" title="多账号或 shell 有 OPENAI_API_KEY 残留时打开">
            <input type="checkbox" data-codex-cmd-prefix-toggle ${withPrefix ? 'checked' : ''} />
            <span>含环境前缀</span>
          </label>
        </div>
        <div class="ch-cmd-list">${items}</div>
      </div>`;
  }

  function formatChHeroLatency(ms) {
    const num = Number(ms);
    if (!Number.isFinite(num) || num <= 0) return '—';
    if (num >= 1000) return `${(num / 1000).toFixed(2)}s`;
    return `${Math.round(num)}ms`;
  }

  function getChHeroBalanceMeta(row) {
    if (!row || row.tool !== 'codex') return null;
    const key = chRowCacheKey(row);
    const loading = Boolean(state.providerRemoteUsageLoadingByKey?.[key]);
    if (row.mode === 'oauth') {
      if (loading) return { labelKind: '额度', valueLabel: '查询中', percent: null, cls: 'is-loading', title: '正在查询官方额度。' };
      if (!row.hasCredential) return { labelKind: '额度', valueLabel: '--%', percent: null, cls: 'is-muted', title: '当前 OAuth 账号未完成登录授权。' };
      return getChOauthAllowanceMeta(row, state.providerRemoteUsageByKey?.[key] || null);
    }
    if (loading) return { labelKind: '余额', valueLabel: '查询中', percent: null, cls: 'is-loading', title: '正在查询远程余额。' };
    if ((!row.hasCredential && !chRowHasRemotePanelCredential(row)) || row.historyOnly) {
      return { labelKind: '余额', valueLabel: '--', percent: null, cls: 'is-muted', title: '当前 Provider 没有可用 API Key 或面板认证。' };
    }
    const cached = state.providerRemoteUsageByKey?.[key] || null;
    if (cached?.error) return { labelKind: '余额', valueLabel: '失败', percent: null, cls: 'is-warn', title: cached.error };
    return getChRemoteBalanceMeta(cached?.result || null);
  }

  function getChHeroSlaMetric(active) {
    if (!active) return null;
    const h = active.health || {};
    const cached = state.providerUptime?.[active.key] || {};
    const uptimePct = chFiniteNumber(cached.uptimePct);
    if (uptimePct != null) {
      return {
        label: 'SLA 24h',
        value: formatChRowPercent(uptimePct),
        cls: uptimePct >= 99 ? 'is-ok' : uptimePct >= 90 ? 'is-warn' : 'is-bad',
        title: `最近 24 小时探测可用率 ${formatChRowPercent(uptimePct)}`,
      };
    }
    if (active.mode === 'oauth') {
      return {
        label: '授权',
        value: active.hasCredential ? '已登录' : '待登录',
        cls: active.hasCredential ? 'is-ok' : 'is-warn',
        title: active.hasCredential ? 'OAuth token 已存在。' : '这个 OAuth 账号还没完成授权。',
      };
    }
    if (h.ok && h.latencyMs) {
      return { label: '延迟', value: formatChHeroLatency(h.latencyMs), cls: 'is-ok', title: '最近一次连通性探测延迟。' };
    }
    if (h.checked && !h.ok) {
      return { label: 'SLA 24h', value: '失败', cls: 'is-bad', title: h.hint || h.errorMessage || '最近一次探测失败。' };
    }
    if (!active.hasCredential) {
      return { label: '凭证', value: '缺 Key', cls: 'is-warn', title: '尚未保存 API Key。' };
    }
    return { label: 'SLA 24h', value: '待采样', cls: 'is-muted', title: '等待自动探测或点击菜单里的重检。' };
  }

  function renderChHeroMetric(metric) {
    if (!metric) return '';
    return `
      <span class="ch-hero-metric ${safeEscape(metric.cls || 'is-muted')}" title="${safeEscape(metric.title || '')}">
        <span>${safeEscape(metric.label || '')}</span>
        <strong>${safeEscape(metric.value || '—')}</strong>
      </span>`;
  }

  function renderChHeroQuickMetrics(active) {
    if (!active) return '';
    const metrics = [];
    metrics.push(getChHeroSlaMetric(active));
    const balance = getChHeroBalanceMeta(active);
    if (balance) {
      metrics.push({
        label: balance.labelKind || '余额',
        value: balance.valueLabel || '--',
        cls: balance.cls || 'is-muted',
        title: balance.title || '',
      });
    }
    if (active.mode === 'apikey') {
      metrics.push({
        label: '凭证',
        value: active.hasCredential ? '已保存' : '缺 Key',
        cls: active.hasCredential ? 'is-ok' : 'is-warn',
        title: active.hasCredential ? 'API Key 已保存，可直接启动使用。' : '启动后大概率无法请求模型。',
      });
    } else if (active.plan || active.email) {
      metrics.push({
        label: active.plan ? '计划' : '账号',
        value: active.plan || active.email,
        cls: 'is-oauth',
        title: active.email || active.plan || '',
      });
    }
    if (isConnectionHubLocalRouterRow(active)) {
      metrics.push({ label: '入口', value: '本地 Router', cls: 'is-router', title: '当前 Provider 走本机 Router。' });
    }
    const html = metrics.filter(Boolean).slice(0, 4).map(renderChHeroMetric).join('');
    return html ? `<div class="ch-hero-metrics">${html}</div>` : '';
  }

  function renderChHeroMoreMenu(active, tool, isOauth) {
    if (!active) return '';
    const items = [];
    if (tool === 'codex') {
      items.push({ label: active.mode === 'oauth' ? '刷新额度' : '刷新余额', icon: 'refresh', attrs: `data-ch-hero-balance-query="${safeEscape(active.key)}"` });
    }
    if (!isOauth) {
      items.push(
        { label: '重检连接', icon: 'refresh', attrs: 'data-ch-detect' },
        { label: '编辑配置', icon: 'edit', attrs: 'data-ch-edit' },
      );
      if (canOpenChRowRecharge(active)) {
        items.push({ label: '打开充值页', icon: 'recharge', attrs: `data-ch-hero-recharge="${safeEscape(active.key)}"` });
      }
    }
    if (tool === 'codex') {
      items.push({ label: '启动方式', icon: 'terminal', attrs: 'data-ch-launch-menu' });
      items.push({ label: '复制启动命令', icon: 'copy', attrs: 'data-ch-cmd-toggle' });
    }
    if (!items.length) return '';
    return `
      <span class="ch-hero-more">
        <button type="button" class="ch-hero-icon" data-ch-hero-menu-trigger title="更多操作" aria-label="更多操作" aria-haspopup="menu">
          ${chRowMenuIcon('more')}
        </button>
        <span class="ch-hero-menu-panel" role="menu">
          ${items.map((item) => `
            <button type="button" class="ch-hero-menu-item" role="menuitem" ${item.attrs}>
              ${chRowMenuIcon(item.icon)}
              <span>${safeEscape(item.label)}</span>
            </button>`).join('')}
        </span>
      </span>`;
  }

  // ── Hero HTML ─────────────────────────────────────────────────────
  function renderHeroHTML(active, tool) {
    if (!active) {
      const copy = primaryAddCopy();
      return `
        <div class="ch-hero-info">
          <div class="ch-hero-eyebrow">CURRENT SESSION</div>
          <div class="ch-hero-empty-title">${safeEscape(copy.emptyTitle)}</div>
          <div class="ch-hero-empty-sub">${safeEscape(copy.emptySub)}</div>
        </div>
        <div class="ch-hero-actions">
          <button type="button" class="ch-hero-ghost" data-ch-add title="${safeEscape(copy.title)}">
            <svg width="13" height="13" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><path d="M8 3v10M3 8h10"/></svg>
            ${safeEscape(copy.emptyAction)}
          </button>
        </div>`;
    }
    const h = active.health || {};
    const isOauth = active.mode === 'oauth';
    // Official OAuth sessions: no connectivity probing — status is always
    // "当前 (OAUTH)". Only API-key sessions show the actual probe result.
    const statusCls = isOauth
      ? 'ok'
      : (active.isActive && h.ok ? 'ok' : h.loading ? 'warn loading' : h.ok ? 'ok' : h.checked ? 'bad' : 'muted');
    const statusTxt = isOauth
      ? '当前'
      : (h.loading ? '检测中' : h.ok ? '已通' : h.checked ? '失败' : '未检测');
    const launchLabel = LAUNCH_LABELS[tool] || '启动';
    const modeTxt = isOauth ? 'OAUTH' : 'API KEY';
    const boundKey = currentBoundProviderKey();
    const isBound = boundKey && active.key === boundKey && active.mode === 'apikey';

    return `
      <div class="ch-hero-info">
        <div class="ch-hero-eyebrow">
          <span>CURRENT SESSION</span>
          <span class="ch-status ${statusCls}">${safeEscape(statusTxt)}</span>
        </div>
        <h2 class="ch-hero-name">${safeEscape(active.name)}</h2>
        <div class="ch-hero-badges">
          <span class="ch-mode ${active.mode}">${modeTxt}</span>
          ${active.model ? `<span class="ch-hero-model">${safeEscape(active.model)}</span>` : ''}
          ${isBound ? '<span class="ch-hero-bound">本项目</span>' : ''}
        </div>
        ${renderChHeroQuickMetrics(active)}
        ${active.baseUrl ? `<div class="ch-hero-url">${safeEscape(active.baseUrl)}</div>` : ''}
      </div>
      <div class="ch-hero-actions">
        <button id="chHeroLaunchBtn" type="button" class="ch-hero-launch" data-ch-launch title="${tool === 'codex' ? '选择应用内终端或外部终端后启动 Codex。' : safeEscape(launchLabel)}">
          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M13 2L4 14h7l-1 8 9-12h-7l1-8z"/></svg>
          ${safeEscape(launchLabel)}
        </button>
        ${renderChHeroMoreMenu(active, tool, isOauth)}
      </div>
      ${renderCodexCmdPalette(active, tool)}`;
  }

  // ── List row balance / allowance display ──────────────────────────
  const CH_BALANCE_VISIBILITY_LS = 'easyaiconfig_provider_balance_visibility_v2';

  function chRowCacheKey(row) {
    return `${row?.tool || 'codex'}:${row?.key || ''}`;
  }

  function chRowHasRemotePanelCredential(row) {
    const cached = state.providerRemoteCredentialByKey?.[chRowCacheKey(row)];
    return Boolean(cached?.exists);
  }

  function inferChRowRemotePanelType(row) {
    const key = chRowCacheKey(row);
    const cachedResult = state.providerRemoteUsageByKey?.[key]?.result || {};
    const credential = state.providerRemoteCredentialByKey?.[key] || {};
    const candidates = [
      cachedResult.providerType,
      cachedResult.auth?.panelType,
      credential.panelType,
    ].map((item) => String(item || '').trim().toLowerCase());
    if (candidates.includes('sub2api')) return 'sub2api';
    if (candidates.includes('newapi')) return 'newapi';
    const authMode = String(credential.authMode || '').toLowerCase();
    if (authMode.startsWith('sub2api')) return 'sub2api';
    if (authMode.startsWith('newapi')) return 'newapi';
    const text = [row?.name, row?.key, row?.baseUrl, credential.baseUrl, credential.panelUrl, cachedResult.baseUrl, cachedResult.panelUrl]
      .filter(Boolean)
      .join(' ')
      .toLowerCase();
    if (text.includes('sub2api') || text.includes('aisubapi') || text.includes('ohlaoo.com')) return 'sub2api';
    return 'newapi';
  }

  function getChRowPanelRoot(row) {
    const key = chRowCacheKey(row);
    const cachedResult = state.providerRemoteUsageByKey?.[key]?.result || {};
    const credential = state.providerRemoteCredentialByKey?.[key] || {};
    return getRemotePanelRootFromBase(
      credential.panelUrl
        || credential.baseUrl
        || cachedResult.panelUrl
        || cachedResult.baseUrl
        || row?.baseUrl
        || '',
    );
  }

  function buildChRowRechargeUrl(row) {
    const root = getChRowPanelRoot(row);
    if (!root) return '';
    return joinRemotePanelPath(root, getRemotePanelRechargePath(inferChRowRemotePanelType(row)));
  }

  function canOpenChRowRecharge(row) {
    if (!row || row.mode !== 'apikey') return false;
    const root = getChRowPanelRoot(row);
    if (!root) return false;
    return !/(^|\/\/)(api\.)?(openai|anthropic)\.com\b/i.test(root);
  }

  async function openChRowRecharge(row) {
    const url = buildChRowRechargeUrl(row);
    if (!url) {
      if (typeof flash === 'function') flash('当前 Provider 没有可打开的充值页地址', 'error');
      return;
    }
    await openExternalUrl(url);
  }

  function readChBalanceVisibility() {
    try {
      const parsed = JSON.parse(localStorage.getItem(CH_BALANCE_VISIBILITY_LS) || '{}');
      return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
    } catch (_) {
      return {};
    }
  }

  function writeChBalanceVisibility(next) {
    try { localStorage.setItem(CH_BALANCE_VISIBILITY_LS, JSON.stringify(next || {})); } catch (_) {}
  }

  function isChRowBalanceVisible(row) {
    const prefs = readChBalanceVisibility();
    const value = prefs[chRowCacheKey(row)];
    return value !== false;
  }

  function setChRowBalanceVisible(row, visible) {
    const key = chRowCacheKey(row);
    if (!key.endsWith(':')) {
      const prefs = readChBalanceVisibility();
      if (visible) prefs[key] = true;
      else prefs[key] = false;
      writeChBalanceVisibility(prefs);
    }
  }

  function chFiniteNumber(value) {
    const num = Number(value);
    return Number.isFinite(num) ? num : null;
  }

  function formatChRowPercent(value) {
    const num = chFiniteNumber(value);
    if (num == null) return '--%';
    const clamped = Math.max(0, Math.min(100, num));
    return `${clamped % 1 === 0 ? clamped.toFixed(0) : clamped.toFixed(1)}%`;
  }

  function getChPercentFromPair(remaining, total) {
    const remainNum = chFiniteNumber(remaining);
    const totalNum = chFiniteNumber(total);
    if (remainNum == null || totalNum == null || totalNum <= 0) return null;
    return (remainNum / totalNum) * 100;
  }

  function getChOauthAllowancePercent(row) {
    const ref = row?.ref || {};
    const quota = ref.quota || ref.allowance || ref.usage || {};
    const direct = [
      row.allowancePercent,
      row.quotaPercent,
      row.quotaRemainingPercent,
      ref.allowancePercent,
      ref.quotaPercent,
      ref.quotaRemainingPercent,
      ref.remainingPercent,
      ref.availablePercent,
      quota.remainingPercent,
      quota.availablePercent,
      quota.percent,
    ];
    for (const value of direct) {
      let num = chFiniteNumber(value);
      if (num == null) continue;
      if (num > 0 && num <= 1) num *= 100;
      return num;
    }
    return getChPercentFromPair(quota.remaining ?? quota.available, quota.total ?? quota.limit);
  }

  function formatChRemoteNumber(value, unit) {
    const num = chFiniteNumber(value);
    if (num == null) return '—';
    const cleanUnit = String(unit || '').trim().toLowerCase();
    const money = Math.abs(num).toLocaleString('zh-CN', {
      minimumFractionDigits: Math.abs(num) >= 100 ? 0 : 2,
      maximumFractionDigits: 2,
    });
    if (cleanUnit === 'rmb' || cleanUnit === 'cny' || cleanUnit === 'yuan' || cleanUnit === '¥' || cleanUnit === '￥') {
      return `¥${money}`;
    }
    if (cleanUnit === 'usd' || cleanUnit === '$') {
      return `$${money}`;
    }
    if (Math.abs(num) >= 1000) return num.toLocaleString('zh-CN', { maximumFractionDigits: 2 });
    if (Math.abs(num) >= 1) return num.toLocaleString('zh-CN', { maximumFractionDigits: 3 });
    return num.toLocaleString('zh-CN', { maximumFractionDigits: 6 });
  }

  function chBalancePercentStyle(percent) {
    const num = chFiniteNumber(percent);
    if (num == null) return '';
    const clamped = Math.max(0, Math.min(100, num));
    return ` style="--ch-balance-fill:${clamped.toFixed(1)}%"`;
  }

  function renderChBalanceDisplay(row, meta, { button = true } = {}) {
    const pct = chFiniteNumber(meta?.percent);
    const title = safeEscape(meta?.title || '');
    const cls = `${meta?.cls || 'is-muted'} ${pct == null ? 'is-empty' : 'has-percent'}`;
    const content = `
      <span class="ch-balance-meter" aria-hidden="true"><span></span></span>
      <span class="ch-balance-copy">
        <span>${safeEscape(meta?.labelKind || '余额')}</span>
        <strong>${safeEscape(meta?.valueLabel || '--')}</strong>
      </span>`;
    if (!button) {
      return `<span class="ch-row-balance ${cls}" title="${title}"${chBalancePercentStyle(pct)}>${content}</span>`;
    }
    return `<button type="button" class="ch-row-balance ${cls}" data-ch-row-balance-query="${safeEscape(row.key)}" title="${title}"${chBalancePercentStyle(pct)}>${content}</button>`;
  }

  function getChRemoteBalanceMeta(result) {
    if (!result) {
      return { labelKind: '余额', valueLabel: '--', percent: null, cls: 'is-muted', title: '点击查询当前 Provider 的远程余额。' };
    }
    const status = String(result.status || '').toLowerCase();
    if (status === 'ok') {
      const balance = result.balance || {};
      const unit = balance.unit || balance.currency || 'raw';
      const remaining = chFiniteNumber(balance.remaining);
      const total = chFiniteNumber(balance.total);
      const pct = getChPercentFromPair(remaining, total);
      if (remaining != null) {
        return {
          labelKind: '余额',
          valueLabel: pct == null ? formatChRemoteNumber(remaining, unit) : `${formatChRemoteNumber(remaining, unit)} · ${formatChRowPercent(pct)}`,
          percent: pct,
          cls: 'is-ok',
          title: result.message || '远程余额已同步。',
        };
      }
      return {
        labelKind: '余额',
        valueLabel: '已同步',
        percent: null,
        cls: 'is-ok',
        title: result.message || '远程接口返回成功，但没有可展示的余额字段。',
      };
    }
    if (status === 'blocked') return { labelKind: '余额', valueLabel: '不支持', percent: null, cls: 'is-warn', title: result.message || '该面板存在 Cloudflare/bot 拦截。' };
    if (status === 'auth_error') return { labelKind: '余额', valueLabel: '无权限', percent: null, cls: 'is-warn', title: result.message || '远程用量接口没有权限。' };
    if (status === 'unsupported') return { labelKind: '余额', valueLabel: '不支持', percent: null, cls: 'is-muted', title: result.message || '该渠道暂不支持远程余额查询。' };
    return { labelKind: '余额', valueLabel: '--', percent: null, cls: 'is-muted', title: result.message || '尚未查询远程余额。' };
  }

  function getChOauthAllowanceMeta(row, cached) {
    if (cached?.error) {
      return { labelKind: '额度', valueLabel: '失败', percent: null, cls: 'is-warn', title: cached.error };
    }
    const result = cached?.result || null;
    if (!row?.hasCredential) {
      return { labelKind: '额度', valueLabel: '--%', percent: null, cls: 'is-muted', title: '当前 OAuth 账号未完成登录授权。' };
    }
    if (!result) {
      const pct = getChOauthAllowancePercent(row);
      return {
        labelKind: '额度',
        valueLabel: pct == null ? '--%' : formatChRowPercent(pct),
        percent: pct,
        cls: pct == null ? 'is-oauth' : 'is-ok',
        title: pct == null ? '点击刷新 Codex 官方 OAuth 额度。' : 'OAuth profile 自带的额度百分比。',
      };
    }
    const status = String(result.status || '').toLowerCase();
    if (status === 'ok') {
      const pct = chFiniteNumber(result.summary?.remainingPercent ?? result.quota?.remainingPercent);
      return {
        labelKind: '额度',
        valueLabel: pct == null ? '已同步' : formatChRowPercent(pct),
        percent: pct,
        cls: 'is-oauth',
        title: result.message || 'Codex OAuth 官方额度已同步。',
      };
    }
    if (status === 'blocked') return { labelKind: '额度', valueLabel: '不支持', percent: null, cls: 'is-warn', title: result.message || '官方接口被 Cloudflare/bot challenge 拦截。' };
    if (status === 'auth_error') return { labelKind: '额度', valueLabel: '无权限', percent: null, cls: 'is-warn', title: result.message || 'OAuth token 无权访问官方额度接口。' };
    if (status === 'network_error') return { labelKind: '额度', valueLabel: '失败', percent: null, cls: 'is-warn', title: result.message || '官方额度接口网络请求失败。' };
    if (status === 'unsupported') return { labelKind: '额度', valueLabel: '不支持', percent: null, cls: 'is-muted', title: result.message || '官方接口没有返回可用额度数据。' };
    return { labelKind: '额度', valueLabel: '--%', percent: null, cls: 'is-muted', title: result.message || '尚未查询官方额度。' };
  }

  function getChBalanceRefreshRows(tool = hubState()?.activeTool || 'codex') {
    if (tool !== 'codex') return [];
    return buildProviderRows('codex').filter((row) => {
      if (!row || row.historyOnly) return false;
      if (row.mode === 'oauth') return row.tool === 'codex' && row.hasCredential;
      return row.tool === 'codex' && row.mode === 'apikey' && (row.hasCredential || chRowHasRemotePanelCredential(row));
    });
  }

  function applyChBalanceRefreshUi(rows = null) {
    const button = document.getElementById('chBalanceRefreshBtn');
    const label = document.getElementById('chBalanceRefreshLabel');
    if (!button) return;
    const tool = hubState()?.activeTool || 'codex';
    const eligible = rows ? rows.filter((row) => getChBalanceRefreshRows(tool).some((item) => item.key === row.key)) : getChBalanceRefreshRows(tool);
    const loading = Boolean(state.providerBalanceBatchLoading);
    button.disabled = loading || eligible.length === 0;
    button.classList.toggle('is-loading', loading);
    button.title = eligible.length
      ? `批量刷新 ${eligible.length} 个 Codex OAuth 额度 / API Key 中转余额`
      : '当前没有可刷新额度或余额的 Codex Provider';
    if (label) label.textContent = loading ? '刷新中' : '刷新额度/余额';
  }

  function renderChRowBalance(row) {
    if (!isChRowBalanceVisible(row)) return '';
    const key = chRowCacheKey(row);
    const loading = Boolean(state.providerRemoteUsageLoadingByKey?.[key]);
    if (row.mode === 'oauth') {
      if (loading) return renderChBalanceDisplay(row, { labelKind: '额度', valueLabel: '查询中', percent: null, cls: 'is-loading', title: '正在查询官方额度。' }, { button: false });
      if (row.tool !== 'codex') {
        return renderChBalanceDisplay(row, { labelKind: '额度', valueLabel: '--%', percent: null, cls: 'is-muted', title: '官方额度查询当前只支持 Codex OAuth。' }, { button: false });
      }
      const cached = state.providerRemoteUsageByKey?.[key] || null;
      const meta = getChOauthAllowanceMeta(row, cached);
      return renderChBalanceDisplay(row, meta);
    }
    if (loading) {
      return renderChBalanceDisplay(row, { labelKind: '余额', valueLabel: '查询中', percent: null, cls: 'is-loading', title: '正在查询远程余额。' }, { button: false });
    }
    if (row.tool !== 'codex') {
      return renderChBalanceDisplay(row, { labelKind: '余额', valueLabel: '--', percent: null, cls: 'is-muted', title: '远程余额暂只支持 Codex API Key Provider。' }, { button: false });
    }
    if ((!row.hasCredential && !chRowHasRemotePanelCredential(row)) || row.historyOnly) {
      return renderChBalanceDisplay(row, { labelKind: '余额', valueLabel: '--', percent: null, cls: 'is-muted', title: '当前 Provider 没有可用 API Key 或面板认证。' }, { button: false });
    }
    const cached = state.providerRemoteUsageByKey?.[key] || null;
    if (cached?.error) {
      return renderChBalanceDisplay(row, { labelKind: '余额', valueLabel: '失败', percent: null, cls: 'is-warn', title: cached.error });
    }
    const meta = getChRemoteBalanceMeta(cached?.result || null);
    return renderChBalanceDisplay(row, meta);
  }

  function getChRowBalanceToggleLabel(row) {
    const visible = isChRowBalanceVisible(row);
    const isOauth = row.mode === 'oauth';
    return visible
      ? (isOauth ? '隐藏额度百分比' : '隐藏余额')
      : (isOauth ? '显示额度百分比' : '显示余额');
  }

  function chRowMenuIcon(kind) {
    const icons = {
      more: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="5" cy="12" r="1.5"/><circle cx="12" cy="12" r="1.5"/><circle cx="19" cy="12" r="1.5"/></svg>',
      terminal: '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="4" width="18" height="16" rx="2"/><path d="M7 9l3 3-3 3"/><path d="M13 15h4"/></svg>',
      edit: '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><path d="M14.5 3.5l6 6-11 11H3.5v-6l11-11z"/></svg>',
      refresh: '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><path d="M21 12a9 9 0 0 1-15.36 6.36L3 21M3 12a9 9 0 0 1 15.36-6.36L21 3"/></svg>',
      delete: '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><path d="M3 6h18M8 6V4h8v2M6 6l1 14h10l1-14"/></svg>',
      eye: '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><path d="M2 12s3.5-8 10-8 10 8 10 8-3.5 8-10 8-10-8-10-8z"/><circle cx="12" cy="12" r="3"/></svg>',
      eyeOff: '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><path d="M3 3l18 18"/><path d="M10.6 10.6A2 2 0 0 0 13.4 13.4"/><path d="M9.9 4.2A9.8 9.8 0 0 1 12 4c6.5 0 10 8 10 8a18.4 18.4 0 0 1-2.3 3.5"/><path d="M6.6 6.6C3.5 8.5 2 12 2 12s3.5 8 10 8a10 10 0 0 0 4.5-1"/></svg>',
      save: '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2z"/><path d="M17 21v-8H7v8"/><path d="M7 3v5h8"/></svg>',
      copy: '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><rect x="9" y="9" width="11" height="11" rx="2"/><path d="M5 15V5a2 2 0 0 1 2-2h10"/></svg>',
      login: '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><path d="M15 3h4a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-4"/><path d="M10 17l5-5-5-5"/><path d="M15 12H3"/></svg>',
      recharge: '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="6" width="18" height="13" rx="2"/><path d="M3 10h18"/><path d="M7 15h4"/></svg>',
    };
    return icons[kind] || icons.more;
  }

	  function renderChRowActionMenu(row, items) {
	    if (!items.length) return '';
	    return `
	        <span class="ch-row-menu">
	          <button type="button" class="ch-row-menu-trigger" data-ch-row-menu-trigger="${safeEscape(row.key)}" title="更多操作" aria-label="更多操作 ${safeEscape(row.name)}" aria-expanded="false">
	            ${chRowMenuIcon('more')}
	          </button>
	          <span class="ch-row-menu-panel" role="menu">
	            ${items.map((item) => `
	              <button type="button" class="ch-row-menu-item ${item.danger ? 'is-danger' : ''} ${item.primary ? 'is-primary' : ''}" role="menuitem" ${item.attrs}>
                ${chRowMenuIcon(item.icon)}
                <span>${safeEscape(item.label)}</span>
              </button>`).join('')}
          </span>
        </span>`;
  }

  async function queryChRowRemoteUsage(row, options = {}) {
    const { silent = false, render = true } = options || {};
    if (!row) return;
    if (row.mode === 'oauth') {
      if (row.tool !== 'codex') {
        setProviderRemoteUsageCache(chRowCacheKey(row), {
          result: { status: 'unsupported', supported: false, providerType: 'unsupported-oauth', message: '官方额度查询当前只支持 Codex OAuth。' },
          error: '',
          fetchedAt: Date.now(),
        }, { tool: row.tool || 'codex', providerKey: row.key || '' });
        if (render) renderConnectionHub();
        return;
      }
      if (!row.hasCredential) {
        if (!silent && typeof flash === 'function') flash('当前 OAuth 账号未完成登录授权，无法查询官方额度', 'error');
        if (render) renderConnectionHub();
        return;
      }
      if (!(await confirmOauthIpRiskBeforeRequest('查询 Codex 官方额度', { silent }))) {
        if (!silent && typeof flash === 'function') flash('已取消官方额度查询', 'info');
        if (render) renderConnectionHub();
        return;
      }
      const key = chRowCacheKey(row);
      if (state.providerRemoteUsageLoadingByKey?.[key]) return;
      state.providerRemoteUsageLoadingByKey[key] = true;
      if (render) renderConnectionHub();
      try {
        const codexHome = row.homePath || (typeof getDashboardCodexHome === 'function' ? getDashboardCodexHome() : '') || state.current?.codexHome || '';
        const res = await api('/api/codex/oauth/usage', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            codexHome,
            profileId: row.profileId || '',
            systemTimeoutMs: 1800,
            fallbackTimeoutMs: 8000,
          }),
          timeoutMs: 15000,
        });
        if (res?.ok && res.data) {
          setProviderRemoteUsageCache(key, { result: res.data, error: '', fetchedAt: Date.now() }, { tool: row.tool || 'codex', providerKey: row.key || '' });
        } else {
          setProviderRemoteUsageCache(key, { result: null, error: res?.error || '官方额度查询失败', fetchedAt: Date.now() }, { tool: row.tool || 'codex', providerKey: row.key || '' });
        }
      } catch (err) {
        setProviderRemoteUsageCache(key, { result: null, error: err?.message || String(err), fetchedAt: Date.now() }, { tool: row.tool || 'codex', providerKey: row.key || '' });
      } finally {
        state.providerRemoteUsageLoadingByKey[key] = false;
        if (render) renderConnectionHub();
      }
      return;
    }
    if (row.tool !== 'codex') {
      setProviderRemoteUsageCache(chRowCacheKey(row), {
        result: { status: 'unsupported', supported: false, providerType: 'unsupported-tool', message: '远程余额暂只支持 Codex API Key Provider。' },
        error: '',
        fetchedAt: Date.now(),
      }, { tool: row.tool || 'codex', providerKey: row.key || '' });
      if (render) renderConnectionHub();
      return;
    }
    if ((!row.hasCredential && !chRowHasRemotePanelCredential(row)) || row.historyOnly) {
      if (!silent && typeof flash === 'function') flash('当前 Provider 没有可用 API Key 或面板认证，无法查询远程余额', 'error');
      if (render) renderConnectionHub();
      return;
    }
    const key = chRowCacheKey(row);
    if (state.providerRemoteUsageLoadingByKey?.[key]) return;
    state.providerRemoteUsageLoadingByKey[key] = true;
    if (render) renderConnectionHub();
    const codexHome = (typeof getDashboardCodexHome === 'function' ? getDashboardCodexHome() : '') || state.current?.codexHome || '';
    try {
      const res = await api('/api/provider/remote-usage', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          scope: el('scopeSelect')?.value || 'global',
          projectPath: el('projectPathInput')?.value?.trim() || '',
          codexHome,
          tool: 'codex',
          mode: 'apikey',
          providerKey: row.key,
          days: 30,
          timeoutMs: 9000,
        }),
        timeoutMs: 26000,
      });
      if (res?.ok && res.data) {
        setProviderRemoteUsageCache(key, { result: res.data, error: '', fetchedAt: Date.now() }, { tool: row.tool || 'codex', providerKey: row.key || '' });
      } else {
        setProviderRemoteUsageCache(key, { result: null, error: res?.error || '远程余额查询失败', fetchedAt: Date.now() }, { tool: row.tool || 'codex', providerKey: row.key || '' });
      }
    } catch (err) {
      setProviderRemoteUsageCache(key, { result: null, error: err?.message || String(err), fetchedAt: Date.now() }, { tool: row.tool || 'codex', providerKey: row.key || '' });
    } finally {
      state.providerRemoteUsageLoadingByKey[key] = false;
      if (render) renderConnectionHub();
    }
  }

  async function refreshChAllBalances(options = {}) {
    const { silent = false } = options || {};
    if (state.providerBalanceBatchLoading) return;
    const rows = getChBalanceRefreshRows(hubState()?.activeTool || 'codex');
    if (!rows.length) {
      if (!silent && typeof flash === 'function') flash('当前没有可刷新额度或余额的 Codex Provider', 'info');
      applyChBalanceRefreshUi();
      return;
    }
    state.providerBalanceBatchLoading = true;
    renderConnectionHub();
    let okCount = 0;
    let failCount = 0;
    let cursor = 0;
    const workerCount = Math.min(3, rows.length);
    const worker = async () => {
      while (cursor < rows.length) {
        const row = rows[cursor++];
        await queryChRowRemoteUsage(row, { silent: true, render: true });
        const cached = state.providerRemoteUsageByKey?.[chRowCacheKey(row)];
        if (cached?.result && !cached?.error) okCount += 1;
        else failCount += 1;
      }
    };
    try {
      await Promise.all(Array.from({ length: workerCount }, worker));
      if (!silent && typeof flash === 'function') {
        flash(failCount ? `已刷新 ${okCount} 个，失败 ${failCount} 个` : `已刷新 ${okCount} 个额度/余额`, failCount ? 'warning' : 'success');
      }
    } finally {
      state.providerBalanceBatchLoading = false;
      renderConnectionHub();
    }
  }

  // ── List HTML ─────────────────────────────────────────────────────
  function rowHTML(r) {
    const h = r.health || {};
    const isOauth = r.mode === 'oauth';
    let dotCls, statusCls, statusTxt;
    if (r.isActive) {
      dotCls = 'current';
      statusCls = 'active';
      statusTxt = '当前';
    } else if (isOauth && !r.hasCredential) {
      dotCls = 'muted';
      statusCls = 'warn';
      statusTxt = '待登录';
    } else if (isOauth) {
      // Official OAuth identities don't get probed — row is pure metadata.
      dotCls = 'ok'; statusCls = ''; statusTxt = '';
    } else if (h.loading) {
      dotCls = 'warn'; statusCls = 'warn loading'; statusTxt = '检测中';
    } else if (h.ok) {
      dotCls = 'ok'; statusCls = 'ok';
      statusTxt = '已通';
    } else if (h.checked) {
      dotCls = 'bad'; statusCls = 'bad';
      // 把诊断 stage 映射成短中文标签放进状态文字（详细 hint 走 title tooltip）
      const stageHuman = {
        dns: 'DNS', tls: 'TLS', connect: '连接', timeout: '超时',
        auth: '鉴权', notfound: '路径', http: 'HTTP', body: '格式', unknown: '失败',
      };
      const label = stageHuman[h.stage] || '失败';
      statusTxt = h.statusCode ? `${label} ${h.statusCode}` : label;
    } else if (r.historyOnly) {
      dotCls = 'muted'; statusCls = 'muted'; statusTxt = '本地草稿';
    } else if (!r.hasCredential) {
      dotCls = 'muted'; statusCls = 'warn'; statusTxt = '缺 Key';
    } else {
      dotCls = 'muted'; statusCls = 'muted'; statusTxt = '未检测';
    }

    // 诊断 tooltip：失败时给 hint + errorMessage + checkedAt；成功时给 latency + modelCount
    let dotTip = '';
    if (isOauth && !r.hasCredential) {
      dotTip = '该 OAuth 账号还没完成登录授权。';
    } else if (isOauth) {
      dotTip = '官方 OAuth 登录，无需主动探测。';
    } else if (h.loading) {
      dotTip = '正在向 /v1/models 发探测请求…';
    } else if (h.ok) {
      const bits = ['连通正常'];
      if (h.latencyMs) bits.push(`延迟 ${h.latencyMs}ms`);
      if (h.modelCount) bits.push(`${h.modelCount} 个模型`);
      if (h.checkedAt) bits.push(`检测于 ${new Date(h.checkedAt).toLocaleTimeString()}`);
      dotTip = bits.join(' · ');
    } else if (h.checked) {
      const lines = [];
      if (h.hint) lines.push(h.hint);
      else if (h.errorMessage) lines.push(h.errorMessage);
      if (h.checkedAt) lines.push(`检测于 ${new Date(h.checkedAt).toLocaleTimeString()}`);
      dotTip = lines.join('\n') || '检测失败';
    } else if (r.historyOnly) {
      dotTip = '本地草稿：~/.codex/config.toml 里已删，重填一次 Key 保存即可恢复';
    } else if (!r.hasCredential) {
      dotTip = '尚未保存 API Key，无法做连通性探测';
    } else {
      dotTip = '尚未探测。点 ↻ 重检 或等自动 ping';
    }

    // P0 #3：当前 cwd 绑定到此 provider 时显示一个轻量「本项目」标签
    const boundKey = currentBoundProviderKey();
    const isBound = boundKey && r.key === boundKey && r.mode === 'apikey';
    const boundPin = isBound
      ? `<span class="ch-row-bound-pin" title="该 Provider 已绑定到当前项目 ${safeEscape(state.projectBinding?.cwd || '')}，启动 Codex 时自动用它">本项目</span>`
      : '';

    const actionItems = [{
      label: getChRowBalanceToggleLabel(r),
      icon: isChRowBalanceVisible(r) ? 'eyeOff' : 'eye',
      attrs: `data-ch-row-balance-toggle="${safeEscape(r.key)}"`,
    }];
    if (r.kind === 'codex-oauth-profile') {
      actionItems.push(
        { label: '重命名', icon: 'edit', attrs: `data-ch-oauth-rename="${safeEscape(r.profileId || '')}"` },
        { label: '删除账号', icon: 'delete', danger: true, attrs: `data-ch-oauth-delete="${safeEscape(r.profileId || '')}"` },
      );
    } else if (r.kind === 'codex-oauth-unsaved') {
      actionItems.push({ label: '保存为 OAuth Profile', icon: 'save', primary: true, attrs: 'data-ch-oauth-save-current="1"' });
    } else if (r.kind === 'claudecode-oauth-profile') {
      actionItems.push(
        { label: '复制 export 命令', icon: 'copy', attrs: `data-ch-cc-oauth-copy-export="${safeEscape(r.profileId || '')}"` },
        { label: '重命名', icon: 'edit', attrs: `data-ch-cc-oauth-rename="${safeEscape(r.profileId || '')}"` },
        { label: '重新登录', icon: 'login', attrs: `data-ch-cc-oauth-relogin="${safeEscape(r.profileId || '')}"` },
        { label: '删除账号', icon: 'delete', danger: true, attrs: `data-ch-cc-oauth-delete="${safeEscape(r.profileId || '')}"` },
      );
    } else if (r.kind === 'claudecode-oauth-default') {
      // 默认行的 "copy export" 实际上是 unset —— 贴到终端后那个会话会回到
      // 读取 ~/.claude/ 的默认路径。profileId 传空字符串作为标记。
      actionItems.push({ label: '复制 unset 命令', icon: 'copy', attrs: 'data-ch-cc-oauth-copy-export=""' });
    } else {
      // API-key provider rows — edit / detect / delete. Bind 操作 moved to
      // 详情 drawer 的「📌 项目绑定」tab — 行内图标按钮太隐晦，需要场景解释。
      const canDelete = r.kind === 'codex-apikey' || r.kind === 'claudecode-apikey';
      if (canOpenChRowRecharge(r)) {
        actionItems.push({ label: '充值', icon: 'recharge', attrs: `data-ch-row-recharge="${safeEscape(r.key)}"` });
      }
      actionItems.push(
        { label: '编辑', icon: 'edit', attrs: `data-ch-row-edit="${safeEscape(r.key)}"` },
        { label: '重检', icon: 'refresh', attrs: `data-ch-row-detect="${safeEscape(r.key)}"` },
      );
      if (canDelete) {
        actionItems.push({ label: '删除 Provider', icon: 'delete', danger: true, attrs: `data-ch-row-delete="${safeEscape(r.key)}" data-ch-row-delete-kind="${safeEscape(r.kind)}"` });
      }
    }

    const actions = renderChRowActionMenu(r, actionItems);
    const planPill = r.plan ? renderOauthPlanPill(r.plan) : '';
    const balanceChip = renderChRowBalance(r);

    return `
      <div class="ch-row ${r.isActive ? 'current' : ''} ${isBound ? 'is-project-bound' : ''}" role="listitem" data-ch-key="${safeEscape(r.key)}" tabindex="0">
        <span class="ch-row-dot ${dotCls}" title="${safeEscape(dotTip)}" aria-label="${safeEscape(statusTxt || '状态')}"></span>
        <span class="ch-row-body">
          <span class="ch-row-title">
            <span class="ch-row-name">${safeEscape(r.name)}</span>
            ${planPill}
            ${boundPin}
          </span>
          <span class="ch-row-meta">
            ${r.model ? `<span class="ch-row-model">${safeEscape(r.model)}</span>` : ''}
            ${r.baseUrl ? `<span class="ch-row-url">${safeEscape(r.baseUrl)}</span>` : ''}
          </span>
        </span>
        <span class="ch-row-status" title="${safeEscape(dotTip)}">${balanceChip}</span>
        <span class="ch-row-actions">${actions}
        </span>
      </div>`;
  }

  function renderListHTML(rows) {
    const s = hubState();
    const tool = s?.activeTool || 'codex';
    const filter = s?.chFilter || 'all';
    const oauth = rows.filter((r) => r.mode === 'oauth');
    const apikey = rows.filter((r) => r.mode === 'apikey');
    const pieces = [];

    // For Codex / ClaudeCode we render the OAuth group header outside the API
    // Key filter, even when empty, so browser authorization stays discoverable.
    const showOauthGroup = filter !== 'apikey' && (oauth.length || tool === 'codex' || tool === 'claudecode');
    if (showOauthGroup) {
      let addBtn = '';
      if (tool === 'codex') {
        addBtn = `<button type="button" class="ch-group-head-add" data-ch-oauth-add title="浏览器授权新增 OAuth 账号 (codex login)" aria-label="浏览器授权新增 OAuth 账号">
             <svg width="11" height="11" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><path d="M8 3v10M3 8h10"/></svg>
             <span class="ch-group-head-add-label">浏览器授权</span>
           </button>`;
      } else if (tool === 'claudecode') {
        addBtn = `<button type="button" class="ch-group-head-add" data-ch-cc-oauth-add title="浏览器授权新增 Claude 账号 (claude auth login)" aria-label="浏览器授权新增 Claude 账号">
             <svg width="11" height="11" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><path d="M8 3v10M3 8h10"/></svg>
             <span class="ch-group-head-add-label">浏览器授权</span>
           </button>`;
      }
      pieces.push(`<div class="ch-group-head"><span class="ch-group-head-text">OAUTH<span class="count">· ${oauth.length}</span></span>${addBtn}</div>`);
      if (oauth.length) pieces.push(oauth.map(rowHTML).join(''));
    }

    if (apikey.length) {
      pieces.push(`<div class="ch-group-head">API KEY<span class="count">· ${apikey.length}</span></div>`);
      pieces.push(apikey.map(rowHTML).join(''));
    }
    if (!pieces.length) {
      const noun = (tool === 'claudecode' && filter !== 'apikey') ? '账号' : 'provider';
      return `<div class="ch-list-empty">没有匹配的 ${noun}</div>`;
    }
    return pieces.join('');
  }

  function updateRibbonCounts(allRows) {
    const all = allRows.length;
    const oauth = allRows.filter((r) => r.mode === 'oauth').length;
    const apikey = allRows.filter((r) => r.mode === 'apikey').length;
    document.querySelectorAll('#chRibbon [data-count]').forEach((el) => {
      const k = el.dataset.count;
      const n = k === 'all' ? all : k === 'oauth' ? oauth : apikey;
      el.textContent = String(n);
    });
  }

  // ── Public render entry ────────────────────────────────────────
  function renderConnectionHub() {
    const hub = document.getElementById('connectionHub');
    if (!hub) return;
    const heroEl = document.getElementById('chHero');
    const listEl = document.getElementById('chList');
    const emptyEl = document.getElementById('chEmpty');
    const toolTitleEl = document.getElementById('chTitleTool');
    const s = hubState();
    if (!s || !heroEl || !listEl) return;

    const tool = s.activeTool || 'codex';
    if (toolTitleEl) toolTitleEl.textContent = TOOL_LABELS[tool] || tool;
    syncPrimaryAddUi();
    applyAutodetectUi(readAutodetectInterval());

    // Shell 集成 banner is self-hiding on non-claudecode tabs / non-unix
    // platforms; safe to call unconditionally before the loading short-circuit.
    renderShellIntegrationPanel();

    // Loading sentinel: if the OAuth profile fetch for this tool hasn't
    // resolved yet, render an explicit loading state instead of either (a)
    // guessing with stale cached data or (b) showing a misleading empty
    // "还没有激活的 Provider" hero. Honest over snappy.
    const codexLoaded = Boolean(window.__chOauthProfiles && window.__chOauthProfiles.loaded);
    const claudeLoaded = Boolean(window.__chClaudeOauthProfiles && window.__chClaudeOauthProfiles.loaded);
    const isLoading = (tool === 'codex' && !codexLoaded) || (tool === 'claudecode' && !claudeLoaded);
    if (isLoading) {
      heroEl.classList.add('empty');
      heroEl.innerHTML = `
        <div class="ch-hero-info">
          <div class="ch-hero-eyebrow"><span>CURRENT SESSION</span></div>
          <div class="ch-hero-empty-title">加载中…</div>
          <div class="ch-hero-empty-sub">从本地配置读取 OAuth 状态…</div>
        </div>`;
      listEl.innerHTML = '<div class="ch-list-empty">加载中…</div>';
      updateRibbonCounts([]);
      if (emptyEl) emptyEl.classList.add('hide');
      return;
    }

    const allRows = buildProviderRows(tool);
    updateRibbonCounts(allRows);
    applyAutodetectUi(readAutodetectInterval());
    applyChBalanceRefreshUi(allRows);

    // Apply search + filter
    const search = (s.chSearch || '').trim().toLowerCase();
    const filter = s.chFilter || 'all';
    const filtered = allRows.filter((r) => {
      if (filter === 'oauth' && r.mode !== 'oauth') return false;
      if (filter === 'apikey' && r.mode !== 'apikey') return false;
      if (!search) return true;
      const hay = [r.name, r.baseUrl, r.model, r.key].filter(Boolean).join(' ').toLowerCase();
      return hay.includes(search);
    });

    const active = allRows.find((r) => r.isActive) || null;
    heroEl.innerHTML = renderHeroHTML(active, tool);
    heroEl.classList.toggle('empty', !active);
    listEl.innerHTML = renderListHTML(filtered);

    if (emptyEl) emptyEl.classList.toggle('hide', allRows.length > 0);

    // 如果在 detail 模式，把详情页也 render 出来
    const hubEl = document.getElementById('connectionHub');
    if (state.providerDetail?.open) {
      if (hubEl) hubEl.classList.add('ch-detail-on');
      const detailEl = document.getElementById('chDetail');
      if (detailEl) detailEl.classList.remove('hide');
      ensureProviderDetailEvents();
      renderProviderDetail();
    } else {
      if (hubEl) hubEl.classList.remove('ch-detail-on');
      const detailEl = document.getElementById('chDetail');
      if (detailEl) { detailEl.classList.remove('is-in'); detailEl.classList.add('hide'); }
    }

    // 懒加载每条 API key 行的 24h uptime（5 分钟缓存）
    fetchRowUptimeSummaries(allRows.filter((r) => r.tool === 'codex' && r.mode === 'apikey' && !r.historyOnly));

    // 同步托盘菜单（每次 hub 重渲染时 push 最新 provider 列表）
    try { if (typeof trayHookOnHubRender === 'function') trayHookOnHubRender(); } catch (_) {}
  }

  async function fetchRowUptimeSummaries(rows) {
    if (!Array.isArray(rows) || !rows.length) return;
    rows = rows.filter((r) => r.tool === 'codex' && r.mode === 'apikey' && !r.historyOnly);
    if (!rows.length) return;
    const codexHome = state.current?.codexHome || '';
    const FRESH_MS = 5 * 60 * 1000;
    const now = Date.now();
    const todo = rows.filter((r) => {
      const cached = state.providerUptime[r.key];
      return !cached || (now - (cached.fetchedAt || 0) > FRESH_MS);
    });
    if (!todo.length) return;
    await Promise.all(todo.map(async (r) => {
      try {
        const params = new URLSearchParams({ providerKey: r.key, codexHome, windowHours: '24' });
        const res = await api(`/api/provider/probe-summary?${params.toString()}`);
        if (res?.ok && res.data) {
          state.providerUptime[r.key] = {
            uptimePct: res.data.uptimePct,
            total: res.data.total,
            fetchedAt: now,
          };
        } else {
          state.providerUptime[r.key] = { uptimePct: null, total: 0, fetchedAt: now };
        }
      } catch (_) {
        state.providerUptime[r.key] = { uptimePct: null, total: 0, fetchedAt: now };
      }
    }));
    // 数据回来后同步列表和顶部当前会话卡片，让 SLA 标签保持最新。
    const listEl = document.getElementById('chList');
    const search = (hubState()?.chSearch || '').trim().toLowerCase();
    const filter = hubState()?.chFilter || 'all';
    const tool = hubState()?.activeTool || 'codex';
    const all = buildProviderRows(tool);
    if (listEl) {
      const filteredAgain = all.filter((r) => {
        if (filter === 'oauth' && r.mode !== 'oauth') return false;
        if (filter === 'apikey' && r.mode !== 'apikey') return false;
        if (!search) return true;
        const hay = [r.name, r.baseUrl, r.model, r.key].filter(Boolean).join(' ').toLowerCase();
        return hay.includes(search);
      });
      listEl.innerHTML = renderListHTML(filteredAgain);
    }
    const heroEl = document.getElementById('chHero');
    if (heroEl) {
      const active = all.find((r) => r.isActive) || null;
      heroEl.innerHTML = renderHeroHTML(active, tool);
      heroEl.classList.toggle('empty', !active);
    }
  }

  // ── Interactions ────────────────────────────────────────────────
  // Populate the underlying form with a provider's current values WITHOUT saving.
  // The user can then edit and hit 保存配置 to apply; a save also re-activates
  // that provider, so "click row → edit → save" is the one-click switch path.
  function loadProviderIntoForm(key) {
    if (!key) return null;
    const s = hubState();
    if (!s) return null;
    const tool = s.activeTool || 'codex';
    if (tool === 'codex') {
      if (key === '__codex_official_oauth__') return null;
      if (key === '__codex_oauth_unsaved__' || key.startsWith('__codex_oauth_profile:')) return null;
      const p = (s.current?.providers || []).find((x) => x.key === key);
      if (p && typeof fillFromProvider === 'function') {
        try { fillFromProvider(p); } catch (err) { console.warn('[ch] fillFromProvider failed', err); }
      }
      return p || null;
    }
    if (tool === 'claudecode') {
      if (key === '__claudecode_oauth_default__' || key.startsWith('__claudecode_oauth_profile:')) return null;
      const profiles = typeof getClaudeProviderProfiles === 'function' ? getClaudeProviderProfiles(s.claudeCodeState) : [];
      const p = (profiles || []).find((x) => x.key === key) || null;
      if (p && typeof fillFromClaudeProvider === 'function') {
        try { fillFromClaudeProvider(p); } catch (err) { console.warn('[ch] fillFromClaudeProvider failed', err); }
      }
      return p;
    }
    if (tool === 'opencode') {
      return ((s.opencodeState?.providers) || []).find((x) => x.key === key) || null;
    }
    return null;
  }

  function openSlideover(mode, providerKey) {
    const so = document.getElementById('chSlideover');
    if (!so) return;

    // OAuth mode is chosen at the outer-list level; inside the drawer we only
    // ever show the API-Key form. Pin the state + rerun the form visibility
    // sync (hides the now-invisible auth block but unhides URL / Key fields).
    const s = hubState();
    const activeTool = s?.activeTool || 'codex';
    let effectiveProviderKey = String(providerKey || '').trim();
    if (mode === 'edit' && !effectiveProviderKey) {
      const rows = buildProviderRows(activeTool);
      const activeApiKey = rows.find((row) => row.isActive && row.mode === 'apikey');
      effectiveProviderKey = activeApiKey?.key || '';
    }
    if (s) s.editingKey = mode === 'edit' ? effectiveProviderKey : '';

    if (s && activeTool === 'codex') {
      s.codexAuthView = 'api_key';
      if (typeof syncCodexAuthView === 'function') {
        try { syncCodexAuthView(); } catch (_) {}
      }
    }

    so.classList.remove('hide');
    // Two rAFs so the initial display:block commits before .open animates in
    requestAnimationFrame(() => requestAnimationFrame(() => so.classList.add('open')));
    so.setAttribute('aria-hidden', 'false');
    document.body.classList.add('ch-so-active');
    const title = document.getElementById('chSlideoverTitle');

    // 内联 !important — CSS 优先级最高，无视任何遗留 !important 规则
    const setImp2 = (e, kvs) => {
      if (!e) return;
      for (const [k, v] of Object.entries(kvs)) e.style.setProperty(k, v, 'important');
    };
    const lockBox = (id, extra = {}) => {
      const e = document.getElementById(id);
      if (!e) return;
      setImp2(e, {
        height: '40px',
        'min-height': '40px',
        'max-height': '40px',
        'box-sizing': 'border-box',
        'padding-top': '0',
        'padding-bottom': '0',
        margin: '0',
        'vertical-align': 'middle',
        'line-height': '38px',
        ...extra,
      });
    };
    lockBox('baseUrlInput', { 'padding-left': '12px', 'padding-right': '12px' });
    lockBox('apiKeyInput', { 'padding-left': '12px', 'padding-right': '36px' });
    lockBox('modelSelect', { 'padding-left': '12px', 'padding-right': '28px' });
    lockBox('modelRefreshBtn', {
      width: '40px', padding: '0',
      display: 'inline-flex',
      'align-items': 'center',
      'justify-content': 'center',
      'line-height': '1',
    });

    // password 眼睛按钮也居中
    setImp2(document.querySelector('.password-toggle-btn'), {
      position: 'absolute',
      top: '50%',
      right: '4px',
      transform: 'translateY(-50%)',
      width: '24px',
      height: '24px',
    });

    if (mode === 'edit' && effectiveProviderKey) {
      const provider = loadProviderIntoForm(effectiveProviderKey);
      if (title) title.textContent = provider ? `编辑 · ${provider.name || provider.key}` : '编辑 Provider';
    } else if (mode === 'add') {
      if (title) title.textContent = '新增 Provider';
      if (s) s.editingKey = '';
      const urlEl = document.getElementById('baseUrlInput');
      const keyEl = document.getElementById('apiKeyInput');
      const providerKeyEl = document.getElementById('claudeProviderKeyInput');
      if (urlEl) urlEl.value = '';
      if (keyEl) keyEl.value = '';
      if (activeTool === 'claudecode') {
        if (providerKeyEl) providerKeyEl.value = '';
        if (s) s.claudeSelectedProviderKey = '';
      }
      setTimeout(() => urlEl && urlEl.focus(), 260);
    } else if (title) {
      title.textContent = '编辑 Provider';
    }
  }

  function closeSlideover() {
    const so = document.getElementById('chSlideover');
    if (!so) return;
    so.classList.remove('open');
    so.setAttribute('aria-hidden', 'true');
    setTimeout(() => so.classList.add('hide'), 220);
    document.body.classList.remove('ch-so-active');
  }

  // ── Codex OAuth profile store (remote) ─────────────────────────
  // Cache layout: { loaded: bool, data: {active, profiles, live, liveHasUnsavedTokens} }
  window.__chOauthProfiles = window.__chOauthProfiles || { loaded: false, data: null };

  async function loadCodexOauthProfiles(opts) {
    const allowAutoSave = !(opts && opts.skipAutoSave);
    const params = new URLSearchParams({
      codexHome: getDashboardCodexHome(),
    });
    try {
      const res = await api(`/api/codex/oauth/profiles?${params.toString()}`, { method: 'GET' });
      if (!res || !res.ok) {
        window.__chOauthProfiles = { loaded: true, data: { active: '', profiles: [], live: {}, liveHasUnsavedTokens: false } };
        renderConnectionHub();
        return;
      }
      window.__chOauthProfiles = { loaded: true, data: res.data || {} };
    } catch (err) {
      console.warn('[ch] load oauth profiles failed', err);
      window.__chOauthProfiles = { loaded: true, data: { active: '', profiles: [], live: {}, liveHasUnsavedTokens: false } };
      renderConnectionHub();
      return;
    }

    // Auto-save: if the live auth.json has OAuth tokens that aren't mapped to
    // any saved profile yet, snapshot it silently. The backend picks a sensible
    // default name (email / "OAuth (PLAN)"); user can rename via ✏ later.
    // Re-entrancy guarded by opts.skipAutoSave so the post-save reload doesn't
    // loop.
    if (allowAutoSave && window.__chOauthProfiles.data?.liveHasUnsavedTokens) {
      try {
        const saveRes = await api('/api/codex/oauth/profiles/save-current', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            name: '',
            codexHome: getDashboardCodexHome(),
          }),
        });
        if (saveRes?.ok) {
          if (typeof flash === 'function') flash('已自动保存官方登录为 OAuth profile', 'success');
          await loadCodexOauthProfiles({ skipAutoSave: true });
          return;
        }
      } catch (err) {
        console.warn('[ch] auto-save oauth profile failed', err);
      }
    }

    renderConnectionHub();
  }

  async function deleteApiKeyProvider(key, kind) {
    if (!key) return;
    const s = hubState();
    const rows = buildProviderRows(s?.activeTool || 'codex');
    const row = rows.find((r) => r.key === key);
    const nameForPrompt = row?.name || key;
    const confirmed = window.confirm(`删除 provider「${nameForPrompt}」？\n会同时清掉配置里的 baseUrl / API Key，不可恢复。`);
    if (!confirmed) return;

    try {
      if (kind === 'codex-apikey') {
        const res = await api('/api/config/delete-provider', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            providerKey: key,
            codexHome: s?.current?.codexHome || '',
            scope: document.getElementById('scopeSelect')?.value || 'global',
          }),
        });
        if (!res || !res.ok) {
          flash?.(res?.error || '删除失败', 'error');
          return;
        }
        if (typeof removeCodexProviderHistoryItem === 'function') {
          removeCodexProviderHistoryItem({ key, baseUrl: row?.baseUrl || '' });
        }
        flash?.('已删除 provider', 'success');
        if (typeof loadState === 'function') await loadState({ preserveForm: false });
      } else if (kind === 'claudecode-apikey') {
        const res = await api('/api/claudecode/provider-delete', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ providerKey: key }),
        });
        if (!res || !res.ok) {
          flash?.(res?.error || '删除失败', 'error');
          return;
        }
        flash?.('已删除 provider', 'success');
        if (typeof loadClaudeCodeState === 'function') await loadClaudeCodeState();
      }
    } catch (err) {
      console.warn('[ch] delete provider failed', err);
      flash?.('删除失败', 'error');
    }
  }

  async function reloadCodexStateThenHub() {
    try {
      if (typeof loadState === 'function') await loadState();
    } catch (err) {
      console.warn('[ch] loadState failed', err);
    }
    await loadCodexOauthProfiles();
  }


  async function activateCurrentCodexOauth(codexHome = '') {
    if (!(await confirmOauthIpRiskBeforeRequest('切换到当前 Codex OAuth'))) return false;
    const targetHome = codexHome || getDashboardCodexHome();
    if (targetHome && el('codexHomeInput')) {
      el('codexHomeInput').value = targetHome;
    }
    const cleared = await api('/api/config/use-oauth', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        scope: el('scopeSelect')?.value || 'global',
        projectPath: el('projectPathInput')?.value?.trim() || '',
        codexHome: targetHome,
      }),
    });
    if (!cleared || !cleared.ok) {
      if (typeof flash === 'function') flash(cleared?.error || '切换 OAuth 模式失败', 'error');
      return false;
    }
    try {
      if (typeof loadState === 'function') await loadState({ preserveForm: false });
    } catch (err) {
      console.warn('[ch] activate oauth loadState failed', err);
    }
    await loadCodexOauthProfiles({ skipAutoSave: true });
    try {
      await refreshDashboardData({ force: true, silent: true, tool: 'codex' });
    } catch (err) {
      console.warn('[ch] activate oauth refreshDashboardData failed', err);
    }
    if (typeof flash === 'function') flash('已切换到官方 OAuth', 'success');
    return true;
  }

  async function saveCurrentOauthAsProfile() {
    if (!(await confirmOauthIpRiskBeforeRequest('保存 Codex OAuth profile'))) return;
    const defaultName = (() => {
      const d = window.__chOauthProfiles?.data;
      const live = d?.live || {};
      if (live.email) return live.email;
      if (live.plan) return `OAuth (${String(live.plan).toUpperCase()})`;
      return '';
    })();
    const name = window.prompt('给这个 OAuth 账号起个名字（可留空自动命名）', defaultName || '') ;
    if (name === null) return; // cancelled
    const res = await api('/api/codex/oauth/profiles/save-current', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        name: name.trim(),
        codexHome: getDashboardCodexHome(),
      }),
    });
    if (!res || !res.ok) {
      if (typeof flash === 'function') flash(res?.error || '保存 OAuth profile 失败', 'error');
      return;
    }
    if (typeof flash === 'function') flash('已保存为 OAuth profile', 'success');
    await loadCodexOauthProfiles();
    return res.data || {};
  }

  async function switchOauthProfile(id) {
    if (!id) return;
    if (!(await confirmOauthIpRiskBeforeRequest('切换 Codex OAuth 账号'))) return;
    const res = await api('/api/codex/oauth/profiles/switch', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id }),
    });
    if (!res || !res.ok) {
      if (typeof flash === 'function') flash(res?.error || '切换 OAuth 账号失败', 'error');
      return;
    }
    const nextCodexHome = res.data?.codexHome || '';
    if (nextCodexHome && el('codexHomeInput')) {
      el('codexHomeInput').value = nextCodexHome;
    }
    // OAuth mode must not leave a model_provider pointer active in this
    // profile's config.toml, otherwise Codex will still use the API-Key
    // provider even though the UI row was switched to an OAuth account.
    if (nextCodexHome) {
      const cleared = await api('/api/config/use-oauth', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          scope: el('scopeSelect')?.value || 'global',
          projectPath: el('projectPathInput')?.value?.trim() || '',
          codexHome: nextCodexHome,
        }),
      });
      if (!cleared || !cleared.ok) {
        if (typeof flash === 'function') flash(cleared?.error || '切换 OAuth 模式失败', 'error');
        return;
      }
    }
    if (typeof flash === 'function') flash('已切换 OAuth 账号', 'success');
    try {
      if (typeof loadState === 'function') await loadState({ preserveForm: false });
    } catch (err) {
      console.warn('[ch] post-switch loadState failed', err);
    }
    await loadCodexOauthProfiles({ skipAutoSave: true });
    try {
      await refreshDashboardData({ force: true, silent: true, tool: 'codex' });
    } catch (err) {
      console.warn('[ch] post-switch refreshDashboardData failed', err);
    }
  }

  async function renameOauthProfile(id) {
    if (!id) return;
    const current = (window.__chOauthProfiles?.data?.profiles || []).find((p) => p.id === id);
    const name = window.prompt('新的名字', current?.name || '');
    if (name == null) return;
    const trimmed = name.trim();
    if (!trimmed) return;
    const res = await api('/api/codex/oauth/profiles/rename', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id, name: trimmed }),
    });
    if (!res || !res.ok) {
      if (typeof flash === 'function') flash(res?.error || '重命名失败', 'error');
      return;
    }
    await loadCodexOauthProfiles();
  }

  async function deleteOauthProfile(id) {
    if (!id) return;
    const confirmed = window.confirm('删除该 OAuth profile（只删除我们存储的副本，不会登出 ChatGPT）？');
    if (!confirmed) return;
    const res = await api('/api/codex/oauth/profiles/delete', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id }),
    });
    if (!res || !res.ok) {
      if (typeof flash === 'function') flash(res?.error || '删除失败', 'error');
      return;
    }
    if (typeof flash === 'function') flash('已删除该 profile', 'success');
    await loadCodexOauthProfiles();
  }

  async function addNewOauthAccount() {
    if (!(await confirmOauthIpRiskBeforeRequest('新增 Codex OAuth 账号'))) return;
    const go = await openUpdateDialog({
      eyebrow: 'Codex OAuth',
      title: '新增官方 OAuth 账号',
      body: updateLines([
        '将创建一个独立的 Codex profile 目录（独立 CODEX_HOME）。',
        '随后会在终端里用该目录执行 codex login。',
        '浏览器授权完成后，这里会自动显示并切到新账号。',
        '整个过程不会覆盖你当前账号的 auth、history 或 sessions。',
      ]),
      confirmText: '继续登录',
      cancelText: '取消',
    });
    if (!go) return;

    const createRes = await api('/api/codex/oauth/profiles/create', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name: '' }),
    });
    if (!createRes || !createRes.ok) {
      if (typeof flash === 'function') flash(createRes?.error || '创建 Codex profile 失败', 'error');
      return;
    }
    const newId = createRes.data?.id;
    const newHome = createRes.data?.codexHome || '';
    if (!newId || !newHome) {
      if (typeof flash === 'function') flash('创建 Codex profile 失败', 'error');
      return;
    }

    try {
      if (typeof launchCodexLogin === 'function') {
        const ok = await launchCodexLogin('', '', newHome);
        if (!ok) {
          await api('/api/codex/oauth/profiles/delete', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ id: newId }),
          });
          return;
        }
      } else {
        if (typeof flash === 'function') flash('未找到 codex login 启动器', 'error');
        return;
      }
    } catch (err) {
      console.warn('[ch] launchCodexLogin failed', err);
    }

    if (typeof flash === 'function') flash('已在终端打开 codex login。完成浏览器授权后会自动切到新账号。', 'info');

    let tries = 0;
    const pollId = setInterval(async () => {
      tries += 1;
      await loadCodexOauthProfiles({ skipAutoSave: true });
      const prof = (window.__chOauthProfiles?.data?.profiles || []).find((p) => p.id === newId);
      if (prof && prof.hasTokens) {
        clearInterval(pollId);
        await switchOauthProfile(newId);
      } else if (tries >= 72) {
        clearInterval(pollId);
        try {
          await api('/api/codex/oauth/profiles/delete', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ id: newId }),
          });
          if (typeof flash === 'function') flash('登录超时未完成，已清理这个空 profile。', 'info');
          await loadCodexOauthProfiles({ skipAutoSave: true });
        } catch (e) {
          console.warn('[ch] orphan codex oauth profile cleanup failed', e);
        }
      }
    }, 2500);
  }

  // ── Shell 集成 · Claude Code account follower ─────────────────
  // Backend owns the truth (scans ~/.zshrc / ~/.bash_profile / ~/.bashrc for
  // our marker block). Frontend holds a lazy-loaded cache so the banner can
  // render synchronously on tab switch; first render kicks off the fetch.
  //
  // Why here (inside the CH closure): renderShellIntegrationPanel is called
  // from renderConnectionHub, so it must be in the same scope. The toggle
  // wiring lives here too — no module-level exports needed, no extra globals.
  window.__chShellIntegration = window.__chShellIntegration || { loaded: false, pending: false, data: null };

  async function loadShellIntegrationStatus() {
    try {
      const res = await api('/api/shell-integration/status', { method: 'GET' });
      window.__chShellIntegration = {
        loaded: true,
        pending: false,
        data: res?.ok ? (res.data || null) : null,
      };
    } catch (err) {
      console.warn('[ch] load shell-integration status failed', err);
      window.__chShellIntegration = { loaded: true, pending: false, data: null };
    }
    renderShellIntegrationPanel();
  }

  async function setShellIntegrationEnabled(enabled) {
    const path = enabled ? '/api/shell-integration/enable' : '/api/shell-integration/disable';
    const res = await api(path, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({}),
    });
    if (!res || !res.ok) {
      if (typeof flash === 'function') flash(res?.error || (enabled ? '启用 Shell 集成失败' : '关闭 Shell 集成失败'), 'error');
      // Reload to sync UI back to reality on failure.
      await loadShellIntegrationStatus();
      return false;
    }
    const nextStatus = res.data?.status || null;
    window.__chShellIntegration = { loaded: true, pending: false, data: nextStatus };

    if (enabled) {
      const applied = Array.isArray(res.data?.applied) ? res.data.applied : [];
      const envPath = nextStatus?.envScriptPath || '~/.codex-config-ui/shell-env.sh';
      if (applied.length) {
        if (typeof flash === 'function') {
          flash(
            `已启用 Shell 集成 · 写入 ${applied.join(', ')}\n新开终端立即生效；当前终端请执行一次：source ${envPath}`,
            'success'
          );
        }
      } else if (typeof flash === 'function') {
        flash('已启用但未找到可写入的 rc 文件（.zshrc / .bash_profile / .bashrc 都不存在）', 'warning');
      }
    } else if (typeof flash === 'function') {
      flash('已关闭 Shell 集成（新开终端的 claude 恢复到默认 ~/.claude/）', 'info');
    }
    renderShellIntegrationPanel();
    return true;
  }

  function renderShellIntegrationPanel() {
    const el = document.getElementById('chShellIntegration');
    if (!el) return;
    const s = hubState();
    const tool = s?.activeTool || 'codex';
    if (tool !== 'claudecode') {
      el.classList.add('hide');
      el.innerHTML = '';
      return;
    }

    // Lazy-load on first ever render (per session).
    const cache = window.__chShellIntegration;
    if (!cache.loaded && !cache.pending) {
      cache.pending = true;
      // Intentionally not awaited — first paint shows "检测中…", subsequent
      // paint triggered by loadShellIntegrationStatus() shows real state.
      loadShellIntegrationStatus();
    }

    if (!cache.loaded) {
      el.classList.remove('hide');
      el.innerHTML = `
        <span class="ch-shellint-icon">⚡</span>
        <div class="ch-shellint-body">
          <div class="ch-shellint-title">Shell 集成 · 让所有终端里的 claude 跟随本 UI 账号</div>
          <div class="ch-shellint-sub muted">检测中…</div>
        </div>
        <label class="ch-shellint-toggle" aria-disabled="true">
          <input type="checkbox" disabled>
          <span class="ch-shellint-toggle-track" aria-hidden="true"></span>
        </label>`;
      return;
    }

    const data = cache.data || {};
    if (data.platform !== 'unix') {
      // Windows / unsupported — hide entirely; feature isn't implemented.
      el.classList.add('hide');
      el.innerHTML = '';
      return;
    }

    el.classList.remove('hide');
    const enabled = Boolean(data.enabled);
    const shells = Array.isArray(data.shells) ? data.shells : [];
    const injectedNames = shells.filter((x) => x.injected).map((x) => x.name);
    const hasActive = Boolean(data.activeProfileDir);
    const envPath = data.envScriptPath || '~/.codex-config-ui/shell-env.sh';

    let subHtml;
    if (enabled) {
      const writtenInto = injectedNames.length
        ? injectedNames.map((n) => `<code>${n}</code>`).join(' · ')
        : '<span class="muted">无注入的 rc</span>';
      const account = hasActive
        ? '<span class="ok">✓ 新开终端自动使用 UI 选中的账号</span>'
        : '<span class="muted">当前未选中账号，新终端走默认 ~/.claude/</span>';
      subHtml = `已启用 · ${writtenInto}<br>${account}`;
    } else {
      const availableToInject = shells.filter((x) => x.rcExists).length;
      if (availableToInject === 0) {
        subHtml = '未检测到 <code>.zshrc</code> / <code>.bash_profile</code> / <code>.bashrc</code>，无法启用。';
      } else {
        subHtml = `关闭中 · 其他终端里的 <code>claude</code> 只会使用默认账号 <code>~/.claude/</code>。<br><span class="muted">开启后将在 rc 文件里注入带标记的引导代码（可随时一键移除）。</span>`;
      }
    }

    el.innerHTML = `
      <span class="ch-shellint-icon">⚡</span>
      <div class="ch-shellint-body">
        <div class="ch-shellint-title">Shell 集成 · 让所有终端里的 claude 跟随本 UI 账号</div>
        <div class="ch-shellint-sub">${subHtml}</div>
      </div>
      <label class="ch-shellint-toggle" title="${enabled ? '关闭' : '启用'} Shell 集成">
        <input type="checkbox" id="chShellIntToggle" ${enabled ? 'checked' : ''}>
        <span class="ch-shellint-toggle-track" aria-hidden="true"></span>
      </label>`;

    const toggle = el.querySelector('#chShellIntToggle');
    if (!toggle) return;
    toggle.addEventListener('change', async (e) => {
      const target = Boolean(e.target.checked);
      // Block double-fire while the request is in flight.
      toggle.disabled = true;
      try {
        if (target && !enabled) {
          const msg = [
            '启用 Shell 集成会做两件事：',
            '',
            '1) 在 ~/.codex-config-ui/shell-env.sh 写入一个"读取当前选中账号并 export CLAUDE_CONFIG_DIR"的小脚本',
            '2) 在你的 .zshrc / .bash_profile / .bashrc（已存在的那几个）末尾追加一段带 BEGIN/END 标记的 source 引导',
            '',
            '修改前会自动备份到 ~/.codex-config-ui/rc-backups/',
            '任何时候关闭开关都会干净移除这些改动。',
            '',
            '继续？',
          ].join('\n');
          if (!window.confirm(msg)) {
            toggle.checked = false;
            return;
          }
        }
        await setShellIntegrationEnabled(target);
      } finally {
        toggle.disabled = false;
      }
    });
  }

  // ── Claude Code OAuth profile store ─────────────────────────────
  // Single source of truth: the backend reads
  //   ~/.codex-config-ui/claudecode-oauth-profiles/profiles.json
  //   + ~/.claude/.claude.json + macOS Keychain entry for the default dir.
  // We hold the last-good response in a module-scoped cache so repeat
  // renders during the same session don't re-fetch. When the cache is
  // `loaded: false` the hub renders a "loading" state instead of guessing
  // — no localStorage, no optimistic rendering.
  window.__chClaudeOauthProfiles = window.__chClaudeOauthProfiles || { loaded: false, data: null };

  async function loadClaudeCodeOauthProfiles() {
    try {
      const res = await api('/api/claudecode/oauth/profiles', { method: 'GET' });
      if (!res || !res.ok) {
        window.__chClaudeOauthProfiles = { loaded: true, data: { active: '', profiles: [], lastSwitchAt: 0 } };
      } else {
        window.__chClaudeOauthProfiles = { loaded: true, data: res.data || {} };
      }
    } catch (err) {
      console.warn('[ch] load claudecode oauth profiles failed', err);
      window.__chClaudeOauthProfiles = { loaded: true, data: { active: '', profiles: [], lastSwitchAt: 0 } };
    }
    // 陈年孤儿清理:后端标 isStale=true 的 profile(15 分钟前建的还没拿到 token),
    // 静默批量删除 —— 让跨 UI session 的脏数据能收敛,不依赖"同一次 poll 的
    // setInterval 存活"。加 __stale_sweep_running 哨兵防止首次 list 刚回来又
    // 触发 render 引发的重复 sweep。
    const data = window.__chClaudeOauthProfiles?.data;
    const staleIds = (data?.profiles || []).filter((p) => p.isStale).map((p) => p.id);
    if (staleIds.length && !window.__chStaleSweepRunning) {
      window.__chStaleSweepRunning = true;
      try {
        for (const id of staleIds) {
          await deleteClaudeCodeOauthProfile(id, { force: true, silent: true });
        }
        if (typeof flash === 'function') {
          flash(`已清理 ${staleIds.length} 个未完成登录的 profile`, 'info');
        }
        // 清完再拉一次列表,避免 UI 上残留 stale 行
        const res2 = await api('/api/claudecode/oauth/profiles', { method: 'GET' });
        if (res2 && res2.ok) window.__chClaudeOauthProfiles = { loaded: true, data: res2.data || {} };
      } finally {
        window.__chStaleSweepRunning = false;
      }
    }
    renderConnectionHub();
  }

  // Switch active Claude Code OAuth identity. Empty id = back to default
  // (~/.claude/). Backend enforces a 60s throttle and refuses when a live
  // `claude` process is detected (unless force=true).
  async function switchClaudeCodeOauthProfile(id, { force = false } = {}) {
    const res = await api('/api/claudecode/oauth/profiles/switch', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id: id || '', force }),
    });
    if (!res || !res.ok) {
      // 后端用 "CLAUDE_RUNNING:<count>:<msg>" 前缀标记"有活跃进程需确认"的风险,
      // 前端识别后弹 confirm 让用户决定是否强切。
      const errMsg = String(res?.error || '');
      const running = errMsg.match(/^CLAUDE_RUNNING:(\d+):([\s\S]*)$/);
      if (running) {
        const confirmed = window.confirm(`${running[2]}\n\n点击"确定"强制切换,"取消"放弃。`);
        if (!confirmed) return;
        return switchClaudeCodeOauthProfile(id, { force: true });
      }
      if (typeof flash === 'function') flash(errMsg || '切换 Claude 账号失败', 'error');
      return;
    }
    if (typeof flash === 'function') {
      const suffix = force ? '(已忽略运行中进程)' : '';
      flash(id
        ? `已切换 Claude 账号${suffix}(下次启动 Claude Code 会使用该账号)`
        : `已切回默认 Claude 账号 (~/.claude/)${suffix}`,
        'success');
    }
    await loadClaudeCodeOauthProfiles();
    // 切换后 Dashboard 统计源头(projects/*.jsonl)变了,Connection Hub 里的
    // 登录邮箱/模型列表也变了,强制拉一次最新状态,否则 UI 还停在旧号数据。
    // 注意:Claude Code 不走 refreshDashboardData(只认 codex/opencode),走
    // ensureClaudeDashboardData → loadClaudeCodeQuickState 这条线。
    try {
      if (typeof loadClaudeCodeState === 'function') await loadClaudeCodeState();
    } catch (e) { console.warn('[ch] post-switch loadClaudeCodeState failed', e); }
    try {
      if (typeof ensureClaudeDashboardData === 'function') {
        await ensureClaudeDashboardData({ force: true });
        if (state.activePage === 'dashboard') renderDashboardPage();
      }
    } catch (e) { console.warn('[ch] post-switch ensureClaudeDashboardData failed', e); }
    invalidateConsoleV3Tool('claudecode');
    if (state.activePage === 'console' && (state.consoleTool || 'codex') === 'claudecode') {
      renderToolConsole();
    }
    // Shell 集成 banner 里显示的 activeProfileDir 变了,刷新状态让文案跟上
    // (e.g. "无选中账号" ↔ "✓ 新开终端自动使用 UI 选中的账号")
    try { await loadShellIntegrationStatus(); } catch (_) {}
  }

  // Copy a ready-to-paste shell command that flips this one terminal session
  // to the given profile — the lightweight alternative to enabling the full
  // Shell 集成 toggle. `profileId` is the empty string for "switch back to
  // default ~/.claude/" (emits `unset CLAUDE_CONFIG_DIR`).
  //
  // Clipboard API is gated behind a secure context + user activation; the
  // icon click is a user activation, and Tauri webview runs as https://tauri.
  // localhost / app:// so it counts as secure. If clipboard fails for any
  // reason (sandboxed browser preview, permissions denied), fall back to
  // `prompt()` so the user can still Ctrl/Cmd-C it out.
  async function copyClaudeExportCommand(profileId) {
    let cmd;
    if (!profileId) {
      cmd = 'unset CLAUDE_CONFIG_DIR';
    } else {
      const prof = (window.__chClaudeOauthProfiles?.data?.profiles || [])
        .find((p) => p.id === profileId);
      const dir = prof?.configDir || '';
      if (!dir) {
        if (typeof flash === 'function') flash('未找到该 profile 的配置目录', 'error');
        return;
      }
      // 双引号包住路径,容纳包含空格/特殊字符的 $HOME。用户直接粘贴即可执行。
      cmd = `export CLAUDE_CONFIG_DIR="${dir}"`;
    }
    try {
      await navigator.clipboard.writeText(cmd);
      if (typeof flash === 'function') {
        flash(profileId
          ? `已复制:\n${cmd}\n\n粘贴到任意终端后,该会话的 claude 会使用该账号`
          : `已复制:\n${cmd}\n\n粘贴到终端后,该会话会切回默认 ~/.claude/`,
          'success');
      }
    } catch (err) {
      console.warn('[ch] clipboard.writeText failed, falling back to prompt', err);
      // 回退:用 prompt 让用户手动 Cmd-C。字段自动全选,一键复制即可。
      window.prompt('自动复制失败 —— 请手动选中下方命令并复制(Cmd-C):', cmd);
    }
  }

  async function renameClaudeCodeOauthProfile(id) {
    if (!id) return;
    const current = (window.__chClaudeOauthProfiles?.data?.profiles || []).find((p) => p.id === id);
    const name = window.prompt('新的名字', current?.name || '');
    if (name == null) return;
    const trimmed = name.trim();
    if (!trimmed) return;
    const res = await api('/api/claudecode/oauth/profiles/rename', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id, name: trimmed }),
    });
    if (!res || !res.ok) {
      if (typeof flash === 'function') flash(res?.error || '重命名失败', 'error');
      return;
    }
    await loadClaudeCodeOauthProfiles();
  }

  async function deleteClaudeCodeOauthProfile(id, { force = false, silent = false } = {}) {
    if (!id) return;
    if (!force && !silent) {
      const confirmed = window.confirm('删除这个 Claude 账号 profile？\n只会删除我们保存的副本（目录 + Keychain 会留作残留，手动用 Keychain Access 清理）。\n你在 anthropic 的账号本身不受影响。');
      if (!confirmed) return;
    }
    const res = await api('/api/claudecode/oauth/profiles/delete', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id, force }),
    });
    if (!res || !res.ok) {
      const errMsg = String(res?.error || '');
      const running = errMsg.match(/^CLAUDE_RUNNING:(\d+):([\s\S]*)$/);
      if (running && !silent) {
        const confirmed = window.confirm(`${running[2]}\n\n点击"确定"强制删除,"取消"放弃。`);
        if (!confirmed) return;
        return deleteClaudeCodeOauthProfile(id, { force: true });
      }
      if (typeof flash === 'function' && !silent) flash(errMsg || '删除失败', 'error');
      return;
    }
    if (typeof flash === 'function' && !silent) flash('已删除该 profile', 'success');
    await loadClaudeCodeOauthProfiles();
  }

  async function addNewClaudeCodeOauthProfile() {
    const ok = window.confirm('接下来会：\n1) 创建一个独立的 Claude 配置目录（profile）\n2) 在终端里用该目录跑 claude auth login\n3) 你在浏览器完成授权后，token 会存到该 profile 独立的 Keychain 条目里\n\n整个过程不影响你现有的 ~/.claude/ 登录。继续？');
    if (!ok) return;

    // Pick the browser BEFORE creating the profile — if user cancels here we
    // don't leave an orphan profile dir behind.
    const browserChoice = await pickClaudeLoginBrowser({ title: '新账号登录 · 选择浏览器' });
    if (browserChoice === null) return;

    const createRes = await api('/api/claudecode/oauth/profiles/create', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name: '' }),
    });
    if (!createRes || !createRes.ok) {
      if (typeof flash === 'function') flash(createRes?.error || '创建 profile 失败', 'error');
      return;
    }
    const newId = createRes.data?.id;
    if (!newId) return;

    // Launch `CLAUDE_CONFIG_DIR=<dir> claude auth login` in a terminal.
    const loginRes = await api('/api/claudecode/login', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ profileId: newId, browserChoice }),
    });
    if (!loginRes || !loginRes.ok) {
      if (typeof flash === 'function') flash(loginRes?.error || '启动 claude login 失败', 'error');
      return;
    }
    if (typeof flash === 'function') flash('已在终端打开登录窗口。完成浏览器授权后回到这里。', 'info');

    // Poll the profiles list — once the target profile picks up an accountUuid
    // from its .claude.json, auto-activate it. 超过 3 分钟仍无 token 视为登录
    // 放弃,静默删除这个空 profile 避免列表累积"登录到一半"的孤儿。
    let tries = 0;
    const pollId = setInterval(async () => {
      tries += 1;
      await loadClaudeCodeOauthProfiles();
      const prof = (window.__chClaudeOauthProfiles?.data?.profiles || []).find((p) => p.id === newId);
      if (prof && prof.hasTokens) {
        clearInterval(pollId);
        await switchClaudeCodeOauthProfile(newId);
      } else if (tries >= 72) {
        clearInterval(pollId);
        // 走 silent 路径:不弹确认,也不 flash;用户根本没登上,就当这次新增不存在
        try {
          await deleteClaudeCodeOauthProfile(newId, { force: true, silent: true });
          if (typeof flash === 'function') flash('登录超时未完成,已清理这个未激活的 profile。', 'info');
        } catch (e) { console.warn('[ch] orphan cleanup failed', e); }
      }
    }, 2500);
  }

  async function reloginClaudeCodeOauthProfile(id) {
    if (!id) return;
    const ok = window.confirm('重新登录会覆盖这个 profile 的 token。原账号状态保留在服务端，只是本机这份凭证换成新的。继续？');
    if (!ok) return;
    const browserChoice = await pickClaudeLoginBrowser({ title: '重新登录 · 选择浏览器' });
    if (browserChoice === null) return;
    const res = await api('/api/claudecode/login', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ profileId: id, browserChoice }),
    });
    if (!res || !res.ok) {
      if (typeof flash === 'function') flash(res?.error || '启动 claude login 失败', 'error');
      return;
    }
    if (typeof flash === 'function') flash('已打开登录窗口。完成授权后账号元数据会自动刷新。', 'info');
    let tries = 0;
    const pollId = setInterval(async () => {
      tries += 1;
      await loadClaudeCodeOauthProfiles();
      if (tries >= 48) clearInterval(pollId);
    }, 2500);
  }

  // Row-body click: activate this provider (modifies Codex's model_provider
  // pointer). Editing that same provider's URL / Key / model is done via the
  // ✏ icon which opens the drawer.
  async function switchRow(key) {
    if (!key) return;
    const s = hubState();
    if (!s) return;
    const tool = s.activeTool || 'codex';
    try {
      if (tool === 'codex') {
        if (key === '__codex_official_oauth__') {
          await activateCurrentCodexOauth();
          return;
        }
        if (key === '__codex_oauth_unsaved__') {
          // Body click on an unsaved OAuth row should switch immediately.
          // Saving it as a named profile is handled by the row action button.
          await activateCurrentCodexOauth(getDashboardCodexHome());
          return;
        }
        if (key.startsWith('__codex_oauth_profile:')) {
          const id = key.slice('__codex_oauth_profile:'.length);
          await switchOauthProfile(id);
          return;
        }
        const p = (s.current?.providers || []).find((x) => x.key === key);
        if (p && typeof quickSwitchCodexProvider === 'function') await quickSwitchCodexProvider(p);
      } else if (tool === 'claudecode') {
        if (key === '__claudecode_oauth_default__') {
          await switchClaudeCodeOauthProfile('');
          return;
        }
        if (key.startsWith('__claudecode_oauth_profile:')) {
          const id = key.slice('__claudecode_oauth_profile:'.length);
          await switchClaudeCodeOauthProfile(id);
          return;
        }
        const profiles = typeof getClaudeProviderProfiles === 'function' ? getClaudeProviderProfiles(s.claudeCodeState) : [];
        const p = (profiles || []).find((x) => x.key === key);
        if (p && typeof quickSwitchClaudeProvider === 'function') await quickSwitchClaudeProvider(p);
      } else if (tool === 'opencode') {
        const p = ((s.opencodeState?.providers) || []).find((x) => x.key === key);
        if (p && typeof quickSwitchOpenCodeProvider === 'function') await quickSwitchOpenCodeProvider(p);
      }
    } catch (err) {
      console.warn('[ch] switch failed', err);
    }
  }

  async function detectRow(key) {
    const s = hubState();
    if (!s) return;
    const tool = s.activeTool || 'codex';
    if (tool === 'codex') {
      const p = (s.current?.providers || []).find((x) => x.key === key);
      if (p && typeof testCodexProviderConnectivity === 'function') {
        try {
          const result = await testCodexProviderConnectivity(p);
          if (result && result.ok === false && result.error && typeof flash === 'function') {
            flash(result.error, 'warning');
          }
        } catch (err) {
          console.warn('[ch] detect failed', err);
        }
        return;
      }
    }
    if (tool === 'claudecode') {
      const profiles = typeof getClaudeProviderProfiles === 'function' ? getClaudeProviderProfiles(s.claudeCodeState) : [];
      const provider = (profiles || []).find((item) => item.key === key);
      if (provider && typeof testClaudeProviderConnectivity === 'function') {
        try {
          const result = await testClaudeProviderConnectivity(provider);
          if (result && result.ok === false && result.error && typeof flash === 'function') {
            flash(result.error, 'warning');
          }
        } catch (err) {
          console.warn('[ch] Claude detect failed', err);
        }
        return;
      }
    }
    document.getElementById('detectBtn')?.click();
  }

  // ── Auto-detect frequency ────────────────────────────────────────
  // Persist user's preferred cadence in localStorage. When > 0, schedules a
  // connectivity tick for eligible Codex API Key providers. Quota/balance
  // refreshes are folded into the same scheduler, but capped to 5 minutes.
  const AUTODETECT_LS_KEY = 'easyaiconfig_ch_autodetect_interval_sec';
  const AUTODETECT_MIN_SEC = 30; // guard against <30s cadence (server-side pressure)
  const AUTODETECT_BALANCE_MIN_MS = 5 * 60 * 1000;
  let autodetectTimerId = 0;
  let autodetectLastBalanceRefreshAt = 0;

  function clearAutodetectTimer() {
    if (autodetectTimerId) {
      clearInterval(autodetectTimerId);
      autodetectTimerId = 0;
    }
  }

  function scheduleAutodetect(sec) {
    clearAutodetectTimer();
    if (!sec || sec < AUTODETECT_MIN_SEC) return;
    autodetectTimerId = setInterval(() => {
      runAutodetectTick({ silentBalance: true });
    }, sec * 1000);
  }

  const AUTODETECT_OPTIONS = [
    { value: 0,    label: '关闭' },
    { value: 60,   label: '60 秒' },
    { value: 300,  label: '5 分钟' },
    { value: 1800, label: '30 分钟' },
    { value: 3600, label: '1 小时' },
  ];

  function labelForInterval(sec) {
    const opt = AUTODETECT_OPTIONS.find((o) => o.value === sec);
    return opt ? opt.label : '关闭';
  }

  function readAutodetectInterval() {
    let saved = 0;
    try {
      const raw = localStorage.getItem(AUTODETECT_LS_KEY);
      if (raw != null) saved = Math.max(0, parseInt(raw, 10) || 0);
    } catch (_) { /* localStorage may be denied; fall back to off */ }
    const allowed = AUTODETECT_OPTIONS.map((o) => o.value);
    return allowed.includes(saved) ? saved : 0;
  }

  function autodetectEligibleRows(tool = hubState()?.activeTool || 'codex') {
    if (tool !== 'codex') return [];
    return buildProviderRows('codex').filter((row) => (
      row.tool === 'codex'
      && row.mode === 'apikey'
      && row.hasCredential
      && !row.historyOnly
      && row.baseUrl
    ));
  }

  function canRunAutodetect(tool = hubState()?.activeTool || 'codex') {
    const canCheckHealth = typeof refreshProviderHealth === 'function' && autodetectEligibleRows(tool).length > 0;
    const canRefreshBalance = typeof refreshChAllBalances === 'function' && getChBalanceRefreshRows(tool).length > 0;
    return canCheckHealth || canRefreshBalance;
  }

  function runAutodetectTick(options = {}) {
    const { forceBalance = false, silentBalance = true } = options || {};
    if (document.hidden) return;
    const tool = hubState()?.activeTool || 'codex';
    if (tool !== 'codex') return;
    if (typeof refreshProviderHealth === 'function' && autodetectEligibleRows(tool).length > 0) {
      try { refreshProviderHealth(true); } catch (_) {}
    }
    if (typeof refreshChAllBalances !== 'function' || getChBalanceRefreshRows(tool).length === 0) return;
    const now = Date.now();
    if (!forceBalance && autodetectLastBalanceRefreshAt && now - autodetectLastBalanceRefreshAt < AUTODETECT_BALANCE_MIN_MS) return;
    autodetectLastBalanceRefreshAt = now;
    refreshChAllBalances({ silent: silentBalance }).catch((err) => {
      console.warn('[ch] auto balance refresh failed', err);
      autodetectLastBalanceRefreshAt = 0;
    });
  }

  function autodetectAvailability() {
    const s = hubState();
    const tool = s?.activeTool || 'codex';
    const rows = buildProviderRows(tool);
    const apiKeyRows = rows.filter((row) => row.mode === 'apikey' && !row.historyOnly);
    const healthRows = autodetectEligibleRows(tool);
    const balanceRows = getChBalanceRefreshRows(tool);
    const canRun = canRunAutodetect(tool);
    if (canRun) {
      return {
        canRun: true,
        valueLabel: null,
        title: healthRows.length
          ? '按所选频率检测 Codex API Key 连通性；额度/余额最多每 5 分钟刷新一次。'
          : `当前没有可连通性探测的 API Key；将按 5 分钟节流刷新 ${balanceRows.length} 个额度/余额。`,
      };
    }
    if (tool !== 'codex') {
      return {
        canRun: false,
        valueLabel: apiKeyRows.length ? '仅 Codex' : '无 API Key',
        title: '自动检测当前仅支持 Codex API Key Provider；官方 OAuth 不参与连通性探测。',
      };
    }
    return {
      canRun: false,
      valueLabel: apiKeyRows.length ? '缺 Key' : '无 API Key',
      title: '自动检测需要已保存 Key 的 Codex API Key Provider，或可查询额度/余额的 Codex Provider。',
    };
  }

  function applyAutodetectUi(sec) {
    const availability = autodetectAvailability();
    const container = document.getElementById('chAutodetect');
    if (container) {
      container.classList.toggle('is-on', availability.canRun && sec > 0);
      container.classList.toggle('is-disabled', !availability.canRun);
      container.title = availability.title;
      if (!availability.canRun) container.dataset.open = 'false';
    }
    const trigger = document.getElementById('chAutodetectTrigger');
    if (trigger) {
      trigger.disabled = !availability.canRun;
      trigger.setAttribute('aria-disabled', availability.canRun ? 'false' : 'true');
      trigger.title = availability.title;
      if (!availability.canRun) trigger.setAttribute('aria-expanded', 'false');
    }
    const valueEl = document.getElementById('chAutodetectValue');
    if (valueEl) valueEl.textContent = availability.canRun ? labelForInterval(sec) : availability.valueLabel;
    document.querySelectorAll('#chAutodetectMenu [data-ad-value]').forEach((btn) => {
      btn.classList.toggle('active', Number(btn.getAttribute('data-ad-value')) === sec);
    });
    if (!availability.canRun) document.getElementById('chAutodetectMenu')?.classList.add('hide');
  }

  function closeAutodetectMenu() {
    const menu = document.getElementById('chAutodetectMenu');
    const trigger = document.getElementById('chAutodetectTrigger');
    const container = document.getElementById('chAutodetect');
    if (menu) menu.classList.add('hide');
    if (trigger) trigger.setAttribute('aria-expanded', 'false');
    if (container) container.dataset.open = 'false';
  }

  function openAutodetectMenu() {
    if (!autodetectAvailability().canRun) {
      closeAutodetectMenu();
      return;
    }
    const menu = document.getElementById('chAutodetectMenu');
    const trigger = document.getElementById('chAutodetectTrigger');
    const container = document.getElementById('chAutodetect');
    if (menu) menu.classList.remove('hide');
    if (trigger) trigger.setAttribute('aria-expanded', 'true');
    if (container) container.dataset.open = 'true';
  }

	  function initAutodetect() {
    const trigger = document.getElementById('chAutodetectTrigger');
    const menu = document.getElementById('chAutodetectMenu');
    if (!trigger || !menu) return;

    const saved = readAutodetectInterval();
    applyAutodetectUi(saved);
    scheduleAutodetect(saved);

    // Auto-failover 触发器（旁边的小按钮）
    const afTrig = document.getElementById('chAutoFailoverTrigger');
    if (afTrig) {
      if (typeof renderAutoFailoverTrigger === 'function') renderAutoFailoverTrigger();
      afTrig.addEventListener('click', (e) => {
        e.stopPropagation();
        if (state.autoFailover?.panelOpen) {
          closeAutoFailoverPanel();
        } else {
          openAutoFailoverPanel();
        }
      });
    }

    trigger.addEventListener('click', (e) => {
      e.stopPropagation();
      if (!autodetectAvailability().canRun) {
        applyAutodetectUi(readAutodetectInterval());
        return;
      }
      const isOpen = !menu.classList.contains('hide');
      if (isOpen) closeAutodetectMenu();
      else openAutodetectMenu();
    });

    menu.addEventListener('click', (e) => {
      const btn = e.target instanceof Element ? e.target.closest('[data-ad-value]') : null;
      if (!btn) return;
      const sec = Math.max(0, parseInt(btn.getAttribute('data-ad-value'), 10) || 0);
      try { localStorage.setItem(AUTODETECT_LS_KEY, String(sec)); } catch (_) {}
      applyAutodetectUi(sec);
      scheduleAutodetect(sec);
      closeAutodetectMenu();
      if (sec > 0 && canRunAutodetect()) runAutodetectTick({ silentBalance: true });
    });

    // Dismiss on outside click / Escape
    document.addEventListener('click', (e) => {
      const container = document.getElementById('chAutodetect');
      if (!container || menu.classList.contains('hide')) return;
      if (!container.contains(e.target)) closeAutodetectMenu();
    });
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && !menu.classList.contains('hide')) closeAutodetectMenu();
    });

	    window.addEventListener('beforeunload', clearAutodetectTimer);
	  }

	  function closeChRowActionMenu() {
	    document.querySelectorAll('.ch-row-menu.is-open').forEach((menu) => {
	      menu.classList.remove('is-open');
	      const panel = menu.querySelector('.ch-row-menu-panel');
	      if (panel instanceof HTMLElement) {
	        panel.style.left = '';
	        panel.style.top = '';
	        panel.style.minWidth = '';
	      }
	      const trigger = menu.querySelector('[data-ch-row-menu-trigger]');
	      if (trigger) trigger.setAttribute('aria-expanded', 'false');
	    });
	  }

	  function openChRowActionMenu(trigger) {
	    if (!(trigger instanceof HTMLElement)) return;
	    const menu = trigger.closest('.ch-row-menu');
	    const panel = menu?.querySelector('.ch-row-menu-panel');
	    if (!(menu instanceof HTMLElement) || !(panel instanceof HTMLElement)) return;

	    const wasOpen = menu.classList.contains('is-open');
	    closeChRowActionMenu();
	    if (wasOpen) return;

	    menu.classList.add('is-open');
	    trigger.setAttribute('aria-expanded', 'true');
	    panel.style.left = '0px';
	    panel.style.top = '0px';
	    panel.style.minWidth = '';

	    const margin = 8;
	    const triggerRect = trigger.getBoundingClientRect();
	    const panelRect = panel.getBoundingClientRect();
	    const panelWidth = Math.max(panelRect.width || 176, 176);
	    const panelHeight = Math.max(panelRect.height || 0, 1);
	    const maxLeft = Math.max(margin, window.innerWidth - panelWidth - margin);
	    let left = Math.min(Math.max(margin, triggerRect.right - panelWidth), maxLeft);
	    let top = triggerRect.bottom + margin;
	    if (top + panelHeight > window.innerHeight - margin) {
	      top = Math.max(margin, triggerRect.top - panelHeight - margin);
	    }
	    panel.style.left = `${Math.round(left)}px`;
	    panel.style.top = `${Math.round(top)}px`;
	    panel.style.minWidth = `${Math.round(panelWidth)}px`;
	  }

  // ── Delegated event wiring (runs once on DOMContentLoaded) ─────
  function wire() {
    const hub = document.getElementById('connectionHub');
    if (!hub || hub.dataset.chWired === '1') return;
    hub.dataset.chWired = '1';

    // Add button
    document.getElementById('chAddBtn')?.addEventListener('click', () => {
      handlePrimaryAdd().catch((err) => console.warn('[ch] primary add failed', err));
    });
    document.getElementById('chBalanceRefreshBtn')?.addEventListener('click', () => {
      refreshChAllBalances().catch((err) => console.warn('[ch] balance refresh failed', err));
    });

    // Hero actions
    const hero = document.getElementById('chHero');
    // 安全前缀 checkbox 用 change 事件，避免 label-click 导致 state 不同步
    hero?.addEventListener('change', (e) => {
      const target = e.target instanceof Element ? e.target : null;
      if (!target) return;
      if (target.matches('[data-codex-cmd-prefix-toggle]')) {
        state.codexCmdShowPrefix = target.checked;
        const heroEl = document.getElementById('chHero');
        if (heroEl) {
          const rows = buildProviderRows(hubState()?.activeTool || 'codex');
          const active = rows.find((r) => r.isActive) || null;
          heroEl.innerHTML = renderHeroHTML(active, hubState()?.activeTool || 'codex');
        }
      }
    });
    hero?.addEventListener('click', async (e) => {
      const target = e.target instanceof Element ? e.target : null;
      if (!target) return;
      const launch = target.closest('[data-ch-launch]');
      if (launch) {
        e.preventDefault();
        e.stopPropagation();
        const s = hubState();
        const tool = s?.activeTool || 'codex';
        if (tool === 'codex' && typeof launchCodex === 'function') {
          if (await openCodexLaunchPicker(launch, { tool })) return;
          launchCodex('chHeroLaunchBtn', 'Codex 已启动', getSelectedCodexTerminalProfile()).catch(console.warn);
        } else {
          launchActiveTool('', 'chHeroLaunchBtn').catch(console.warn);
        }
        return;
      }
      const launchMenu = target.closest('[data-ch-launch-menu]');
      if (launchMenu) {
        e.preventDefault();
        e.stopPropagation();
        await openCodexLaunchPicker(document.getElementById('chHeroLaunchBtn') || launchMenu, { tool: hubState()?.activeTool || 'codex' });
        return;
      }
      const edit = target.closest('[data-ch-edit]');
      if (edit) { openSlideover('edit'); return; }
      const detect = target.closest('[data-ch-detect]');
      if (detect) {
        const s = hubState();
        const rows = buildProviderRows(s?.activeTool || 'codex');
        const active = rows.find((r) => r.isActive);
        if (active && !active.readOnly) detectRow(active.key);
        else document.getElementById('detectBtn')?.click();
        return;
      }
      const add = target.closest('[data-ch-add]');
      if (add) {
        handlePrimaryAdd().catch((err) => console.warn('[ch] primary add failed', err));
        return;
      }
      const heroBalanceQuery = target.closest('[data-ch-hero-balance-query]');
      if (heroBalanceQuery) {
        const key = heroBalanceQuery.getAttribute('data-ch-hero-balance-query') || '';
        const row = buildProviderRows(hubState()?.activeTool || 'codex').find((item) => item.key === key);
        if (row) queryChRowRemoteUsage(row).catch((err) => console.warn('[ch] hero balance query failed', err));
        return;
      }
      const heroRecharge = target.closest('[data-ch-hero-recharge]');
      if (heroRecharge) {
        const key = heroRecharge.getAttribute('data-ch-hero-recharge') || '';
        const row = buildProviderRows(hubState()?.activeTool || 'codex').find((item) => item.key === key);
        if (row) openChRowRecharge(row).catch((err) => console.warn('[ch] hero recharge failed', err));
        return;
      }
      // Codex 启动命令面板开/关（"安全前缀"无论 OAuth/API 默认都关，
      // 用户自己点上去才补 unset / CODEX_HOME）
      const cmdToggle = target.closest('[data-ch-cmd-toggle]');
      if (cmdToggle) {
        state.codexCmdPaletteOpen = !state.codexCmdPaletteOpen;
        const heroEl = document.getElementById('chHero');
        if (heroEl) {
          const rows = buildProviderRows(hubState()?.activeTool || 'codex');
          const active = rows.find((r) => r.isActive) || null;
          heroEl.innerHTML = renderHeroHTML(active, hubState()?.activeTool || 'codex');
          heroEl.classList.toggle('empty', !active);
        }
        return;
      }
      // 复制某条启动命令
      const cmdCopy = target.closest('[data-codex-cmd-copy]');
      if (cmdCopy) {
        const idx = Number(cmdCopy.dataset.codexCmdCopy);
        const preset = CODEX_LAUNCH_PRESETS[idx];
        if (!preset) return;
        const rows = buildProviderRows(hubState()?.activeTool || 'codex');
        const active = rows.find((r) => r.isActive);
        if (!active) {
          if (typeof flash === 'function') flash('当前没有激活的 provider', 'error');
          return;
        }
        const cmd = buildCodexLaunchCommand({
          codexHome: active.homePath || state.current?.codexHome || '',
          isOauth: active.mode === 'oauth',
          flags: preset.flags,
          isWindows: String(state.current?.launch?.platform || '').toLowerCase() === 'win32',
          withPrefix: Boolean(state.codexCmdShowPrefix),
          usesLocalRouter: isConnectionHubLocalRouterRow(active),
        });
        navigator.clipboard?.writeText(cmd)
          .then(() => {
            if (typeof flash === 'function') flash(`已复制：${preset.title}`, 'success');
          })
          .catch((err) => {
            console.warn('[codex cmd copy] clipboard failed', err);
            window.prompt('自动复制失败 —— 请手动选中下方命令并 Cmd-C：', cmd);
          });
        return;
      }
    });

    // Row clicks
    const list = document.getElementById('chList');
	    list?.addEventListener('click', (e) => {
	      const target = e.target instanceof Element ? e.target : null;
	      if (!target) return;
		      const menuTrigger = target.closest('[data-ch-row-menu-trigger]');
		      if (menuTrigger) {
		        e.preventDefault();
		        e.stopPropagation();
		        openChRowActionMenu(menuTrigger);
		        return;
		      }
		      const balanceToggle = target.closest('[data-ch-row-balance-toggle]');
		      if (balanceToggle) {
		        e.preventDefault();
		        e.stopPropagation();
		        closeChRowActionMenu();
		        const key = balanceToggle.getAttribute('data-ch-row-balance-toggle') || '';
		        const row = buildProviderRows(hubState()?.activeTool || 'codex').find((item) => item.key === key);
		        if (!row) return;
	        const nextVisible = !isChRowBalanceVisible(row);
	        setChRowBalanceVisible(row, nextVisible);
	        renderConnectionHub();
	        if (nextVisible && row.tool === 'codex' && (row.hasCredential || chRowHasRemotePanelCredential(row)) && !row.historyOnly && !state.providerRemoteUsageByKey?.[chRowCacheKey(row)]) {
	          queryChRowRemoteUsage(row).catch((err) => console.warn('[ch] row balance query failed', err));
	        }
	        return;
	      }
	      const balanceQuery = target.closest('[data-ch-row-balance-query]');
		      if (balanceQuery) {
		        e.preventDefault();
		        e.stopPropagation();
		        closeChRowActionMenu();
		        const key = balanceQuery.getAttribute('data-ch-row-balance-query') || '';
		        const row = buildProviderRows(hubState()?.activeTool || 'codex').find((item) => item.key === key);
		        if (row) queryChRowRemoteUsage(row).catch((err) => console.warn('[ch] row balance query failed', err));
	        return;
	      }
	      const rechargeBtn = target.closest('[data-ch-row-recharge]');
		      if (rechargeBtn) {
		        e.preventDefault();
		        e.stopPropagation();
		        closeChRowActionMenu();
		        const key = rechargeBtn.getAttribute('data-ch-row-recharge') || '';
		        const row = buildProviderRows(hubState()?.activeTool || 'codex').find((item) => item.key === key);
		        if (row) openChRowRecharge(row).catch((err) => console.warn('[ch] open recharge failed', err));
		        return;
		      }
	      // OAuth profile actions (rename / delete / save-current / add-new)
	      const addOauth = target.closest('[data-ch-oauth-add]');
	      if (addOauth) { e.stopPropagation(); closeChRowActionMenu(); addNewOauthAccount(); return; }
	      const saveOauth = target.closest('[data-ch-oauth-save-current]');
	      if (saveOauth) { e.stopPropagation(); closeChRowActionMenu(); saveCurrentOauthAsProfile(); return; }
	      const renameOauth = target.closest('[data-ch-oauth-rename]');
	      if (renameOauth) { e.stopPropagation(); closeChRowActionMenu(); renameOauthProfile(renameOauth.getAttribute('data-ch-oauth-rename')); return; }
	      const deleteOauth = target.closest('[data-ch-oauth-delete]');
	      if (deleteOauth) { e.stopPropagation(); closeChRowActionMenu(); deleteOauthProfile(deleteOauth.getAttribute('data-ch-oauth-delete')); return; }

      // Claude Code OAuth profile actions
	      const ccAddOauth = target.closest('[data-ch-cc-oauth-add]');
	      if (ccAddOauth) { e.stopPropagation(); closeChRowActionMenu(); addNewClaudeCodeOauthProfile(); return; }
	      const ccCopyExport = target.closest('[data-ch-cc-oauth-copy-export]');
	      if (ccCopyExport) {
	        e.stopPropagation();
	        closeChRowActionMenu();
	        copyClaudeExportCommand(ccCopyExport.getAttribute('data-ch-cc-oauth-copy-export') || '');
	        return;
	      }
	      const ccRename = target.closest('[data-ch-cc-oauth-rename]');
	      if (ccRename) { e.stopPropagation(); closeChRowActionMenu(); renameClaudeCodeOauthProfile(ccRename.getAttribute('data-ch-cc-oauth-rename')); return; }
	      const ccRelogin = target.closest('[data-ch-cc-oauth-relogin]');
	      if (ccRelogin) { e.stopPropagation(); closeChRowActionMenu(); reloginClaudeCodeOauthProfile(ccRelogin.getAttribute('data-ch-cc-oauth-relogin')); return; }
	      const ccDelete = target.closest('[data-ch-cc-oauth-delete]');
	      if (ccDelete) { e.stopPropagation(); closeChRowActionMenu(); deleteClaudeCodeOauthProfile(ccDelete.getAttribute('data-ch-cc-oauth-delete')); return; }

	      const editBtn = target.closest('[data-ch-row-edit]');
	      if (editBtn) { e.stopPropagation(); closeChRowActionMenu(); openSlideover('edit', editBtn.getAttribute('data-ch-row-edit')); return; }
	      const detectBtn = target.closest('[data-ch-row-detect]');
	      if (detectBtn) { e.stopPropagation(); closeChRowActionMenu(); detectRow(detectBtn.getAttribute('data-ch-row-detect')); return; }
	      const delBtn = target.closest('[data-ch-row-delete]');
	      if (delBtn) {
	        e.stopPropagation();
	        closeChRowActionMenu();
	        const key = delBtn.getAttribute('data-ch-row-delete');
	        const kind = delBtn.getAttribute('data-ch-row-delete-kind') || '';
	        deleteApiKeyProvider(key, kind);
        return;
      }
      const row = target.closest('[data-ch-key]');
      if (row) {
	        const key = row.getAttribute('data-ch-key');
	        // 点行 = 打开详情 drawer（不再直接切换）。
	        // 切换 / 编辑 / 测试 / 删除 都是 drawer 内或行内显式按钮。
	        closeChRowActionMenu();
	        openProviderDetail(key);
	      }
	    });
    list?.addEventListener('keydown', (e) => {
      if (e.key !== 'Enter' && e.key !== ' ') return;
      const target = e.target instanceof Element ? e.target : null;
      const row = target && target.closest('[data-ch-key]');
      if (row) {
        const key = row.getAttribute('data-ch-key');
        e.preventDefault();
        openProviderDetail(key);
      }
    });

    // Ribbon filter
    const ribbon = document.getElementById('chRibbon');
    ribbon?.addEventListener('click', (e) => {
      const target = e.target instanceof Element ? e.target : null;
      const btn = target && target.closest('[data-ch-filter]');
      if (!btn) return;
      const s = hubState();
      if (!s) return;
      s.chFilter = btn.getAttribute('data-ch-filter');
      ribbon.querySelectorAll('.ch-ribbon-item').forEach((b) => b.classList.toggle('active', b === btn));
      renderConnectionHub();
    });

    // Search
    const search = document.getElementById('chSearchInput');
    const clear = document.getElementById('chSearchClear');
    const searchWrap = search?.closest('.ch-search');
    searchWrap?.addEventListener('pointerdown', (event) => {
      event.stopPropagation();
      if (event.target === searchWrap || event.target.closest('svg')) search?.focus();
    });
    searchWrap?.addEventListener('click', (event) => event.stopPropagation());
    if (search) {
      search.addEventListener('input', () => {
        const s = hubState();
        if (!s) return;
        s.chSearch = search.value;
        if (clear) clear.classList.toggle('hide', !search.value);
        renderConnectionHub();
      });
    }
    if (clear) {
      clear.addEventListener('click', () => {
        if (search) { search.value = ''; search.focus(); }
        const s = hubState();
        if (s) s.chSearch = '';
        clear.classList.add('hide');
        renderConnectionHub();
      });
    }

    // Close slide-over (scrim, X button, Escape)
    document.querySelectorAll('[data-ch-close]').forEach((el) => el.addEventListener('click', closeSlideover));
	    document.addEventListener('keydown', (e) => {
	      if (e.key === 'Escape') {
	        closeChRowActionMenu();
	        const so = document.getElementById('chSlideover');
	        if (so && so.classList.contains('open')) closeSlideover();
	      }
	    });
	    document.addEventListener('click', (e) => {
	      const target = e.target instanceof Element ? e.target : null;
	      if (target?.closest('.ch-row-menu')) return;
	      closeChRowActionMenu();
	    });
	    document.addEventListener('scroll', closeChRowActionMenu, true);
	    window.addEventListener('resize', closeChRowActionMenu);

    // Save button in the drawer: wait for the actual save result. If the
    // backend rejects URL / Key / model, keep the drawer open so the user can
    // fix the field that failed.
    const saveBtn = document.getElementById('saveBtn');
    if (saveBtn) {
      saveBtn.addEventListener('click', async (event) => {
        const so = document.getElementById('chSlideover');
        if (!so || !so.classList.contains('open')) return;
        event.preventDefault();
        event.stopImmediatePropagation();
        const saved = await saveConfigOnly();
        if (saved) closeSlideover();
      }, true);
    }

    const drawerSaveBtn = document.getElementById('providerDrawerSaveBtn');
    if (drawerSaveBtn) {
      drawerSaveBtn.addEventListener('click', async (event) => {
        event.preventDefault();
        setBusy('providerDrawerSaveBtn', true, '保存中...');
        let saved = false;
        try {
          saved = await saveConfigOnly();
        } finally {
          setBusy('providerDrawerSaveBtn', false);
        }
        if (saved) closeSlideover();
      });
    }

    // Launch button: close drawer after launch (same as before, no save-restore needed)
    const launchBtn = document.getElementById('launchBtn');
    if (launchBtn) {
      launchBtn.addEventListener('click', () => {
        setTimeout(() => {
          const so = document.getElementById('chSlideover');
          if (so && so.classList.contains('open')) closeSlideover();
        }, 120);
      });
    }

    // Auto-detect frequency
    initAutodetect();
  }

  // Expose hub render so renderCurrentConfig() can call it
  window.renderConnectionHub = renderConnectionHub;
  window.__chLoadOauthProfiles = loadCodexOauthProfiles;
  window.__chLoadClaudeCodeOauthProfiles = loadClaudeCodeOauthProfiles;
  // 让外面的 detail drawer / auto-failover 能拿到 hub 内部函数
  window.__chBuildRows = buildProviderRows;
  window.__chHubState = hubState;
  window.__chSwitchRow = switchRow;
  window.__chOpenSlideover = openSlideover;
  window.__chDeleteApiKeyProvider = deleteApiKeyProvider;
  window.__chBuildCodexLaunchCmd = buildCodexLaunchCommand;

  async function initialLoad() {
    wire();
    // Prime persistent app settings (ipGateBlock etc.) so launches have the
    // right policy even if the user never opens the console page.
    if (typeof loadAppSettings === 'function') loadAppSettings();
    // Kick off both OAuth profile fetches in parallel. Each loader calls
    // renderConnectionHub() on completion, so the first user-visible render
    // already has real backend data — no localStorage cache, no guessing.
    // If renderCurrentConfig / tool switches call renderConnectionHub in the
    // meantime, the hub falls back to an explicit "加载中..." state for the
    // still-loading tool (handled in renderConnectionHub itself).
    await Promise.all([
      loadProviderRemoteUsageCache(),
      loadCodexOauthProfiles(),
      loadClaudeCodeOauthProfiles(),
    ]);
  }

  function initSecondaryCollapse() {
    const KEY = 'ea_sec_collapsed';
    const apply = (on) => {
      document.body.classList.toggle('sec-collapsed', !!on);
      try { localStorage.setItem(KEY, on ? '1' : '0'); } catch (_) {}
    };
    try { if (localStorage.getItem(KEY) === '1') apply(true); } catch (_) {}
    document.getElementById('secondaryCollapseBtn')?.addEventListener('click', () => apply(true));
    document.getElementById('secondaryExpandBtn')?.addEventListener('click', () => apply(false));
  }

  // ES modules are deferred: DOM is usually already ready when this runs,
  // so always init collapse bindings (don't only register on DOMContentLoaded).
  try { initSecondaryCollapse(); } catch (_) {}

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initialLoad);
  } else {
    initialLoad();
  }
})();
